import React, { useRef, useEffect, useState } from 'react';
import { QuoteCategory, QuoteItem } from '../types';
import { Trash2, Plus, Sparkles, Bold, Italic, Link, Image as ImageIcon, Table, List, ListOrdered, FileText, ChevronDown, ChevronUp, BookOpen, Layers, Box, Eye, EyeOff, Replace, Printer, Percent, GripVertical } from 'lucide-react';

interface CategoryTableProps {
  category: QuoteCategory;
  currency: string;
  globalMargin: number;
  onUpdateCategory: (id: string, field: keyof QuoteCategory, value: any) => void;
  onDeleteCategory: (id: string) => void;
  onAddItem: (categoryId: string, isSurcharge?: boolean) => void;
  onUpdateItem: (categoryId: string, itemId: string, field: keyof QuoteItem, value: any) => void;
  onDeleteItem: (categoryId: string, itemId: string) => void;
  onAiSuggest: (categoryId: string, categoryName: string) => void;
  onOpenCatalog: (categoryId: string, itemId?: string) => void;
  onMoveCategory?: (id: string, direction: 'up' | 'down') => void;
  isAiLoading: boolean;
  readOnly?: boolean; // New prop for locking edits
  hidePrices?: boolean; // New prop for hiding price columns (Contract mode or Toggle)

  // Drag Category Props
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent, id: string) => void;
  onDragOver?: (e: React.DragEvent, id: string) => void;
  onDragEnd?: (e: React.DragEvent) => void;
}

export const CategoryTable: React.FC<CategoryTableProps> = ({
  category,
  currency,
  globalMargin,
  onUpdateCategory,
  onDeleteCategory,
  onAddItem,
  onUpdateItem,
  onDeleteItem,
  onAiSuggest,
  onOpenCatalog,
  onMoveCategory,
  isAiLoading,
  readOnly = false,
  hidePrices = false,
  draggable, onDragStart, onDragOver, onDragEnd
}) => {
  const [showRichText, setShowRichText] = useState(!!category.textContent);
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Sync initial content
  useEffect(() => {
    if (showRichText && editorRef.current && category.textContent && editorRef.current.innerHTML !== category.textContent) {
       editorRef.current.innerHTML = category.textContent;
    }
  }, [showRichText, category.id]); 

  const formatNumber = (num: number) => {
    return num.toLocaleString('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const getSellingPrice = (costPrice: number) => {
    return costPrice * (1 + globalMargin / 100);
  };

  const isEmpty = category.items.length === 0 && !category.textContent;
  const isHidden = category.isHidden;
  const isHiddenFromPrint = category.isHiddenFromPrint;

  // --- Editor Logic ---
  const handleInput = () => {
    if (editorRef.current && !readOnly) {
      onUpdateCategory(category.id, 'textContent', editorRef.current.innerHTML);
    }
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const insertImage = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (readerEvent) => {
          const result = readerEvent.target?.result as string;
          execCmd('insertImage', result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const insertLink = () => {
    const url = prompt('Vložte URL odkazu (napr. na video):');
    if (url) execCmd('createLink', url);
  };

  const insertTable = () => {
    const html = `
      <table style="width: 100%; border-collapse: collapse; margin: 10px 0;">
        <tbody>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
        </tbody>
      </table>
      <p><br/></p>
    `;
    execCmd('insertHTML', html);
  };

  const toggleRichText = () => {
      setShowRichText(!showRichText);
  };

  const toggleSection = () => {
      if(readOnly) return;
      const newSection = category.section === 'shaft' ? 'lift' : 'shaft';
      onUpdateCategory(category.id, 'section', newSection);
  };

  const toggleVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHidden', !isHidden);
  };

  const togglePrintVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHiddenFromPrint', !isHiddenFromPrint);
  }

  // --- ITEM DRAG & DROP HANDLERS ---
  const onDragStartItem = (e: React.DragEvent, itemId: string) => {
      e.stopPropagation(); // Stop propagation so category D&D doesn't trigger
      setDraggedItemId(itemId);
      e.dataTransfer.effectAllowed = 'move';
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndItem = (e: React.DragEvent) => {
      e.stopPropagation();
      setDraggedItemId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverItem = (e: React.DragEvent, targetItemId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!draggedItemId || draggedItemId === targetItemId) return;

      const items = category.items;
      const draggedIndex = items.findIndex(i => i.id === draggedItemId);
      const targetIndex = items.findIndex(i => i.id === targetItemId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      onUpdateCategory(category.id, 'items', newItems);
  };

  // Determine classes based on hidden states
  let wrapperClasses = "mb-2 flex border rounded-lg overflow-hidden bg-white shadow-sm break-inside-avoid transition-all";
  if (isHidden) {
      // Completely hidden (Grayed out)
      wrapperClasses += " opacity-60 grayscale border-dashed border-gray-400 print:hidden";
  } else if (isHiddenFromPrint) {
      // Hidden from Print ONLY (Red dashed border in UI)
      wrapperClasses += " border-red-300 border-2 border-dashed print:hidden bg-red-50/30";
  } else {
      // Normal
      wrapperClasses += " border-gray-200 print:border-gray-200 print:shadow-none";
  }

  if (isEmpty) wrapperClasses += " print:hidden";
  if (readOnly) wrapperClasses += " border-gray-100";

  return (
    <div className={wrapperClasses}>

      {/* STRICT PRINT HIDING LOGIC */}
      {/* This allows Admin to see prices on screen, but enforces hiding in Print */}
      {hidePrices && (
          <style>{`
              @media print {
                  .price-column-strict { display: none !important; }
              }
          `}</style>
      )}

      {/* Left Vertical Sidebar - Category Name (With D&D Handle) */}
      <div 
          className={`w-8 border-r border-gray-200 flex flex-col items-center py-2 relative print:border-gray-300 print:w-6 ${isHidden ? 'bg-gray-200' : isHiddenFromPrint ? 'bg-red-50' : 'bg-gray-50'} ${draggable && !readOnly ? 'cursor-grab active:cursor-grabbing' : ''}`}
          draggable={draggable && !readOnly}
          onDragStart={(e) => onDragStart && onDragStart(e, category.id)}
          onDragOver={(e) => onDragOver && onDragOver(e, category.id)}
          onDragEnd={onDragEnd}
      >

        {/* Section Toggle (Lift/Shaft) */}
        <button 
            onClick={toggleSection}
            disabled={readOnly}
            className={`no-print p-0.5 rounded mb-2 transition ${category.section === 'shaft' ? 'text-blue-600 bg-blue-100 hover:bg-blue-200' : 'text-gray-400 hover:bg-gray-200'} ${readOnly ? 'opacity-50 cursor-not-allowed' : ''}`}
            title={category.section === 'shaft' ? "Patrí do: Šachta / Konštrukcia" : "Patrí do: Výťah / Technológia"}
        >
            {category.section === 'shaft' ? <Box size={14} /> : <Layers size={14} />}
        </button>

        {/* Vertically Centered Text */}
        <div className="flex-1 flex items-center justify-center">
             <div className="transform -rotate-90 whitespace-nowrap">
                {readOnly ? (
                    <span className="font-bold text-xs text-gray-800 w-48 text-center block uppercase tracking-wide">{category.name}</span>
                ) : (
                    <input
                        type="text"
                        value={category.name}
                        onChange={(e) => onUpdateCategory(category.id, 'name', e.target.value)}
                        className="bg-transparent font-bold text-xs text-gray-800 text-center focus:outline-none focus:text-black placeholder-gray-400 print:text-black w-48 uppercase tracking-wide"
                        placeholder="NÁZOV KATEGÓRIE"
                    />
                )}
            </div>
        </div>
      </div>

      {/* Right Content - Table & Actions */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Category Toolbar - Hide most actions if ReadOnly */}
        <div className={`bg-white p-1 flex justify-end gap-2 border-b border-gray-100 print:hidden ${readOnly ? 'bg-gray-50' : ''}`}>

           {/* Move Buttons */}
           {!readOnly && onMoveCategory && (
                <div className="flex gap-1 mr-auto border-r pr-2 border-gray-200">
                     <button onClick={() => onMoveCategory(category.id, 'up')} className="p-0.5 hover:bg-gray-100 rounded text-gray-500" title="Posunúť hore"><ChevronUp size={14}/></button>
                     <button onClick={() => onMoveCategory(category.id, 'down')} className="p-0.5 hover:bg-gray-100 rounded text-gray-500" title="Posunúť dole"><ChevronDown size={14}/></button>
                </div>
           )}

           {category.section === 'shaft' && (
               <span className="mr-auto text-[10px] font-bold text-blue-600 uppercase tracking-wider bg-blue-50 px-1.5 py-0.5 rounded border border-blue-100 flex items-center gap-1">
                   <Box size={10}/> Šachta
               </span>
           )}

            {!readOnly && (
                <>
                    {/* HIDE FROM PRINT (But Calculate) */}
                    <button
                        onClick={togglePrintVisibility}
                        className={`flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-medium rounded transition ${isHiddenFromPrint ? 'bg-red-100 text-red-600 border border-red-200' : 'text-gray-400 hover:bg-gray-100 hover:text-black'}`}
                        title={isHiddenFromPrint ? "Položka sa TLAČÍ (Zahrnutá v cene)" : "Skryť pri tlači (ALE POČÍTAŤ CENU)"}
                    >
                         <div className="relative">
                            <Printer size={14} />
                            {isHiddenFromPrint && <div className="absolute inset-0 flex items-center justify-center"><div className="w-full h-0.5 bg-red-600 rotate-45 transform"></div></div>}
                         </div>
                    </button>

                    {/* HIDE COMPLETELY (Exclude) */}
                    <button
                        onClick={toggleVisibility}
                        className={`flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-medium rounded transition ${isHidden ? 'bg-gray-300 text-gray-700' : 'text-gray-400 hover:bg-gray-100 hover:text-black'}`}
                        title={isHidden ? "Zobraziť (Zahrnúť do ceny)" : "Skryť ÚPLNE (Vyradiť z ceny)"}
                    >
                        {isHidden ? <EyeOff size={14} /> : <Eye size={14} />}
                    </button>

                    <div className="w-px bg-gray-200 mx-1"></div>

                    <button
                        onClick={toggleRichText}
                        className={`flex items-center gap-1 px-2 py-0.5 text-[10px] font-medium rounded transition ${showRichText ? 'bg-blue-50 text-blue-700' : 'text-gray-500 hover:bg-gray-100'}`}
                        title="Pridať textový popis"
                    >
                        <FileText size={12} />
                        {showRichText ? 'Text' : 'Text'}
                    </button>

                    <button
                        onClick={() => onDeleteCategory(category.id)}
                        className="text-gray-300 hover:text-red-600 transition p-0.5"
                        title="Odstrániť kategóriu"
                    >
                        <Trash2 size={14} />
                    </button>
                </>
            )}
            {readOnly && (
                 <span className="text-[10px] text-gray-400 font-medium uppercase tracking-wider flex items-center gap-1">
                     <FileText size={10}/> Príloha
                 </span>
            )}
        </div>

        {/* 1. Items Table - COMPACT DESIGN */}
        {category.items.length > 0 && (
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-xs text-left">
            <thead className="bg-gray-50 text-gray-500 border-b border-gray-200">
              <tr className="text-[10px] uppercase tracking-wider">
                {!readOnly && <th className="px-1 py-1 w-4 no-print"></th>}
                <th className="px-2 py-1 w-6 no-print align-top font-medium">#</th>
                <th className="px-2 py-1 align-top w-auto font-medium">Popis položky</th>
                <th className="px-1 py-1 w-12 text-right align-top font-medium">M.J.</th>
                <th className="px-1 py-1 w-12 text-right align-top font-medium">Mn.</th>

                {/* Price Column */}
                <th className={`px-2 py-1 w-20 text-right align-top font-medium price-column-strict ${hidePrices ? '' : ''}`}>
                    <span className={`print:hidden ${readOnly ? 'text-black' : 'text-blue-600'}`}>
                        {readOnly ? 'Cena' : 'Nákup'}
                    </span>
                    <span className="hidden print:inline">Cena</span>
                </th>

                {!readOnly && <th className="px-1 py-1 w-10 no-print align-top"></th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 print:divide-gray-100">
              {category.items.map((item, index) => {
                const sellingPrice = getSellingPrice(item.unitPrice);
                return (
                <tr 
                    key={item.id} 
                    className={`group transition-colors print:hover:bg-transparent ${item.isSurcharge ? 'bg-gray-50/50' : 'hover:bg-gray-50'}`}
                    draggable={!readOnly}
                    onDragStart={(e) => onDragStartItem(e, item.id)}
                    onDragOver={(e) => onDragOverItem(e, item.id)}
                    onDragEnd={onDragEndItem}
                >
                  {!readOnly && (
                      <td className="px-1 py-1 text-center no-print text-gray-300 cursor-grab hover:text-gray-500 align-top pt-1.5">
                          <GripVertical size={12}/>
                      </td>
                  )}
                  <td className="px-2 py-1 text-gray-400 no-print align-top text-[10px] pt-1.5">{index + 1}</td>
                  <td className="px-2 py-0.5 align-top relative">
                    {readOnly ? (
                        <div className={`text-gray-900 whitespace-pre-wrap leading-tight py-1 ${item.isSurcharge ? 'pl-4 italic text-gray-600 text-[11px]' : 'text-xs'}`}>
                            {item.isSurcharge && <span className="absolute left-0 top-1.5 text-gray-400 text-[10px]">•</span>}
                            {item.description}
                        </div>
                    ) : (
                        <div className={`flex gap-1 py-0.5 ${item.isSurcharge ? 'pl-4' : ''}`}>
                             {item.isSurcharge && <span className="absolute left-1 top-2 text-gray-400 text-[10px]">•</span>}
                             <textarea
                                rows={1}
                                value={item.description}
                                onChange={(e) => {
                                    onUpdateItem(category.id, item.id, 'description', e.target.value);
                                    e.target.style.height = 'auto';
                                    e.target.style.height = e.target.scrollHeight + 'px';
                                }}
                                onInput={(e) => {
                                    const target = e.target as HTMLTextAreaElement;
                                    target.style.height = 'auto';
                                    target.style.height = target.scrollHeight + 'px';
                                }}
                                onFocus={(e) => {
                                    e.target.style.height = 'auto';
                                    e.target.style.height = e.target.scrollHeight + 'px';
                                }}
                                className={`w-full bg-transparent focus:outline-none focus:text-black resize-none text-xs placeholder-gray-300 print:text-black leading-normal overflow-hidden py-0.5 ${item.isSurcharge ? 'italic text-gray-600' : 'text-gray-800 font-medium'}`}
                                placeholder="Názov položky..."
                                style={{ minHeight: '1.25rem' }}
                            />
                            {/* In-row Catalog Button */}
                            <button
                                onClick={() => onOpenCatalog(category.id, item.id)}
                                className="no-print self-start p-1 text-blue-300 hover:text-blue-600 rounded transition opacity-0 group-hover:opacity-100 focus:opacity-100 mt-0.5"
                                title="Vybrať variant z katalógu"
                            >
                                <BookOpen size={12} />
                            </button>
                        </div>
                    )}
                  </td>
                  <td className="px-1 py-0.5 align-top text-right pt-1.5">
                    {readOnly ? (
                        <span className="text-gray-600 text-[11px]">{item.unit}</span>
                    ) : (
                        <select
                            value={item.unit}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'unit', e.target.value)}
                            className="w-full text-right bg-transparent text-gray-500 border-none rounded px-0 py-0 focus:outline-none focus:text-black appearance-none print:bg-transparent print:text-black text-[11px] cursor-pointer hover:bg-gray-100"
                        >
                            <option value="ks">ks</option>
                            <option value="m">m</option>
                            <option value="hod">hod</option>
                            <option value="kpl">kpl</option>
                            <option value="set">set</option>
                        </select>
                    )}
                  </td>
                  <td className="px-1 py-0.5 align-top text-right pt-1.5">
                    {readOnly ? (
                        <span className="text-gray-900 font-bold text-xs">{item.quantity}</span>
                    ) : (
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={item.quantity}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'quantity', parseFloat(e.target.value) || 0)}
                            className="w-full text-right bg-transparent text-gray-900 font-bold focus:outline-none print:text-black text-xs p-0 hover:bg-gray-100 rounded"
                        />
                    )}
                  </td>

                  {/* Price Column */}
                  <td className="px-2 py-0.5 align-top text-right price-column-strict pt-1.5">
                    {readOnly ? (
                        <span className="text-xs font-medium text-black block">
                            {formatNumber(sellingPrice)}
                        </span>
                    ) : (
                        <>
                            {/* EDIT MODE: Input for Cost */}
                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={item.unitPrice}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                                className={`w-full text-right bg-transparent font-medium focus:outline-none text-xs print:hidden cursor-text p-0 hover:bg-blue-50 rounded ${hidePrices ? 'text-gray-400' : 'text-blue-600'}`}
                                placeholder="0.00"
                                title="Nákupná cena"
                            />
                            {/* PRINT MODE: Calculated Selling Price */}
                            <span className="hidden print:block text-xs font-medium text-black">
                                {formatNumber(sellingPrice)}
                            </span>
                        </>
                    )}
                  </td>

                  {/* Actions */}
                  {!readOnly && (
                    <td className="px-1 py-0.5 text-center no-print align-top flex justify-center gap-0.5 pt-1">
                        <button
                            onClick={() => onAddItem(category.id, true)}
                            className="text-gray-300 hover:text-blue-500 hover:bg-blue-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                            title="Pridať príplatok / pod-položku"
                        >
                            <Percent size={12} />
                        </button>
                        <button
                            onClick={() => onDeleteItem(category.id, item.id)}
                            className="text-gray-300 hover:text-red-500 hover:bg-red-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <Trash2 size={12} />
                        </button>
                    </td>
                  )}
                </tr>
              )})}
            </tbody>
          </table>
        </div>
        )}

          {!readOnly && (
            <div className="p-1 border-t border-gray-100 bg-white no-print flex gap-2 justify-center opacity-0 hover:opacity-100 transition-opacity">
                <button
                onClick={() => onAddItem(category.id)}
                className="flex items-center gap-1 text-[10px] font-bold text-gray-400 hover:text-blue-600 px-2 py-0.5 rounded hover:bg-blue-50 transition uppercase tracking-wide"
                >
                <Plus size={12} /> Pridať riadok
                </button>
            </div>
          )}

          {/* 2. Embedded Rich Text Area */}
          {(showRichText || (readOnly && category.textContent)) && (
            <div className="border-t border-gray-100 p-4 bg-white">
                <div className="mb-2 text-[10px] font-bold text-gray-400 uppercase tracking-wider print:hidden">Technická špecifikácia / Prílohy</div>
                <div
                    ref={editorRef}
                    contentEditable={!readOnly}
                    onInput={handleInput}
                    className={`rich-text-content w-full min-h-[60px] outline-none text-gray-900 text-xs leading-relaxed ${readOnly ? 'pointer-events-none' : ''}`}
                    dangerouslySetInnerHTML={{ __html: category.textContent || '' }}
                />
            </div>
          )}
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { QuoteCategory, QuoteItem } from '../types';
import { Trash2, Plus, Sparkles, Bold, Italic, Link, Image as ImageIcon, Table, List, ListOrdered, FileText, ChevronDown, ChevronUp, BookOpen, Layers, Box, Eye, EyeOff, Replace, Printer, Percent, GripVertical } from 'lucide-react';

interface CategoryTableProps {
  category: QuoteCategory;
  currency: string;
  globalMargin: number;
  onUpdateCategory: (id: string, field: keyof QuoteCategory, value: any) => void;
  onDeleteCategory: (id: string) => void;
  onAddItem: (categoryId: string, isSurcharge?: boolean) => void;
  onUpdateItem: (categoryId: string, itemId: string, field: keyof QuoteItem, value: any) => void;
  onDeleteItem: (categoryId: string, itemId: string) => void;
  onAiSuggest: (categoryId: string, categoryName: string) => void;
  onOpenCatalog: (categoryId: string, itemId?: string) => void;
  onMoveCategory?: (id: string, direction: 'up' | 'down') => void;
  isAiLoading: boolean;
  readOnly?: boolean; // New prop for locking edits
  hidePrices?: boolean; // New prop for hiding price columns (Contract mode or Toggle)

  // Drag Category Props
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent, id: string) => void;
  onDragOver?: (e: React.DragEvent, id: string) => void;
  onDragEnd?: (e: React.DragEvent) => void;
}

export const CategoryTable: React.FC<CategoryTableProps> = ({
  category,
  currency,
  globalMargin,
  onUpdateCategory,
  onDeleteCategory,
  onAddItem,
  onUpdateItem,
  onDeleteItem,
  onAiSuggest,
  onOpenCatalog,
  onMoveCategory,
  isAiLoading,
  readOnly = false,
  hidePrices = false,
  draggable, onDragStart, onDragOver, onDragEnd
}) => {
  const [showRichText, setShowRichText] = useState(!!category.textContent);
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Sync initial content
  useEffect(() => {
    if (showRichText && editorRef.current && category.textContent && editorRef.current.innerHTML !== category.textContent) {
       editorRef.current.innerHTML = category.textContent;
    }
  }, [showRichText, category.id]); 

  const formatNumber = (num: number) => {
    return num.toLocaleString('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const getSellingPrice = (costPrice: number) => {
    return costPrice * (1 + globalMargin / 100);
  };

  const isEmpty = category.items.length === 0 && !category.textContent;
  const isHidden = category.isHidden;
  const isHiddenFromPrint = category.isHiddenFromPrint;

  // --- Editor Logic ---
  const handleInput = () => {
    if (editorRef.current && !readOnly) {
      onUpdateCategory(category.id, 'textContent', editorRef.current.innerHTML);
    }
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const insertImage = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (readerEvent) => {
          const result = readerEvent.target?.result as string;
          execCmd('insertImage', result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const insertLink = () => {
    const url = prompt('Vložte URL odkazu (napr. na video):');
    if (url) execCmd('createLink', url);
  };

  const insertTable = () => {
    const html = `
      <table style="width: 100%; border-collapse: collapse; margin: 10px 0;">
        <tbody>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
        </tbody>
      </table>
      <p><br/></p>
    `;
    execCmd('insertHTML', html);
  };

  const toggleRichText = () => {
      setShowRichText(!showRichText);
  };

  const toggleSection = () => {
      if(readOnly) return;
      const newSection = category.section === 'shaft' ? 'lift' : 'shaft';
      onUpdateCategory(category.id, 'section', newSection);
  };

  const toggleVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHidden', !isHidden);
  };

  const togglePrintVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHiddenFromPrint', !isHiddenFromPrint);
  }

  // --- ITEM DRAG & DROP HANDLERS ---
  const onDragStartItem = (e: React.DragEvent, itemId: string) => {
      e.stopPropagation(); // Stop propagation so category D&D doesn't trigger
      setDraggedItemId(itemId);
      e.dataTransfer.effectAllowed = 'move';
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndItem = (e: React.DragEvent) => {
      e.stopPropagation();
      setDraggedItemId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverItem = (e: React.DragEvent, targetItemId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!draggedItemId || draggedItemId === targetItemId) return;

      const items = category.items;
      const draggedIndex = items.findIndex(i => i.id === draggedItemId);
      const targetIndex = items.findIndex(i => i.id === targetItemId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      onUpdateCategory(category.id, 'items', newItems);
  };

  // Determine classes based on hidden states
  let wrapperClasses = "mb-2 flex border rounded-lg overflow-hidden bg-white shadow-sm break-inside-avoid transition-all";
  if (isHidden) {
      // Completely hidden (Grayed out)
      wrapperClasses += " opacity-60 grayscale border-dashed border-gray-400 print:hidden";
  } else if (isHiddenFromPrint) {
      // Hidden from Print ONLY (Red dashed border in UI)
      wrapperClasses += " border-red-300 border-2 border-dashed print:hidden bg-red-50/30";
  } else {
      // Normal
      wrapperClasses += " border-gray-200 print:border-gray-200 print:shadow-none";
  }

  if (isEmpty) wrapperClasses += " print:hidden";
  if (readOnly) wrapperClasses += " border-gray-100";

  return (
    <div className={wrapperClasses}>

      {/* STRICT PRINT HIDING LOGIC */}
      {/* This allows Admin to see prices on screen, but enforces hiding in Print */}
      {hidePrices && (
          <style>{`
              @media print {
                  .price-column-strict { display: none !important; }
              }
          `}</style>
      )}

      {/* Left Vertical Sidebar - Category Name (With D&D Handle) */}
      <div 
          className={`w-8 border-r border-gray-200 flex flex-col items-center py-2 relative print:border-gray-300 print:w-6 ${isHidden ? 'bg-gray-200' : isHiddenFromPrint ? 'bg-red-50' : 'bg-gray-50'} ${draggable && !readOnly ? 'cursor-grab active:cursor-grabbing' : ''}`}
          draggable={draggable && !readOnly}
          onDragStart={(e) => onDragStart && onDragStart(e, category.id)}
          onDragOver={(e) => onDragOver && onDragOver(e, category.id)}
          onDragEnd={onDragEnd}
      >

        {/* Section Toggle (Lift/Shaft) */}
        <button 
            onClick={toggleSection}
            disabled={readOnly}
            className={`no-print p-0.5 rounded mb-2 transition ${category.section === 'shaft' ? 'text-blue-600 bg-blue-100 hover:bg-blue-200' : 'text-gray-400 hover:bg-gray-200'} ${readOnly ? 'opacity-50 cursor-not-allowed' : ''}`}
            title={category.section === 'shaft' ? "Patrí do: Šachta / Konštrukcia" : "Patrí do: Výťah / Technológia"}
        >
            {category.section === 'shaft' ? <Box size={14} /> : <Layers size={14} />}
        </button>

        {/* Vertically Centered Text */}
        <div className="flex-1 flex items-center justify-center">
             <div className="transform -rotate-90 whitespace-nowrap">
                {readOnly ? (
                    <span className="font-bold text-xs text-gray-800 w-48 text-center block uppercase tracking-wide">{category.name}</span>
                ) : (
                    <input
                        type="text"
                        value={category.name}
                        onChange={(e) => onUpdateCategory(category.id, 'name', e.target.value)}
                        className="bg-transparent font-bold text-xs text-gray-800 text-center focus:outline-none focus:text-black placeholder-gray-400 print:text-black w-48 uppercase tracking-wide"
                        placeholder="NÁZOV KATEGÓRIE"
                    />
                )}
            </div>
        </div>
      </div>

      {/* Right Content - Table & Actions */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Category Toolbar - Hide most actions if ReadOnly */}
        <div className={`bg-white p-1 flex justify-end gap-2 border-b border-gray-100 print:hidden ${readOnly ? 'bg-gray-50' : ''}`}>

           {/* Move Buttons */}
           {!readOnly && onMoveCategory && (
                <div className="flex gap-1 mr-auto border-r pr-2 border-gray-200">
                     <button onClick={() => onMoveCategory(category.id, 'up')} className="p-0.5 hover:bg-gray-100 rounded text-gray-500" title="Posunúť hore"><ChevronUp size={14}/></button>
                     <button onClick={() => onMoveCategory(category.id, 'down')} className="p-0.5 hover:bg-gray-100 rounded text-gray-500" title="Posunúť dole"><ChevronDown size={14}/></button>
                </div>
           )}

           {category.section === 'shaft' && (
               <span className="mr-auto text-[10px] font-bold text-blue-600 uppercase tracking-wider bg-blue-50 px-1.5 py-0.5 rounded border border-blue-100 flex items-center gap-1">
                   <Box size={10}/> Šachta
               </span>
           )}

            {!readOnly && (
                <>
                    {/* HIDE FROM PRINT (But Calculate) */}
                    <button
                        onClick={togglePrintVisibility}
                        className={`flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-medium rounded transition ${isHiddenFromPrint ? 'bg-red-100 text-red-600 border border-red-200' : 'text-gray-400 hover:bg-gray-100 hover:text-black'}`}
                        title={isHiddenFromPrint ? "Položka sa TLAČÍ (Zahrnutá v cene)" : "Skryť pri tlači (ALE POČÍTAŤ CENU)"}
                    >
                         <div className="relative">
                            <Printer size={14} />
                            {isHiddenFromPrint && <div className="absolute inset-0 flex items-center justify-center"><div className="w-full h-0.5 bg-red-600 rotate-45 transform"></div></div>}
                         </div>
                    </button>

                    {/* HIDE COMPLETELY (Exclude) */}
                    <button
                        onClick={toggleVisibility}
                        className={`flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-medium rounded transition ${isHidden ? 'bg-gray-300 text-gray-700' : 'text-gray-400 hover:bg-gray-100 hover:text-black'}`}
                        title={isHidden ? "Zobraziť (Zahrnúť do ceny)" : "Skryť ÚPLNE (Vyradiť z ceny)"}
                    >
                        {isHidden ? <EyeOff size={14} /> : <Eye size={14} />}
                    </button>

                    <div className="w-px bg-gray-200 mx-1"></div>

                    <button
                        onClick={toggleRichText}
                        className={`flex items-center gap-1 px-2 py-0.5 text-[10px] font-medium rounded transition ${showRichText ? 'bg-blue-50 text-blue-700' : 'text-gray-500 hover:bg-gray-100'}`}
                        title="Pridať textový popis"
                    >
                        <FileText size={12} />
                        {showRichText ? 'Text' : 'Text'}
                    </button>

                    <button
                        onClick={() => onDeleteCategory(category.id)}
                        className="text-gray-300 hover:text-red-600 transition p-0.5"
                        title="Odstrániť kategóriu"
                    >
                        <Trash2 size={14} />
                    </button>
                </>
            )}
            {readOnly && (
                 <span className="text-[10px] text-gray-400 font-medium uppercase tracking-wider flex items-center gap-1">
                     <FileText size={10}/> Príloha
                 </span>
            )}
        </div>

        {/* 1. Items Table - COMPACT DESIGN */}
        {category.items.length > 0 && (
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-xs text-left">
            <thead className="bg-gray-50 text-gray-500 border-b border-gray-200">
              <tr className="text-[10px] uppercase tracking-wider">
                {!readOnly && <th className="px-1 py-1 w-4 no-print"></th>}
                <th className="px-2 py-1 w-6 no-print align-top font-medium">#</th>
                <th className="px-2 py-1 align-top w-auto font-medium">Popis položky</th>
                <th className="px-1 py-1 w-12 text-right align-top font-medium">M.J.</th>
                <th className="px-1 py-1 w-12 text-right align-top font-medium">Mn.</th>

                {/* Price Column */}
                <th className={`px-2 py-1 w-20 text-right align-top font-medium price-column-strict ${hidePrices ? '' : ''}`}>
                    <span className={`print:hidden ${readOnly ? 'text-black' : 'text-blue-600'}`}>
                        {readOnly ? 'Cena' : 'Nákup'}
                    </span>
                    <span className="hidden print:inline">Cena</span>
                </th>

                {!readOnly && <th className="px-1 py-1 w-10 no-print align-top"></th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 print:divide-gray-100">
              {category.items.map((item, index) => {
                const sellingPrice = getSellingPrice(item.unitPrice);
                return (
                <tr 
                    key={item.id} 
                    className={`group transition-colors print:hover:bg-transparent ${item.isSurcharge ? 'bg-gray-50/50' : 'hover:bg-gray-50'}`}
                    draggable={!readOnly}
                    onDragStart={(e) => onDragStartItem(e, item.id)}
                    onDragOver={(e) => onDragOverItem(e, item.id)}
                    onDragEnd={onDragEndItem}
                >
                  {!readOnly && (
                      <td className="px-1 py-1 text-center no-print text-gray-300 cursor-grab hover:text-gray-500 align-top pt-1.5">
                          <GripVertical size={12}/>
                      </td>
                  )}
                  <td className="px-2 py-1 text-gray-400 no-print align-top text-[10px] pt-1.5">{index + 1}</td>
                  <td className="px-2 py-0.5 align-top relative">
                    {readOnly ? (
                        <div className={`text-gray-900 whitespace-pre-wrap leading-tight py-1 ${item.isSurcharge ? 'pl-4 italic text-gray-600 text-[11px]' : 'text-xs'}`}>
                            {item.isSurcharge && <span className="absolute left-0 top-1.5 text-gray-400 text-[10px]">•</span>}
                            {item.description}
                        </div>
                    ) : (
                        <div className={`flex gap-1 py-0.5 ${item.isSurcharge ? 'pl-4' : ''}`}>
                             {item.isSurcharge && <span className="absolute left-1 top-2 text-gray-400 text-[10px]">•</span>}
                             <textarea
                                rows={1}
                                value={item.description}
                                onChange={(e) => {
                                    onUpdateItem(category.id, item.id, 'description', e.target.value);
                                    e.target.style.height = 'auto';
                                    e.target.style.height = e.target.scrollHeight + 'px';
                                }}
                                onInput={(e) => {
                                    const target = e.target as HTMLTextAreaElement;
                                    target.style.height = 'auto';
                                    target.style.height = target.scrollHeight + 'px';
                                }}
                                onFocus={(e) => {
                                    e.target.style.height = 'auto';
                                    e.target.style.height = e.target.scrollHeight + 'px';
                                }}
                                className={`w-full bg-transparent focus:outline-none focus:text-black resize-none text-xs placeholder-gray-300 print:text-black leading-normal overflow-hidden py-0.5 ${item.isSurcharge ? 'italic text-gray-600' : 'text-gray-800 font-medium'}`}
                                placeholder="Názov položky..."
                                style={{ minHeight: '1.25rem' }}
                            />
                            {/* In-row Catalog Button */}
                            <button
                                onClick={() => onOpenCatalog(category.id, item.id)}
                                className="no-print self-start p-1 text-blue-300 hover:text-blue-600 rounded transition opacity-0 group-hover:opacity-100 focus:opacity-100 mt-0.5"
                                title="Vybrať variant z katalógu"
                            >
                                <BookOpen size={12} />
                            </button>
                        </div>
                    )}
                  </td>
                  <td className="px-1 py-0.5 align-top text-right pt-1.5">
                    {readOnly ? (
                        <span className="text-gray-600 text-[11px]">{item.unit}</span>
                    ) : (
                        <select
                            value={item.unit}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'unit', e.target.value)}
                            className="w-full text-right bg-transparent text-gray-500 border-none rounded px-0 py-0 focus:outline-none focus:text-black appearance-none print:bg-transparent print:text-black text-[11px] cursor-pointer hover:bg-gray-100"
                        >
                            <option value="ks">ks</option>
                            <option value="m">m</option>
                            <option value="hod">hod</option>
                            <option value="kpl">kpl</option>
                            <option value="set">set</option>
                        </select>
                    )}
                  </td>
                  <td className="px-1 py-0.5 align-top text-right pt-1.5">
                    {readOnly ? (
                        <span className="text-gray-900 font-bold text-xs">{item.quantity}</span>
                    ) : (
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={item.quantity}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'quantity', parseFloat(e.target.value) || 0)}
                            className="w-full text-right bg-transparent text-gray-900 font-bold focus:outline-none print:text-black text-xs p-0 hover:bg-gray-100 rounded"
                        />
                    )}
                  </td>

                  {/* Price Column */}
                  <td className="px-2 py-0.5 align-top text-right price-column-strict pt-1.5">
                    {readOnly ? (
                        <span className="text-xs font-medium text-black block">
                            {formatNumber(sellingPrice)}
                        </span>
                    ) : (
                        <>
                            {/* EDIT MODE: Input for Cost */}
                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={item.unitPrice}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                                className={`w-full text-right bg-transparent font-medium focus:outline-none text-xs print:hidden cursor-text p-0 hover:bg-blue-50 rounded ${hidePrices ? 'text-gray-400' : 'text-blue-600'}`}
                                placeholder="0.00"
                                title="Nákupná cena"
                            />
                            {/* PRINT MODE: Calculated Selling Price */}
                            <span className="hidden print:block text-xs font-medium text-black">
                                {formatNumber(sellingPrice)}
                            </span>
                        </>
                    )}
                  </td>

                  {/* Actions */}
                  {!readOnly && (
                    <td className="px-1 py-0.5 text-center no-print align-top flex justify-center gap-0.5 pt-1">
                        <button
                            onClick={() => onAddItem(category.id, true)}
                            className="text-gray-300 hover:text-blue-500 hover:bg-blue-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                            title="Pridať príplatok / pod-položku"
                        >
                            <Percent size={12} />
                        </button>
                        <button
                            onClick={() => onDeleteItem(category.id, item.id)}
                            className="text-gray-300 hover:text-red-500 hover:bg-red-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <Trash2 size={12} />
                        </button>
                    </td>
                  )}
                </tr>
              )})}
            </tbody>
          </table>
        </div>
        )}

          {!readOnly && (
            <div className="p-1 border-t border-gray-100 bg-white no-print flex gap-2 justify-center opacity-0 hover:opacity-100 transition-opacity">
                <button
                onClick={() => onAddItem(category.id)}
                className="flex items-center gap-1 text-[10px] font-bold text-gray-400 hover:text-blue-600 px-2 py-0.5 rounded hover:bg-blue-50 transition uppercase tracking-wide"
                >
                <Plus size={12} /> Pridať riadok
                </button>
            </div>
          )}

          {/* 2. Embedded Rich Text Area */}
          {(showRichText || (readOnly && category.textContent)) && (
            <div className="border-t border-gray-100 p-4 bg-white">
                <div className="mb-2 text-[10px] font-bold text-gray-400 uppercase tracking-wider print:hidden">Technická špecifikácia / Prílohy</div>
                <div
                    ref={editorRef}
                    contentEditable={!readOnly}
                    onInput={handleInput}
                    className={`rich-text-content w-full min-h-[60px] outline-none text-gray-900 text-xs leading-relaxed ${readOnly ? 'pointer-events-none' : ''}`}
                    dangerouslySetInnerHTML={{ __html: category.textContent || '' }}
                />
            </div>
          )}
      </div>
    </div>
  );
};

