      let liftSale = 0;

      let shaftCost = 0;
      let shaftSale = 0;

      data.categories.forEach(cat => {
          if (cat.isHidden) return; // Completely excluded

          const margin = cat.section === 'shaft' ? data.shaftMargin : data.globalMargin;

          cat.items.forEach(item => {
              const itemTotalCost = item.quantity * item.unitPrice; 
              // item.unitPrice IS the Purchase Cost entered in edit mode
              const itemTotalSale = itemTotalCost * (1 + margin / 100);

              if (cat.section === 'shaft') {
                  shaftCost += itemTotalCost;
                  shaftSale += itemTotalSale;
              } else {
                  liftCost += itemTotalCost;
                  liftSale += itemTotalSale;
              }
          });
      });

      totalPurchase = liftCost + shaftCost;
      totalSelling = liftSale + shaftSale;

      const vatRate = data.vatRate ?? 23; 

      return {
          totalPurchase,
          totalSelling,
          liftCost,
          liftSale,
          liftProfit: liftSale - liftCost,
          shaftCost,
          shaftSale,
          shaftProfit: shaftSale - shaftCost,
          vat: totalSelling * (vatRate / 100),
          gross: totalSelling * (1 + vatRate / 100)
      };
  };

