                        {/* COLORFUL MARGIN & VAT INPUTS (New Large Design) */}
                        <div className="no-print mb-6 bg-white p-4 rounded-xl border-2 border-blue-100 shadow-lg">
                            <div className="text-sm font-bold text-gray-800 uppercase tracking-wider text-center mb-3 border-b pb-2">Ekonomika projektu</div>

                            <div className="grid grid-cols-2 gap-6 mb-4">
                                {/* Lift Column */}
                                <div className="flex flex-col gap-2 p-3 bg-blue-50/50 rounded-lg border border-blue-200">
                                    <div className="text-xs font-bold text-blue-800 uppercase text-center border-b border-blue-200 pb-1">Výťah (Technológia)</div>
                                    <div className="flex justify-between text-xs text-gray-600">
                                        <span>Nákup:</span>
                                        <span className="font-mono font-bold">{totals.liftCost.toFixed(0)} €</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs font-bold w-12">Marža:</span>
                                        <div className="relative flex-1">
                                            <input 
                                                type="number" 
                                                value={data.globalMargin} 
                                                onChange={e => setData({...data, globalMargin: +e.target.value})}
                                                className="w-full text-center font-bold text-blue-800 bg-white border border-blue-300 rounded px-1 text-sm focus:ring-2 focus:ring-blue-400 outline-none h-8"
                                            />
                                            <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-blue-400 font-bold">%</span>
                                        </div>
                                    </div>
                                    <div className="flex justify-between items-center bg-blue-600 text-white p-2 rounded shadow-sm font-bold text-sm" title="Čistý zisk z výťahu">
                                        <span>Zisk:</span>
                                        <span>{totals.liftProfit.toFixed(2)} €</span>
                                    </div>
                                </div>

                                {/* Shaft Column */}
                                <div className="flex flex-col gap-2 p-3 bg-orange-50/50 rounded-lg border border-orange-200">
                                    <div className="text-xs font-bold text-orange-800 uppercase text-center border-b border-orange-200 pb-1">Šachta / Montáž</div>
                                    <div className="flex justify-between text-xs text-gray-600">
                                        <span>Nákup:</span>
                                        <span className="font-mono font-bold">{totals.shaftCost.toFixed(0)} €</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs font-bold w-12">Marža:</span>
                                        <div className="relative flex-1">
                                            <input 
                                                type="number" 
                                                value={data.shaftMargin} 
                                                onChange={e => setData({...data, shaftMargin: +e.target.value})}
                                                className="w-full text-center font-bold text-orange-800 bg-white border border-orange-300 rounded px-1 text-sm focus:ring-2 focus:ring-orange-400 outline-none h-8"
                                            />
                                            <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-orange-400 font-bold">%</span>
                                        </div>
                                    </div>
                                    <div className="flex justify-between items-center bg-orange-500 text-white p-2 rounded shadow-sm font-bold text-sm" title="Čistý zisk zo šachty">
                                        <span>Zisk:</span>
                                        <span>{totals.shaftProfit.toFixed(2)} €</span>
                                    </div>
                                </div>
                            </div>

                            {/* VAT Row */}
                            <div className="flex items-center gap-3 bg-purple-50 p-2 rounded border border-purple-100">
                                <label className="text-xs font-bold text-purple-700 uppercase shrink-0">Sadzba DPH:</label>
                                <div className="relative w-20">
                                    <input 
                                        type="number" 
                                        value={data.vatRate ?? 23} 
                                        onChange={e => setData({...data, vatRate: +e.target.value})}
                                        className="w-full text-center font-bold text-purple-800 bg-white border border-purple-200 rounded px-1 text-sm focus:ring-2 focus:ring-purple-400 outline-none h-7"
                                    />
                                    <span className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] text-purple-400 font-bold">%</span>
                                </div>
                                <div className="text-sm text-purple-600 font-bold ml-auto">
                                    {formatCurrency(totals.vat)}
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-between text-2xl font-bold text-gray-900 mb-1">
                            <span>Cena Celkom:</span>
                            <span>{formatCurrency(totals.totalSelling)}</span>
                        </div>
                        <div className="text-right text-xs text-gray-500 mb-2">bez DPH</div>

                        <div className="flex justify-between text-sm text-gray-600 pt-2 border-t border-gray-200">
                            <span>DPH ({data.vatRate ?? 23}%):</span>
                            <span>{formatCurrency(totals.vat)}</span>
                        </div>
                        <div className="flex justify-between text-lg font-bold text-black mt-2 bg-gray-100 p-2 rounded">
                            <span>Spolu s DPH:</span>
                            <span>{formatCurrency(totals.gross)}</span>
                        </div>
                    </div>
                </div>
            </>

            {/* Terms */}
            {!isContractMode && (
                <div className="mt-12 break-inside-avoid">
                    <h3 className="font-bold uppercase text-sm mb-2 text-gray-800">Obchodné podmienky & Záruka</h3>
                    <StandaloneRichTextEditor 
                        content={data.terms} 
                        onChange={val => setData({...data, terms: val})} 
                        className="min-h-[200px] print:min-h-0 print:h-auto" 
                        stickyToolbar={false} 
                        minimalPadding={true} 
                    />
