  const handleImportData = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              // Fix: Explicitly type the parsed JSON to avoiding 'unknown' errors
              // Added ( ... as any) to ensure JSON.parse doesn't return unknown in strict mode
              const imported = (JSON.parse(e.target?.result as string) as any) as {
                  products?: Product[];
                  clients?: Client[];
                  suppliers?: Supplier[];
                  templates?: QuoteTemplate[];
                  settings?: AppSettings;
                  savedQuotes?: QuoteData[];
                  contractTemplates?: ContractTemplate[];
                  customCategories?: string[];
                  cabinClasses?: CabinClass[];
                  data?: QuoteData;
              };

              if (imported.products) setProducts(imported.products);
              if (imported.clients) setClients(imported.clients);
              if (imported.suppliers) setSuppliers(imported.suppliers);
              if (imported.templates) setTemplates(imported.templates);
              if (imported.settings) setSettings(imported.settings);
              if (imported.savedQuotes) setSavedQuotes(imported.savedQuotes);
              if (imported.contractTemplates) setContractTemplates(imported.contractTemplates);

              // MERGE Categories
              if (imported.customCategories && Array.isArray(imported.customCategories)) {
                  const importedCats = imported.customCategories;
                  // Use Array.from(new Set(...)) to ensure type safety and uniqueness
                  const mergedCats = Array.from(new Set<string>([...DEFAULT_CATEGORIES, ...importedCats]));
                  setAvailableCategories(mergedCats);
              } else if (imported.products && Array.isArray(imported.products)) {
                  // Fallback if no categories property in file
                  // STRICT TYPE CAST to Product[] to avoid 'unknown' errors
                  const productsList = imported.products as Product[];
                  const prodCats = productsList.map((p) => p.category);
                  const mergedCats = Array.from(new Set<string>([...DEFAULT_CATEGORIES, ...prodCats]));
                  setAvailableCategories(mergedCats);
              }

              if (imported.cabinClasses) setCabinClasses(imported.cabinClasses);
              if (imported.data) setData(imported.data);
              alert("Dáta boli úspešne obnovené.");
          } catch (err) { 
              console.error(err);
              alert("Chyba pri importe súboru.");
          }
      };
      reader.readAsText(file);
  };

  const handleImportCatalog = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const importedProducts = (JSON.parse(e.target?.result as string) as any) as Product[];
              if (Array.isArray(importedProducts)) {
                  // Merge strategy: Overwrite by ID, append new
                  const newProductMap = new Map(products.map(p => [p.id, p]));
                  importedProducts.forEach(p => newProductMap.set(p.id, p));
                  const finalProducts = Array.from(newProductMap.values());

                  setProducts(finalProducts);

                  // SYNC CATEGORIES: Ensure all categories in imported products exist in availableCategories
                  const newCats = new Set(availableCategories);
                  finalProducts.forEach(p => newCats.add(p.category));
                  setAvailableCategories(Array.from(newCats));

                  alert(`Katalóg úspešne aktualizovaný (${importedProducts.length} produktov).`);
              } else {
                  alert("Chybný formát súboru.");
              }
          } catch (err) {
              console.error(err);
              alert("Chyba pri čítaní súboru.");
          }
      };
      reader.readAsText(file);
  };

