import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, ClipboardList, AlertTriangle, Box, Gauge, Zap, Ruler, ArrowRightFromLine, Settings, ShieldCheck, PaintBucket, Move } from 'lucide-react';
import { LiftLayoutSketch } from './LiftLayoutSketch';

interface TechSpecTableProps {
  data: LiftLayoutData;
  isVisible: boolean;
  onToggleVisibility: () => void;
  embedded?: boolean;
}

export const TechSpecTable: React.FC<TechSpecTableProps> = ({
  data,
  isVisible,
  onToggleVisibility,
  embedded = false
}) => {

  const getLiftTypeLabel = (val: string) => {
      const map: Record<string, string> = { 
          'passenger': 'Osobný', 
          'freight': 'Nákladný', 
          'home': 'Domáci', 
          'hospital': 'Lôžkový',
          'invalid': 'Invalid (EN81-70)'
      };
      return map[val] || val;
  };
  const getDriveLabel = (val: string) => {
      const map: Record<string, string> = { 'traction': 'Trakčný', 'hydraulic': 'Hydraulický', 'mrl': 'MRL (Bez strojovne)', 'drum': 'Bubnový' };
      return map[val] || val;
  };
  const getDoorLabel = (val?: string) => {
      const map: Record<string, string> = { 'central': 'Automat Centrál', 'telescopic': 'Automat Teleskop', 'bus': 'Ručné + BUS' };
      return map[val || 'central'] || val;
  };

  // EN 81-21 & EN 81-70 Logic Check
  const getSafetyMeasures = () => {
      const measures = [];
      if (data.pitDepth < 1100 || data.headroomHeight < 3400) {
          measures.push("Riešenie priehlbeň/hlava: ELGO LIMAX 33 CP (EN 81-21)");
      }
      if (data.liftType === 'invalid') {
          measures.push("Výbava invalid: Zrkadlo, Madlo, Hlas, Braille (EN 81-70)");
      }
      return measures;
  };

  const safetyMeasures = getSafetyMeasures();
  const stationCount = data.stationLabels ? data.stationLabels.split(',').length : 0;

  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border border-dashed border-gray-300 rounded-xl bg-gray-50 text-gray-400 flex justify-between items-center hover:bg-gray-100 transition cursor-pointer" onClick={onToggleVisibility}>
              <span className="flex items-center gap-2 font-medium"><ClipboardList size={18}/> Technická špecifikácia je skrytá</span>
              <Eye size={20}/>
          </div>
      );
  }

  // Helper for Data Rows
  const DataRow = ({ icon: Icon, label, value, subValue }: any) => (
      <div className="flex items-center justify-between p-1.5 border-b border-gray-100 last:border-0 hover:bg-blue-50/50 transition h-8">
          <div className="flex items-center gap-2 overflow-hidden">
              <Icon size={12} className="text-gray-400 shrink-0"/>
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tight truncate">{label}</span>
          </div>
          <div className="text-right">
              <div className="text-[11px] font-bold text-gray-900 leading-none">{value}</div>
              {subValue && <div className="text-[9px] text-gray-400 leading-none">{subValue}</div>}
          </div>
      </div>
  );

  const Content = (
      <div className="bg-white flex flex-col h-full">
          {/* Header */}
          <div className="px-4 py-2 border-b border-gray-200 bg-gray-50 flex justify-between items-center">
              <div className="flex items-center gap-2">
                  <div className="bg-blue-600 text-white p-1 rounded">
                      <ClipboardList size={14} />
                  </div>
                  <h3 className="text-sm font-bold text-gray-800 uppercase tracking-wide">Technické Parametre Zariadenia</h3>
              </div>
              {!embedded && (
                  <button onClick={onToggleVisibility} className="text-gray-400 hover:text-blue-600 transition no-print">
                      <Eye size={16} />
                  </button>
              )}
          </div>

          <div className="flex flex-col md:flex-row divide-y md:divide-y-0 md:divide-x divide-gray-200">

              {/* LEFT COLUMN: DATA GRID */}
              <div className="flex-1 p-0">
                  <div className="grid grid-cols-2 divide-x divide-gray-100">

                      {/* Column A */}
                      <div className="p-2">
                          <DataRow icon={Box} label="Typ Zariadenia" value={getLiftTypeLabel(data.liftType)} />
                          <DataRow icon={Gauge} label="Nosnosť / Osoby" value={`${data.ratedLoad} kg`} subValue={`${data.numberOfPersons} osôb`} />
                          <DataRow icon={Zap} label="Rýchlosť / Pohon" value={`${data.ratedSpeed} m/s`} subValue={getDriveLabel(data.driveType)} />
                          <DataRow icon={Ruler} label="Zdvih / Stanice" value={`${data.travelHeight} mm`} subValue={`${stationCount} staníc`} />
                          <DataRow icon={Settings} label="Napájanie" value={data.powerSupply} />
                          <DataRow icon={Move} label="Lanovanie / Médium" value={data.suspensionType} subValue={data.tractionMedium === 'belts' ? 'Pásy' : 'Laná'} />
                          <DataRow icon={Box} label="Strojovňa / CWT" value={data.machineRoomPosition === 'head' ? 'MRL (V šachte)' : 'Hore'} subValue={`Protiváha: ${data.counterWeightPosition}`} />
                      </div>

                      {/* Column B */}
                      <div className="p-2">
                          <DataRow icon={ArrowRightFromLine} label="Šachta (Š x H)" value={`${data.shaftWidth} x ${data.shaftDepth}`} subValue="mm (vnútorný rozmer)" />
                          <DataRow icon={ArrowRightFromLine} label="Hlava / Priehlbeň" value={`${data.headroomHeight} / ${data.pitDepth}`} subValue="mm" />
                          <DataRow icon={Box} label="Kabína (Š x H)" value={`${Math.round(data.cabinWidth)} x ${Math.round(data.cabinDepth)}`} subValue={`mm (${data.cabinClass || 'Standard'})`} />
                          <DataRow icon={ArrowRightFromLine} label="Dvere (Šírka PL)" value={`${data.doorWidth} mm`} subValue={`DO: ${data.doorOpeningWidth} / VDO: ${data.doorOpeningHeight}`} />
                          <DataRow icon={Settings} label="Typ Dverí" value={getDoorLabel(data.doorType)} subValue={data.doorOperation === 'manual' ? 'Manuálne' : 'Automatické'} />
                          <DataRow icon={PaintBucket} label="Povrch / Odolnosť" value={data.doorFinish} subValue={`Požiarna: ${data.doorFireRating}`} />
                          <DataRow icon={ShieldCheck} label="Vodidlá" value={`Kab: ${data.guideTypeCar}`} subValue={`CWT: ${data.guideTypeCwt}`} />
                      </div>
                  </div>

                  {/* Safety / Notes Footer */}
                  {(safetyMeasures.length > 0 || data.notes) && (
                      <div className="bg-yellow-50 p-2 border-t border-yellow-100 text-[10px] text-yellow-800">
                          {safetyMeasures.map((m, i) => (
                              <div key={i} className="flex items-center gap-1 font-bold">
                                  <AlertTriangle size={10} className="text-yellow-600"/> {m}
                              </div>
                          ))}
                          {data.notes && <div className="mt-1 italic text-gray-600 border-t border-yellow-200 pt-1">{data.notes}</div>}
                      </div>
                  )}
              </div>

              {/* RIGHT COLUMN: SKETCH INTEGRATION */}
              <div className="w-full md:w-[35%] bg-gray-50/50 flex flex-col items-center justify-center p-2 relative min-h-[250px]">
                  <div className="absolute top-2 right-2 text-[9px] font-bold text-gray-300 uppercase tracking-widest pointer-events-none">Dispozičný Náčrt</div>
                  {/* Reuse the existing sketch component but scale it to fit */}
                  <div className="scale-90 origin-center w-full h-full flex items-center justify-center">
                      <LiftLayoutSketch data={data} isVisible={true} />
                  </div>
              </div>
          </div>
      </div>
  );

  if (embedded) return <div className="h-full border rounded-xl overflow-hidden shadow-sm">{Content}</div>;

  return (
    <div className="mb-8 break-inside-avoid shadow-lg rounded-xl overflow-hidden border border-gray-200 transition-all hover:shadow-xl bg-white">
        {Content}
    </div>
  );
};

