  const handleLayoutChange = (field: keyof LiftLayoutData, value: any) => {
      setData(prev => {
          const newData = {
              ...prev,
              layout: { ...prev.layout!, [field]: value }
          };

          // --- TRIAD AUTOMATION LOGIC ---
          // Update dependent fields directly in the new state object
          if (field === 'machineRoomPosition') {
              if (value === 'above') {
                  newData.layout.suspensionType = '1:1';
                  newData.layout.bracketType = 'standard';
              } else if (value === 'head') {
                  // MRL -> 2:1 -> Combined Logic forced
                  newData.layout.suspensionType = '2:1';
                  newData.layout.bracketType = 'combined';
              }
          }
          else if (field === 'suspensionType') {
              if (value === '1:1') {
                  newData.layout.machineRoomPosition = 'above';
                  newData.layout.bracketType = 'standard';
              } else if (value === '2:1') {
                  newData.layout.machineRoomPosition = 'head';
                  newData.layout.bracketType = 'combined';
              }
          }
          // -----------------------------

          // --- AUTO CALCULATION FOR LDO/RDO (SHAFT - DO) ---
          // Rule: Shaft = LDO + DO + RDO
          // If Shaft or DO changes, Recalculate LDO and RDO (Centered)
          if (field === 'shaftWidth' || field === 'doorOpeningWidth') {
              const sw = field === 'shaftWidth' ? value : prev.layout?.shaftWidth || 0;
              const doW = field === 'doorOpeningWidth' ? value : prev.layout?.doorOpeningWidth || 0;

              if (sw > 0 && doW > 0 && sw > doW) {
                  const remainder = sw - doW;
                  const half = Math.floor(remainder / 2);
                  newData.layout.LDO = half;
                  newData.layout.RDO = remainder - half; // Handle odd numbers
              }
          }
          // If LDO changes, Recalculate RDO
          else if (field === 'LDO') {
              const sw = prev.layout?.shaftWidth || 0;
              const doW = prev.layout?.doorOpeningWidth || 0;
              const newLDO = value;
              if (sw > 0 && doW > 0) {
                  newData.layout.RDO = Math.max(0, sw - doW - newLDO);
              }
          }
          // If RDO changes, Recalculate LDO
          else if (field === 'RDO') {
              const sw = prev.layout?.shaftWidth || 0;
              const doW = prev.layout?.doorOpeningWidth || 0;
              const newRDO = value;
              if (sw > 0 && doW > 0) {
                  newData.layout.LDO = Math.max(0, sw - doW - newRDO);
              }
