// --- EN 81-20 HELPER ---
const calculateEn8120 = (width: number, depth: number) => {
    // EN 81-20 Table 6 (Simplified) - Max Area for Rated Load
    // EN 81-20 Table 7 (Simplified) - Max Persons for Area (Or min area for persons)

    const area = (width * depth) / 1000000;

    // Rough interpolation logic for Passenger Lifts (Table 6)
    // Area -> Rated Load (Mass)
    let suggestedLoad = 0;
    if (area <= 0.37) suggestedLoad = 100;
    else if (area <= 0.50) suggestedLoad = 180;
    else if (area <= 0.70) suggestedLoad = 300; // 4 pers
    else if (area <= 0.90) suggestedLoad = 375; // 5 pers
    else if (area <= 1.17) suggestedLoad = 450; // 6 pers
    else if (area <= 1.30) suggestedLoad = 525; // 7 pers
    else if (area <= 1.45) suggestedLoad = 600; // 8 pers
    else if (area <= 1.60) suggestedLoad = 630; // 8 pers (standard)
    else if (area <= 1.66) suggestedLoad = 675; // 9 pers
    else if (area <= 2.00) suggestedLoad = 800; // 10 pers
    else if (area <= 2.35) suggestedLoad = 1000; // 13 pers
    else suggestedLoad = Math.floor(area / 0.16) * 100; // rough approx for big lifts

    // Persons (Table 7 - Min Area / Max Persons)
    let persons = 0;
    if (suggestedLoad < 450) persons = Math.floor(suggestedLoad / 75); // rough
    else if (suggestedLoad >= 450 && suggestedLoad < 630) persons = 6;
    else if (suggestedLoad >= 630 && suggestedLoad < 800) persons = 8;
    else if (suggestedLoad >= 800 && suggestedLoad < 1000) persons = 10;
    else if (suggestedLoad >= 1000) persons = 13;
    else persons = Math.floor(suggestedLoad / 75);

    return { area, suggestedLoad, persons };
};

