  const DataRow = ({ label, value, subValue, highlight = false }: any) => (
      <div className={`flex items-center justify-between px-4 py-2.5 border-b border-gray-200 last:border-0 ${highlight ? 'bg-gray-50' : ''}`}>
          <div className="flex flex-col justify-center">
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{label}</span>
          </div>
          <div className="text-right">
              <div className="text-sm font-bold text-gray-900">{value}</div>
              {subValue && <div className="text-[10px] text-gray-500 font-medium">{subValue}</div>}
          </div>
      </div>
  );

  const Content = (
      <div className="bg-white flex flex-col md:flex-row h-full">

          {/* LEFT COLUMN: SPECS */}
          <div className="flex-1 flex flex-col border-r border-gray-300">
              {/* Header */}
              <div className="px-4 py-3 border-b-2 border-gray-800 bg-gray-100 flex justify-between items-center">
                  <div className="flex items-center gap-2">
                      <div className="bg-gray-800 text-white p-1 rounded">
                          <Settings size={14} />
                      </div>
                      <h3 className="text-sm font-bold text-gray-800 uppercase tracking-widest">Technické Parametre</h3>
                  </div>
                  {!embedded && (
                      <button onClick={onToggleVisibility} className="text-gray-400 hover:text-blue-600 transition no-print">
                          <Eye size={16} />
                      </button>
                  )}
              </div>

              {/* Data Grid - Single or Dual Column within Left Panel */}
              <div className="grid grid-cols-2 divide-x divide-gray-200 flex-1">

                  {/* Sub-Column 1 */}
                  <div className="flex flex-col">
                      <DataRow label="Typ Zariadenia" value={getLiftTypeLabel(data.liftType)} highlight />
                      <DataRow label="Nosnosť / Osoby" value={`${data.ratedLoad} kg`} subValue={`${data.numberOfPersons} osôb`} />
                      <DataRow label="Rýchlosť" value={`${data.ratedSpeed} m/s`} subValue={getDriveLabel(data.driveType)} highlight />
                      <DataRow label="Zdvih / Stanice" value={`${data.travelHeight} mm`} subValue={`${stationCount} staníc`} />
                      <DataRow label="Strojovňa" value={data.machineRoomPosition === 'head' ? 'MRL (V šachte)' : 'Hore'} subValue={data.powerSupply} highlight />
                      <DataRow label="Lanovanie" value={data.suspensionType} subValue={data.tractionMedium === 'belts' ? 'Pásy' : 'Laná'} />
                  </div>

                  {/* Sub-Column 2 */}
                  <div className="flex flex-col">
                      <DataRow label="Šachta (Š x H)" value={`${data.shaftWidth} x ${data.shaftDepth}`} subValue="mm (vnútorný rozmer)" highlight />
                      <DataRow label="Hlava / Priehlbeň" value={`${data.headroomHeight} / ${data.pitDepth}`} subValue="mm" />
                      <DataRow label="Kabína (Š x H)" value={`${Math.round(data.cabinWidth)} x ${Math.round(data.cabinDepth)}`} subValue={`Trieda: ${data.cabinClass || 'Standard'}`} highlight />
                      <DataRow label="Dvere (Šírka PL)" value={`${data.doorWidth} mm`} subValue={`DO: ${data.doorOpeningWidth} / VDO: ${data.doorOpeningHeight}`} />
                      <DataRow label="Typ Dverí" value={getDoorLabel(data.doorType)} subValue={`${data.doorFinish} (${data.doorFireRating})`} highlight />
                      <DataRow label="Vodidlá" value={`K: ${data.guideTypeCar}`} subValue={`Protiváha: ${data.guideTypeCwt}`} />
                  </div>
              </div>

              {/* Footer (Notes/Safety) - Always at bottom */}
