                              <div key={i} className="flex items-center gap-2 text-[10px] font-bold text-red-700 uppercase">
                                  <AlertTriangle size={12} className="shrink-0"/> {m}
                              </div>
                          ))}
                      </div>
                  ) : (
                      <div className="text-[10px] text-gray-400 uppercase font-bold flex items-center gap-2">
                          <ShieldCheck size={12}/> Bezpečnostné prvky podľa STN EN 81-20/50
                      </div>
                  )}
                  {data.notes && <div className="mt-2 text-[10px] italic text-gray-600 border-t border-gray-200 pt-1 leading-tight">{data.notes}</div>}
              </div>
          </div>

          {/* RIGHT COLUMN: SKETCH - Maximized */}
          <div className="w-full md:w-[38%] bg-white flex flex-col relative overflow-hidden print:border-l print:border-gray-300">
              <div className="absolute top-0 left-0 bg-gray-800 text-white text-[9px] font-bold uppercase px-2 py-1 z-10 rounded-br">
                  Dispozičný Náčrt
              </div>

              {/* Sketch Container - Flex grow to fill height */}
              <div className="flex-1 flex items-center justify-center p-0 min-h-[300px]">
                  <LiftLayoutSketch data={data} isVisible={true} />
              </div>

              {/* Bottom aligned label for consistency */}
              <div className="bg-gray-100 text-center py-1 border-t border-gray-200 text-[9px] text-gray-500 font-mono uppercase">
                  Pôdorys šachty (Top View)
              </div>
          </div>
      </div>
  );

  if (embedded) return <div className="h-full border-2 border-gray-800 rounded-lg overflow-hidden shadow-sm">{Content}</div>;

  return (
    <div className="mb-8 break-inside-avoid border-2 border-gray-800 rounded-lg overflow-hidden shadow-md bg-white">
        {Content}
    </div>
  );
};

import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, EyeOff, PenTool } from 'lucide-react';

interface LiftLayoutSketchProps {
  data: LiftLayoutData;
  onChange?: (field: keyof LiftLayoutData, value: any) => void;
  isVisible?: boolean;
  onToggleVisibility?: () => void;
}

// Helper Components
const GuideT: React.FC<{x:number, y:number, rotation:number, color?:string}> = ({ x, y, rotation, color = "#000" }) => (
    <g transform={`translate(${x}, ${y}) rotate(${rotation})`}>
        <rect x="-8" y="-2" width="16" height="4" fill={color} />
        <rect x="-2" y="-2" width="4" height="12" fill={color} />
    </g>
);

const DimLine = ({ x1, y1, x2, y2, text, offset = 30, color = "#000", fontSize = 12, isInside = false }: any) => {
    const dx = x2 - x1; const dy = y2 - y1; const len = Math.sqrt(dx*dx + dy*dy);
    if(len === 0) return null;
    const ux = -dy / len; const uy = dx / len;
    const nx1 = x1 + ux * offset; const ny1 = y1 + uy * offset;
    const nx2 = x2 + ux * offset; const ny2 = y2 + uy * offset;
    const mx = (nx1 + nx2) / 2; const my = (ny1 + ny2) / 2;
    return (
      <g>
        <line x1={x1} y1={y1} x2={nx1} y2={ny1} stroke={color} strokeWidth="0.5" opacity="0.3" />
        <line x1={x2} y1={y2} x2={nx2} y2={ny2} stroke={color} strokeWidth="0.5" opacity="0.3" />
        <line x1={nx1} y1={ny1} x2={nx2} y2={ny2} stroke={color} strokeWidth="1" />
        <circle cx={nx1} cy={ny1} r={2} fill={color} />
        <circle cx={nx2} cy={ny2} r={2} fill={color} />
        {!isInside && <rect x={mx - (String(text).length * 3.5)} y={my - 7} width={String(text).length * 7} height={14} fill="white" fillOpacity="0.8" rx={2} />}
        <text x={mx} y={my} dy={4} textAnchor="middle" fill={color} fontSize={fontSize} fontWeight="bold">{text}</text>
      </g>
    );
};

export const LiftLayoutSketch: React.FC<LiftLayoutSketchProps> = ({ 
  data,
  onChange,
  isVisible = true,
  onToggleVisibility
}) => {
  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border border-dashed border-gray-300 rounded bg-gray-50 text-gray-400 flex justify-between items-center w-full">
              <div className="flex items-center gap-2">
                 <PenTool size={18}/>
                 <span className="text-sm font-bold uppercase">Nákres (Skrytý)</span>
              </div>
              {onToggleVisibility && <button onClick={onToggleVisibility} className="hover:text-blue-600"><Eye size={20}/></button>}
          </div>
      );
  }

  // Visual Config
  const svgSize = 420; const center = svgSize / 2;
  const VISUAL_SHAFT_SIZE = 300;
  const VISUAL_CABIN_WIDTH = 180;
  const VISUAL_CABIN_DEPTH = 200;

  // --- ASYMMETRY CALCULATION (LDO/RDO) ---
  let horizontalShift = 0;
  if (data.LDO !== undefined && data.doorOpeningWidth && data.shaftWidth > 0) {
      const realShaftCenter = data.shaftWidth / 2;
      const realCabinCenter = data.LDO + (data.doorOpeningWidth / 2);
      const shiftMm = realCabinCenter - realShaftCenter;
      const scale = VISUAL_SHAFT_SIZE / data.shaftWidth;
      horizontalShift = shiftMm * scale;

      const maxShift = (VISUAL_SHAFT_SIZE - VISUAL_CABIN_WIDTH) / 2 - 10;
      if (horizontalShift > maxShift) horizontalShift = maxShift;
      if (horizontalShift < -maxShift) horizontalShift = -maxShift;
  }

  const shaftX = center - (VISUAL_SHAFT_SIZE / 2); 
  const shaftY = center - (VISUAL_SHAFT_SIZE / 2);
  const cabinX = center - (VISUAL_CABIN_WIDTH / 2) + horizontalShift; 
  const cabinY = center - (VISUAL_CABIN_DEPTH / 2);
  const activeCenter = center + horizontalShift;

  const inputCwtW = (data.cwtWidth || 120) / 6; const inputCwtL = (data.cwtDepth || 650) / 6;
  let cwtX = 0, cwtY = 0, cwtW = 0, cwtH = 0;
  if (data.counterWeightPosition === 'back') { cwtW = inputCwtL; cwtH = inputCwtW; cwtX = center - (cwtW / 2); cwtY = shaftY + 15; } 
  else if (data.counterWeightPosition === 'left') { cwtW = inputCwtW; cwtH = inputCwtL; cwtX = shaftX + 15; cwtY = center - (cwtH / 2); } 
  else if (data.counterWeightPosition === 'right') { cwtW = inputCwtW; cwtH = inputCwtL; cwtX = shaftX + VISUAL_SHAFT_SIZE - 15 - cwtW; cwtY = center - (cwtH / 2); }

  const renderDoorVisuals = (isRear: boolean) => {
      const yPosShaft = isRear ? shaftY : shaftY + VISUAL_SHAFT_SIZE;
      const yPosCabin = isRear ? cabinY : cabinY + VISUAL_CABIN_DEPTH;
      const mirror = isRear ? -1 : 1; const vDoorW = 140; 
      const doorStart = activeCenter - (vDoorW / 2);

      if (data.doorType === 'bus') {
          const folds = 4; const foldW = vDoorW / folds;
          let dPath = `M ${doorStart},${yPosCabin}`;
          for(let i=0; i<4; i++) dPath += ` L ${doorStart + (i*foldW) + (foldW/2)},${yPosCabin - (15 * mirror)} L ${doorStart + ((i+1)*foldW)},${yPosCabin}`;
          return [<path key={`bus-door-${isRear}`} d={dPath} fill="none" stroke="#0284c7" strokeWidth="2" />];
      } else {
          const arrowY = yPosShaft + (10 * mirror);
          return [<g key={`central-${isRear}`} transform={`translate(${activeCenter}, ${arrowY})`}>
                   <line x1={2} y1={0} x2={20} y2={0} stroke="#666" strokeWidth="1" /><line x1={-2} y1={0} x2={-20} y2={0} stroke="#666" strokeWidth="1" />
                   <rect x={-70} y={isRear ? 0 : -5} width={10} height={5} fill="#666"/><rect x={60} y={isRear ? 0 : -5} width={10} height={5} fill="#666"/>
               </g>];
      }
  };

  const renderRails = () => {
      const els = [];
      if (data.frameType === 'backpack') {
          let railWall = data.counterWeightPosition; 
          if (railWall === 'back') {
              els.push(<GuideT key="cr1" x={activeCenter - 60} y={cabinY} rotation={0} />);
              els.push(<GuideT key="cr2" x={activeCenter + 60} y={cabinY} rotation={0} />);
          } else if (railWall === 'left') {
              els.push(<GuideT key="cr1" x={cabinX} y={center - 60} rotation={90} />);
              els.push(<GuideT key="cr2" x={cabinX} y={center + 60} rotation={90} />);
          } else if (railWall === 'right') {
              els.push(<GuideT key="cr1" x={cabinX + VISUAL_CABIN_WIDTH} y={center - 60} rotation={270} />);
              els.push(<GuideT key="cr2" x={cabinX + VISUAL_CABIN_WIDTH} y={center + 60} rotation={270} />);
          }
      } else {
          els.push(<GuideT key="cr1" x={cabinX} y={center} rotation={90} />);
          els.push(<GuideT key="cr2" x={cabinX + VISUAL_CABIN_WIDTH} y={center} rotation={270} />);
      }

      if (data.counterWeightPosition === 'back') {
          els.push(<GuideT key="cwt1" x={cwtX} y={cwtY + cwtH/2} rotation={90} color="#666"/>);
          els.push(<GuideT key="cwt2" x={cwtX + cwtW} y={cwtY + cwtH/2} rotation={270} color="#666"/>);
      } else {
          els.push(<GuideT key="cwt1" x={cwtX + cwtW/2} y={cwtY} rotation={180} color="#666"/>);
          els.push(<GuideT key="cwt2" x={cwtX + cwtW/2} y={cwtY + cwtH} rotation={0} color="#666"/>);
      }
      return els;
  };

  return (
       <div className="w-full h-full flex flex-col items-center justify-center relative bg-gray-50">
            <div className="absolute top-2 right-2 z-10 no-print flex gap-2">
                {onToggleVisibility && <button onClick={onToggleVisibility} className="p-1 rounded text-gray-400 hover:text-black hover:bg-gray-100 bg-white/50"><EyeOff size={16} /></button>}
           </div>

           {/* SVG fills the container completely now */}
           <svg 
                viewBox={`0 0 ${svgSize} ${svgSize}`} 
                className="w-full h-full p-4" 
                preserveAspectRatio="xMidYMid meet"
           >
                <defs><pattern id="hatch" patternUnits="userSpaceOnUse" width="10" height="10" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="10" stroke="#000000" strokeWidth="1" opacity="0.1"/></pattern></defs>

                {/* Background & Shaft */}
                <rect x={shaftX} y={shaftY} width={VISUAL_SHAFT_SIZE} height={VISUAL_SHAFT_SIZE} fill="url(#hatch)" stroke="black" strokeWidth="4" />
                <rect x={shaftX-5} y={shaftY-5} width={VISUAL_SHAFT_SIZE+10} height={VISUAL_SHAFT_SIZE+10} fill="none" stroke="black" strokeWidth="0.5" />

                {horizontalShift !== 0 && (
                    <line x1={center} y1={shaftY} x2={center} y2={shaftY + VISUAL_SHAFT_SIZE} stroke="red" strokeWidth="0.5" strokeDasharray="4" opacity="0.5" />
                )}

                {/* Cabin & CWT */}
                <rect x={cabinX} y={cabinY} width={VISUAL_CABIN_WIDTH} height={VISUAL_CABIN_DEPTH} fill="#e0f2fe" stroke="#0284c7" strokeWidth="2" />
                <rect x={cwtX} y={cwtY} width={cwtW} height={cwtH} fill="#ef4444" stroke="#7f1d1d" strokeWidth="1" />

                {renderRails()}

                {/* Door Thresholds */}
                <line x1={shaftX + 60} y1={shaftY + VISUAL_SHAFT_SIZE} x2={shaftX + VISUAL_SHAFT_SIZE - 60} y2={shaftY + VISUAL_SHAFT_SIZE} stroke="white" strokeWidth={6} />
                <line x1={cabinX} y1={cabinY + VISUAL_CABIN_DEPTH} x2={cabinX + VISUAL_CABIN_WIDTH} y2={cabinY + VISUAL_CABIN_DEPTH} stroke="#0284c7" strokeWidth="3" />
                {renderDoorVisuals(false)}

                <text x={activeCenter} y={shaftY + VISUAL_SHAFT_SIZE + 25} textAnchor="middle" fontSize="16" fontWeight="bold" fill="#000">A</text>

                {data.isThroughCar && <><line x1={shaftX + 60} y1={shaftY} x2={shaftX + VISUAL_SHAFT_SIZE - 60} y2={shaftY} stroke="white" strokeWidth={6} /><line x1={cabinX} y1={cabinY} x2={cabinX + VISUAL_CABIN_WIDTH} y2={cabinY} stroke="#0284c7" strokeWidth="3" />{renderDoorVisuals(true)}<text x={activeCenter} y={shaftY - 15} textAnchor="middle" fontSize="16" fontWeight="bold" fill="#000">B</text></>}

                {/* Dimensions */}
                <DimLine x1={shaftX} y1={shaftY} x2={shaftX+VISUAL_SHAFT_SIZE} y2={shaftY} text={`Š ${data.shaftWidth}`} offset={-30} />
                <DimLine x1={shaftX} y1={shaftY} x2={shaftX} y2={shaftY+VISUAL_SHAFT_SIZE} text={`H ${data.shaftDepth}`} offset={-30} />
                <DimLine x1={cabinX} y1={cabinY} x2={cabinX+VISUAL_CABIN_WIDTH} y2={cabinY} text={`Kabína ${Math.round(data.cabinWidth)}`} offset={20} color="#0284c7" isInside />
                <DimLine x1={cabinX+VISUAL_CABIN_WIDTH} y1={cabinY} x2={cabinX+VISUAL_CABIN_WIDTH} y2={cabinY+VISUAL_CABIN_DEPTH} text={`${Math.round(data.cabinDepth)}`} offset={-20} color="#0284c7" isInside />
                <DimLine x1={shaftX + 60} y1={shaftY + VISUAL_SHAFT_SIZE} x2={shaftX + VISUAL_SHAFT_SIZE - 60} y2={shaftY + VISUAL_SHAFT_SIZE} text={`PL ${Math.round(data.doorWidth)}`} offset={35} />

                {horizontalShift !== 0 && (
                    <>
                        <text x={shaftX + 10} y={shaftY + VISUAL_SHAFT_SIZE - 10} fontSize="9" fill="gray">LDO: {data.LDO}</text>
                        <text x={shaftX + VISUAL_SHAFT_SIZE - 50} y={shaftY + VISUAL_SHAFT_SIZE - 10} fontSize="9" fill="gray">RDO: {data.RDO}</text>
                    </>
                )}
           </svg>
           {data.stationLabels && <div className="absolute bottom-0 w-full text-center py-1 bg-white/90 border-t border-gray-100"><span className="text-[9px] font-bold text-gray-500 uppercase tracking-wide mr-1">Stanice:</span><span className="text-[9px] font-bold text-black break-words whitespace-normal leading-tight">{data.stationLabels}</span></div>}
      </div>
  );
};

import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, ClipboardList, AlertTriangle, Settings, ShieldCheck } from 'lucide-react';
import { LiftLayoutSketch } from './LiftLayoutSketch';

interface TechSpecTableProps {
  data: LiftLayoutData;
  isVisible: boolean;
  onToggleVisibility: () => void;
  embedded?: boolean;
}

export const TechSpecTable: React.FC<TechSpecTableProps> = ({
  data,
  isVisible,
  onToggleVisibility,
  embedded = false
}) => {

  const getLiftTypeLabel = (val: string) => {
      const map: Record<string, string> = { 
          'passenger': 'Osobný výťah', 
          'freight': 'Nákladný výťah', 
          'home': 'Domáci výťah', 
          'hospital': 'Lôžkový výťah',
          'invalid': 'Invalidný (EN81-70)'
      };
      return map[val] || val;
  };
  const getDriveLabel = (val: string) => {
      const map: Record<string, string> = { 'traction': 'Trakčný', 'hydraulic': 'Hydraulický', 'mrl': 'MRL (Bez strojovne)', 'drum': 'Bubnový' };
      return map[val] || val;
  };
  const getDoorLabel = (val?: string) => {
      const map: Record<string, string> = { 'central': 'Automatické Centrálne', 'telescopic': 'Automatické Teleskopické', 'bus': 'Ručné + BUS (Sklápacie)' };
      return map[val || 'central'] || val;
  };

  const getSafetyMeasures = () => {
      const measures = [];
      if (data.pitDepth < 1100 || data.headroomHeight < 3400) {
          measures.push("Znížená hlava/priehlbeň (EN 81-21)");
      }
      if (data.liftType === 'invalid') {
          measures.push("Výbava invalid (EN 81-70)");
      }
      return measures;
  };

  const safetyMeasures = getSafetyMeasures();
  const stationCount = data.stationLabels ? data.stationLabels.split(',').length : 0;

  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border-2 border-dashed border-gray-300 rounded-lg bg-gray-50 text-gray-400 flex justify-between items-center hover:bg-gray-100 transition cursor-pointer" onClick={onToggleVisibility}>
              <span className="flex items-center gap-2 font-bold uppercase text-sm"><ClipboardList size={18}/> Technická špecifikácia (Skrytá)</span>
              <Eye size={20}/>
          </div>
      );
