  // Optimized Single Column Row
  const DataRow = ({ label, value, subValue, highlight = false, isLast = false }: any) => (
      <div className={`flex items-baseline justify-between px-5 py-3 border-b border-gray-200 ${highlight ? 'bg-gray-50/80' : ''} ${isLast ? 'border-b-0' : ''}`}>
          <div className="w-1/3">
              <span className="text-[11px] font-bold text-gray-500 uppercase tracking-widest block">{label}</span>
          </div>
          <div className="w-2/3 text-right">
              <div className="text-sm font-bold text-gray-900 leading-tight">{value}</div>
              {subValue && <div className="text-[11px] text-gray-500 font-medium mt-0.5">{subValue}</div>}
          </div>
      </div>
  );

  const Content = (
      <div className="bg-white flex flex-row h-full items-stretch">

          {/* LEFT COLUMN: SPECS (50%) - Determines Height */}
          <div className="w-1/2 flex flex-col border-r-2 border-gray-100">
              {/* Header */}
              <div className="px-5 py-4 border-b-2 border-gray-800 bg-white">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <div className="bg-gray-900 text-white p-1.5 rounded">
                            <Settings size={16} />
                        </div>
                        <h3 className="text-base font-bold text-gray-900 uppercase tracking-widest">Technické Parametre</h3>
                    </div>
                    {!embedded && (
                      <button onClick={onToggleVisibility} className="text-gray-300 hover:text-blue-600 transition no-print">
                          <Eye size={16} />
                      </button>
                    )}
                  </div>
              </div>

              {/* Data Rows - Single Stack */}
              <div className="flex-1 flex flex-col justify-start">
                  <DataRow label="Zariadenie" value={getLiftTypeLabel(data.liftType)} subValue={`Pohon: ${getDriveLabel(data.driveType)}`} highlight/>
                  <DataRow label="Nosnosť / Osoby" value={`${data.ratedLoad} kg`} subValue={`${data.numberOfPersons} osôb (podľa EN 81-20)`} />
                  <DataRow label="Rozmery Kabíny" value={`${Math.round(data.cabinWidth)} x ${Math.round(data.cabinDepth)} mm`} subValue={`Trieda: ${data.cabinClass || 'Štandard'}`} highlight/>
                  <DataRow label="Rozmery Dverí" value={`PL ${data.doorWidth} x ${data.doorOpeningHeight} mm`} subValue={getDoorLabel(data.doorType)} />
                  <DataRow label="Rozmery Šachty" value={`${data.shaftWidth} x ${data.shaftDepth} mm`} subValue={`Hlava: ${data.headroomHeight} / Priehlbeň: ${data.pitDepth}`} highlight/>
                  <DataRow label="Zdvih / Stanice" value={`${(data.travelHeight/1000).toFixed(2)} m`} subValue={`${stationCount} Staníc / ${data.numberOfStops} Nástupíšť`} />
                  <DataRow label="Rýchlosť" value={`${data.ratedSpeed} m/s`} subValue={`Lanovanie: ${data.suspensionType} (${data.tractionMedium === 'belts' ? 'Pásy' : 'Laná'})`} highlight/>
                  <DataRow label="Strojovňa" value={data.machineRoomPosition === 'head' ? 'Bez strojovne (MRL)' : data.machineRoomPosition === 'above' ? 'Strojovňa Hore' : 'Skrinka'} subValue={`Napájanie: ${data.powerSupply}`} />
                  <DataRow label="Povrchová Úprava" value={`Dvere: ${data.doorFinish}`} subValue={`Kabína: podľa vzorkovníka`} highlight isLast={true} />
              </div>

              {/* Footer (Notes/Safety) - Clean bottom block */}
              <div className="border-t-2 border-gray-800 bg-gray-50 p-4">
                  {safetyMeasures.length > 0 ? (
                      <div className="space-y-1.5">
                          {safetyMeasures.map((m, i) => (
                              <div key={i} className="flex items-start gap-2 text-[10px] font-bold text-red-700 uppercase">
                                  <AlertTriangle size={14} className="shrink-0 mt-0.5"/> <span>{m}</span>
                              </div>
