import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, ClipboardList, AlertTriangle, Settings, ShieldCheck, Zap } from 'lucide-react';
import { LiftLayoutSketch } from './LiftLayoutSketch';

interface TechSpecTableProps {
  data: LiftLayoutData;
  isVisible: boolean;
  onToggleVisibility: () => void;
  embedded?: boolean;
}

export const TechSpecTable: React.FC<TechSpecTableProps> = ({
  data,
  isVisible,
  onToggleVisibility,
  embedded = false
}) => {

  const getLiftTypeLabel = (val: string) => {
      const map: Record<string, string> = { 
          'passenger': 'Osobný výťah', 
          'freight': 'Nákladný výťah', 
          'home': 'Domáci výťah', 
          'hospital': 'Lôžkový výťah',
          'invalid': 'Invalidný (EN81-70)'
      };
      return map[val] || val;
  };
  const getDriveLabel = (val: string) => {
      const map: Record<string, string> = { 'traction': 'Trakčný', 'hydraulic': 'Hydraulický', 'mrl': 'MRL (Bez strojovne)', 'drum': 'Bubnový' };
      return map[val] || val;
  };
  const getDoorLabel = (val?: string) => {
      const map: Record<string, string> = { 'central': 'Automatické Centrálne', 'telescopic': 'Automatické Teleskopické', 'bus': 'Ručné + BUS (Sklápacie)' };
      return map[val || 'central'] || val;
  };

  const getSafetyMeasures = () => {
      const measures = [];
      if (data.pitDepth < 1100 || data.headroomHeight < 3400) {
          measures.push("Znížená hlava/priehlbeň (EN 81-21)");
      }
      if (data.liftType === 'invalid') {
          measures.push("Výbava invalid (EN 81-70)");
      }
      return measures;
  };

  const getEntrancesLabel = () => {
      const e = data.entrances || 'A';
      if (e === 'AB') return 'A+B (Prechodný 180°)';
      if (e === 'AC') return 'A+C (Prechodný 90°)';
      return 'A (Nepriechodný)';
  };

  const safetyMeasures = getSafetyMeasures();
  const stationCount = data.stationLabels ? data.stationLabels.split(',').length : 0;

  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border-2 border-dashed border-gray-300 rounded-lg bg-gray-50 text-gray-400 flex justify-between items-center hover:bg-gray-100 transition cursor-pointer" onClick={onToggleVisibility}>
              <span className="flex items-center gap-2 font-bold uppercase text-sm"><ClipboardList size={18}/> Technická špecifikácia (Skrytá)</span>
              <Eye size={20}/>
          </div>
      );
  }

  // Optimized Single Column Row - Reduced padding for compactness
  const DataRow = ({ label, value, subValue, highlight = false, isLast = false }: any) => (
      <div className={`flex items-baseline justify-between px-4 py-2 border-b border-gray-200 ${highlight ? 'bg-gray-50/80' : ''} ${isLast ? 'border-b-0' : ''}`}>
          <div className="w-1/3">
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest block">{label}</span>
          </div>
          <div className="w-2/3 text-right">
              <div className="text-[13px] font-bold text-gray-900 leading-tight">{value}</div>
              {subValue && <div className="text-[10px] text-gray-500 font-medium mt-0.5">{subValue}</div>}
          </div>
      </div>
  );

  const Content = (
      <div className="bg-white flex flex-row items-stretch border-b border-gray-200">

          {/* LEFT COLUMN: SPECS (50%) - Determines Height */}
          <div className="w-1/2 flex flex-col border-r-2 border-gray-100">
              {/* Header */}
              <div className="px-4 py-3 border-b-2 border-gray-800 bg-white">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <div className="bg-gray-900 text-white p-1 rounded">
                            <Settings size={14} />
                        </div>
                        <h3 className="text-sm font-bold text-gray-900 uppercase tracking-widest">Technické Parametre</h3>
                    </div>
                    {!embedded && (
                      <button onClick={onToggleVisibility} className="text-gray-300 hover:text-blue-600 transition no-print">
                          <Eye size={16} />
                      </button>
                    )}
                  </div>
              </div>

              {/* Data Rows - Single Stack */}
              <div className="flex-col justify-start">
                  <DataRow label="Zariadenie" value={getLiftTypeLabel(data.liftType)} subValue={`Pohon: ${getDriveLabel(data.driveType)}`} highlight/>
                  <DataRow label="Nosnosť / Osoby" value={`${data.ratedLoad} kg`} subValue={`${data.numberOfPersons} osôb (podľa EN 81-20)`} />
                  <DataRow label="Kabína / Design" value={`Typ: ${data.cabinClass || 'FUN'}`} subValue="Povrchová úprava podľa vzorkovníka" highlight/>
                  <DataRow label="Rozmery Kabíny" value={`${Math.round(data.cabinWidth)} x ${Math.round(data.cabinDepth)} mm`} subValue={`Výška: 2100 mm (štandard)`} />
                  <DataRow label="Dvere / Vstupy" value={getEntrancesLabel()} subValue={`${getDoorLabel(data.doorType)} (${data.doorWidth}x${data.doorOpeningHeight})`} highlight/>
                  <DataRow label="Rozmery Šachty" value={`${data.shaftWidth} x ${data.shaftDepth} mm`} subValue={`Hlava: ${data.headroomHeight} / Priehlbeň: ${data.pitDepth}`} />
                  <DataRow label="Zdvih / Stanice" value={`${(data.travelHeight/1000).toFixed(2)} m`} subValue={`${stationCount} Staníc / ${data.numberOfStops} Nástupíšť`} highlight/>
                  <DataRow label="Pohon / Riadenie" value="VVVF + CANopen 417" subValue={`Rýchlosť: ${data.ratedSpeed} m/s`} />
                  <DataRow label="Strojovňa" value={data.machineRoomPosition === 'head' ? 'Bez strojovne (MRL)' : 'Strojovňa'} subValue={`Napájanie: ${data.powerSupply}`} highlight/>
                  <DataRow label="Nosné prostriedky" value={data.tractionMedium === 'belts' ? 'Pásy (Certifikované)' : 'Oceľové laná'} subValue={`Lanovanie: ${data.suspensionType}`} isLast={true} />
              </div>

              {/* Footer (Notes/Safety) - Clean bottom block */}
              <div className="border-t-2 border-gray-800 bg-gray-50 p-3 mt-auto">
                  {safetyMeasures.length > 0 ? (
                      <div className="space-y-1">
                          {safetyMeasures.map((m, i) => (
                              <div key={i} className="flex items-start gap-2 text-[9px] font-bold text-red-700 uppercase">
                                  <AlertTriangle size={12} className="shrink-0 mt-0.5"/> <span>{m}</span>
                              </div>
                          ))}
                      </div>
                  ) : (
                      <div className="text-[9px] text-gray-400 uppercase font-bold flex items-center gap-2">
                          <ShieldCheck size={12}/> Plne v súlade s STN EN 81-20/50
                      </div>
                  )}
                  {data.notes && <div className="mt-1 text-[9px] italic text-gray-600 border-t border-gray-200 pt-1 leading-tight">{data.notes}</div>}
              </div>
          </div>

          {/* RIGHT COLUMN: SKETCH (50%) - Fits height of text automatically due to flex stretch */}
          <div className="w-1/2 bg-white flex flex-col relative overflow-hidden">
              <div className="absolute top-0 right-0 bg-gray-100 text-gray-500 text-[9px] font-bold uppercase px-2 py-1 z-10 rounded-bl border-b border-l border-gray-200">
                  Pôdorys
              </div>

              {/* Sketch Container - H-FULL to fill the flex container height determined by the text column */}
              <div className="flex-1 flex items-center justify-center p-0 h-full w-full">
                  <LiftLayoutSketch data={data} isVisible={true} />
              </div>
          </div>
      </div>
  );

  if (embedded) return <div className="border-2 border-gray-800 rounded-xl overflow-hidden shadow-sm bg-white">{Content}</div>;

  return (
    <div className="mb-8 break-inside-avoid border-2 border-gray-800 rounded-xl overflow-hidden shadow-md bg-white">
        {Content}
    </div>
  );
};

import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, EyeOff, PenTool } from 'lucide-react';

interface LiftLayoutSketchProps {
  data: LiftLayoutData;
  onChange?: (field: keyof LiftLayoutData, value: any) => void;
  isVisible?: boolean;
  onToggleVisibility?: () => void;
}

// Helper Components
const GuideT: React.FC<{x:number, y:number, rotation:number, color?:string}> = ({ x, y, rotation, color = "#000" }) => (
    <g transform={`translate(${x}, ${y}) rotate(${rotation})`}>
        <rect x="-8" y="-2" width="16" height="4" fill={color} />
        <rect x="-2" y="-2" width="4" height="12" fill={color} />
    </g>
);

const DimLine = ({ x1, y1, x2, y2, text, offset = 30, color = "#000", fontSize = 12, isInside = false }: any) => {
    const dx = x2 - x1; const dy = y2 - y1; const len = Math.sqrt(dx*dx + dy*dy);
    if(len === 0) return null;
    const ux = -dy / len; const uy = dx / len;
    const nx1 = x1 + ux * offset; const ny1 = y1 + uy * offset;
    const nx2 = x2 + ux * offset; const ny2 = y2 + uy * offset;
    const mx = (nx1 + nx2) / 2; const my = (ny1 + ny2) / 2;
    return (
      <g>
        <line x1={x1} y1={y1} x2={nx1} y2={ny1} stroke={color} strokeWidth="0.5" opacity="0.3" />
        <line x1={x2} y1={y2} x2={nx2} y2={ny2} stroke={color} strokeWidth="0.5" opacity="0.3" />
        <line x1={nx1} y1={ny1} x2={nx2} y2={ny2} stroke={color} strokeWidth="1" />
        <circle cx={nx1} cy={ny1} r={2} fill={color} />
        <circle cx={nx2} cy={ny2} r={2} fill={color} />
        {!isInside && <rect x={mx - (String(text).length * 3.5)} y={my - 7} width={String(text).length * 7} height={14} fill="white" fillOpacity="0.8" rx={2} />}
        <text x={mx} y={my} dy={4} textAnchor="middle" fill={color} fontSize={fontSize} fontWeight="bold">{text}</text>
      </g>
    );
};

export const LiftLayoutSketch: React.FC<LiftLayoutSketchProps> = ({ 
  data,
  onChange,
  isVisible = true,
  onToggleVisibility
}) => {
  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border border-dashed border-gray-300 rounded bg-gray-50 text-gray-400 flex justify-between items-center w-full">
              <div className="flex items-center gap-2">
                 <PenTool size={18}/>
                 <span className="text-sm font-bold uppercase">Nákres (Skrytý)</span>
              </div>
              {onToggleVisibility && <button onClick={onToggleVisibility} className="hover:text-blue-600"><Eye size={20}/></button>}
          </div>
      );
  }

  // Visual Config
  const svgSize = 420; const center = svgSize / 2;
  const VISUAL_SHAFT_SIZE = 300;
  const VISUAL_CABIN_WIDTH = 180;
  const VISUAL_CABIN_DEPTH = 200;

  // --- ASYMMETRY CALCULATION (LDO/RDO) ---
  let horizontalShift = 0;
  if (data.LDO !== undefined && data.doorOpeningWidth && data.shaftWidth > 0) {
      const realShaftCenter = data.shaftWidth / 2;
      const realCabinCenter = data.LDO + (data.doorOpeningWidth / 2);
      const shiftMm = realCabinCenter - realShaftCenter;
      const scale = VISUAL_SHAFT_SIZE / data.shaftWidth;
      horizontalShift = shiftMm * scale;

      const maxShift = (VISUAL_SHAFT_SIZE - VISUAL_CABIN_WIDTH) / 2 - 10;
      if (horizontalShift > maxShift) horizontalShift = maxShift;
      if (horizontalShift < -maxShift) horizontalShift = -maxShift;
  }

  const shaftX = center - (VISUAL_SHAFT_SIZE / 2); 
  const shaftY = center - (VISUAL_SHAFT_SIZE / 2);
  const cabinX = center - (VISUAL_CABIN_WIDTH / 2) + horizontalShift; 
  const cabinY = center - (VISUAL_CABIN_DEPTH / 2);
  const activeCenter = center + horizontalShift;

  const inputCwtW = (data.cwtWidth || 120) / 6; const inputCwtL = (data.cwtDepth || 650) / 6;
  let cwtX = 0, cwtY = 0, cwtW = 0, cwtH = 0;
  if (data.counterWeightPosition === 'back') { cwtW = inputCwtL; cwtH = inputCwtW; cwtX = center - (cwtW / 2); cwtY = shaftY + 15; } 
  else if (data.counterWeightPosition === 'left') { cwtW = inputCwtW; cwtH = inputCwtL; cwtX = shaftX + 15; cwtY = center - (cwtH / 2); } 
  else if (data.counterWeightPosition === 'right') { cwtW = inputCwtW; cwtH = inputCwtL; cwtX = shaftX + VISUAL_SHAFT_SIZE - 15 - cwtW; cwtY = center - (cwtH / 2); }

  // DOOR RENDERING HELPERS
  const renderDoor = (side: 'A' | 'B' | 'C') => {
      let yPosShaft = 0, yPosCabin = 0, rot = 0, cx = 0, cy = 0;
      let label = side;
      let isSide = false;

      if (side === 'A') { // Front
          yPosShaft = shaftY + VISUAL_SHAFT_SIZE;
          yPosCabin = cabinY + VISUAL_CABIN_DEPTH;
          cx = activeCenter;
          cy = yPosShaft + 25;
      } else if (side === 'B') { // Rear (180)
          yPosShaft = shaftY;
          yPosCabin = cabinY;
          cx = activeCenter;
          cy = yPosShaft - 15;
          rot = 180;
      } else if (side === 'C') { // Side (90) - Determine Left/Right based on CWT
          // If CWT is right, C door is left, etc. Default Right if back.
          isSide = true;
          // Simple visual representation for side door
          // We put it on the RIGHT side by default unless CWT is there
          const onRight = data.counterWeightPosition !== 'right';
          const xPosShaft = onRight ? shaftX + VISUAL_SHAFT_SIZE : shaftX;
          const xPosCabin = onRight ? cabinX + VISUAL_CABIN_WIDTH : cabinX;

          return (
              <g key="door-C">
                  {/* Thresholds */}
                  <line x1={xPosShaft} y1={center - 40} x2={xPosShaft} y2={center + 40} stroke="white" strokeWidth={6} />
                  <line x1={xPosCabin} y1={center - 30} x2={xPosCabin} y2={center + 30} stroke="#0284c7" strokeWidth={3} />
                  {/* Label */}
                  <text x={onRight ? xPosShaft + 20 : xPosShaft - 20} y={center} textAnchor="middle" fontSize="16" fontWeight="bold" fill="#000">C</text>
              </g>
          );
      }

      if (!isSide) {
          const vDoorW = 140; 
          const doorStart = activeCenter - (vDoorW / 2);

          return (
              <g key={`door-${side}`}>
                  {/* Shaft Threshold */}
                  <line x1={shaftX + 60} y1={yPosShaft} x2={shaftX + VISUAL_SHAFT_SIZE - 60} y2={yPosShaft} stroke="white" strokeWidth={6} />
                  {/* Cabin Threshold */}
                  <line x1={cabinX} y1={yPosCabin} x2={cabinX + VISUAL_CABIN_WIDTH} y2={yPosCabin} stroke="#0284c7" strokeWidth={3} />

                  {/* Door Mechanism Visual */}
                  {data.doorType === 'bus' ? (
                      // Bus Door Path
                      <path d={`M ${doorStart},${yPosCabin} L ${doorStart + 35},${yPosCabin - (side==='B'?-15:15)} L ${doorStart + 70},${yPosCabin}`} fill="none" stroke="#0284c7" strokeWidth="2" />
                  ) : (
                      // Central/Tel Visual
                      <g transform={`translate(${cx}, ${yPosShaft + (side==='B'?10:-10)})`}>
                          <line x1={2} y1={0} x2={20} y2={0} stroke="#666" strokeWidth="1" /><line x1={-2} y1={0} x2={-20} y2={0} stroke="#666" strokeWidth="1" />
                          <rect x={-70} y={-2} width={10} height={4} fill="#666"/><rect x={60} y={-2} width={10} height={4} fill="#666"/>
                      </g>
                  )}
                  <text x={cx} y={cy} textAnchor="middle" fontSize="16" fontWeight="bold" fill="#000">{label}</text>
              </g>
          );
      }
      return null;
  };

  const entrances = data.entrances || 'A';

  return (
       <div className="w-full h-full flex flex-col items-center justify-center relative bg-white">
            <div className="absolute top-2 right-2 z-10 no-print flex gap-2">
                {onToggleVisibility && <button onClick={onToggleVisibility} className="p-1 rounded text-gray-400 hover:text-black hover:bg-gray-100 bg-white/50"><EyeOff size={16} /></button>}
           </div>

           {/* SVG fills the container completely now */}
           <svg 
                viewBox={`0 0 ${svgSize} ${svgSize}`} 
                className="w-full h-full p-2" 
                preserveAspectRatio="xMidYMid meet"
           >
                <defs><pattern id="hatch" patternUnits="userSpaceOnUse" width="10" height="10" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="10" stroke="#000000" strokeWidth="1" opacity="0.1"/></pattern></defs>

                {/* Background & Shaft */}
                <rect x={shaftX} y={shaftY} width={VISUAL_SHAFT_SIZE} height={VISUAL_SHAFT_SIZE} fill="url(#hatch)" stroke="black" strokeWidth="4" />
                <rect x={shaftX-5} y={shaftY-5} width={VISUAL_SHAFT_SIZE+10} height={VISUAL_SHAFT_SIZE+10} fill="none" stroke="black" strokeWidth="0.5" />

                {horizontalShift !== 0 && (
                    <line x1={center} y1={shaftY} x2={center} y2={shaftY + VISUAL_SHAFT_SIZE} stroke="red" strokeWidth="0.5" strokeDasharray="4" opacity="0.5" />
                )}

                {/* Cabin & CWT */}
                <rect x={cabinX} y={cabinY} width={VISUAL_CABIN_WIDTH} height={VISUAL_CABIN_DEPTH} fill="#e0f2fe" stroke="#0284c7" strokeWidth="2" />
                <rect x={cwtX} y={cwtY} width={cwtW} height={cwtH} fill="#ef4444" stroke="#7f1d1d" strokeWidth="1" />

                {renderRails()}

                {/* DOORS */}
                {renderDoor('A')}
                {(entrances === 'AB') && renderDoor('B')}
                {(entrances === 'AC') && renderDoor('C')}

                {/* Dimensions */}
                <DimLine x1={shaftX} y1={shaftY} x2={shaftX+VISUAL_SHAFT_SIZE} y2={shaftY} text={`Š ${data.shaftWidth}`} offset={-30} />
                <DimLine x1={shaftX} y1={shaftY} x2={shaftX} y2={shaftY+VISUAL_SHAFT_SIZE} text={`H ${data.shaftDepth}`} offset={-30} />
                <DimLine x1={cabinX} y1={cabinY} x2={cabinX+VISUAL_CABIN_WIDTH} y2={cabinY} text={`Kabína ${Math.round(data.cabinWidth)}`} offset={20} color="#0284c7" isInside />
                <DimLine x1={cabinX+VISUAL_CABIN_WIDTH} y1={cabinY} x2={cabinX+VISUAL_CABIN_WIDTH} y2={cabinY+VISUAL_CABIN_DEPTH} text={`${Math.round(data.cabinDepth)}`} offset={-20} color="#0284c7" isInside />
                <DimLine x1={shaftX + 60} y1={shaftY + VISUAL_SHAFT_SIZE} x2={shaftX + VISUAL_SHAFT_SIZE - 60} y2={shaftY + VISUAL_SHAFT_SIZE} text={`PL ${Math.round(data.doorWidth)}`} offset={35} />

                {horizontalShift !== 0 && (
                    <>
                        <text x={shaftX + 10} y={shaftY + VISUAL_SHAFT_SIZE - 10} fontSize="9" fill="gray">LDO: {data.LDO}</text>
                        <text x={shaftX + VISUAL_SHAFT_SIZE - 50} y={shaftY + VISUAL_SHAFT_SIZE - 10} fontSize="9" fill="gray">RDO: {data.RDO}</text>
                    </>
                )}
           </svg>
           {data.stationLabels && <div className="absolute bottom-0 w-full text-center py-1 bg-white/90 border-t border-gray-100"><span className="text-[9px] font-bold text-gray-500 uppercase tracking-wide mr-1">Stanice:</span><span className="text-[9px] font-bold text-black break-words whitespace-normal leading-tight">{data.stationLabels}</span></div>}
      </div>
  );
};

import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, EyeOff, PenTool } from 'lucide-react';

