      if (!data.layout) return;
      const { shaftWidth, shaftDepth, gapLeft, gapRight, gapFront, gapRear, frameType, guideTypeCar } = data.layout;
      const getRailDepth = (type?: string) => {
          if (!type) return 80;
          if (type.includes('T45') || type.includes('T50')) return 50;
          if (type.includes('T70') || type.includes('T75')) return 70;
          if (type.includes('T89') || type.includes('T90')) return 90;
          if (type.includes('T125') || type.includes('T127')) return 125;
          return 80;
      };
      const railDepth = getRailDepth(guideTypeCar); const wallThickness = 30; 
      let newWidth = shaftWidth - gapLeft - gapRight - (2 * wallThickness);
      if (frameType === 'central') { newWidth = newWidth - (2 * railDepth); }
      let newDepth = shaftDepth - gapFront - gapRear - (2 * wallThickness);
