            <div className="flex gap-2">{data.type === 'quote' && (<button onClick={() => createRelatedOrder(data)} className="px-4 py-1.5 bg-blue-600 text-white hover:bg-blue-700 rounded text-sm font-bold flex items-center gap-2 shadow"><FileInput size={14}/> Vytvoriť Objednávku</button>)}{data.type === 'order' && (<button onClick={() => createRelatedContract(data)} className="px-4 py-1.5 bg-green-600 text-white hover:bg-green-700 rounded text-sm font-bold flex items-center gap-2 shadow"><FileCheck size={14}/> Vytvoriť Zmluva</button>)}</div>
