            <div className="mb-8 break-inside-avoid">
                {data.showTechSpecs !== false && (
                    <TechSpecTable 
                        data={data.layout || DEFAULT_LAYOUT} 
                        isVisible={true} 
                        onToggleVisibility={toggleTechSpecs} 
                        embedded={true} 
                    />
