                onInput={handleInput}
                className={`rich-text-content w-full min-h-[60px] outline-none text-gray-900 text-xs leading-relaxed ${readOnly ? 'pointer-events-none' : ''}`}
                dangerouslySetInnerHTML={{ __html: category.textContent || '' }}
            />
        </div>
      )}
    </div>
  );
};

