// --- EN 81-20 HELPER ---
const calculateEn8120 = (width: number, depth: number) => {
    const area = (width * depth) / 1000000;
    const perimeter = (width + depth) * 2;
    // Wall Area = Perimeter * 2.04m (as requested)
    const wallArea = (perimeter * 2040) / 1000000;

    let suggestedLoad = 0;
    if (area <= 0.37) suggestedLoad = 100;
    else if (area <= 0.50) suggestedLoad = 180;
    else if (area <= 0.70) suggestedLoad = 300; 
    else if (area <= 0.90) suggestedLoad = 375;
    else if (area <= 1.17) suggestedLoad = 450; 
    else if (area <= 1.30) suggestedLoad = 525; 
    else if (area <= 1.45) suggestedLoad = 600; 
    else if (area <= 1.60) suggestedLoad = 630; 
    else if (area <= 1.66) suggestedLoad = 675; 
    else if (area <= 2.00) suggestedLoad = 800; 
    else if (area <= 2.35) suggestedLoad = 1000; 
    else suggestedLoad = Math.floor(area / 0.16) * 100; 

    let persons = 0;
    if (suggestedLoad < 450) persons = Math.floor(suggestedLoad / 75); 
    else if (suggestedLoad >= 450 && suggestedLoad < 630) persons = 6;
    else if (suggestedLoad >= 630 && suggestedLoad < 800) persons = 8;
    else if (suggestedLoad >= 800 && suggestedLoad < 1000) persons = 10;
    else if (suggestedLoad >= 1000) persons = 13;
    else persons = Math.floor(suggestedLoad / 75);

    return { area, wallArea, suggestedLoad, persons };
};

