// --- EN 81-20 HELPER (FIXED FOR 1275kg) ---
const calculateEn8120 = (width: number, depth: number) => {
    const area = (width * depth) / 1000000;
    const perimeter = (width + depth) * 2;
    const wallArea = (perimeter * 2040) / 1000000;

    // EN 81-20 Table 6 (Strict Lookup)
    // This table defines the MAXIMUM available area for a given rated load.
    // We look for the first entry where current area <= maxArea.
    const standards = [
        { maxArea: 0.37, load: 100, persons: 1 },
        { maxArea: 0.58, load: 180, persons: 2 },
        { maxArea: 0.70, load: 225, persons: 3 },
        { maxArea: 0.90, load: 300, persons: 4 },
        { maxArea: 1.17, load: 450, persons: 6 }, // Standard
        { maxArea: 1.30, load: 525, persons: 7 }, 
        { maxArea: 1.45, load: 600, persons: 8 },
        { maxArea: 1.66, load: 630, persons: 8 }, // Standard
        { maxArea: 2.00, load: 800, persons: 10 }, // Standard
        { maxArea: 2.35, load: 900, persons: 12 }, 
        { maxArea: 2.40, load: 1000, persons: 13 }, // Standard (Max 2.40m2)
        { maxArea: 2.65, load: 1125, persons: 15 }, // Semi-standard
        { maxArea: 2.95, load: 1275, persons: 17 }, // Standard (For 2.47m2)
        { maxArea: 3.10, load: 1350, persons: 18 },
        { maxArea: 3.25, load: 1425, persons: 19 },
        { maxArea: 3.40, load: 1500, persons: 20 }, // Freight heavy
        { maxArea: 3.56, load: 1600, persons: 21 }, // Standard Freight/Pax
        { maxArea: 4.20, load: 2000, persons: 26 }
    ];

    // Find first standard where current area fits
    let result = standards.find(s => area <= s.maxArea);

    let suggestedLoad = 0;
    let persons = 0;

    if (result) {
        suggestedLoad = result.load;
        persons = result.persons;
    } else {
        // Fallback for huge lifts > 2000kg
        suggestedLoad = Math.ceil((area / 0.16) / 100) * 100;
        persons = Math.round(suggestedLoad / 75);
    }

    return { area, wallArea, suggestedLoad, persons };
};

