  const handleLayoutChange = (field: keyof LiftLayoutData, value: any) => {
      setData(prev => {
          const newData = { ...prev, layout: { ...prev.layout!, [field]: value } };
          if (field === 'entrances') { newData.layout.isThroughCar = (value === 'AB' || value === 'AC'); }
