  const openEmailModal = () => { setEmailModalProps({ to: data.client.email || '', subject: `${data.number} - ${data.title}`, message: `Vážený obchodný partner,\n\nv nadväznosti na Váš dopyt Vám v prílohe zasielame cenovú ponuku č. ${data.number}.\n\nVeríme, že naša ponuka splní Vaše očakávan a tešíme sa na prípadnú spoluprácu.\n\nV prípade akýchkoľvek otázok nás neváhajte kontaktovať.\n\nS úctou,\n\n${data.supplier.name}\n${data.supplier.email || ''}\n${data.supplier.phone || ''}` }); setIsEmailModalOpen(true); };

  const generateDocNumber = (type: 'quote' | 'order' | 'contract') => {
