            <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2"><Calculator className="text-blue-600"/> SmartQuote SK <span className="text-xs bg-gray-200 text-gray-600 px-2 py-1 rounded">v{APP_VERSION}</span></h1>
            <div className="flex gap-2 items-center">
                <button onClick={() => window.print()} className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm" title="Tlačiť alebo Uložiť ako PDF"><Printer size={16}/> Tlačiť / PDF</button>
                <button onClick={openEmailModal} className="px-3 py-2 bg-green-600 hover:bg-green-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm" title="Odoslať PDF E-mailom"><Mail size={16}/> Odoslať</button>
                <div className="h-6 w-px bg-gray-300 mx-2"></div>
                <button onClick={handleNewQuote} className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm border border-blue-800" title="Nová prázdna ponuka"><PlusCircle size={16}/> Nová CP</button>
                <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-2 bg-purple-100 hover:bg-purple-200 text-purple-800 font-bold rounded flex items-center gap-2 border border-purple-300 text-sm"><Settings size={16}/> Katalóg</button>
                <button onClick={handleSaveCurrentQuote} className="px-3 py-2 bg-green-100 hover:bg-green-200 text-green-800 font-bold rounded flex items-center gap-2 border border-green-300 text-sm" title="Uložiť zmeny"><Save size={16}/> Uložiť</button>
                <button onClick={() => setShowArchive(true)} className="px-3 py-2 bg-gray-200 hover:bg-gray-300 rounded text-gray-700 font-bold flex items-center gap-2 text-sm"><Archive size={16}/> Archív</button>
                <button onClick={() => setIsSettingsModalOpen(true)} className="p-2 bg-gray-200 hover:bg-gray-300 rounded text-gray-700"><Settings size={18}/></button>
                <label className="flex items-center gap-2 ml-2 cursor-pointer bg-white border px-3 py-1 rounded-full shadow-sm hover:bg-gray-50"><input type="checkbox" checked={data.hideItemPrices} onChange={e => setData({...data, hideItemPrices: e.target.checked})} className="rounded text-blue-600 focus:ring-blue-500"/><span className="text-xs font-bold text-gray-600">Skryť ceny (Tlač)</span></label>
                <button onClick={handleLogout} className="ml-2 p-2 bg-red-100 hover:bg-red-200 text-red-700 rounded-full" title="Odhlásiť"><LogOut size={16}/></button>
            </div>
        </div>
        {/* ... STATUS BAR ... */}
        <div className="bg-white p-2 rounded-lg border border-blue-200 shadow-sm flex items-center justify-between">
            <div className="flex items-center gap-4">
                 <button onClick={() => handleNavigateToRelated('quote')} disabled={data.type === 'quote'} className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'quote' ? 'bg-yellow-100 text-yellow-800 ring-2 ring-yellow-400 cursor-default' : 'bg-gray-100 text-gray-500 hover:bg-yellow-50 hover:text-yellow-700'}`}>1. Cenová Ponuka {data.type !== 'quote' && <CheckCircle size={12}/>}</button>
                 <ArrowRight size={16} className="text-gray-300"/>
                 <button onClick={() => handleNavigateToRelated('order')} disabled={data.type === 'order'} className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'order' ? 'bg-blue-100 text-blue-800 ring-2 ring-blue-400 cursor-default' : 'bg-gray-100 text-gray-500 hover:bg-blue-50 hover:text-blue-700'}`}>2. Objednávka {data.type !== 'order' && savedQuotes.some(q => q.type === 'order' && q.relatedDocId === (data.type==='quote'?data.id:data.relatedDocId)) && <CheckCircle size={12}/>}</button>
                 <ArrowRight size={16} className="text-gray-300"/>
                 <button onClick={() => handleNavigateToRelated('contract')} disabled={data.type === 'contract'} className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'contract' ? 'bg-green-100 text-green-800 ring-2 ring-green-400 cursor-default' : 'bg-gray-100 text-gray-500 hover:bg-green-50 hover:text-green-700'}`}>3. Zmluva</button>
            </div>
            <div className="flex gap-2">{data.type === 'quote' && (<button onClick={() => createRelatedOrder(data)} className="px-4 py-1.5 bg-blue-600 text-white hover:bg-blue-700 rounded text-sm font-bold flex items-center gap-2 shadow"><FileInput size={14}/> Vytvoriť Objednávku</button>)}{data.type === 'order' && (<button onClick={() => createRelatedContract(data)} className="px-4 py-1.5 bg-green-600 text-white hover:bg-green-700 rounded text-sm font-bold flex items-center gap-2 shadow"><FileCheck size={14}/> Vytvoriť Zmluva</button>)}</div>
        </div>
      </div>

      {/* ... MODALS ... */}
      <ProductDatabaseModal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} onSelectProduct={handleSelectProduct} products={products} onAddProduct={handleAddProduct} onDeleteProduct={handleDeleteProduct} layout={data.layout} />
      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={handleAddProduct} onUpdateProduct={handleUpdateProduct} onDeleteProduct={handleDeleteProduct} customCategories={availableCategories} onAddCategory={handleAddCategory} onDeleteCategory={handleDeleteCategory} onImportCatalog={handleImportCatalog} cabinClasses={cabinClasses} onAddCabinClass={handleAddCabinClass} onUpdateCabinClass={handleUpdateCabinClass} onDeleteCabinClass={handleDeleteCabinClass} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details, email: c.email, phone: c.phone}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details, email: s.email, phone: s.phone}, logoUrl: s.logoUrl})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <TemplateDatabaseModal isOpen={isTemplateModalOpen} onClose={() => setIsTemplateModalOpen(false)} mode={templateModalMode} templateType={templateContext} templates={templates} onSelectTemplate={handleLoadTemplate} onSaveTemplate={handleSaveTemplate} onDeleteTemplate={handleDeleteTemplate} />
      <ContractRepositoryModal isOpen={isContractRepoOpen} onClose={() => setIsContractRepoOpen(false)} templates={contractTemplates} onSelectTemplate={handleSelectContractTemplate} onSaveCurrent={handleSaveContractTemplate} onDeleteTemplate={handleDeleteContractTemplate} />
      <SettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={settings} onSaveSettings={handleSaveSettings} onExportData={handleExportData} onImportData={handleImportData} onFactoryReset={handleFactoryReset} appVersion={APP_VERSION} />
      <EmailModal isOpen={isEmailModalOpen} onClose={() => setIsEmailModalOpen(false)} onSend={handleSendEmail} defaultTo={emailModalProps.to} defaultSubject={emailModalProps.subject} defaultMessage={emailModalProps.message} />
      <MaterialCalculatorModal isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} layout={data.layout || DEFAULT_LAYOUT} onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories} onAddCategory={handleAddCategory} cabinClasses={cabinClasses} />
      {showArchive && (
          <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 no-print">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-5xl max-h-[85vh] flex flex-col">
                  <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl"><h2 className="text-xl font-bold flex items-center gap-2"><Archive className="text-blue-600"/> Archív Dokladov</h2><button onClick={() => setShowArchive(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button></div>
                  <div className="p-4 border-b bg-white"><div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} /><input type="text" placeholder="Hľadať podľa čísla dokladu alebo mena klienta..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" /></div></div>
                  <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                      {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => (
                          <div key={q.id} className="p-4 bg-white border border-gray-200 rounded-lg mb-2 flex justify-between items-center shadow-sm hover:border-blue-300 transition-all">
                              <div><div className="font-bold text-lg text-gray-800 flex items-center gap-2">{q.number} <span className={`text-xs px-2 py-0.5 rounded uppercase ${q.type==='quote'?'bg-yellow-100 text-yellow-800':q.type==='order'?'bg-blue-100 text-blue-800':'bg-green-100 text-green-800'}`}>{q.type === 'quote' ? 'Ponuka' : q.type === 'order' ? 'Objednávka' : 'Zmluva'}</span></div><div className="text-sm text-gray-600 font-medium">{q.client.name || 'Bez klienta'}</div><div className="text-xs text-gray-400 mt-1">Zo dňa: {q.date}</div></div>
                              <div className="flex gap-2"><button onClick={() => loadFromStorage(q)} className="px-3 py-1.5 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold rounded text-sm">Otvoriť</button>{q.type === 'quote' && (<button onClick={() => createRelatedOrder(q)} className="px-3 py-1.5 bg-blue-50 hover:bg-blue-100 text-blue-700 font-bold rounded text-sm border border-blue-200 flex items-center gap-1"><FileInput size={14}/> Obj.</button>)}{q.type === 'order' && (<button onClick={() => createRelatedContract(q)} className="px-3 py-1.5 bg-green-50 hover:bg-green-100 text-green-700 font-bold rounded text-sm border border-green-200 flex items-center gap-1"><FileCheck size={14}/> Zmluva</button>)}<button onClick={() => handleDeleteQuote(q.id)} className="px-3 py-1.5 bg-red-50 hover:bg-red-100 text-red-600 rounded text-sm border border-red-200" title="Vymazať z archívu"><Trash2 size={16}/></button></div>
                          </div>
                      ))}{savedQuotes.length === 0 && <div className="text-center text-gray-400 py-8 italic">Žiadne uložené doklady.</div>}
                  </div>
              </div>
          </div>
      )}

      {/* --- CONFIG PANEL --- */}
      <div className="max-w-[210mm] mx-auto mb-8 p-6 bg-amber-50 rounded-xl border border-amber-200 shadow-sm text-sm no-print">
             {/* 1. ROW: BASICS */}
             <div className="grid grid-cols-12 gap-4 mb-4 pb-4 border-b border-amber-200">
                <div className="col-span-12 font-bold text-amber-900 uppercase flex items-center gap-2 mb-1"><Sliders size={16}/> Základné Parametre</div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Typ výťahu</label><select value={data.layout?.liftType} onChange={e => handleLayoutChange('liftType', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 bg-white font-bold"><option value="passenger">Osobný</option><option value="freight">Nákladný</option><option value="home">Domáci</option><option value="invalid">Invalidný (EN 81-70)</option></select></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Nosnosť (kg)</label><input type="number" value={data.layout?.ratedLoad} onChange={e => handleLayoutChange('ratedLoad', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Osoby</label><input type="number" value={data.layout?.numberOfPersons} onChange={e => handleLayoutChange('numberOfPersons', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Rýchlosť (m/s)</label><input type="number" step="0.1" value={data.layout?.ratedSpeed} onChange={e => handleLayoutChange('ratedSpeed', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Stanice / Štart</label><div className="flex gap-1"><input type="number" value={data.layout?.numberOfStops} onChange={e => handleLayoutChange('numberOfStops', +e.target.value)} className="w-2/3 h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white" title="Počet staníc"/><input type="number" value={data.layout?.startStation ?? 0} onChange={e => handleLayoutChange('startStation', +e.target.value)} className="w-1/3 h-10 border border-gray-300 rounded px-1 text-center font-bold text-sm bg-gray-50" title="Východzia stanica (napr. -1)"/></div></div>
                 <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Napájanie</label><input type="text" value={data.layout?.powerSupply} onChange={e => handleLayoutChange('powerSupply', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold bg-white text-blue-700"/></div>
             </div>

             {/* 2. ROW: SHAFT */}
             <div className="grid grid-cols-12 gap-4 mb-4 pb-4 border-b border-amber-200">
                <div className="col-span-12 font-bold text-amber-900 uppercase flex items-center gap-2 mb-1"><ArrowRightLeft size={16}/> Šachta & Rozmery</div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Šírka Šachty</label><input type="number" value={data.layout?.shaftWidth} onChange={e => handleLayoutChange('shaftWidth', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-xl bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Hĺbka Šachty</label><input type="number" value={data.layout?.shaftDepth} onChange={e => handleLayoutChange('shaftDepth', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-xl bg-white"/></div>
                 <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Hlava (HQ)</label><input type="number" value={data.layout?.headroomHeight} onChange={e => handleLayoutChange('headroomHeight', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                 <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Priehlbeň (HS)</label><input type="number" value={data.layout?.pitDepth} onChange={e => handleLayoutChange('pitDepth', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                 <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Zdvih (mm)</label><input type="number" value={data.layout?.travelHeight} onChange={e => handleLayoutChange('travelHeight', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-medium bg-white"/></div>

                 <div className="col-span-2 flex items-center pt-4">
                     <label className="flex items-center gap-2 cursor-pointer">
                         <input type="checkbox" checked={data.layout?.hasExternalShaft} onChange={e => handleToggleExternalShaft(e.target.checked)} className="rounded text-orange-600 focus:ring-orange-500"/>
                         <span className="text-[10px] font-bold text-amber-800 uppercase leading-tight">Vonkajšia oceľová konštrukcia</span>
                     </label>
                 </div>

                <div className="col-span-12 mt-2 bg-white/50 p-2 rounded border border-amber-100 flex items-center gap-4">
                     <span className="text-xs font-bold uppercase text-amber-800 w-24">Medzery (mm):</span>
                     <div className="flex gap-2 flex-1">
                        <div className="flex-1"><label className="text-[9px] text-gray-500 block text-center">Ľavá</label><input type="number" value={data.layout?.gapLeft} onChange={e => handleLayoutChange('gapLeft', +e.target.value)} className="w-full h-8 border border-gray-200 bg-white rounded text-center text-sm font-bold"/></div>
                        <div className="flex-1"><label className="text-[9px] text-gray-500 block text-center">Pravá</label><input type="number" value={data.layout?.gapRight} onChange={e => handleLayoutChange('gapRight', +e.target.value)} className="w-full h-8 border border-gray-200 bg-white rounded text-center text-sm font-bold"/></div>
                        <div className="flex-1"><label className="text-[9px] text-gray-500 block text-center">Predná</label><input type="number" value={data.layout?.gapFront} onChange={e => handleLayoutChange('gapFront', +e.target.value)} className="w-full h-8 border border-gray-200 bg-white rounded text-center text-sm font-bold"/></div>
                        <div className="flex-1"><label className="text-[9px] text-gray-500 block text-center">Zadná</label><input type="number" value={data.layout?.gapRear} onChange={e => handleLayoutChange('gapRear', +e.target.value)} className="w-full h-8 border border-gray-200 bg-white rounded text-center text-sm font-bold"/></div>
                     </div>
                </div>
             </div>

             {/* 3. ROW: CABIN & DOORS */}
             <div className="grid grid-cols-12 gap-6 mb-4 pb-4 border-b border-amber-200">
                <div className="col-span-12 font-bold text-blue-900 uppercase flex items-center gap-2 mb-1"><Box size={16}/> Kabína a Dvere</div>

                {/* 1. Left: Cabin Dims & Auto Buttons */}
                <div className="col-span-4 grid grid-cols-2 gap-3 p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                    <div className="col-span-2 text-xs font-bold text-blue-800 uppercase border-b border-blue-200 pb-1 mb-1 flex justify-between items-center">
                        <span>Rozmery Kabíny</span>
                        {/* AREA CALCULATION HELPER */}
                        <div className="flex items-center gap-1 text-[9px] text-blue-600 bg-white px-1.5 py-0.5 rounded border border-blue-200" title="Vypočítaná plocha podlahy">
                            <Ruler size={10}/> {currentAreaInfo.area.toFixed(2)} m²
                        </div>
                    </div>
                    <div><label className="text-[9px] uppercase font-bold text-blue-800 block mb-1">Šírka (mm)</label><input type="number" value={data.layout?.cabinWidth} onChange={e => handleLayoutChange('cabinWidth', +e.target.value)} className="w-full h-10 border border-blue-300 rounded px-2 text-center font-bold text-xl bg-white text-blue-900"/></div>
                    <div><label className="text-[9px] uppercase font-bold text-blue-800 block mb-1">Hĺbka (mm)</label><input type="number" value={data.layout?.cabinDepth} onChange={e => handleLayoutChange('cabinDepth', +e.target.value)} className="w-full h-10 border border-blue-300 rounded px-2 text-center font-bold text-xl bg-white text-blue-900"/></div>

                    {/* NEW: Cabin Height Input */}
                    <div className="col-span-2">
                        <label className="text-[9px] uppercase font-bold text-blue-800 block mb-1">Výška Kabíny (mm)</label>
                        <input type="number" value={data.layout?.cabinHeight || 2100} onChange={e => handleLayoutChange('cabinHeight', +e.target.value)} className="w-full h-8 border border-blue-300 rounded px-2 text-center font-bold text-base bg-white text-blue-900"/>
                    </div>

                    <div className="col-span-2">
                        <label className="text-[9px] uppercase font-bold text-blue-800 block mb-1">Trieda Kabíny</label>
                        <select value={data.layout?.cabinClass || 'FUN'} onChange={e => handleLayoutChange('cabinClass', e.target.value)} className="w-full h-8 text-xs font-bold border border-blue-300 rounded px-2 bg-white text-blue-900">
                            {cabinClasses.map(cc => (
                                <option key={cc.id} value={cc.name}>
                                    {cc.name} ({cc.description})
                                </option>
                            ))}
                        </select>
                    </div>

                    <div className="col-span-2 flex gap-2 mt-1">
                        <button onClick={() => handleCalculateDim('81-20')} className={`flex-1 h-8 border text-[10px] rounded font-bold transition flex items-center justify-center ${calcSuccess === '81-20' ? 'bg-green-500 text-white border-green-600' : 'bg-white border-blue-300 text-blue-700 hover:bg-blue-50'}`}>Auto 81-20</button>
                        <button onClick={() => handleCalculateDim('81-21')} className={`flex-1 h-8 border text-[10px] rounded font-bold transition flex items-center justify-center ${calcSuccess === '81-21' ? 'bg-green-500 text-white border-green-600' : 'bg-blue-600 border-blue-700 text-white hover:bg-blue-700'}`}>Auto 81-21</button>
                    </div>
                    {/* RECALCULATE BUTTON */}
                    <div className="col-span-2 mt-1">
                        <button onClick={handleRecalculateLoad} className="w-full h-8 bg-blue-100 hover:bg-blue-200 text-blue-800 border border-blue-300 rounded font-bold text-[10px] flex items-center justify-center gap-2 transition" title="Prepočítať nosnosť podľa zadanej plochy">
                            <RefreshCw size={12}/> Prepočítať Nosnosť
                        </button>
                    </div>
                    {/* CALCULATION FEEDBACK */}
                    <div className="col-span-2 text-[9px] text-blue-700 leading-tight bg-blue-100 p-1.5 rounded flex flex-col gap-1 mt-1">
                        <div className="flex justify-between font-bold">
                            <span>EN81-20: {currentAreaInfo.persons} osôb</span>
                            <span>Min. {currentAreaInfo.suggestedLoad} kg</span>
                        </div>
                        <div className="flex items-center gap-1 text-blue-500 font-medium border-t border-blue-200 pt-1">
                            <Maximize size={10}/> Plocha stien (2040mm): <strong>{currentAreaInfo.wallArea.toFixed(2)} m²</strong>
                        </div>
                    </div>
                </div>

                {/* 2. Middle: Door Tech */}
                <div className="col-span-4 grid grid-cols-2 gap-3 p-3 bg-gray-50 rounded-lg border border-gray-200">
                    <div className="col-span-2 text-xs font-bold text-gray-500 uppercase border-b border-gray-200 pb-1 mb-1">Dvere Technológia</div>

                    <div className="col-span-2"><label className="text-[9px] uppercase font-bold text-gray-500 block mb-1">Šírka Dverí (PL)</label><input type="number" value={data.layout?.doorWidth} onChange={e => handleLayoutChange('doorWidth', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>

                    <div><label className="text-[9px] uppercase font-bold text-gray-500 block mb-1">Ovládanie</label><select value={data.layout?.doorOperation} onChange={e => handleLayoutChange('doorOperation', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-xs font-bold bg-white"><option value="automatic">Automatické</option><option value="manual">Manuálne</option></select></div>
                    <div><label className="text-[9px] uppercase font-bold text-gray-500 block mb-1">Typ</label><select value={data.layout?.doorType} onChange={e => handleLayoutChange('doorType', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-xs font-bold bg-white"><option value="central">Centrál</option><option value="telescopic">Teleskop</option><option value="bus">BUS</option></select></div>

                    <div><label className="text-[9px] uppercase font-bold text-gray-500 block mb-1">Odolnosť</label><select value={data.layout?.doorFireRating || 'EW60'} onChange={e => handleLayoutChange('doorFireRating', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-1 text-xs font-bold bg-white"><option value="None">Bez</option><option value="EW60">EW60</option><option value="EI60">EI60</option><option value="EI120">EI120</option></select></div>
                    <div><label className="text-[9px] uppercase font-bold text-gray-500 block mb-1">Povrch</label><select value={data.layout?.doorFinish || 'RAL 7032'} onChange={e => handleLayoutChange('doorFinish', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-1 text-xs font-bold bg-white"><option value="RAL 7032">RAL</option><option value="Nerez Brus">Brus</option><option value="Nerez Lesk">Lesk</option><option value="Skinplate">Skin</option></select></div>
                </div>

                {/* 3. Right: Stavebné & Entrances */}
                <div className="col-span-4 grid grid-cols-2 gap-3 p-3 bg-yellow-50/50 rounded-lg border border-yellow-200">
                    <div className="col-span-2 text-xs font-bold text-yellow-800 uppercase border-b border-yellow-200 pb-1 mb-1">Stavebné Údaje</div>

                    <div><label className="text-[9px] uppercase font-bold text-blue-600 block mb-1">DO (Šírka)</label><input type="number" value={data.layout?.doorOpeningWidth} onChange={e => handleLayoutChange('doorOpeningWidth', +e.target.value)} className="w-full h-10 border border-blue-200 rounded px-1 text-center font-bold text-lg bg-white"/></div>
                    <div><label className="text-[9px] uppercase font-bold text-blue-600 block mb-1">VDO (Výška)</label><input type="number" value={data.layout?.doorOpeningHeight} onChange={e => handleLayoutChange('doorOpeningHeight', +e.target.value)} className="w-full h-10 border border-blue-200 rounded px-1 text-center font-bold text-lg bg-white"/></div>

                    <div><label className="text-[9px] uppercase font-bold text-gray-500 block mb-1" title="Ostrenie vľavo">LDO (mm)</label><input type="number" value={data.layout?.LDO} onChange={e => handleLayoutChange('LDO', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-1 text-center font-bold text-lg bg-white"/></div>
                    <div><label className="text-[9px] uppercase font-bold text-gray-500 block mb-1" title="Ostrenie vpravo">RDO (mm)</label><input type="number" value={data.layout?.RDO} onChange={e => handleLayoutChange('RDO', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-1 text-center font-bold text-lg bg-white"/></div>
                </div>
             </div>

             {/* 4. ROW: TECHNOLOGY (RESTORED FULLY) */}
             <div className="grid grid-cols-12 gap-4">
                <div className="col-span-12 font-bold text-amber-900 uppercase flex items-center gap-2 mb-1"><Settings size={16}/> Technológia</div>

                {/* Entrances */}
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Vstupy (Orientácia)</label>
                    <select value={data.layout?.entrances || 'A'} onChange={e => handleLayoutChange('entrances', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-xs font-bold bg-white text-green-700">
                        <option value="A">A (Nepriechodný)</option>
                        <option value="AB">A+B (Prechodný 180°)</option>
                        <option value="AC">A+C (Prechodný 90°)</option>
                    </select>
                </div>

                {/* Drive Type */}
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Typ Pohonu</label>
                    <select value={data.layout?.driveType || 'traction'} onChange={e => handleLayoutChange('driveType', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-xs font-bold bg-white">
                        <option value="traction">Trakčný (Lanový)</option>
                        <option value="hydraulic">Hydraulický</option>
                        <option value="drum">Bubnový</option>
                        <option value="mrl">MRL (Bez strojovne)</option>
                    </select>
                </div>

                {/* Traction Medium */}
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Nosné prostr.</label>
                    <select value={data.layout?.tractionMedium || 'ctp'} onChange={e => handleLayoutChange('tractionMedium', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-xs font-bold bg-white">
                        <option value="ropes">Oceľové Laná</option>
                        <option value="belts">Pásy (Belts)</option>
                        <option value="ctp">CTP Laná</option>
                    </select>
                </div>

                <div className="col-span-2">
                    <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Vodidlá Kabína</label>
                    <select value={data.layout?.guideTypeCar} onChange={e => handleLayoutChange('guideTypeCar', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white">{railTypes.map(r => <option key={r} value={r}>{r}</option>)}</select>
                    {/* RECOMMENDATION BADGE */}
                    {data.layout?.guideTypeCar !== recommendedRails.car && (
                        <button 
                            onClick={() => handleLayoutChange('guideTypeCar', recommendedRails.car)}
                            className="text-[9px] text-orange-600 font-bold mt-1 flex items-center gap-1 hover:text-orange-800 hover:bg-orange-50 rounded px-1 w-full"
                            title="Kliknutím aplikujete odporúčané vodítko"
                        >
                            <Info size={10}/> Odporúčané: {recommendedRails.car}
                        </button>
                    )}
                </div>
                <div className="col-span-2">
                    <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Vodidlá CWT</label>
                    <select value={data.layout?.guideTypeCwt} onChange={e => handleLayoutChange('guideTypeCwt', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white">{railTypes.map(r => <option key={r} value={r}>{r}</option>)}</select>
                    {/* RECOMMENDATION BADGE */}
                    {data.layout?.guideTypeCwt !== recommendedRails.cwt && (
                        <button 
                            onClick={() => handleLayoutChange('guideTypeCwt', recommendedRails.cwt)}
                            className="text-[9px] text-orange-600 font-bold mt-1 flex items-center gap-1 hover:text-orange-800 hover:bg-orange-50 rounded px-1 w-full"
                            title="Kliknutím aplikujete odporúčané vodítko"
                        >
                            <Info size={10}/> Odporúčané: {recommendedRails.cwt}
                        </button>
                    )}
                </div>

                {/* Bracket Type Selector */}
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Typ Konzol</label>
                    <select value={data.layout?.bracketType || 'standard'} onChange={e => handleLayoutChange('bracketType', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white text-blue-700">
                        <option value="standard">Štandard (2x Hlavná)</option>
                        <option value="combined">Kombinované (BUS + Hlavná)</option>
                    </select>
                </div>

                {/* Guide Rail Length Selector */}
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Dĺžka Vodidla</label>
                    <select value={data.layout?.guideRailLength || 5000} onChange={e => handleLayoutChange('guideRailLength', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white">
                        <option value={5000}>5000 mm</option>
                        <option value={2500}>2500 mm</option>
                    </select>
                </div>

                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Rám (Záves)</label><select value={data.layout?.frameType} onChange={e => handleLayoutChange('frameType', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white"><option value="central">Centrálny (Záves)</option><option value="backpack">Ruksak (Backpack)</option></select></div>

                <div className="col-span-2 flex items-end">
                     <button 
                        onClick={() => setIsMaterialModalOpen(true)} 
                        className="w-full h-10 bg-gradient-to-r from-orange-400 to-orange-500 hover:from-orange-500 hover:to-orange-600 text-white font-bold rounded shadow flex items-center justify-center gap-2 text-xs"
                        title="Otvoriť sprievodcu materiálom (Kalkulačka)"
                     >
                        <Calculator size={14}/> Materiálový Sprievodca
                     </button>
                </div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Strojovňa</label><select value={data.layout?.machineRoomPosition} onChange={e => handleLayoutChange('machineRoomPosition', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white"><option value="head">MRL (V šachte)</option><option value="above">Hore</option><option value="cabinet">Skrinka</option></select></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Protiváha</label><select value={data.layout?.counterWeightPosition} onChange={e => handleLayoutChange('counterWeightPosition', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white"><option value="back">Vzadu</option><option value="left">Vľavo</option><option value="right">Vpravo</option></select></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Lanovanie</label><select value={data.layout?.suspensionType} onChange={e => handleLayoutChange('suspensionType', e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-sm font-bold bg-white"><option value="1:1">1:1</option><option value="2:1">2:1</option><option value="4:1">4:1</option></select></div>
             </div>
      </div>

import React, { useState, useEffect, useRef } from 'react';
import { LiftLayoutData, Product, CabinClass } from '../types';
import { X, Calculator, Check, AlertTriangle, Settings, Box, Zap, Construction, Truck, Package, Hammer, ArrowLeft, ArrowRight, ListCheck, Search, Plus, Filter, Layers, Save, Trash2, GripVertical, Gauge, ScanLine, RotateCcw, FileText, Download, Copy, FolderOpen } from 'lucide-react';

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean;
        autoType?: string; // Type identifier for quantity recalculation (e.g. 'rails', 'brackets')
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    categoryOrder: string[];
}

interface MaterialTemplate {
    id: string;
    name: string;
    data: MaterialWizardData;
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen,
  onClose,
  layout,
  onInsert,
  products,
  customCategories,
  onAddCategory,
  cabinClasses
}) => {
  const [tabs, setTabs] = useState<{id: string, label: string, color: string}[]>([]);
  const [activeTab, setActiveTab] = useState('Dvere');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);

  const [activeCategories, setActiveCategories] = useState<Set<string>>(new Set());

  const [isCategorySettingsOpen, setIsCategorySettingsOpen] = useState(false);
  const [isTemplateMenuOpen, setIsTemplateMenuOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);

  const [savedTemplates, setSavedTemplates] = useState<MaterialTemplate[]>([]);
  const [newTemplateName, setNewTemplateName] = useState('');

  const [draggedItemIdx, setDraggedItemIdx] = useState<number | null>(null);
  const isInitialized = useRef(false);

  // --- INITIALIZATION ---

  useEffect(() => {
      const storedTemplates = localStorage.getItem('smartquote_material_templates');
      if (storedTemplates) {
          try {
              setSavedTemplates(JSON.parse(storedTemplates));
          } catch (e) { console.error("Error loading templates", e); }
      }
  }, []);

  useEffect(() => {
      if(isOpen) {
          // Default Categories: ALL Custom Categories except Addons
          // This ensures tabs are visible immediately
          if(activeCategories.size === 0) {
             const defaults = new Set(customCategories.filter(c => !['Montáž', 'Doprava', 'Balné'].includes(c)));
             setActiveCategories(defaults);
          }

          // Try load last state
          const lastStateStr = localStorage.getItem('smartquote_wizard_last_state');
          if (lastStateStr) {
              try {
                  const lastState: MaterialWizardData = JSON.parse(lastStateStr);

                  // RECALCULATE QUANTITIES BASED ON CURRENT LAYOUT
                  const freshQuantities = calculateQuantitiesOnly(layout);

                  // Merge: Update ONLY quantities for items that have matching autoType
                  const updatedItems = lastState.items.map(item => {
                      if (item.isAuto && item.autoType && freshQuantities[item.autoType] !== undefined) {
                          return { ...item, quantity: freshQuantities[item.autoType] };
                      }
                      return item;
                  });

                  setBomItems(updatedItems);

                  setIncludeTransport(lastState.includeTransport);
                  setIncludePackaging(lastState.includePackaging);
                  setIncludeAssembly(lastState.includeAssembly);

                  if (lastState.categoryOrder && lastState.categoryOrder.length > 0) {
                      setActiveCategories(new Set(lastState.categoryOrder));
                  }

                  isInitialized.current = true;
                  return; 
              } catch (e) {}
          }

          // Fallback: Fresh Calculation if no history
          if (!isInitialized.current) {
              // const freshBOM = calculateFullBOM(layout); 
              // PER USER REQUEST: Keep tabs visible (via activeCategories above), but empty items for manual entry
              setBomItems([]); 
              isInitialized.current = true;
          }
      }
  }, [isOpen, layout]); // Recalculate if layout changes when opening

  // Auto-save
  useEffect(() => {
      if (isOpen && isInitialized.current) {
          const currentState: MaterialWizardData = {
              items: bomItems,
              includeTransport,
              includePackaging,
              includeAssembly,
              categoryOrder: Array.from(activeCategories)
          };
          localStorage.setItem('smartquote_wizard_last_state', JSON.stringify(currentState));
      }
  }, [bomItems, includeTransport, includePackaging, includeAssembly, activeCategories, isOpen]);

  // Sync Tabs
  useEffect(() => {
    const generatedTabs = customCategories
        .filter(cat => {
            if (cat === 'Oceľová konštrukcia' && !layout.hasExternalShaft) return false;
            if (['Montáž', 'Doprava', 'Balné'].includes(cat)) return false;
            return activeCategories.has(cat);
        })
        .map(cat => ({
            id: cat,
            label: cat,
            color: 'blue'
        }));

    setTabs(generatedTabs);

    if (generatedTabs.length > 0) {
        if (!generatedTabs.find(t => t.id === activeTab)) {
            setActiveTab(generatedTabs[0].id);
        }
    } else if (generatedTabs.length === 0) {
        // Fallback tab if nothing selected
        setTabs([{id: 'Info', label: 'Info', color: 'gray'}]);
        setActiveTab('Info');
    }
  }, [customCategories, activeCategories, layout.hasExternalShaft, activeTab]);

  // --- CALCULATIONS ---

  // Helper: Just get quantity map based on layout
  const calculateQuantitiesOnly = (l: LiftLayoutData): Record<string, number> => {
      const travel = l.travelHeight || 0;
      const hq = l.headroomHeight || 0;
      const pit = l.pitDepth || 0;
      const totalHeight = travel + hq + pit;
      const railLength = l.guideRailLength || 5000;
      const bracketSpan = 2500; // Standard span
      const stops = l.numberOfStops || 2;

      // 1. RAILS
      // Count per line: Ceiling(Total / Length)
      // Total Car: 2 lines. Total CWT: 2 lines.
      const railLinesCar = 2;
      const railLinesCwt = 2;
      const barsPerLine = Math.ceil(totalHeight / railLength);

      const railsCarTotal = barsPerLine * railLinesCar;
      const railsCwtTotal = barsPerLine * railLinesCwt;

      // 2. FISHPLATES (Spojky)
      // Per line: bars - 1 (min 0)
      const fishplatesPerLine = Math.max(0, barsPerLine - 1);
      const fishplatesTotalCar = fishplatesPerLine * railLinesCar;
      const fishplatesTotalCwt = fishplatesPerLine * railLinesCwt;
      const fishplatesTotal = fishplatesTotalCar + fishplatesTotalCwt;

      // 3. BRACKETS (Konzoly)
      // Logic: 1 at bottom (starts at 500mm usually), then every 2500mm, + 1 at Top.
      // Effective height for brackets = TotalHeight
      // Count = Math.ceil(TotalHeight / Span) + 1 (Base bracket)
      const bracketsPerLine = Math.ceil(totalHeight / bracketSpan) + 1;

      // Main Brackets: 2 lines
      const bracketsMainTotal = bracketsPerLine * 2;

      // CWT Brackets: Always calculated as 2 lines (Left + Right rails supported)
      // Even for backpack, usually implies 2 fastening points per level
      const bracketsCwtTotal = bracketsPerLine * 2;

      // 4. CLIPS (Príchytky)
      // Clips = Total Brackets * 2 (because 1 standard bracket holds 1 rail with 2 clips)
      const clipsCar = bracketsMainTotal * 2;
      const clipsCwt = bracketsCwtTotal * 2; // This results in 4 clips per CWT level (2 rails * 2 clips)
      const clipsTotal = clipsCar + clipsCwt;

      return {
          'rails_car': railsCarTotal,
          'rails_cwt': railsCwtTotal,
          'fishplates': fishplatesTotal,
          'fishplates_car': fishplatesTotalCar,
          'fishplates_cwt': fishplatesTotalCwt,

          'brackets_main': bracketsMainTotal,
          'brackets_cwt': bracketsCwtTotal,

          'clips': clipsTotal,
          'clips_car': clipsCar,
          'clips_cwt': clipsCwt,

          'doors_shaft': stops,
          'doors_car': l.isThroughCar ? 2 : 1,

          'machine': 1,
          'rope_length': Number(((totalHeight * (l.suspensionType === '2:1' ? 2 : 1) * (l.numberOfPersons <= 8 ? 4 : 6) / 1000) + 15).toFixed(1)) // Approx ropes
      };
  };

  const findSmartItem = (keywords: string[], dimension?: number | string, category?: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      if (dimension) {
          const dimStr = String(dimension);
          const exactMatch = products.find(p => {
              const nameLow = p.name.toLowerCase();
              const hasAllKeys = lowerKeys.every(k => nameLow.includes(k));
              const hasDim = nameLow.includes(dimStr);
              const matchCat = category ? p.category === category : true;
              return hasAllKeys && hasDim && matchCat;
          });
          if (exactMatch) return exactMatch;
      }
      return products.find(p => {
          const matchName = lowerKeys.every(k => p.name.toLowerCase().includes(k));
          const matchCat = category ? p.category === category : true;
          return matchName && matchCat;
      });
  };

  const calculateFullBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const qtys = calculateQuantitiesOnly(l);

    // --- CATEGORY MAPPING ---
    const catMap = {
        guides: 'Vodítka a kotvenie',
        doors: 'Dvere',
        cabin: 'Kabína a rám',
        drive: 'Pohon',
        electro: 'Elektro',
        shaftInt: 'Ostatné šachta', 
        construction: 'Oceľová konštrukcia'
    };

    const addItem = (desc: string, qty: number, unit: string, cat: string, autoType: string, keys: string[], dim?: any) => {
        if (qty <= 0) return;
        const product = findSmartItem(keys, dim, cat);
        items.push({
            category: cat,
            description: product ? product.name : desc,
            quantity: Number(qty.toFixed(2)),
            unit: unit,
            productId: product?.id,
            price: product?.price || 0,
            isAuto: true,
            autoType: autoType // CRITICAL: This connects the item to the dynamic calculation
        });
    };

    // 1. GUIDES
    addItem(`Vodidlá Kabína ${l.guideTypeCar} (${l.guideRailLength}mm)`, qtys['rails_car'], 'ks', catMap.guides, 'rails_car', [l.guideTypeCar || 'T90'], l.guideRailLength);
    addItem(`Vodidlá Protiváha ${l.guideTypeCwt} (${l.guideRailLength}mm)`, qtys['rails_cwt'], 'ks', catMap.guides, 'rails_cwt', [l.guideTypeCwt || 'T50'], l.guideRailLength);

    addItem(`Spojka vodidla ${l.guideTypeCar}`, qtys['fishplates_car'], 'ks', catMap.guides, 'fishplates_car', ['spojka', l.guideTypeCar || 'T90']);
    addItem(`Spojka vodidla ${l.guideTypeCwt}`, qtys['fishplates_cwt'], 'ks', catMap.guides, 'fishplates_cwt', ['spojka', l.guideTypeCwt || 'T50']);

    addItem(`Konzola Hlavná (á 2.5m)`, qtys['brackets_main'], 'ks', catMap.guides, 'brackets_main', ['konzola', 'hlavná']);
    addItem(`Konzola Protiváhy (á 2.5m)`, qtys['brackets_cwt'], 'ks', catMap.guides, 'brackets_cwt', ['konzola']); // Generic if distinct

    addItem(`Príchytka vodidla ${l.guideTypeCar}`, qtys['clips_car'], 'ks', catMap.guides, 'clips_car', ['príchytka', l.guideTypeCar || 'T90']);
    addItem(`Príchytka vodidla ${l.guideTypeCwt}`, qtys['clips_cwt'], 'ks', catMap.guides, 'clips_cwt', ['príchytka', l.guideTypeCwt || 'T50']);

    // 2. DOORS
    const sDoorType = l.doorOperation === 'manual' ? 'Krídlové' : 'Automatické';
    addItem(`Šachtové dvere ${sDoorType} ${l.doorWidth}`, qtys['doors_shaft'], 'ks', catMap.doors, 'doors_shaft', ['dvere', sDoorType === 'Krídlové' ? 'krídlové' : 'automatické'], l.doorWidth);
    const cDoorType = l.doorType === 'bus' ? 'BUS' : 'Automatické';
    addItem(`Kabínové dvere ${cDoorType} ${l.doorWidth}`, qtys['doors_car'], 'ks', catMap.doors, 'doors_car', ['dvere', cDoorType === 'BUS' ? 'bus' : 'automatické'], l.doorWidth);

    // 3. CABIN
    let linkedSet = null;
    if (cabinClasses && l.cabinClass) {
        const cls = cabinClasses.find(c => c.name === l.cabinClass);
        if (cls?.linkedProductId) linkedSet = products.find(p => p.id === cls.linkedProductId);
    }
    if (linkedSet) {
        items.push({
            category: catMap.cabin, description: linkedSet.name, quantity: 1, unit: 'ks',
            productId: linkedSet.id, price: linkedSet.price, isAuto: true, autoType: 'cabin_set'
        });
    } else {
        addItem(`Kabína ${l.cabinClass} (${Math.round(l.cabinWidth)}x${Math.round(l.cabinDepth)}mm)`, 1, 'ks', catMap.cabin, 'cabin_set', ['kabína']);
    }
    addItem(`Rám kabíny (${l.frameType})`, 1, 'ks', catMap.cabin, 'car_frame', ['rám', l.frameType === 'backpack' ? 'batoh' : 'rám']);

    // 4. DRIVE
    addItem('Trakčný stroj', 1, 'ks', catMap.drive, 'machine', [l.tractionMedium || 'lan', 'stroj']);

    return items;
  };

  const moveTab = (index: number, direction: 'left' | 'right') => {
      if (direction === 'left' && index === 0) return;
      if (direction === 'right' && index === tabs.length - 1) return;
      const newTabs = [...tabs];
      const targetIndex = direction === 'left' ? index - 1 : index + 1;
      [newTabs[index], newTabs[targetIndex]] = [newTabs[targetIndex], newTabs[index]];
      setTabs(newTabs);
  };

  const toggleCategory = (catId: string) => {
      const newSet = new Set(activeCategories);
      if (newSet.has(catId)) newSet.delete(catId);
      else newSet.add(catId);
      setActiveCategories(newSet);
  };

  const handleAddCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setNewCatName('');
          toggleCategory(newCatName);
      }
  };

  const updateItem = (idx: number, field: string, value: any) => {
      const newItems = [...bomItems];
      // @ts-ignore
      newItems[idx][field] = value;
      if (field === 'productId') {
          const p = products.find(prod => prod.id === value);
          if (p) {
              newItems[idx].price = p.price;
              newItems[idx].description = p.name;
              newItems[idx].unit = p.unit;
          }
      }
      setBomItems(newItems);
  };

  const handleDeleteItem = (index: number) => {
      setBomItems(bomItems.filter((_, i) => i !== index));
  };

  const addCustomItem = (isSet: boolean = false) => {
      setBomItems([...bomItems, { 
          category: activeTab, 
          description: isSet ? 'Výber SETU...' : 'Nová požiadavka', 
          quantity: 1, 
          unit: isSet ? 'set' : 'ks', 
          price: 0,
          isAuto: false 
      }]);
  };

  const handleInsert = () => {
      // Final save before insert
      const currentState = {
          items: bomItems,
          includeTransport,
          includePackaging,
          includeAssembly,
          categoryOrder: Array.from(activeCategories)
      };
      localStorage.setItem('smartquote_wizard_last_state', JSON.stringify(currentState));

      onInsert({
          ...currentState,
          categoryOrder: tabs.map(t => t.id)
      });
      onClose();
  };

  // --- TEMPLATES ---
  const handleSaveTemplate = () => {
      if(!newTemplateName.trim()) return;
      const newTemplate: MaterialTemplate = {
          id: crypto.randomUUID(),
          name: newTemplateName,
          data: {
              items: bomItems,
              includeTransport, includePackaging, includeAssembly,
              categoryOrder: Array.from(activeCategories)
          }
      };
      const updated = [...savedTemplates, newTemplate];
      setSavedTemplates(updated);
      localStorage.setItem('smartquote_material_templates', JSON.stringify(updated));
      setNewTemplateName('');
      alert("Šablóna uložená.");
  };

  const handleLoadTemplate = (template: MaterialTemplate) => {
      if(window.confirm(`Načítať šablónu "${template.name}"?`)) {
          // When loading template, we also try to update quantities if possible
          const freshQuantities = calculateQuantitiesOnly(layout);
          const updatedTemplateItems = template.data.items.map(item => {
               if (item.isAuto && item.autoType && freshQuantities[item.autoType] !== undefined) {
                   return { ...item, quantity: freshQuantities[item.autoType] };
               }
               return item;
          });

          setBomItems(updatedTemplateItems);
          setIncludeTransport(template.data.includeTransport);
          setIncludePackaging(template.data.includePackaging);
          setIncludeAssembly(template.data.includeAssembly);
          if (template.data.categoryOrder) {
              setActiveCategories(new Set(template.data.categoryOrder));
          }
          setIsTemplateMenuOpen(false);
      }
  };

  const handleDeleteTemplate = (id: string) => {
      if(window.confirm("Vymazať šablónu?")) {
          const updated = savedTemplates.filter(t => t.id !== id);
          setSavedTemplates(updated);
          localStorage.setItem('smartquote_material_templates', JSON.stringify(updated));
      }
  };

  const handleResetToDefaults = () => {
      if(window.confirm("Týmto zahodíte manuálne zmeny a prepočítate zoznam podľa aktuálnych rozmerov výťahu (šírka, zdvih, atď.). Pokračovať?")) {
          const fresh = calculateFullBOM(layout);
          // Keep only active categories
          const filtered = fresh.filter(i => activeCategories.has(i.category));
          setBomItems(filtered);
      }
  };

  // Drag handlers
  const onDragStartItem = (e: React.DragEvent, index: number) => {
      setDraggedItemIdx(index);
      e.dataTransfer.effectAllowed = 'move';
  };
  const onDragOverItem = (e: React.DragEvent, targetIndex: number) => {
      e.preventDefault();
      if (draggedItemIdx === null || draggedItemIdx === targetIndex) return;
      const newItems = [...bomItems];
      const [reorderedItem] = newItems.splice(draggedItemIdx, 1);
      newItems.splice(targetIndex, 0, reorderedItem);
      setBomItems(newItems);
      setDraggedItemIdx(targetIndex);
  };

  if (!isOpen) return null;

  const currentCatName = activeTab;
  const currentItems = bomItems.map((item, index) => ({ item, index })).filter(({ item }) => item.category === currentCatName);
  const categoryProducts = products.filter(p => p.category === currentCatName);
  const subcategories = Array.from(new Set(categoryProducts.map(p => p.subcategory || 'Ostatné'))).sort();

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Calculator className="text-orange-500" />
            <div>
                <h2 className="text-xl font-bold text-gray-800">Materiálový Sprievodca</h2>
                <div className="text-xs text-gray-500">Automatický výpočet komponentov</div>
            </div>
          </div>

          <div className="flex gap-2 relative">
               <button onClick={() => setIsTemplateMenuOpen(!isTemplateMenuOpen)} className={`px-3 py-2 rounded-lg border flex items-center gap-2 text-sm font-bold transition ${isTemplateMenuOpen ? 'bg-purple-100 text-purple-700 border-purple-300 shadow-inner' : 'text-gray-600 hover:bg-gray-100'}`}>
                   <FolderOpen size={16}/> Šablóny
               </button>
               <button onClick={() => setIsCategorySettingsOpen(!isCategorySettingsOpen)} className={`p-2 rounded-full border transition ${isCategorySettingsOpen ? 'bg-blue-100 text-blue-600 border-blue-300' : 'text-gray-500 hover:bg-gray-100'}`} title="Správa Kategórií">
                    <Filter size={20}/>
               </button>
               <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
          </div>
        </div>

        {/* TEMPLATE MENU */}
        {isTemplateMenuOpen && (
            <div className="absolute top-16 right-4 z-[150] bg-white border border-purple-200 p-4 shadow-2xl rounded-xl w-[320px] animate-in fade-in slide-in-from-top-2">
                <div className="space-y-4">
                    <div className="bg-purple-50 p-3 rounded-lg border border-purple-100">
                        <h4 className="text-xs font-bold text-purple-800 uppercase mb-2 flex items-center gap-2"><Save size={14}/> Uložiť novú šablónu</h4>
                        <div className="flex gap-2">
                            <input className="border rounded px-2 py-1 text-sm flex-1 bg-white" placeholder="Názov..." value={newTemplateName} onChange={e => setNewTemplateName(e.target.value)} />
                            <button onClick={handleSaveTemplate} className="bg-purple-600 text-white px-3 py-1 rounded text-sm font-bold hover:bg-purple-700">Uložiť</button>
                        </div>
                    </div>
                    <div>
                        <h4 className="text-xs font-bold text-gray-500 uppercase mb-2">Uložené</h4>
                        <div className="space-y-1 max-h-48 overflow-y-auto border rounded p-1 bg-gray-50 custom-scrollbar">
                            {savedTemplates.length === 0 && <div className="text-gray-400 text-xs italic p-2 text-center">Žiadne šablóny.</div>}
                            {savedTemplates.map(t => (
                                <div key={t.id} className="flex justify-between items-center p-2 hover:bg-white border border-transparent hover:border-gray-200 rounded cursor-pointer" onClick={() => handleLoadTemplate(t)}>
                                    <span className="text-sm font-bold text-gray-700 truncate">{t.name}</span>
                                    <button onClick={(e) => { e.stopPropagation(); handleDeleteTemplate(t.id); }} className="text-red-400 hover:bg-red-100 p-1 rounded"><Trash2 size={14}/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Category Settings */}
        {isCategorySettingsOpen && (
            <div className="bg-gray-50 border-b p-4 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4 shadow-inner max-h-48 overflow-y-auto">
                {customCategories.filter(c => !['Montáž','Doprava','Balné'].includes(c)).map(c => (
                    <label key={c} className="flex items-center gap-2 cursor-pointer bg-white border p-2 rounded shadow-sm hover:bg-blue-50">
                        <input type="checkbox" checked={activeCategories.has(c)} onChange={() => toggleCategory(c)} className="rounded text-blue-600"/>
                        <span className="text-sm font-medium break-all">{c}</span>
                    </label>
                ))}
                <div className="col-span-full flex gap-2 pt-2 border-t mt-2">
                    <input className="border rounded px-2 py-1 text-sm w-48" placeholder="Nová kategória..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleAddCategory()}/>
                    <button onClick={handleAddCategory} className="px-3 py-1 bg-blue-600 text-white rounded text-xs font-bold">Pridať</button>
                </div>
            </div>
        )}

        {/* Tabs */}
        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-2 py-2 transition ${activeTab===tab.id ? 'bg-white border-gray-300' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`}>
                     {activeTab === tab.id && idx > 0 && <button onClick={() => moveTab(idx, 'left')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowLeft size={12}/></button>}
                     <button onClick={() => setActiveTab(tab.id)} className={`mx-2 text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? `text-${tab.color}-600` : 'text-gray-500'}`}>{tab.label}</button>
                     {activeTab === tab.id && idx < tabs.length - 1 && <button onClick={() => moveTab(idx, 'right')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowRight size={12}/></button>}
                 </div>
            ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">
            {currentItems.length === 0 && <div className="text-center text-gray-400 italic py-8">Žiadne položky v tejto kategórii.</div>}

            {currentItems.length > 0 && (
            <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                        <tr>
                            <th className="w-8"></th>
                            <th className="p-3 text-left w-1/3">Požiadavka (Výpočet)</th>
                            <th className="p-3 text-left w-1/3">Produkt zo Skladu</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {currentItems.map(({ item, index: originalIndex }) => {
                            return (
                                <tr 
                                    key={originalIndex} 
                                    draggable
                                    onDragStart={(e) => onDragStartItem(e, originalIndex)}
                                    onDragOver={(e) => onDragOverItem(e, originalIndex)}
                                    className={`transition ${item.isAuto ? 'hover:bg-blue-50' : 'bg-yellow-50 hover:bg-yellow-100'}`}
                                >
                                    <td className="p-2 text-center text-gray-300 cursor-grab hover:text-gray-500"><GripVertical size={16}/></td>
                                    <td className="p-3 relative">
                                        <input value={item.description} onChange={e => updateItem(originalIndex, 'description', e.target.value)} className="w-full bg-transparent font-medium text-gray-800 focus:outline-none"/>
                                        {!item.isAuto && <span className="text-[9px] font-bold text-yellow-600 uppercase absolute top-1 right-2 bg-yellow-100 px-1 rounded">Manual</span>}
                                        {item.isAuto && item.autoType && <span className="text-[9px] font-bold text-blue-600 uppercase absolute top-1 right-2 bg-blue-100 px-1 rounded">Auto: {item.autoType}</span>}
                                    </td>
                                    <td className="p-3">
                                        <div className="relative">
                                            <select value={item.productId || ''} onChange={e => updateItem(originalIndex, 'productId', e.target.value)} className={`w-full p-2 border rounded text-sm font-bold ${item.productId ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-400 border-gray-200'}`}>
                                                <option value="">-- Vybrať produkt --</option>
                                                {subcategories.map(subcat => {
                                                    const subProds = categoryProducts.filter(p => (p.subcategory || 'Ostatné') === subcat);
                                                    return (
                                                        <optgroup key={subcat} label={subcat}>
                                                            {subProds.sort((a,b) => (a.type === 'composite' ? -1 : 1)).map(p => (
                                                                <option key={p.id} value={p.id}>{p.type === 'composite' ? '📦 ' : ''}{p.name} ({p.price}€)</option>
                                                            ))}
                                                        </optgroup>
                                                    );
                                                })}
                                            </select>
                                            {!item.productId && <div title="Položka nie je spárovaná so skladom" className="absolute right-8 top-1/2 -translate-y-1/2 text-orange-400 pointer-events-none"><AlertTriangle size={14} /></div>}
                                        </div>
                                    </td>
                                    <td className="p-3 text-right"><input type="number" value={item.quantity} onChange={e => updateItem(originalIndex, 'quantity', +e.target.value)} className="w-full text-right font-bold text-blue-600 bg-transparent focus:outline-none text-base"/></td>
                                    <td className="p-3 text-right font-mono text-gray-600">{item.price ? item.price.toFixed(2) : '-'} €</td>
                                    <td className="p-3 text-center"><button onClick={() => handleDeleteItem(originalIndex)} className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition"><Trash2 size={16}/></button></td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            )}

            <div className="flex gap-2">
                <button onClick={() => addCustomItem(false)} className="flex-1 py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-600 hover:bg-blue-50 transition flex justify-center items-center gap-2 font-medium"><Plus size={18} /> Pridať vlastnú požiadavku</button>
                <button onClick={() => addCustomItem(true)} className="flex-1 py-3 border-2 border-dashed border-purple-300 rounded-lg text-purple-600 hover:border-purple-500 hover:bg-purple-50 transition flex justify-center items-center gap-2 font-bold bg-purple-50/50"><Layers size={18} /> + Pridať SET</button>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 bg-blue-50 p-3 rounded border border-blue-100">
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Hammer size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Montáž technológie</span></label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Truck size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Doprava materiálu</span></label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Package size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Balné a manipulácia</span></label>
            </div>

            <div className="flex justify-between items-center">
                <button onClick={handleResetToDefaults} className="text-xs text-orange-600 hover:text-orange-800 font-bold flex items-center gap-2 px-3 py-1 bg-orange-50 rounded border border-orange-200" title="Zahodiť manuálne zmeny a prepočítať podľa layoutu"><RotateCcw size={14}/> Prepočítať podľa aktuálneho výťahu</button>
                <div className="flex gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium transition">Zrušiť</button>
                    <button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold flex items-center gap-2 shadow-sm transition"><Check size={18} /> Potvrdiť a Vložiť</button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

