            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 bg-blue-50 p-3 rounded border border-blue-100">
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Hammer size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Montáž technológie</span></label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Truck size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Doprava materiálu</span></label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Package size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Balné a manipulácia</span></label>
            </div>

            <div className="flex justify-between items-center">
                <button onClick={handleResetToDefaults} className="text-xs text-orange-600 hover:text-orange-800 font-bold flex items-center gap-2 px-3 py-1 bg-orange-50 rounded border border-orange-200" title="Zahodiť manuálne zmeny a prepočítať podľa layoutu"><RotateCcw size={14}/> Prepočítať podľa aktuálneho výťahu</button>
                <div className="flex gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium transition">Zrušiť</button>
                    <button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold flex items-center gap-2 shadow-sm transition"><Check size={18} /> Potvrdiť a Vložiť</button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, ClipboardList, AlertTriangle, Settings, ShieldCheck, Zap } from 'lucide-react';
import { LiftLayoutSketch } from './LiftLayoutSketch';

interface TechSpecTableProps {
  data: LiftLayoutData;
  isVisible: boolean;
  onToggleVisibility: () => void;
  embedded?: boolean;
}

export const TechSpecTable: React.FC<TechSpecTableProps> = ({
  data,
  isVisible,
  onToggleVisibility,
  embedded = false
}) => {

  const getLiftTypeLabel = (val: string) => {
      const map: Record<string, string> = { 
          'passenger': 'Osobný výťah', 
          'freight': 'Nákladný výťah', 
          'home': 'Domáci výťah', 
          'hospital': 'Lôžkový výťah',
          'invalid': 'Invalidný (EN81-70)'
      };
      return map[val] || val;
  };
  const getDriveLabel = (val: string) => {
      const map: Record<string, string> = { 'traction': 'Trakčný', 'hydraulic': 'Hydraulický', 'mrl': 'MRL (Bez strojovne)', 'drum': 'Bubnový' };
      return map[val] || val;
  };
  const getDoorLabel = (val?: string) => {
      const map: Record<string, string> = { 'central': 'Automatické Centrálne', 'telescopic': 'Automatické Teleskopické', 'bus': 'Ručné + BUS (Sklápacie)' };
      return map[val || 'central'] || val;
  };

  const getTractionLabel = (val?: string) => {
      if (val === 'belts') return 'Pásy (Certifikované)';
      if (val === 'ctp') return 'CTP Laná (Plast)';
      return 'Oceľové laná';
  };

  const getSafetyMeasures = () => {
      const measures = [];
      if (data.pitDepth < 1100 || data.headroomHeight < 3400) {
          measures.push("Znížená hlava/priehlbeň (EN 81-21)");
      }
      if (data.liftType === 'invalid') {
          measures.push("Výbava invalid (EN 81-70)");
      }
      return measures;
  };

  const getEntrancesLabel = () => {
      const e = data.entrances || 'A';
      if (e === 'AB') return 'A+B (Prechodný 180°)';
      if (e === 'AC') return 'A+C (Prechodný 90°)';
      return 'A (Nepriechodný)';
  };

  const safetyMeasures = getSafetyMeasures();
  const stationCount = data.stationLabels ? data.stationLabels.split(',').length : 0;

  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border-2 border-dashed border-gray-300 rounded-lg bg-gray-50 text-gray-400 flex justify-between items-center hover:bg-gray-100 transition cursor-pointer" onClick={onToggleVisibility}>
              <span className="flex items-center gap-2 font-bold uppercase text-sm"><ClipboardList size={18}/> Technická špecifikácia (Skrytá)</span>
              <Eye size={20}/>
          </div>
      );
  }

  // Optimized Single Column Row - Compact Print Version (py-2 -> py-1)
  const DataRow = ({ label, value, subValue, highlight = false, isLast = false }: any) => (
      <div className={`flex items-baseline justify-between px-4 py-1 border-b border-gray-200 ${highlight ? 'bg-gray-50/80' : ''} ${isLast ? 'border-b-0' : ''}`}>
          <div className="w-1/3">
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest block">{label}</span>
          </div>
          <div className="w-2/3 text-right">
              <div className="text-[13px] font-bold text-gray-900 leading-tight">{value}</div>
              {subValue && <div className="text-[10px] text-gray-500 font-medium mt-0.5">{subValue}</div>}
          </div>
      </div>
  );

  const Content = (
      <div className="bg-white flex flex-row items-stretch border-b border-gray-200">

          {/* LEFT COLUMN: SPECS (50%) - Determines Height */}
          <div className="w-1/2 flex flex-col border-r-2 border-gray-100">
              {/* Header */}
              <div className="px-4 py-2 border-b-2 border-gray-800 bg-white">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <div className="bg-gray-900 text-white p-1 rounded">
                            <Settings size={14} />
                        </div>
                        <h3 className="text-sm font-bold text-gray-900 uppercase tracking-widest">Technické Parametre</h3>
                    </div>
                    {!embedded && (
                      <button onClick={onToggleVisibility} className="text-gray-300 hover:text-blue-600 transition no-print">
                          <Eye size={16} />
                      </button>
                    )}
                  </div>
              </div>

              {/* Data Rows - Single Stack */}
              <div className="flex-col justify-start">
                  <DataRow label="Zariadenie" value={getLiftTypeLabel(data.liftType)} subValue={`Pohon: ${getDriveLabel(data.driveType)}`} highlight/>
                  <DataRow label="Nosnosť / Osoby" value={`${data.ratedLoad} kg`} subValue={`${data.numberOfPersons} osôb (podľa EN 81-20)`} />
                  <DataRow label="Kabína" value={data.cabinClass || 'FUN'} subValue="Povrch: Podľa vzorkovníka" highlight/>
                  <DataRow label="Rozmery Kabíny" value={`${Math.round(data.cabinWidth)} x ${Math.round(data.cabinDepth)} mm`} subValue={`Výška: ${data.cabinHeight || 2100} mm`} />
                  <DataRow label="Dvere / Vstupy" value={getEntrancesLabel()} subValue={`${getDoorLabel(data.doorType)} (${data.doorWidth}x${data.doorOpeningHeight})`} highlight/>
                  <DataRow label="Rozmery Šachty" value={`${data.shaftWidth} x ${data.shaftDepth} mm`} subValue={`Hlava: ${data.headroomHeight} / Priehlbeň: ${data.pitDepth}`} />
                  <DataRow label="Zdvih / Stanice" value={`${(data.travelHeight/1000).toFixed(2)} m`} subValue={`${stationCount} Staníc / ${data.numberOfStops} Nástupíšť`} highlight/>
                  <DataRow label="Pohon / Riadenie" value="VVVF + CANopen 417" subValue={`Rýchlosť: ${data.ratedSpeed} m/s`} />
                  <DataRow label="Strojovňa" value={data.machineRoomPosition === 'head' ? 'Bez strojovne (MRL)' : 'Strojovňa'} subValue={`Napájanie: ${data.powerSupply}`} highlight/>
                  <DataRow label="Nosné prostriedky" value={getTractionLabel(data.tractionMedium)} subValue={`Lanovanie: ${data.suspensionType}`} isLast={true} />
              </div>

              {/* Footer (Notes/Safety) - Clean bottom block */}
              <div className="border-t-2 border-gray-800 bg-gray-50 p-2 mt-auto">
                  {safetyMeasures.length > 0 ? (
                      <div className="space-y-1">
                          {safetyMeasures.map((m, i) => (
                              <div key={i} className="flex items-start gap-2 text-[9px] font-bold text-red-700 uppercase">
                                  <AlertTriangle size={12} className="shrink-0 mt-0.5"/> <span>{m}</span>
                              </div>
                          ))}
                      </div>
                  ) : (
                      <div className="text-[9px] text-gray-400 uppercase font-bold flex items-center gap-2">
                          <ShieldCheck size={12}/> Plne v súlade s STN EN 81-20/50
                      </div>
                  )}
                  {data.notes && <div className="mt-1 text-[9px] italic text-gray-600 border-t border-gray-200 pt-1 leading-tight">{data.notes}</div>}
              </div>
          </div>

          {/* RIGHT COLUMN: SKETCH (50%) - Fits height of text automatically due to flex stretch */}
          <div className="w-1/2 bg-white flex flex-col relative overflow-hidden">
              <div className="absolute top-0 right-0 bg-gray-100 text-gray-500 text-[9px] font-bold uppercase px-2 py-1 z-10 rounded-bl border-b border-l border-gray-200">
                  Pôdorys
              </div>

              {/* Sketch Container - H-FULL to fill the flex container height determined by the text column */}
              <div className="flex-1 flex items-center justify-center p-0 h-full w-full">
                  <LiftLayoutSketch data={data} isVisible={true} />
              </div>
          </div>
      </div>
  );

  if (embedded) return <div className="border-2 border-gray-800 rounded-xl overflow-hidden shadow-sm bg-white">{Content}</div>;

  return (
    <div className="mb-8 break-inside-avoid border-2 border-gray-800 rounded-xl overflow-hidden shadow-md bg-white">
        {Content}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { LiftLayoutData, Product, CabinClass } from '../types';
import { X, Calculator, Check, AlertTriangle, Settings, Box, Zap, Construction, Truck, Package, Hammer, ArrowLeft, ArrowRight, ListCheck, Search, Plus, Filter, Layers, Save, Trash2, GripVertical, Gauge, ScanLine, RotateCcw, FileText, Download, Copy, FolderOpen } from 'lucide-react';

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean;
        autoType?: string; // Type identifier for quantity recalculation (e.g. 'rails', 'brackets')
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    categoryOrder: string[];
}

interface MaterialTemplate {
    id: string;
    name: string;
    data: MaterialWizardData;
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen,
  onClose,
  layout,
  onInsert,
  products,
  customCategories,
  onAddCategory,
  cabinClasses
}) => {
  const [tabs, setTabs] = useState<{id: string, label: string, color: string}[]>([]);
  const [activeTab, setActiveTab] = useState('Dvere');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);

  const [activeCategories, setActiveCategories] = useState<Set<string>>(new Set());

  const [isCategorySettingsOpen, setIsCategorySettingsOpen] = useState(false);
  const [isTemplateMenuOpen, setIsTemplateMenuOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);

  const [savedTemplates, setSavedTemplates] = useState<MaterialTemplate[]>([]);
  const [newTemplateName, setNewTemplateName] = useState('');

  const [draggedItemIdx, setDraggedItemIdx] = useState<number | null>(null);
  const isInitialized = useRef(false);

  // --- INITIALIZATION ---

  useEffect(() => {
      const storedTemplates = localStorage.getItem('smartquote_material_templates');
      if (storedTemplates) {
          try {
              setSavedTemplates(JSON.parse(storedTemplates));
          } catch (e) { console.error("Error loading templates", e); }
      }
  }, []);

  useEffect(() => {
      if(isOpen) {
          // Default Categories: ALL Custom Categories except Addons
          // This ensures tabs are visible immediately
          if(activeCategories.size === 0) {
             const defaults = new Set(customCategories.filter(c => !['Montáž', 'Doprava', 'Balné'].includes(c)));
             setActiveCategories(defaults);
          }

          // Try load last state
          const lastStateStr = localStorage.getItem('smartquote_wizard_last_state');
          if (lastStateStr) {
              try {
                  const lastState: MaterialWizardData = JSON.parse(lastStateStr);

                  // RECALCULATE QUANTITIES BASED ON CURRENT LAYOUT
                  const freshQuantities = calculateQuantitiesOnly(layout);

                  // Merge: Update ONLY quantities for items that have matching autoType
                  const updatedItems = lastState.items.map(item => {
                      if (item.isAuto && item.autoType && freshQuantities[item.autoType] !== undefined) {
                          return { ...item, quantity: freshQuantities[item.autoType] };
                      }
                      return item;
                  });

                  setBomItems(updatedItems);

                  setIncludeTransport(lastState.includeTransport);
                  setIncludePackaging(lastState.includePackaging);
                  setIncludeAssembly(lastState.includeAssembly);

                  if (lastState.categoryOrder && lastState.categoryOrder.length > 0) {
                      setActiveCategories(new Set(lastState.categoryOrder));
                  }

                  isInitialized.current = true;
                  return; 
              } catch (e) {}
          }

          // Fallback: Fresh Calculation if no history
          if (!isInitialized.current) {
              const freshBOM = calculateFullBOM(layout); 
              setBomItems(freshBOM); // RESTORED: Auto-populate on first open
              isInitialized.current = true;
          }
      }
  }, [isOpen, layout]); // Recalculate if layout changes when opening

  // Auto-save
  useEffect(() => {
      if (isOpen && isInitialized.current) {
          const currentState: MaterialWizardData = {
              items: bomItems,
              includeTransport,
              includePackaging,
              includeAssembly,
              categoryOrder: Array.from(activeCategories)
          };
          localStorage.setItem('smartquote_wizard_last_state', JSON.stringify(currentState));
      }
  }, [bomItems, includeTransport, includePackaging, includeAssembly, activeCategories, isOpen]);

  // Sync Tabs
  useEffect(() => {
    const generatedTabs = customCategories
        .filter(cat => {
            if (cat === 'Oceľová konštrukcia' && !layout.hasExternalShaft) return false;
            if (['Montáž', 'Doprava', 'Balné'].includes(cat)) return false;
            return activeCategories.has(cat);
        })
        .map(cat => ({
            id: cat,
            label: cat,
            color: 'blue'
        }));

    setTabs(generatedTabs);

    if (generatedTabs.length > 0) {
        if (!generatedTabs.find(t => t.id === activeTab)) {
            setActiveTab(generatedTabs[0].id);
        }
    } else if (generatedTabs.length === 0) {
        // Fallback tab if nothing selected
        setTabs([{id: 'Info', label: 'Info', color: 'gray'}]);
        setActiveTab('Info');
    }
  }, [customCategories, activeCategories, layout.hasExternalShaft, activeTab]);

  // --- CALCULATIONS ---

  // Helper: Just get quantity map based on layout
  const calculateQuantitiesOnly = (l: LiftLayoutData): Record<string, number> => {
      const travel = l.travelHeight || 0;
      const hq = l.headroomHeight || 0;
      const pit = l.pitDepth || 0;
      const totalHeight = travel + hq + pit;
      const railLength = l.guideRailLength || 5000;
      const bracketSpan = 2500; // Standard span
      const stops = l.numberOfStops || 2;

      // 1. RAILS
      // Count per line: Ceiling(Total / Length)
      // Total Car: 2 lines. Total CWT: 2 lines.
      const railLinesCar = 2;
      const railLinesCwt = 2;
      const barsPerLine = Math.ceil(totalHeight / railLength);

      const railsCarTotal = barsPerLine * railLinesCar;
      const railsCwtTotal = barsPerLine * railLinesCwt;

      // 2. FISHPLATES (Spojky)
      // Per line: bars - 1 (min 0)
      const fishplatesPerLine = Math.max(0, barsPerLine - 1);
      const fishplatesTotalCar = fishplatesPerLine * railLinesCar;
      const fishplatesTotalCwt = fishplatesPerLine * railLinesCwt;
      const fishplatesTotal = fishplatesTotalCar + fishplatesTotalCwt;

      // 3. BRACKETS (Konzoly)
      // Logic: 1 at bottom (starts at 500mm usually), then every 2500mm, + 1 at Top.
      // Effective height for brackets = TotalHeight
      // Count = Math.ceil(TotalHeight / Span) + 1 (Base bracket)
      const bracketsPerLine = Math.ceil(totalHeight / bracketSpan) + 1;

      // Main Brackets: 2 lines
      const bracketsMainTotal = bracketsPerLine * 2;

      // CWT Brackets: Always calculated as 2 lines (Left + Right rails supported)
      // Even for backpack, usually implies 2 fastening points per level
      const bracketsCwtTotal = bracketsPerLine * 2;

      // 4. CLIPS (Príchytky)
      // Clips = Total Brackets * 2 (because 1 standard bracket holds 1 rail with 2 clips)
      const clipsCar = bracketsMainTotal * 2;
      const clipsCwt = bracketsCwtTotal * 2; // This results in 4 clips per CWT level (2 rails * 2 clips)
      const clipsTotal = clipsCar + clipsCwt;

      return {
          'rails_car': railsCarTotal,
          'rails_cwt': railsCwtTotal,
          'fishplates': fishplatesTotal,
          'fishplates_car': fishplatesTotalCar,
          'fishplates_cwt': fishplatesTotalCwt,

          'brackets_main': bracketsMainTotal,
          'brackets_cwt': bracketsCwtTotal,

          'clips': clipsTotal,
          'clips_car': clipsCar,
          'clips_cwt': clipsCwt,

          'doors_shaft': stops,
          'doors_car': l.isThroughCar ? 2 : 1,

          'machine': 1,
          'rope_length': Number(((totalHeight * (l.suspensionType === '2:1' ? 2 : 1) * (l.numberOfPersons <= 8 ? 4 : 6) / 1000) + 15).toFixed(1)) // Approx ropes
      };
  };

  const findSmartItem = (keywords: string[], dimension?: number | string, category?: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      if (dimension) {
          const dimStr = String(dimension);
          const exactMatch = products.find(p => {
              const nameLow = p.name.toLowerCase();
              const hasAllKeys = lowerKeys.every(k => nameLow.includes(k));
              const hasDim = nameLow.includes(dimStr);
              const matchCat = category ? p.category === category : true;
              return hasAllKeys && hasDim && matchCat;
          });
          if (exactMatch) return exactMatch;
      }
      return products.find(p => {
          const matchName = lowerKeys.every(k => p.name.toLowerCase().includes(k));
          const matchCat = category ? p.category === category : true;
          return matchName && matchCat;
      });
  };

  const calculateFullBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const qtys = calculateQuantitiesOnly(l);

    // --- CATEGORY MAPPING ---
    const catMap = {
        guides: 'Vodítka a kotvenie',
        doors: 'Dvere',
        cabin: 'Kabína a rám',
        drive: 'Pohon',
        electro: 'Elektro',
        shaftInt: 'Ostatné šachta', 
        construction: 'Oceľová konštrukcia'
    };

    const addItem = (desc: string, qty: number, unit: string, cat: string, autoType: string, keys: string[], dim?: any) => {
        if (qty <= 0) return;
        const product = findSmartItem(keys, dim, cat);
        items.push({
            category: cat,
            description: product ? product.name : desc,
            quantity: Number(qty.toFixed(2)),
            unit: unit,
            productId: product?.id,
            price: product?.price || 0,
            isAuto: true,
            autoType: autoType // CRITICAL: This connects the item to the dynamic calculation
        });
    };

    // 1. GUIDES
    addItem(`Vodidlá Kabína ${l.guideTypeCar} (${l.guideRailLength}mm)`, qtys['rails_car'], 'ks', catMap.guides, 'rails_car', [l.guideTypeCar || 'T90'], l.guideRailLength);
    addItem(`Vodidlá Protiváha ${l.guideTypeCwt} (${l.guideRailLength}mm)`, qtys['rails_cwt'], 'ks', catMap.guides, 'rails_cwt', [l.guideTypeCwt || 'T50'], l.guideRailLength);

    addItem(`Spojka vodidla ${l.guideTypeCar}`, qtys['fishplates_car'], 'ks', catMap.guides, 'fishplates_car', ['spojka', l.guideTypeCar || 'T90']);
    addItem(`Spojka vodidla ${l.guideTypeCwt}`, qtys['fishplates_cwt'], 'ks', catMap.guides, 'fishplates_cwt', ['spojka', l.guideTypeCwt || 'T50']);

    addItem(`Konzola Hlavná (á 2.5m)`, qtys['brackets_main'], 'ks', catMap.guides, 'brackets_main', ['konzola', 'hlavná']);
    addItem(`Konzola Protiváhy (á 2.5m)`, qtys['brackets_cwt'], 'ks', catMap.guides, 'brackets_cwt', ['konzola']); // Generic if distinct

    addItem(`Príchytka vodidla ${l.guideTypeCar}`, qtys['clips_car'], 'ks', catMap.guides, 'clips_car', ['príchytka', l.guideTypeCar || 'T90']);
    addItem(`Príchytka vodidla ${l.guideTypeCwt}`, qtys['clips_cwt'], 'ks', catMap.guides, 'clips_cwt', ['príchytka', l.guideTypeCwt || 'T50']);

    // 2. DOORS
    const sDoorType = l.doorOperation === 'manual' ? 'Krídlové' : 'Automatické';
    addItem(`Šachtové dvere ${sDoorType} ${l.doorWidth}`, qtys['doors_shaft'], 'ks', catMap.doors, 'doors_shaft', ['dvere', sDoorType === 'Krídlové' ? 'krídlové' : 'automatické'], l.doorWidth);
    const cDoorType = l.doorType === 'bus' ? 'BUS' : 'Automatické';
    addItem(`Kabínové dvere ${cDoorType} ${l.doorWidth}`, qtys['doors_car'], 'ks', catMap.doors, 'doors_car', ['dvere', cDoorType === 'BUS' ? 'bus' : 'automatické'], l.doorWidth);

    // 3. CABIN
    let linkedSet = null;
    if (cabinClasses && l.cabinClass) {
        const cls = cabinClasses.find(c => c.name === l.cabinClass);
        if (cls?.linkedProductId) linkedSet = products.find(p => p.id === cls.linkedProductId);
    }
    if (linkedSet) {
        items.push({
            category: catMap.cabin, description: linkedSet.name, quantity: 1, unit: 'ks',
            productId: linkedSet.id, price: linkedSet.price, isAuto: true, autoType: 'cabin_set'
        });
    } else {
        addItem(`Kabína ${l.cabinClass} (${Math.round(l.cabinWidth)}x${Math.round(l.cabinDepth)}mm)`, 1, 'ks', catMap.cabin, 'cabin_set', ['kabína']);
    }
    addItem(`Rám kabíny (${l.frameType})`, 1, 'ks', catMap.cabin, 'car_frame', ['rám', l.frameType === 'backpack' ? 'batoh' : 'rám']);

    // 4. DRIVE
    addItem('Trakčný stroj', 1, 'ks', catMap.drive, 'machine', [l.tractionMedium || 'lan', 'stroj']);

    return items;
  };

  const moveTab = (index: number, direction: 'left' | 'right') => {
      if (direction === 'left' && index === 0) return;
      if (direction === 'right' && index === tabs.length - 1) return;
      const newTabs = [...tabs];
      const targetIndex = direction === 'left' ? index - 1 : index + 1;
      [newTabs[index], newTabs[targetIndex]] = [newTabs[targetIndex], newTabs[index]];
      setTabs(newTabs);
  };

  const toggleCategory = (catId: string) => {
      const newSet = new Set(activeCategories);
      if (newSet.has(catId)) newSet.delete(catId);
      else newSet.add(catId);
      setActiveCategories(newSet);
  };

  const handleAddCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setNewCatName('');
          toggleCategory(newCatName);
      }
  };

  const updateItem = (idx: number, field: string, value: any) => {
      const newItems = [...bomItems];
      // @ts-ignore
      newItems[idx][field] = value;
      if (field === 'productId') {
          const p = products.find(prod => prod.id === value);
          if (p) {
              newItems[idx].price = p.price;
              newItems[idx].description = p.name;
              newItems[idx].unit = p.unit;
          }
      }
      setBomItems(newItems);
  };

  const handleDeleteItem = (index: number) => {
      setBomItems(bomItems.filter((_, i) => i !== index));
  };

  const addCustomItem = (isSet: boolean = false) => {
      setBomItems([...bomItems, { 
          category: activeTab, 
          description: isSet ? 'Výber SETU...' : 'Nová požiadavka', 
          quantity: 1, 
          unit: isSet ? 'set' : 'ks', 
          price: 0,
          isAuto: false 
      }]);
  };

  const handleInsert = () => {
      // Final save before insert
      const currentState = {
          items: bomItems,
          includeTransport,
          includePackaging,
          includeAssembly,
          categoryOrder: Array.from(activeCategories)
      };
      localStorage.setItem('smartquote_wizard_last_state', JSON.stringify(currentState));

      onInsert({
          ...currentState,
          categoryOrder: tabs.map(t => t.id)
      });
      onClose();
  };

  // --- TEMPLATES ---
  const handleSaveTemplate = () => {
      if(!newTemplateName.trim()) return;
      const newTemplate: MaterialTemplate = {
          id: crypto.randomUUID(),
          name: newTemplateName,
          data: {
              items: bomItems,
              includeTransport, includePackaging, includeAssembly,
              categoryOrder: Array.from(activeCategories)
          }
      };
      const updated = [...savedTemplates, newTemplate];
      setSavedTemplates(updated);
      localStorage.setItem('smartquote_material_templates', JSON.stringify(updated));
      setNewTemplateName('');
      alert("Šablóna uložená.");
  };

  const handleLoadTemplate = (template: MaterialTemplate) => {
      if(window.confirm(`Načítať šablónu "${template.name}"?`)) {
          // When loading template, we also try to update quantities if possible
          const freshQuantities = calculateQuantitiesOnly(layout);
          const updatedTemplateItems = template.data.items.map(item => {
               if (item.isAuto && item.autoType && freshQuantities[item.autoType] !== undefined) {
                   return { ...item, quantity: freshQuantities[item.autoType] };
               }
               return item;
          });

          setBomItems(updatedTemplateItems);
          setIncludeTransport(template.data.includeTransport);
          setIncludePackaging(template.data.includePackaging);
          setIncludeAssembly(template.data.includeAssembly);
          if (template.data.categoryOrder) {
              setActiveCategories(new Set(template.data.categoryOrder));
          }
          setIsTemplateMenuOpen(false);
      }
  };

  const handleDeleteTemplate = (id: string) => {
      if(window.confirm("Vymazať šablónu?")) {
          const updated = savedTemplates.filter(t => t.id !== id);
          setSavedTemplates(updated);
          localStorage.setItem('smartquote_material_templates', JSON.stringify(updated));
      }
  };

  const handleResetToDefaults = () => {
      if(window.confirm("Týmto zahodíte manuálne zmeny a prepočítate zoznam podľa aktuálnych rozmerov výťahu (šírka, zdvih, atď.). Pokračovať?")) {
          const fresh = calculateFullBOM(layout);
          // Keep only active categories
          const filtered = fresh.filter(i => activeCategories.has(i.category));
          setBomItems(filtered);
      }
  };

  // Drag handlers
  const onDragStartItem = (e: React.DragEvent, index: number) => {
      setDraggedItemIdx(index);
      e.dataTransfer.effectAllowed = 'move';
  };
  const onDragOverItem = (e: React.DragEvent, targetIndex: number) => {
      e.preventDefault();
      if (draggedItemIdx === null || draggedItemIdx === targetIndex) return;
      const newItems = [...bomItems];
      const [reorderedItem] = newItems.splice(draggedItemIdx, 1);
      newItems.splice(targetIndex, 0, reorderedItem);
      setBomItems(newItems);
      setDraggedItemIdx(targetIndex);
  };

  if (!isOpen) return null;

  const currentCatName = activeTab;
  const currentItems = bomItems.map((item, index) => ({ item, index })).filter(({ item }) => item.category === currentCatName);
  const categoryProducts = products.filter(p => p.category === currentCatName);
  const subcategories = Array.from(new Set(categoryProducts.map(p => p.subcategory || 'Ostatné'))).sort();

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Calculator className="text-orange-500" />
            <div>
                <h2 className="text-xl font-bold text-gray-800">Materiálový Sprievodca</h2>
                <div className="text-xs text-gray-500">Automatický výpočet komponentov</div>
            </div>
          </div>

          <div className="flex gap-2 relative">
               <button onClick={() => setIsTemplateMenuOpen(!isTemplateMenuOpen)} className={`px-3 py-2 rounded-lg border flex items-center gap-2 text-sm font-bold transition ${isTemplateMenuOpen ? 'bg-purple-100 text-purple-700 border-purple-300 shadow-inner' : 'text-gray-600 hover:bg-gray-100'}`}>
                   <FolderOpen size={16}/> Šablóny
               </button>
               <button onClick={() => setIsCategorySettingsOpen(!isCategorySettingsOpen)} className={`p-2 rounded-full border transition ${isCategorySettingsOpen ? 'bg-blue-100 text-blue-600 border-blue-300' : 'text-gray-500 hover:bg-gray-100'}`} title="Správa Kategórií">
                    <Filter size={20}/>
               </button>
               <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
          </div>
        </div>

        {/* TEMPLATE MENU */}
        {isTemplateMenuOpen && (
            <div className="absolute top-16 right-4 z-[150] bg-white border border-purple-200 p-4 shadow-2xl rounded-xl w-[320px] animate-in fade-in slide-in-from-top-2">
                <div className="space-y-4">
                    <div className="bg-purple-50 p-3 rounded-lg border border-purple-100">
                        <h4 className="text-xs font-bold text-purple-800 uppercase mb-2 flex items-center gap-2"><Save size={14}/> Uložiť novú šablónu</h4>
                        <div className="flex gap-2">
                            <input className="border rounded px-2 py-1 text-sm flex-1 bg-white" placeholder="Názov..." value={newTemplateName} onChange={e => setNewTemplateName(e.target.value)} />
                            <button onClick={handleSaveTemplate} className="bg-purple-600 text-white px-3 py-1 rounded text-sm font-bold hover:bg-purple-700">Uložiť</button>
                        </div>
                    </div>
                    <div>
                        <h4 className="text-xs font-bold text-gray-500 uppercase mb-2">Uložené</h4>
                        <div className="space-y-1 max-h-48 overflow-y-auto border rounded p-1 bg-gray-50 custom-scrollbar">
                            {savedTemplates.length === 0 && <div className="text-gray-400 text-xs italic p-2 text-center">Žiadne šablóny.</div>}
                            {savedTemplates.map(t => (
                                <div key={t.id} className="flex justify-between items-center p-2 hover:bg-white border border-transparent hover:border-gray-200 rounded cursor-pointer" onClick={() => handleLoadTemplate(t)}>
                                    <span className="text-sm font-bold text-gray-700 truncate">{t.name}</span>
                                    <button onClick={(e) => { e.stopPropagation(); handleDeleteTemplate(t.id); }} className="text-red-400 hover:bg-red-100 p-1 rounded"><Trash2 size={14}/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Category Settings */}
        {isCategorySettingsOpen && (
            <div className="bg-gray-50 border-b p-4 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4 shadow-inner max-h-48 overflow-y-auto">
                {customCategories.filter(c => !['Montáž','Doprava','Balné'].includes(c)).map(c => (
                    <label key={c} className="flex items-center gap-2 cursor-pointer bg-white border p-2 rounded shadow-sm hover:bg-blue-50">
                        <input type="checkbox" checked={activeCategories.has(c)} onChange={() => toggleCategory(c)} className="rounded text-blue-600"/>
                        <span className="text-sm font-medium break-all">{c}</span>
                    </label>
                ))}
                <div className="col-span-full flex gap-2 pt-2 border-t mt-2">
                    <input className="border rounded px-2 py-1 text-sm w-48" placeholder="Nová kategória..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleAddCategory()}/>
                    <button onClick={handleAddCategory} className="px-3 py-1 bg-blue-600 text-white rounded text-xs font-bold">Pridať</button>
                </div>
            </div>
        )}

        {/* Tabs */}
        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-2 py-2 transition ${activeTab===tab.id ? 'bg-white border-gray-300' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`}>
                     {activeTab === tab.id && idx > 0 && <button onClick={() => moveTab(idx, 'left')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowLeft size={12}/></button>}
                     <button onClick={() => setActiveTab(tab.id)} className={`mx-2 text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? `text-${tab.color}-600` : 'text-gray-500'}`}>{tab.label}</button>
                     {activeTab === tab.id && idx < tabs.length - 1 && <button onClick={() => moveTab(idx, 'right')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowRight size={12}/></button>}
                 </div>
            ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">
            {currentItems.length === 0 && <div className="text-center text-gray-400 italic py-8">Žiadne položky v tejto kategórii.</div>}

            {currentItems.length > 0 && (
            <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                        <tr>
                            <th className="w-8"></th>
                            <th className="p-3 text-left w-1/3">Požiadavka (Výpočet)</th>
                            <th className="p-3 text-left w-1/3">Produkt zo Skladu</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {currentItems.map(({ item, index: originalIndex }) => {
                            return (
                                <tr 
                                    key={originalIndex} 
                                    draggable
                                    onDragStart={(e) => onDragStartItem(e, originalIndex)}
                                    onDragOver={(e) => onDragOverItem(e, originalIndex)}
                                    className={`transition ${item.isAuto ? 'hover:bg-blue-50' : 'bg-yellow-50 hover:bg-yellow-100'}`}
                                >
                                    <td className="p-2 text-center text-gray-300 cursor-grab hover:text-gray-500"><GripVertical size={16}/></td>
                                    <td className="p-3 relative">
                                        <input value={item.description} onChange={e => updateItem(originalIndex, 'description', e.target.value)} className="w-full bg-transparent font-medium text-gray-800 focus:outline-none"/>
                                        {!item.isAuto && <span className="text-[9px] font-bold text-yellow-600 uppercase absolute top-1 right-2 bg-yellow-100 px-1 rounded">Manual</span>}
                                        {item.isAuto && item.autoType && <span className="text-[9px] font-bold text-blue-600 uppercase absolute top-1 right-2 bg-blue-100 px-1 rounded">Auto: {item.autoType}</span>}
                                    </td>
                                    <td className="p-3">
                                        <div className="relative">
                                            <select value={item.productId || ''} onChange={e => updateItem(originalIndex, 'productId', e.target.value)} className={`w-full p-2 border rounded text-sm font-bold ${item.productId ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-400 border-gray-200'}`}>
                                                <option value="">-- Vybrať produkt --</option>
                                                {subcategories.map(subcat => {
                                                    const subProds = categoryProducts.filter(p => (p.subcategory || 'Ostatné') === subcat);
                                                    return (
                                                        <optgroup key={subcat} label={subcat}>
                                                            {subProds.sort((a,b) => (a.type === 'composite' ? -1 : 1)).map(p => (
                                                                <option key={p.id} value={p.id}>{p.type === 'composite' ? '📦 ' : ''}{p.name} ({p.price}€)</option>
                                                            ))}
                                                        </optgroup>
                                                    );
                                                })}
                                            </select>
                                            {!item.productId && <div title="Položka nie je spárovaná so skladom" className="absolute right-8 top-1/2 -translate-y-1/2 text-orange-400 pointer-events-none"><AlertTriangle size={14} /></div>}
                                        </div>
                                    </td>
                                    <td className="p-3 text-right"><input type="number" value={item.quantity} onChange={e => updateItem(originalIndex, 'quantity', +e.target.value)} className="w-full text-right font-bold text-blue-600 bg-transparent focus:outline-none text-base"/></td>
                                    <td className="p-3 text-right font-mono text-gray-600">{item.price ? item.price.toFixed(2) : '-'} €</td>
                                    <td className="p-3 text-center"><button onClick={() => handleDeleteItem(originalIndex)} className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition"><Trash2 size={16}/></button></td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            )}

            <div className="flex gap-2">
                <button onClick={() => addCustomItem(false)} className="flex-1 py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-600 hover:bg-blue-50 transition flex justify-center items-center gap-2 font-medium"><Plus size={18} /> Pridať vlastnú požiadavku</button>
                <button onClick={() => addCustomItem(true)} className="flex-1 py-3 border-2 border-dashed border-purple-300 rounded-lg text-purple-600 hover:border-purple-500 hover:bg-purple-50 transition flex justify-center items-center gap-2 font-bold bg-purple-50/50"><Layers size={18} /> + Pridať SET</button>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 bg-blue-50 p-3 rounded border border-blue-100">
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Hammer size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Montáž technológie</span></label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Truck size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Doprava materiálu</span></label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Package size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Balné a manipulácia</span></label>
            </div>

            <div className="flex justify-between items-center">
                <button onClick={handleResetToDefaults} className="text-xs text-orange-600 hover:text-orange-800 font-bold flex items-center gap-2 px-3 py-1 bg-orange-50 rounded border border-orange-200" title="Zahodiť manuálne zmeny a prepočítať podľa layoutu"><RotateCcw size={14}/> Prepočítať podľa aktuálneho výťahu</button>
                <div className="flex gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium transition">Zrušiť</button>
                    <button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold flex items-center gap-2 shadow-sm transition"><Check size={18} /> Potvrdiť a Vložiť</button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { QuoteCategory, QuoteItem } from '../types';
import { Trash2, Plus, Sparkles, Bold, Italic, Link, Image as ImageIcon, Table, List, ListOrdered, FileText, ChevronDown, ChevronUp, BookOpen, Layers, Box, Eye, EyeOff, Replace, Printer, Percent, GripVertical } from 'lucide-react';

interface CategoryTableProps {
  category: QuoteCategory;
  currency: string;
  globalMargin: number;
  onUpdateCategory: (id: string, field: keyof QuoteCategory, value: any) => void;
  onDeleteCategory: (id: string) => void;
  onAddItem: (categoryId: string, isSurcharge?: boolean) => void;
  onUpdateItem: (categoryId: string, itemId: string, field: keyof QuoteItem, value: any) => void;
  onDeleteItem: (categoryId: string, itemId: string) => void;
  onAiSuggest: (categoryId: string, categoryName: string) => void;
  onOpenCatalog: (categoryId: string, itemId?: string) => void;
  onMoveCategory?: (id: string, direction: 'up' | 'down') => void;
  isAiLoading: boolean;
  readOnly?: boolean; 
  hidePrices?: boolean;
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent, id: string) => void;
  onDragOver?: (e: React.DragEvent, id: string) => void;
  onDragEnd?: (e: React.DragEvent) => void;
}

export const CategoryTable: React.FC<CategoryTableProps> = ({
  category,
  currency,
  globalMargin,
  onUpdateCategory,
  onDeleteCategory,
  onAddItem,
  onUpdateItem,
  onDeleteItem,
  onAiSuggest,
  onOpenCatalog,
  onMoveCategory,
  isAiLoading,
  readOnly = false,
  hidePrices = false,
  draggable, onDragStart, onDragOver, onDragEnd
}) => {
  const [showRichText, setShowRichText] = useState(!!category.textContent);
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // FIX: Cursor jumping issue logic
  // We only update the innerHTML if the incoming prop is significantly different
  // from the current ref content (e.g. loaded from template), preventing overwrite during typing.
  useEffect(() => {
    if (showRichText && editorRef.current) {
       const currentContent = editorRef.current.innerHTML;
       const newContent = category.textContent || '';

       if (newContent !== currentContent) {
           editorRef.current.innerHTML = newContent;
       }
    }
  }, [showRichText, category.textContent]); 

  const formatNumber = (num: number) => {
    return num.toLocaleString('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const getSellingPrice = (costPrice: number) => {
    return costPrice * (1 + globalMargin / 100);
  };

  const isEmpty = category.items.length === 0 && !category.textContent;
  const isHidden = category.isHidden;
  const isHiddenFromPrint = category.isHiddenFromPrint;

  // --- Editor Logic ---
  const handleInput = () => {
    if (editorRef.current && !readOnly) {
      const content = editorRef.current.innerHTML;
      if (content !== category.textContent) {
          onUpdateCategory(category.id, 'textContent', content);
      }
    }
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const insertImage = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (readerEvent) => {
          const result = readerEvent.target?.result as string;
          execCmd('insertImage', result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const insertLink = () => {
    const url = prompt('Vložte URL odkazu (napr. na video):');
    if (url) execCmd('createLink', url);
  };

  const insertTable = () => {
    const html = `
      <table style="width: 100%; border-collapse: collapse; margin: 10px 0;">
        <tbody>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
        </tbody>
      </table>
      <p><br/></p>
    `;
    execCmd('insertHTML', html);
  };

  const toggleRichText = () => {
      setShowRichText(!showRichText);
  };

  const toggleSection = () => {
      if(readOnly) return;
      const newSection = category.section === 'shaft' ? 'lift' : 'shaft';
      onUpdateCategory(category.id, 'section', newSection);
  };

  const toggleVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHidden', !isHidden);
  };

  const togglePrintVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHiddenFromPrint', !isHiddenFromPrint);
  }

  // --- ITEM DRAG & DROP HANDLERS ---
  const onDragStartItem = (e: React.DragEvent, itemId: string) => {
      e.stopPropagation(); // Stop propagation so category D&D doesn't trigger
      setDraggedItemId(itemId);
      e.dataTransfer.effectAllowed = 'move';
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndItem = (e: React.DragEvent) => {
      e.stopPropagation();
      setDraggedItemId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverItem = (e: React.DragEvent, targetItemId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!draggedItemId || draggedItemId === targetItemId) return;

      const items = category.items;
      const draggedIndex = items.findIndex(i => i.id === draggedItemId);
      const targetIndex = items.findIndex(i => i.id === targetItemId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      onUpdateCategory(category.id, 'items', newItems);
  };

  // Determine classes based on hidden states
  // Reduced margin bottom for print compactness (mb-4 -> print:mb-2)
  let wrapperClasses = "mb-4 print:mb-2 border-2 border-gray-800 rounded-xl overflow-hidden bg-white shadow-sm break-inside-avoid transition-all";
  if (isHidden) {
      wrapperClasses += " opacity-60 grayscale border-dashed border-gray-400 print:hidden";
  } else if (isHiddenFromPrint) {
      wrapperClasses += " border-red-300 border-dashed print:hidden bg-red-50/30";
  }

  if (isEmpty) wrapperClasses += " print:hidden";
  if (readOnly) wrapperClasses += " border-gray-800"; // Always dark border in read mode too for consistency

  return (
    <div 
        className={wrapperClasses}
        draggable={draggable && !readOnly}
        onDragStart={(e) => onDragStart && onDragStart(e, category.id)}
        onDragOver={(e) => onDragOver && onDragOver(e, category.id)}
        onDragEnd={onDragEnd}
    >

      {/* STRICT PRINT HIDING LOGIC */}
      {hidePrices && (
          <style>{`
              @media print {
                  .price-column-strict { display: none !important; }
              }
          `}</style>
      )}

      {/* HEADER BAR - Reduced padding for print: py-3 -> print:py-1 */}
      <div className="px-4 py-3 print:py-1 border-b-2 border-gray-800 bg-white flex justify-between items-center print:bg-gray-50">
          <div className="flex items-center gap-2 flex-1">
              <div className={`p-1.5 rounded text-white ${category.section === 'shaft' ? 'bg-orange-600' : 'bg-gray-900'}`}>
                  {category.section === 'shaft' ? <Box size={14} /> : <Layers size={14} />}
              </div>

              {/* Category Name Input / Display - STANDARD TEXT FIELD */}
              {readOnly ? (
                  <h3 className="text-sm font-bold text-gray-900 uppercase tracking-widest text-left">{category.name}</h3>
              ) : (
                  <input
                      type="text"
                      value={category.name}
                      onChange={(e) => onUpdateCategory(category.id, 'name', e.target.value)}
                      className="bg-transparent font-bold text-sm text-gray-900 focus:outline-none focus:text-black placeholder-gray-400 print:text-black w-full text-left"
                      placeholder="Názov kategórie"
                  />
              )}
          </div>

          {/* Action Toolbar */}
          <div className="flex items-center gap-1 no-print">
               {!readOnly && onMoveCategory && (
                    <div className="flex gap-1 mr-2 border-r pr-2 border-gray-200">
                         <button onClick={() => onMoveCategory(category.id, 'up')} className="p-1 hover:bg-gray-100 rounded text-gray-400 hover:text-gray-700"><ChevronUp size={14}/></button>
                         <button onClick={() => onMoveCategory(category.id, 'down')} className="p-1 hover:bg-gray-100 rounded text-gray-400 hover:text-gray-700"><ChevronDown size={14}/></button>
                    </div>
               )}
               {!readOnly && (
                   <>
                        <button onClick={toggleSection} className="p-1 text-gray-300 hover:text-orange-500" title="Prepnúť sekciu (Výťah/Šachta)">
                            {category.section === 'shaft' ? <Box size={14} /> : <Layers size={14} />}
                        </button>
                        <button onClick={togglePrintVisibility} className={`p-1 ${isHiddenFromPrint ? 'text-red-500' : 'text-gray-300 hover:text-black'}`} title="Skryť pri tlači"><Printer size={14}/></button>
                        <button onClick={toggleVisibility} className={`p-1 ${isHidden ? 'text-gray-500' : 'text-gray-300 hover:text-black'}`} title="Skryť úplne"><Eye size={14}/></button>
                        <button onClick={toggleRichText} className={`p-1 ${showRichText ? 'text-blue-500' : 'text-gray-300 hover:text-blue-500'}`} title="Text"><FileText size={14}/></button>
                        <button onClick={() => onDeleteCategory(category.id)} className="p-1 text-gray-300 hover:text-red-600"><Trash2 size={14}/></button>
                   </>
               )}
          </div>
      </div>

      {/* Items Table */}
      {category.items.length > 0 ? (
      <div className="bg-white">
          <table className="w-full text-xs text-left">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr className="text-[10px] uppercase text-gray-500 tracking-wider">
                {!readOnly && <th className="w-6 no-print"></th>}
                <th className="px-4 py-1 font-bold w-10 text-center text-gray-400">#</th>
                <th className="px-2 py-1 font-bold text-left">Položka</th>
                <th className="px-2 py-1 font-bold text-right w-16">M.J.</th>
                <th className="px-2 py-1 font-bold text-right w-16">Mn.</th>
                <th className={`px-4 py-1 font-bold text-right w-24 price-column-strict ${hidePrices ? '' : ''}`}>
                    {readOnly ? 'Cena' : 'Nákup'}
                </th>
                {!readOnly && <th className="w-16 no-print"></th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {category.items.map((item, index) => {
                const sellingPrice = getSellingPrice(item.unitPrice);
                return (
                <tr 
                    key={item.id} 
                    className={`group transition-colors ${item.isSurcharge ? 'bg-gray-50/50' : 'hover:bg-gray-50'}`}
                    draggable={!readOnly}
                    onDragStart={(e) => onDragStartItem(e, item.id)}
                    onDragOver={(e) => onDragOverItem(e, item.id)}
                    onDragEnd={onDragEndItem}
                >
                  {!readOnly && (
                      <td className="text-center no-print text-gray-300 cursor-grab hover:text-gray-500 align-middle">
                          <GripVertical size={12} className="mx-auto"/>
                      </td>
                  )}
                  {/* COMPACT PADDING: py-2 -> py-0.5 for print */}
                  <td className="px-4 py-2 print:py-0.5 text-center text-gray-400 font-medium text-[10px] align-top pt-2.5 print:pt-1">{index + 1}</td>

                  {/* DESCRIPTION CELL - FORCED LEFT ALIGN */}
                  <td className="px-2 py-1 print:py-0.5 align-top relative text-left">
                    {readOnly ? (
                        <div className={`text-gray-900 whitespace-pre-wrap leading-tight py-1.5 print:py-0 text-left ${item.isSurcharge ? 'pl-4 italic text-gray-600 text-[11px]' : 'text-xs font-medium'}`}>
                            {item.isSurcharge && <span className="absolute left-0 top-2 text-gray-400 text-[10px]">•</span>}
                            {item.description}
                        </div>
                    ) : (
                        <div className={`flex gap-1 py-1 print:py-0 ${item.isSurcharge ? 'pl-4' : ''}`}>
                             {item.isSurcharge && <span className="absolute left-1 top-2.5 text-gray-400 text-[10px]">•</span>}
                             <textarea
                                rows={1}
                                value={item.description}
                                onChange={(e) => {
                                    onUpdateItem(category.id, item.id, 'description', e.target.value);
                                    e.target.style.height = 'auto';
                                    e.target.style.height = e.target.scrollHeight + 'px';
                                }}
                                className={`w-full bg-transparent focus:outline-none focus:text-black resize-none text-xs placeholder-gray-300 print:text-black leading-normal overflow-hidden py-0.5 text-left ${item.isSurcharge ? 'italic text-gray-600' : 'text-gray-900 font-bold'}`}
                                style={{ minHeight: '1.5rem' }}
                                placeholder="Názov položky..."
                            />
                            <button
                                onClick={() => onOpenCatalog(category.id, item.id)}
                                className="no-print self-start p-1 text-blue-300 hover:text-blue-600 rounded transition opacity-0 group-hover:opacity-100 focus:opacity-100 mt-0.5"
                                title="Katalóg"
                            >
                                <BookOpen size={12} />
                            </button>
                        </div>
                    )}
                  </td>

                  {/* UNIT */}
                  <td className="px-2 py-1 print:py-0.5 align-top text-right pt-2 print:pt-0.5">
                    {readOnly ? (
                        <span className="text-gray-500 text-[10px] uppercase font-bold">{item.unit}</span>
                    ) : (
                        <select
                            value={item.unit}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'unit', e.target.value)}
                            className="w-full text-right bg-transparent text-gray-500 font-bold text-[10px] uppercase border-none focus:outline-none cursor-pointer hover:bg-gray-100 rounded px-1 print:appearance-none"
                        >
                            <option value="ks">KS</option>
                            <option value="m">M</option>
                            <option value="kpl">KPL</option>
                            <option value="set">SET</option>
                            <option value="hod">HOD</option>
                        </select>
                    )}
                  </td>

                  {/* QUANTITY */}
                  <td className="px-2 py-1 print:py-0.5 align-top text-right pt-2 print:pt-0.5">
                    {readOnly ? (
                        <span className="text-gray-900 font-bold text-xs">{item.quantity}</span>
                    ) : (
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={item.quantity === 0 ? '' : item.quantity}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'quantity', parseFloat(e.target.value) || 0)}
                            className="w-full text-right bg-transparent text-gray-900 font-bold focus:outline-none text-xs p-0 hover:bg-gray-100 rounded"
                        />
                    )}
                  </td>

                  {/* PRICE */}
                  <td className="px-4 py-1 print:py-0.5 align-top text-right price-column-strict pt-2 print:pt-0.5">
                    {readOnly ? (
                        <span className="text-xs font-bold text-gray-900 block">
                            {formatNumber(sellingPrice)}
                        </span>
                    ) : (
                        <>
                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={item.unitPrice === 0 ? '' : item.unitPrice}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                                className={`w-full text-right bg-transparent font-bold focus:outline-none text-xs print:hidden cursor-text p-0 hover:bg-blue-50 rounded ${hidePrices ? 'text-gray-300' : 'text-blue-600'}`}
                                placeholder="0.00"
                            />
                            <span className="hidden print:block text-xs font-bold text-black">
                                {formatNumber(sellingPrice)}
                            </span>
                        </>
                    )}
                  </td>

                  {/* ACTIONS */}
                  {!readOnly && (
                    <td className="px-2 py-1 text-center no-print align-top pt-1.5">
                        <div className="flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => onAddItem(category.id, true)} className="text-gray-300 hover:text-blue-500"><Percent size={12} /></button>
                            <button onClick={() => onDeleteItem(category.id, item.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={12} /></button>
                        </div>
                    </td>
                  )}
                </tr>
              )})}
            </tbody>
          </table>
      </div>
      ) : (
          !readOnly && (
            <div className="p-4 text-center text-gray-400 italic text-xs no-print border-b border-gray-100 bg-gray-50/50">
                Žiadne položky. Použite tlačidlo "+" alebo Materiálového Sprievodcu.
            </div>
          )
      )}

      {!readOnly && (
        <div className="p-1 border-t border-gray-100 bg-white no-print flex gap-2 justify-center opacity-0 hover:opacity-100 transition-opacity">
            <button
            onClick={() => onAddItem(category.id)}
            className="flex items-center gap-1 text-[10px] font-bold text-gray-400 hover:text-blue-600 px-2 py-0.5 rounded hover:bg-blue-50 transition uppercase tracking-wide"
            >
            <Plus size={12} /> Pridať riadok
            </button>
        </div>
      )}

      {/* Embedded Rich Text Area - Forced Left */}
      {(showRichText || (readOnly && category.textContent)) && (
        <div className="border-t border-gray-200 p-4 print:p-2 bg-white text-left">
            <div className="mb-2 text-[10px] font-bold text-gray-400 uppercase tracking-wider print:hidden">Technická špecifikácia / Prílohy</div>
            {/* FIX: Removed dangerouslySetInnerHTML to prevent re-render loop killing cursor position */}
            <div
                ref={editorRef}
                contentEditable={!readOnly}
                onInput={handleInput}
                className={`rich-text-content w-full min-h-[60px] outline-none text-gray-900 text-xs leading-relaxed text-left ${readOnly ? 'pointer-events-none' : ''}`}
            />
        </div>
      )}
    </div>
  );
};

