      return `${prefix}_SK_${numStr}_${year}_BA`;
  };

  const handleUnlockNumber = () => { const code = prompt("Zadajte admin kód pre úpravu čísla:"); if (code === '123') { setIsNumberEditable(true); } else if (code !== null) { alert("Nesprávny kód"); } };

