  const addCategory = (type: 'items'|'text', name?: string, items?: QuoteItem[], section: 'lift'|'shaft' = 'lift', textContent?: string) => {
      setData(prev => ({ ...prev, categories: [...prev.categories, { id: generateId(), type, name: name || (type === 'text' ? 'Textová sekcia' : 'Nová kategória'), items: items ? items.map(i => ({...i, id: generateId()})) : [], isExpanded: true, section, textContent: textContent || (type === 'text' ? '<p>Sem napíšte text...</p>' : undefined) }] }));
  };
  const handleAddItem = (catId: string, isSurcharge = false) => {
