                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/><Package size={18} className="text-blue-600"/><span className="text-sm font-bold text-blue-800">Balné a manipulácia</span></label>
            </div>

