// INITIAL MASTER CATEGORIES - Default structure for new quotes
const DEFAULT_CATEGORIES_LIST = [
    'Dvere', 
    'Kabína a rám', 
    'Pohon', 
    'Vodítka a kotvenie', 
    'Obmedzovač', 
    'Elektro', 
