  driveType: 'traction' | 'hydraulic' | 'mrl' | 'drum';
  ratedLoad: number;
  numberOfPersons: number;
  ratedSpeed: number;
  powerSupply: string;

  shaftWidth: number;
  shaftDepth: number;
  cabinWidth: number;
  cabinDepth: number;
  cabinHeight: number; 
  doorWidth: number;
  doorOffsetL: number;

  doorOpeningWidth?: number; 
  doorOpeningHeight?: number; 
  LDO?: number; 
  RDO?: number; 

  cabinClass?: string; 

  pitDepth: number;
  headroomHeight: number;
  travelHeight: number;

  doorType?: 'central' | 'telescopic' | 'bus';
  doorOperation?: 'automatic' | 'manual';
  doorFireRating?: 'EW60' | 'EI60' | 'EI120' | 'None';
  doorFinish?: 'RAL 7032' | 'Nerez Brus' | 'Nerez Lesk' | 'Skinplate';

  entrances: 'A' | 'AB' | 'AC';
  isThroughCar?: boolean; 

  counterWeightPosition: 'back' | 'left' | 'right';
  machineRoomPosition?: 'head' | 'above' | 'cabinet';
  suspensionType?: '1:1' | '2:1' | '4:1';
  tractionMedium?: 'ropes' | 'belts' | 'ctp';
  frameType?: 'central' | 'backpack';

  carDBG?: number;
  cwtDBG?: number;
  cwtWidth?: number;
  cwtDepth?: number;
  guideTypeCar?: RailType;
  guideTypeCwt?: RailType;
  guideRailLength?: 2500 | 5000; 

  bracketType?: 'standard' | 'combined';

  gapLeft: number;
  gapRight: number;
  gapRear: number;
  gapFront: number;

  stationLabels?: string;
  numberOfStops?: number;
  numberOfEntrances?: number; 
  startStation?: number;

  hasExternalShaft?: boolean;

  notes: string;
}

