  id: string;
  relatedDocId?: string;
  number: string;
  type: DocumentType;
  quoteMode?: 'lift' | 'control_system'; // NEW: Mode switch
  title: string;
  logoUrl?: string;
  date: string;
  validUntil: string;
  clientReference?: string;
  supplier: {
    name: string;
    details: string;
    email?: string;
    phone?: string;
