export interface ProductAttributeOption {
    label: string;
    priceDelta: number;
    value: string | number;
}

export interface ProductAttribute {
    name: string;
    options: ProductAttributeOption[];
}

export interface ProductComponent {
    productId: string;
    quantity: number;
}

export interface Product {
  id: string;
  category: string; 
  subcategory?: string; 
  name: string;
  manufacturer?: string; 
  supplier?: string; 
  unit: string;
  price: number;
