  const generateDocNumber = (type: 'quote' | 'order' | 'contract', quoteMode?: 'lift' | 'control_system') => {
      const year = new Date().getFullYear().toString().slice(-2);
      let seq = 1; 
      let prefix = 'CP';

      if (type === 'quote') {
          // Check Mode to determine prefix and sequence
          if (quoteMode === 'control_system') {
              seq = settings.nextRsSequence || 1;
              prefix = 'RS'; // Separate prefix for Control Systems
          } else {
              seq = settings.nextCpSequence || 1;
              prefix = 'CP';
          }
      } else if (type === 'order') { 
          seq = settings.nextObjSequence; 
          prefix = 'OBJ'; 
      } else if (type === 'contract') { 
          seq = settings.nextPlSequence; 
          prefix = 'PL'; 
      }

      const numStr = seq.toString().padStart(3, '0');
      return `${prefix}_SK_${numStr}_${year}_BA`;
  };

