              if (data.quoteMode === 'control_system' && newSeq >= (settings.nextRsSequence || 1)) {
                  setSettings(prev => ({...prev, nextRsSequence: newSeq + 1}));
              } else if (newSeq >= settings.nextCpSequence) {
                  setSettings(prev => ({...prev, nextCpSequence: newSeq + 1}));
              }
