                    <div className="flex justify-between text-lg font-bold text-black mt-2 bg-gray-100 p-2 rounded">
                        <span>Spolu s DPH:</span>
                        <span>{formatCurrency(totals.gross)}</span>
                    </div>
                </div>
            </div>

            {!isContractMode && (
