                                    <div className="text-xs text-gray-500">Načíta dáta zo súboru .json a nahradí aktuálne</div>
                                </div>
                                <div className="bg-gray-200 text-gray-600 px-3 py-1 rounded text-xs font-bold group-hover:bg-gray-300">NAHRAŤ</div>
                            </button>
