          if (wData.includeAssembly) activeCategoryNames.add('Montáž'); else activeCategoryNames.delete('Montáž');
          if (wData.includeTransport) activeCategoryNames.add('Doprava'); else activeCategoryNames.delete('Doprava');
          if (wData.includePackaging) activeCategoryNames.add('Balné'); else activeCategoryNames.delete('Balné');
          newData.categories = newData.categories.filter(c => {
              if (c.type === 'text') return true;
              if (c.name === 'Oceľová konštrukcia' && newData.layout?.hasExternalShaft) return true;
              return activeCategoryNames.has(c.name);
          });
          newData.categories.forEach(c => { if (activeCategoryNames.has(c.name) && c.type === 'items') { c.items = []; } });
          activeCategoryNames.forEach(catName => {
               if (!catName) return;
               let cat = newData.categories.find(c => c.name === catName);
               if (!cat) {
                   cat = { id: generateId(), name: catName, type: 'items', items: [], isExpanded: true, section: catName === 'Oceľová konštrukcia' ? 'shaft' : 'lift', textContent: settings.defaultCategoryTexts?.[catName] };
                   newData.categories.push(cat);
               }
          });
          const findCat = (namePart: string) => newData.categories.find(c => c.name === namePart);
          wData.items.forEach(bomItem => {
              if (!activeCategoryNames.has(bomItem.category)) return;
              const category = findCat(bomItem.category);
              if (category) {
                  category.items.push({ id: generateId(), description: bomItem.description, unit: bomItem.unit, quantity: bomItem.quantity, unitPrice: bomItem.price || 0, purchasePrice: 0, vatRate: 23 });
              }
          });
          if (wData.includeAssembly) { const cat = findCat('Montáž'); if (cat && cat.items.length === 0) { cat.items.push({ id: generateId(), description: 'Montáž technológie', unit: 'kpl', quantity: 1, unitPrice: 1500, purchasePrice: 0, vatRate: 23 }); } }
          if (wData.includeTransport) { const cat = findCat('Doprava'); if (cat && cat.items.length === 0) { cat.items.push({ id: generateId(), description: 'Doprava', unit: 'kpl', quantity: 1, unitPrice: wData.transportPrice || 200, purchasePrice: 0, vatRate: 23 }); } }
          if (wData.includePackaging) { const cat = findCat('Balné'); if (cat && cat.items.length === 0) { cat.items.push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); } }
          return newData;
      });
  };

  const handleLoadTemplate = (template: QuoteTemplate) => { setData(prev => ({ ...prev, categories: [...prev.categories, ...template.data.categories.map(c => ({...c, id: generateId(), items: c.items.map(i => ({...i, id: generateId()}))}))] })); setIsTemplateModalOpen(false); };
  const handleSaveTemplate = (name: string, type: 'lift' | 'shaft') => { setTemplates([...templates, { id: generateId(), name, type, data: { categories: data.categories.filter(c => c.section === type), layout: data.layout, margin: type === 'shaft' ? data.shaftMargin : data.globalMargin } }]); };
  const handleDeleteTemplate = (id: string) => setTemplates(templates.filter(t => t.id !== id));
  const handleSelectContractTemplate = (content: string) => { setData(prev => ({ ...prev, contractBody: content })); setIsContractRepoOpen(false); };
  const handleSaveContractTemplate = (name: string) => { setContractTemplates([...contractTemplates, { id: generateId(), name, content: data.contractBody || '' }]); };
  const handleDeleteContractTemplate = (id: string) => setContractTemplates(contractTemplates.filter(t => t.id !== id));
  const handleSaveSettings = (newSettings: AppSettings) => setSettings(newSettings);

  const handleExportData = () => {
      const blob = new Blob([JSON.stringify({ data, products, clients, suppliers, templates, settings, savedQuotes, contractTemplates, customCategories: availableCategories, cabinClasses: cabinClasses }, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = `smartquote-backup-${new Date().toISOString().split('T')[0]}.json`; a.click();
  };

  const handleFactoryReset = () => {
      setProducts([]); setClients([]); setSuppliers([]); setTemplates([]); setSavedQuotes([]); setAvailableCategories(DEFAULT_CATEGORIES_LIST); setCabinClasses(DEFAULT_CABIN_CLASSES); setSettings({ nextCpSequence: 1, nextRsSequence: 1, nextObjSequence: 1, nextPlSequence: 1 }); setData({...data, id: generateId(), categories: []}); localStorage.clear(); window.location.reload();
  };

  const handleSendEmail = (to: string, subject: string, message: string) => { window.open(`mailto:${to}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(message)}`); setIsEmailModalOpen(false); };

  const openEmailModal = () => { setEmailModalProps({ to: data.client.email || '', subject: `${data.number} - ${data.title}`, message: `Dobrý deň,\n\nzasielame Vám cenovú ponuku č. ${data.number}.\n\nS pozdravom,\n${data.supplier.name}` }); setIsEmailModalOpen(true); };

  const generateDocNumber = (type: 'quote' | 'order' | 'contract', quoteMode?: 'lift' | 'control_system') => {
      const year = new Date().getFullYear().toString().slice(-2);
      let seq = 1; let prefix = 'CP';
      if (type === 'quote') {
          if (quoteMode === 'control_system') { seq = settings.nextRsSequence || 1; prefix = 'RS'; } else { seq = settings.nextCpSequence || 1; prefix = 'CP'; }
      } else if (type === 'order') { seq = settings.nextObjSequence; prefix = 'OBJ'; } else if (type === 'contract') { seq = settings.nextPlSequence; prefix = 'PL'; }
      return `${prefix}_SK_${seq.toString().padStart(3, '0')}_${year}_BA`;
  };

  const handleUnlockNumber = () => { const code = prompt("Admin kód:"); if (code === '123') setIsNumberEditable(true); };

  const handleSaveCurrentQuote = () => {
      const now = Date.now();
      const quoteToSave = { ...data, lastUpdated: now };
      const existing = savedQuotes.find(q => q.number === data.number && q.id !== data.id);
      if (existing) {
          if (!window.confirm(`Doklad ${data.number} už existuje. Prepísať?`)) return;
          const newArchive = savedQuotes.filter(q => q.id !== existing.id).map(q => q.id === data.id ? quoteToSave : q);
          if (!newArchive.find(q => q.id === data.id)) newArchive.push(quoteToSave);
          setSavedQuotes(newArchive);
      } else {
          setSavedQuotes(prev => { const ex = prev.find(q=>q.id===data.id); return ex ? prev.map(q=>q.id===data.id?quoteToSave:q) : [...prev, quoteToSave]; });
      }
      alert(`Uložené: ${data.number}`);
  };

  const handleDuplicateQuote = () => {
      const suggestedNum = generateDocNumber('quote', data.quoteMode);
      const userNum = window.prompt(`Kópia dokladu. Nové číslo:`, suggestedNum);
      if (!userNum) return;
      const match = userNum.match(/_(\d{3})_/);
      if (match && match[1]) {
          const newSeq = parseInt(match[1], 10);
          if (!isNaN(newSeq)) {
              if (data.quoteMode === 'control_system' && newSeq >= (settings.nextRsSequence || 1)) setSettings(p => ({...p, nextRsSequence: newSeq + 1}));
              else if (newSeq >= settings.nextCpSequence) setSettings(p => ({...p, nextCpSequence: newSeq + 1}));
          }
      } else {
           if (data.quoteMode === 'control_system') setSettings(p => ({...p, nextRsSequence: (p.nextRsSequence || 1) + 1}));
           else setSettings(p => ({...p, nextCpSequence: p.nextCpSequence + 1}));
      }
      const newData: QuoteData = { ...data, id: generateId(), number: userNum, title: `${data.title} (Kópia)`, date: new Date().toISOString().split('T')[0], relatedDocId: undefined, categories: data.categories.map(c => ({...c, id: generateId(), items: c.items.map(i => ({...i, id: generateId()}))})) };
      setSavedQuotes(prev => [...prev, { ...newData, lastUpdated: Date.now() }]);
      setData(newData);
      setCalcSuccess(null);
  };

  const handleCalculateDim = (std: string) => {
      if (!data.layout) return;
      const { shaftWidth, shaftDepth, gapLeft, gapRight, gapFront, gapRear, frameType, guideTypeCar } = data.layout;
      const railDepth = guideTypeCar?.includes('T12') ? 125 : 85;
      let newWidth = shaftWidth - gapLeft - gapRight - 80;
      if (frameType === 'central') newWidth -= (2 * railDepth);
      let newDepth = shaftDepth - gapFront - gapRear - 60;
      const { suggestedLoad, persons } = calculateEn8120(newWidth, newDepth);
      setData(prev => ({ ...prev, layout: { ...prev.layout!, cabinWidth: Math.round(newWidth), cabinDepth: Math.round(newDepth), ratedLoad: suggestedLoad, numberOfPersons: persons } }));
      setCalcSuccess(std); setTimeout(() => setCalcSuccess(null), 2000);
  };

  const openNewQuoteModal = () => {
      if (data.categories.length > 0 && window.confirm("Uložiť rozpracovanú ponuku?")) handleSaveCurrentQuote();
      setIsNewQuoteModalOpen(true);
  };

  const handleCreateQuote = (type: 'lift' | 'control_system') => {
      setIsNewQuoteModalOpen(false);
      const newNum = generateDocNumber('quote', type);
      if (type === 'control_system') setSettings(p => ({...p, nextRsSequence: (p.nextRsSequence || 1) + 1}));
      else setSettings(p => ({...p, nextCpSequence: p.nextCpSequence + 1}));

      const cats = type === 'lift' ? DEFAULT_CATEGORIES_LIST : CONTROL_SYSTEM_CATEGORIES;
      const initCats: QuoteCategory[] = cats.map(name => ({ id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift', textContent: settings.defaultCategoryTexts?.[name] }));

      setData({ id: generateId(), number: newNum, type: 'quote', quoteMode: type, title: type === 'lift' ? 'Cenová Ponuka - Výťah' : 'Cenová Ponuka - RS', date: new Date().toISOString().split('T')[0], validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0], supplier: data.supplier, client: { name: '', details: '' }, layout: { ...DEFAULT_LAYOUT }, controlLayout: { ...DEFAULT_CONTROL_LAYOUT }, categories: initCats, terms: DEFAULT_TERMS_HTML, currency: '€', globalMargin: 15, shaftMargin: 20, vatRate: 23, hideItemPrices: true, showTechSpecs: true, contractBody: DEFAULT_CONTRACT_TEXT });
      setCalcSuccess(null); setHasShaft(false);
  };

  const handleDeleteQuote = (id: string) => { 
      const q = savedQuotes.find(q => q.id === id);
      if (q && window.confirm("Vymazať?")) { 
          setSavedQuotes(savedQuotes.filter(sq => sq.id !== id));
          const match = q.number.match(/_(\d{3})_/);
          if (match && match[1]) {
              const seq = parseInt(match[1], 10);
              const isRs = q.number.startsWith('RS');
              if (isRs && seq === (settings.nextRsSequence || 1) - 1) setSettings(p => ({...p, nextRsSequence: seq}));
              else if (!isRs && seq === settings.nextCpSequence - 1) setSettings(p => ({...p, nextCpSequence: seq}));
          }
      } 
  };

  const loadFromStorage = (q: QuoteData) => { setData(q); setShowArchive(false); };
  const createRelatedOrder = (q: QuoteData) => { const newNum = generateDocNumber('order'); const order: QuoteData = { ...q, id: generateId(), relatedDocId: q.id, number: newNum, type: 'order', title: `Objednávka k ${q.number}`, date: new Date().toISOString().split('T')[0] }; setSavedQuotes(p => [...p, order]); setSettings(p => ({...p, nextObjSequence: p.nextObjSequence + 1})); setData(order); setShowArchive(false); };
  const createRelatedContract = (q: QuoteData) => { const newNum = generateDocNumber('contract'); const contract: QuoteData = { ...q, id: generateId(), relatedDocId: q.id, number: newNum, type: 'contract', title: `Zmluva ${newNum}`, date: new Date().toISOString().split('T')[0] }; setSavedQuotes(p => [...p, contract]); setSettings(p => ({...p, nextPlSequence: p.nextPlSequence + 1})); setData(contract); setShowArchive(false); };
  const handleNavigateToRelated = (type: DocumentType) => { const target = savedQuotes.find(q => (data.type === 'quote' && q.type === type && q.relatedDocId === data.id) || (data.type !== 'quote' && q.id === data.relatedDocId)); if(target) loadFromStorage(target); };
  const toggleTechSpecs = () => setData(prev => ({...prev, showTechSpecs: !prev.showTechSpecs}));
  const addCategory = (type: 'items'|'text', name?: string, items?: QuoteItem[]) => { setData(p => ({ ...p, categories: [...p.categories, { id: generateId(), type, name: name || (type==='text'?'Text':'Nová'), items: items || [], isExpanded: true, section: 'lift', textContent: name ? settings.defaultCategoryTexts?.[name] : undefined }] })); };
  const handleAddItem = (catId: string, isSurcharge = false) => { setData(p => ({ ...p, categories: p.categories.map(c => c.id === catId ? { ...c, items: [...c.items, { id: generateId(), description: isSurcharge ? 'Príplatok' : 'Položka', unit: 'ks', quantity: 1, unitPrice: 0, purchasePrice: 0, vatRate: 23, isSurcharge }] } : c) })); };
  const handleOpenCatalog = (catId: string, itemId?: string) => { setIsProductModalOpen(true); };
  const handleAiCategoryItems = async (catId: string, name: string) => { setIsAiLoading(catId); const s = await generateSuggestion(name, 'category_items'); if(s) { const items = s.split(',').map(d => ({ id: generateId(), description: d.trim(), unit: 'ks', quantity: 1, unitPrice: 0, purchasePrice: 0, vatRate: 23 })); setData(p => ({ ...p, categories: p.categories.map(c => c.id === catId ? {...c, items: [...c.items, ...items]} : c) })); } setIsAiLoading(false); };
  const moveCategory = (id: string, dir: 'up' | 'down') => { const idx = data.categories.findIndex(c => c.id === id); if ((dir==='up' && idx===0) || (dir==='down' && idx===data.categories.length-1)) return; const newCats = [...data.categories]; [newCats[idx], newCats[dir==='up'?idx-1:idx+1]] = [newCats[dir==='up'?idx-1:idx+1], newCats[idx]]; setData(p => ({ ...p, categories: newCats })); };
  const onDragStartCat = (e: React.DragEvent, id: string) => { setDraggedCatId(id); };
  const onDragOverCat = (e: React.DragEvent, targetId: string) => { e.preventDefault(); if (!draggedCatId || draggedCatId === targetId) return; const items = data.categories; const dIdx = items.findIndex(i => i.id === draggedCatId); const tIdx = items.findIndex(i => i.id === targetId); if (dIdx === -1 || tIdx === -1) return; const newItems = [...items]; const [removed] = newItems.splice(dIdx, 1); newItems.splice(tIdx, 0, removed); setData(p => ({...p, categories: newItems})); };

  if (!isAuthenticated) return <LoginGate onLogin={handleLogin} />;
  const recommendedRails = getRailTypesForLoad(data.layout?.ratedLoad || 630);

  return (
      <div className="min-h-screen bg-gray-100 p-4 md:p-8 font-sans print:bg-white print:p-0">
      <style>{`@media print { body, #root, .print-container { overflow: visible !important; height: auto !important; margin: 0 !important; } .pageNumber::after { counter-increment: page; content: counter(page); } }`}</style>

      <div className="no-print mb-6">
        <div className="flex flex-col xl:flex-row justify-between items-center mb-4 gap-4">
            <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2 self-start xl:self-center"><Calculator className="text-blue-600"/> SmartQuote SK <span className="text-xs bg-gray-200 text-gray-600 px-2 py-1 rounded">v{APP_VERSION}</span></h1>
            <div className="flex flex-wrap gap-2 items-center justify-end w-full xl:w-auto">
                <button onClick={() => window.print()} className="px-3 py-2 h-9 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm whitespace-nowrap"><Printer size={16}/> Tlačiť</button>
                <button onClick={openEmailModal} className="px-3 py-2 h-9 bg-green-600 hover:bg-green-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm whitespace-nowrap"><Mail size={16}/> Odoslať</button>
                <div className="h-6 w-px bg-gray-300 mx-2 hidden sm:block"></div>
                <button onClick={handleDuplicateQuote} className="px-3 py-2 h-9 bg-orange-100 hover:bg-orange-200 text-orange-800 font-bold rounded flex items-center gap-2 border border-orange-300 text-sm whitespace-nowrap"><Copy size={16}/> Kópia</button>
                <button onClick={openNewQuoteModal} className="px-3 py-2 h-9 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm border border-blue-800 whitespace-nowrap"><PlusCircle size={16}/> Nová CP</button>
                <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-2 h-9 bg-purple-100 hover:bg-purple-200 text-purple-800 font-bold rounded flex items-center gap-2 border border-purple-300 text-sm whitespace-nowrap"><Settings size={16}/> Katalóg</button>
                <button onClick={handleSaveCurrentQuote} className="px-3 py-2 h-9 bg-green-100 hover:bg-green-200 text-green-800 font-bold rounded flex items-center gap-2 border border-green-300 text-sm whitespace-nowrap"><Save size={16}/> Uložiť</button>
                <button onClick={() => setShowArchive(true)} className="px-3 py-2 h-9 bg-gray-200 hover:bg-gray-300 rounded text-gray-700 font-bold flex items-center gap-2 text-sm whitespace-nowrap"><Archive size={16}/> Archív</button>
                <button onClick={() => setIsSettingsModalOpen(true)} className="p-2 h-9 bg-gray-200 hover:bg-gray-300 rounded text-gray-700"><Settings size={18}/></button>
                <label className="flex items-center gap-2 ml-2 cursor-pointer bg-white border px-3 py-1 rounded-full shadow-sm hover:bg-gray-50 h-9 whitespace-nowrap"><input type="checkbox" checked={data.hideItemPrices} onChange={e => setData({...data, hideItemPrices: e.target.checked})} className="rounded text-blue-600"/><span className="text-xs font-bold text-gray-600">Skryť ceny</span></label>
                <button onClick={handleLogout} className="ml-2 p-2 h-9 bg-red-100 hover:bg-red-200 text-red-700 rounded-full"><LogOut size={16}/></button>
            </div>
        </div>
        <div className="bg-white p-2 rounded-lg border border-blue-200 shadow-sm flex items-center justify-between overflow-x-auto">
            <div className="flex items-center gap-4 min-w-max">
                 <button onClick={() => handleNavigateToRelated('quote')} disabled={data.type === 'quote'} className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'quote' ? 'bg-yellow-100 text-yellow-800 ring-2 ring-yellow-400' : 'bg-gray-100 text-gray-500'}`}>1. Cenová Ponuka {data.type !== 'quote' && <CheckCircle size={12}/>}</button>
                 <ArrowRight size={16} className="text-gray-300"/>
                 <button onClick={() => handleNavigateToRelated('order')} disabled={data.type === 'order'} className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'order' ? 'bg-blue-100 text-blue-800 ring-2 ring-blue-400' : 'bg-gray-100 text-gray-500'}`}>2. Objednávka {data.type !== 'order' && savedQuotes.some(q => q.type === 'order' && q.relatedDocId === (data.type==='quote'?data.id:data.relatedDocId)) && <CheckCircle size={12}/>}</button>
                 <ArrowRight size={16} className="text-gray-300"/>
                 <button onClick={() => handleNavigateToRelated('contract')} disabled={data.type === 'contract'} className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'contract' ? 'bg-green-100 text-green-800 ring-2 ring-green-400' : 'bg-gray-100 text-gray-500'}`}>3. Zmluva</button>
            </div>
            <div className="flex gap-2 ml-4">{data.type === 'quote' && (<button onClick={() => createRelatedOrder(data)} className="px-4 py-1.5 bg-blue-600 text-white hover:bg-blue-700 rounded text-sm font-bold flex items-center gap-2 shadow whitespace-nowrap"><FileInput size={14}/> Vytvoriť Objednávku</button>)}{data.type === 'order' && (<button onClick={() => createRelatedContract(data)} className="px-4 py-1.5 bg-green-600 text-white hover:bg-green-700 rounded text-sm font-bold flex items-center gap-2 shadow whitespace-nowrap"><FileCheck size={14}/> Vytvoriť Zmluva</button>)}</div>
        </div>
      </div>

      {/* ... MODALS ... */}
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={handleCreateQuote} />
      <ProductDatabaseModal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} onSelectProduct={handleSelectProduct} products={products} onAddProduct={handleAddProduct} onDeleteProduct={handleDeleteProduct} layout={data.layout} />
      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={handleAddProduct} onUpdateProduct={handleUpdateProduct} onDeleteProduct={handleDeleteProduct} customCategories={availableCategories} onAddCategory={handleAddCategory} onDeleteCategory={handleDeleteCategory} onImportCatalog={handleImportCatalog} cabinClasses={cabinClasses} onAddCabinClass={handleAddCabinClass} onUpdateCabinClass={handleUpdateCabinClass} onDeleteCabinClass={handleDeleteCabinClass} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details, email: c.email, phone: c.phone}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details, email: s.email, phone: s.phone}, logoUrl: s.logoUrl})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <TemplateDatabaseModal isOpen={isTemplateModalOpen} onClose={() => setIsTemplateModalOpen(false)} mode={templateModalMode} templateType={templateContext} templates={templates} onSelectTemplate={handleLoadTemplate} onSaveTemplate={handleSaveTemplate} onDeleteTemplate={handleDeleteTemplate} />
      <ContractRepositoryModal isOpen={isContractRepoOpen} onClose={() => setIsContractRepoOpen(false)} templates={contractTemplates} onSelectTemplate={handleSelectContractTemplate} onSaveCurrent={handleSaveContractTemplate} onDeleteTemplate={handleDeleteContractTemplate} />
      <SettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={settings} onSaveSettings={handleSaveSettings} onExportData={handleExportData} onImportData={handleImportData} onFactoryReset={handleFactoryReset} appVersion={APP_VERSION} availableCategories={availableCategories} />
      <EmailModal isOpen={isEmailModalOpen} onClose={() => setIsEmailModalOpen(false)} onSend={handleSendEmail} defaultTo={emailModalProps.to} defaultSubject={emailModalProps.subject} defaultMessage={emailModalProps.message} />
      <MaterialCalculatorModal 
          key={data.id} // FORCE RESET ON QUOTE CHANGE
          isOpen={isMaterialModalOpen} 
          onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout || DEFAULT_LAYOUT} 
          onInsert={handleMaterialWizardInsert} 
          products={products} 
          customCategories={availableCategories} 
          onAddCategory={handleAddCategory} 
          cabinClasses={cabinClasses}
          initialState={data.wizardData} 
      />
      {showArchive && (
          <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 no-print">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-5xl max-h-[85vh] flex flex-col">
                  <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl"><h2 className="text-xl font-bold flex items-center gap-2"><Archive className="text-blue-600"/> Archív</h2><button onClick={() => setShowArchive(false)} className="p-2 hover:bg-gray-200 rounded-full"><X size={20}/></button></div>
                  <div className="p-4 border-b bg-white"><div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} /><input type="text" placeholder="Hľadať..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" /></div></div>
                  <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                      {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase()) || q.clientReference?.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => (
                          <div key={q.id} className="p-4 bg-white border border-gray-200 rounded-lg mb-2 flex justify-between items-center shadow-sm hover:border-blue-300 transition-all">
                              <div>
                                  <div className="font-bold text-lg text-gray-800 flex items-center gap-2">{q.number} {q.quoteMode === 'control_system' && <span className="text-[10px] bg-green-500 text-white px-1.5 py-0.5 rounded font-bold uppercase">RS</span>}</div>
                                  <div className="text-sm text-gray-600 font-medium">{q.client.name || 'Bez klienta'} {q.clientReference && <span className="text-blue-600 ml-2">({q.clientReference})</span>}</div>
