import React from 'react';
import { LiftLayoutData, ControlSystemLayout } from '../types';
import { Eye, ClipboardList, AlertTriangle, Settings, ShieldCheck, Zap, Cpu } from 'lucide-react';
import { LiftLayoutSketch } from './LiftLayoutSketch';

interface TechSpecTableProps {
  data: LiftLayoutData;
  controlData?: ControlSystemLayout; // Added support for Control System Data
  isVisible: boolean;
  onToggleVisibility: () => void;
  embedded?: boolean;
  mode: 'lift' | 'control_system'; // Added Mode
}

export const TechSpecTable: React.FC<TechSpecTableProps> = ({
  data,
  controlData,
  isVisible,
  onToggleVisibility,
  embedded = false,
  mode
}) => {

  const getLiftTypeLabel = (val: string) => {
      const map: Record<string, string> = { 
          'passenger': 'Osobný výťah', 
          'freight': 'Nákladný výťah', 
          'home': 'Domáci výťah', 
          'hospital': 'Lôžkový výťah',
          'invalid': 'Invalidný (EN81-70)'
      };
      return map[val] || val;
  };
  const getDriveLabel = (val: string) => {
      const map: Record<string, string> = { 'traction': 'Trakčný', 'hydraulic': 'Hydraulický', 'mrl': 'MRL (Bez strojovne)', 'drum': 'Bubnový' };
      return map[val] || val;
  };
  const getDoorLabel = (val?: string) => {
      const map: Record<string, string> = { 'central': 'Automatické Centrálne', 'telescopic': 'Automatické Teleskopické', 'bus': 'Ručné + BUS (Sklápacie)' };
      return map[val || 'central'] || val;
  };

  const getTractionLabel = (val?: string) => {
      if (val === 'belts') return 'Pásy (Certifikované)';
      if (val === 'ctp') return 'CTP Laná (Plast)';
      return 'Oceľové laná';
  };

  const getSafetyMeasures = () => {
      const measures = [];
      if (data.pitDepth < 1100 || data.headroomHeight < 3400) {
          measures.push("Znížená hlava/priehlbeň (EN 81-21)");
      }
      if (data.liftType === 'invalid') {
          measures.push("Výbava invalid (EN 81-70)");
      }
      return measures;
  };

  const getEntrancesLabel = () => {
      const e = data.entrances || 'A';
      if (e === 'AB') return 'A+B (Prechodný 180°)';
      if (e === 'AC') return 'A+C (Prechodný 90°)';
      return 'A (Nepriechodný)';
  };

  const safetyMeasures = getSafetyMeasures();

  const numEntrances = data.numberOfEntrances || data.numberOfStops;
  const cabinHeight = data.cabinHeight || 2100;
  const wallArea = ((data.cabinWidth + data.cabinDepth) * 2 * cabinHeight / 1000000).toFixed(2);

  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border-2 border-dashed border-gray-300 rounded-lg bg-gray-50 text-gray-400 flex justify-between items-center hover:bg-gray-100 transition cursor-pointer" onClick={onToggleVisibility}>
              <span className="flex items-center gap-2 font-bold uppercase text-sm"><ClipboardList size={18}/> Technická špecifikácia (Skrytá)</span>
              <Eye size={20}/>
          </div>
      );
  }

  // Optimized Single Column Row
  const DataRow = ({ label, value, subValue, highlight = false, isLast = false }: any) => (
      <div className={`flex items-baseline justify-between px-4 py-1 border-b border-gray-200 ${highlight ? 'bg-gray-50/80' : ''} ${isLast ? 'border-b-0' : ''}`}>
          <div className="w-1/3">
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest block">{label}</span>
          </div>
          <div className="w-2/3 text-right">
              <div className="text-[13px] font-bold text-gray-900 leading-tight">{value}</div>
              {subValue && <div className="text-[10px] text-gray-500 font-medium mt-0.5">{subValue}</div>}
          </div>
      </div>
  );

  // --- CONTENT FOR CONTROL SYSTEM MODE ---
  if (mode === 'control_system' && controlData) {
      return (
        <div className="mb-8 break-inside-avoid border-2 border-gray-800 rounded-xl overflow-hidden shadow-md bg-white">
            <div className="bg-white flex flex-col">
                {/* Header */}
                <div className="px-4 py-2 border-b-2 border-gray-800 bg-white flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <div className="bg-green-600 text-white p-1 rounded">
                            <Cpu size={14} />
                        </div>
                        <h3 className="text-sm font-bold text-gray-900 uppercase tracking-widest">Špecifikácia Riadiaceho Systému</h3>
                    </div>
                    {!embedded && <button onClick={onToggleVisibility} className="text-gray-300 hover:text-blue-600 transition no-print"><Eye size={16} /></button>}
                </div>

                <div className="flex flex-row items-stretch">
                    {/* COL 1 */}
                    <div className="w-1/2 border-r border-gray-200">
                        <DataRow label="Pohon" value={controlData.driveType === 'gearless' ? 'Bezprevodový' : controlData.driveType === 'geared' ? 'Prevodový' : 'Hydraulika'} subValue={controlData.driveManufacturer} highlight/>
                        <DataRow label="Parametre Motora" value={`${controlData.motorPower} kW / ${controlData.nominalCurrent} A`} subValue={`Brzda: ${controlData.brakeVoltage}`} />
                        <DataRow label="Riadenie" value={controlData.operationMode === 'simplex' ? 'Simplex' : controlData.operationMode === 'duplex' ? 'Duplex' : 'Skupina'} subValue={`Umiestnenie: ${controlData.mainCabinetLocation}`} highlight/>
                        <DataRow label="Revízia" value={controlData.inspectionBox ? 'Revízna skrinka (Box)' : 'Bez revíznej jazdy'} />
                        <DataRow label="Stanice / Zdvih" value={`${controlData.numberOfStops} Staníc`} subValue={`Zdvih: ${(controlData.travel/1000).toFixed(2)}m / Hlava: ${controlData.shaftHeadroom}mm`} highlight/>
                    </div>
                    {/* COL 2 */}
                    <div className="w-1/2">
                        <DataRow label="Dvere" value={controlData.doorType === 'automatic' ? 'Automatické' : controlData.doorType === 'bus' ? 'BUS' : 'Ručné'} subValue={controlData.doorManufacturer ? `${controlData.doorManufacturer} (${controlData.doorControl})` : controlData.doorControl} highlight/>
                        <DataRow label="Displeje" value={`Kabína: ${controlData.displaysCabin.toUpperCase()}`} subValue={`Stanice: ${controlData.displaysLanding.toUpperCase()} (${controlData.landingStationsConfiguration === 'all' ? 'Všetky' : 'Len 0'})`} />
