                    <div><label className="text-[9px] uppercase font-bold text-blue-800 block mb-1">Šírka</label><input type="number" value={data.layout?.cabinWidth} onChange={e => handleLayoutChange('cabinWidth', +e.target.value)} className="w-full h-10 border border-blue-300 rounded px-2 text-center font-bold text-xl bg-white text-blue-900"/></div>
                    <div><label className="text-[9px] uppercase font-bold text-blue-800 block mb-1">Hĺbka</label><input type="number" value={data.layout?.cabinDepth} onChange={e => handleLayoutChange('cabinDepth', +e.target.value)} className="w-full h-10 border border-blue-300 rounded px-2 text-center font-bold text-xl bg-white text-blue-900"/></div>
                    <div className="col-span-2"><label className="text-[9px] uppercase font-bold text-blue-800 block mb-1">Výška Kabíny</label><input type="number" value={data.layout?.cabinHeight || 2100} onChange={e => handleLayoutChange('cabinHeight', +e.target.value)} className="w-full h-8 border border-blue-300 rounded px-2 text-center font-bold text-base bg-white text-blue-900"/></div>
