                    <div className="col-span-2 mt-1"><button onClick={handleRecalculateLoad} className="w-full h-8 bg-blue-100 hover:bg-blue-200 text-blue-800 border border-blue-300 rounded font-bold text-[10px] flex items-center justify-center gap-2 transition"><RefreshCw size={12}/> Prepočítať Nosnosť</button></div>
                </div>
                <div className="col-span-4 grid grid-cols-2 gap-3 p-3 bg-gray-50 rounded-lg border border-gray-200">
                    <div className="col-span-2 text-xs font-bold text-gray-500 uppercase border-b border-gray-200 pb-1 mb-1">Dvere Technológia</div>
