            {isContractMode && <h3 className="font-bold text-lg mb-4 text-center uppercase tracking-widest border-b pb-2">Príloha č. 1: Položkovitý Rozpočet</h3>}

            <div className="space-y-4">
                {data.categories.map(cat => <CategoryTable key={cat.id} category={cat} currency={data.currency} globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin} onUpdateCategory={(id, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id === id ? {...c, [f]: v} : c)}))} onDeleteCategory={(id) => setData(prev => ({...prev, categories: prev.categories.filter(c => c.id !== id)}))} onAddItem={handleAddItem} onUpdateItem={(cid, iid, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)}))} onDeleteItem={(cid, iid) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)}))} onAiSuggest={handleAiCategoryItems} onOpenCatalog={handleOpenCatalog} onMoveCategory={moveCategory} isAiLoading={isAiLoading === cat.id} draggable={true} onDragStart={onDragStartCat} onDragOver={onDragOverCat} onDragEnd={onDragEndCat} hidePrices={data.hideItemPrices || isContractMode} readOnly={data.type !== 'quote'} mode={data.quoteMode} />)}
                {!isContractMode && <div className="no-print mt-4 p-4 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center gap-2 bg-gray-50 hover:bg-gray-100 transition"><span className="text-sm font-bold uppercase mb-2">Pridať novú sekciu</span><div className="flex flex-wrap justify-center gap-2"><button onClick={() => addCategory('items', 'Nová Kategória')} className="px-3 py-1.5 bg-white border border-gray-300 rounded-full text-sm font-bold hover:border-blue-500 hover:text-blue-600 shadow-sm flex items-center gap-1"><PlusCircle size={14}/> Prázdna Kategória</button><button onClick={() => addCategory('text', 'Textová Sekcia')} className="px-3 py-1.5 bg-white border border-gray-300 rounded-full text-sm font-bold hover:border-purple-500 hover:text-purple-600 shadow-sm flex items-center gap-1"><FileText size={14}/> Text / Obrázok</button></div></div>}
            </div>

            <div className="mt-12 pt-4 border-t-2 border-gray-800 flex justify-end break-inside-avoid">
                <div className="w-full max-w-md">
                    <div className="flex justify-between mb-2 text-sm text-gray-500 no-print"><span>Náklady (Bez DPH):</span><span>{formatCurrency(totals.totalPurchase)}</span></div>
                    <div className="no-print mb-6 print:mb-2 bg-white p-4 print:p-2 rounded-xl border-2 border-blue-100 shadow-lg">
                        <div className="text-sm font-bold text-gray-800 uppercase tracking-wider text-center mb-3 border-b pb-2">Ekonomika projektu</div>
                        <div className="grid grid-cols-2 gap-6 print:gap-2 mb-4 print:mb-2">
                            <div className="flex flex-col gap-2 p-3 bg-blue-50/50 rounded-lg border border-blue-200">
                                <div className="text-xs font-bold text-blue-800 uppercase text-center border-b border-blue-200 pb-1">{isControlMode ? 'Riadiaci Systém' : 'Výťah'}</div>
                                <div className="flex justify-between text-xs text-gray-600"><span>Nákup:</span><span className="font-mono font-bold">{totals.liftCost.toFixed(0)} €</span></div>
                                <div className="flex items-center gap-2"><span className="text-xs font-bold w-12">Marža:</span><div className="relative flex-1"><input type="number" value={data.globalMargin} onChange={e => setData({...data, globalMargin: +e.target.value})} className="w-full text-center font-bold text-blue-800 bg-white border border-blue-300 rounded px-1 text-sm h-8"/><span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-blue-400 font-bold">%</span></div></div>
                                <div className="flex justify-between items-center bg-blue-600 text-white p-2 rounded shadow-sm font-bold text-sm"><span>Zisk:</span><span>{totals.liftProfit.toFixed(2)} €</span></div>
                            </div>
                            <div className="flex flex-col gap-2 p-3 bg-orange-50/50 rounded-lg border border-orange-200">
                                <div className="text-xs font-bold text-orange-800 uppercase text-center border-b border-orange-200 pb-1">Šachta / Montáž</div>
                                <div className="flex justify-between text-xs text-gray-600"><span>Nákup:</span><span className="font-mono font-bold">{totals.shaftCost.toFixed(0)} €</span></div>
                                <div className="flex items-center gap-2"><span className="text-xs font-bold w-12">Marža:</span><div className="relative flex-1"><input type="number" value={data.shaftMargin} onChange={e => setData({...data, shaftMargin: +e.target.value})} className="w-full text-center font-bold text-orange-800 bg-white border border-orange-300 rounded px-1 text-sm h-8"/><span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-orange-400 font-bold">%</span></div></div>
                                <div className="flex justify-between items-center bg-orange-500 text-white p-2 rounded shadow-sm font-bold text-sm"><span>Zisk:</span><span>{totals.shaftProfit.toFixed(2)} €</span></div>
                            </div>
                        </div>
                        <div className="flex items-center gap-3 bg-purple-50 p-2 rounded border border-purple-100"><label className="text-xs font-bold text-purple-700 uppercase shrink-0">DPH:</label><div className="relative w-20"><input type="number" value={data.vatRate ?? 23} onChange={e => setData({...data, vatRate: +e.target.value})} className="w-full text-center font-bold text-purple-800 bg-white border border-purple-200 rounded px-1 text-sm h-7"/><span className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] text-purple-400 font-bold">%</span></div><div className="text-sm text-purple-600 font-bold ml-auto">{formatCurrency(totals.vat)}</div></div>
                    </div>
                    <div className="flex justify-between text-2xl font-bold text-gray-900 mb-1"><span>Cena Celkom:</span><span>{formatCurrency(totals.totalSelling)}</span></div>
                    <div className="text-right text-xs text-gray-500 mb-2">bez DPH</div>
                    <div className="flex justify-between text-sm text-gray-600 pt-2 border-t border-gray-200"><span>DPH ({data.vatRate ?? 23}%):</span><span>{formatCurrency(totals.vat)}</span></div>
                    <div className="flex justify-between text-lg font-bold text-black mt-2 bg-gray-100 p-2 rounded"><span>Spolu s DPH:</span><span>{formatCurrency(totals.gross)}</span></div>
                </div>
            </div>

            {!isContractMode && <div className="mt-12 break-inside-avoid"><h3 className="font-bold uppercase text-sm mb-2 text-gray-800">Obchodné podmienky & Záruka</h3><StandaloneRichTextEditor content={data.terms} onChange={val => setData({...data, terms: val})} className="min-h-[200px] print:min-h-0 print:h-auto" stickyToolbar={false} minimalPadding={true} /></div>}
            {data.type !== 'quote' && <div className="mt-16 grid grid-cols-2 gap-16 break-inside-avoid"><div><div className="border-b border-gray-800 mb-2 h-16"></div><div className="text-center text-xs font-bold uppercase text-gray-600">Dátum a Podpis (Objednávateľ)</div></div><div><div className="border-b border-gray-800 mb-2 h-16"></div><div className="text-center text-xs font-bold uppercase text-gray-600">Dátum a Podpis (Dodávateľ)</div></div></div>}
        </div>
      </div>
      <div className="print-footer"><div>{data.number} | {data.title}</div><div>Strana <span className="pageNumber"></span></div><div>SmartQuote SK</div></div>
    </div>
  );
};

