import { LiftLayoutData, Product, CabinClass, ControlSystemLayout } from '../types';
import { X, Calculator, Check, AlertTriangle, Settings, Box, Zap, Construction, Truck, Package, Hammer, ArrowLeft, ArrowRight, ListCheck, Search, Plus, Filter, Layers, Save, Trash2, GripVertical, Gauge, ScanLine, RotateCcw, FileText, Download, Copy, FolderOpen, Info, Cpu } from 'lucide-react';

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  controlLayout?: ControlSystemLayout; // Added support for Control Layout
  mode: 'lift' | 'control_system'; // Added mode
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
  initialState?: MaterialWizardData; 
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean;
        autoType?: string; 
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

interface MaterialTemplate {
    id: string;
    name: string;
