                                  >
                                      <Layers size={16}/> Zložený SET
                                  </button>
                              </div>

                              <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-lg border border-gray-200">
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Cena (€)</label>
