              const start = field === 'startStation' ? value : prev.layout?.startStation || 0;
              const labels = Array.from({length: stops}, (_, i) => i + start).join(',');
              newData.layout!.stationLabels = labels;
              if (newData.layout.entrances === 'A') {
                  newData.layout.numberOfEntrances = stops;
              }
          }
          if (field === 'entrances' && value === 'A') {
              newData.layout.numberOfEntrances = newData.layout.numberOfStops;
          }
          return newData;
      });
  };

  const handleToggleExternalShaft = (checked: boolean) => {
      handleLayoutChange('hasExternalShaft', checked);
      if (checked) {
          const exists = data.categories.find(c => c.name === 'Oceľová konštrukcia');
          if (!exists) { addCategory('items', 'Oceľová konštrukcia', SHAFT_TEMPLATE, 'shaft', SHAFT_DETAILS_HTML); }
      }
  };

  const handleRecalculateLoad = () => {
      if (!data.layout) return;
      const { cabinWidth, cabinDepth } = data.layout;
      const { suggestedLoad, persons } = calculateEn8120(cabinWidth, cabinDepth);
      setData(prev => ({ 
          ...prev, 
          layout: { 
              ...prev.layout!, 
              ratedLoad: suggestedLoad,       
              numberOfPersons: persons        
          } 
      }));
      alert(`Prepočítané pre plochu ${((cabinWidth * cabinDepth)/1000000).toFixed(2)} m2: ${suggestedLoad}kg / ${persons} osôb`);
  };

  const addCategory = (type: 'items' | 'text', name: string = 'Nová Kategória', items: QuoteItem[] = [], section: 'lift' | 'shaft' = 'lift', defaultText?: string) => {
      const newCategory: QuoteCategory = {
          id: generateId(), type, name, items, isExpanded: true, section,
          textContent: type === 'text' ? (defaultText || '') : (settings.defaultCategoryTexts?.[name] || '')
      };
      setData(prev => ({ ...prev, categories: [...prev.categories, newCategory] }));
  };

  const updateCategory = (id: string, field: keyof QuoteCategory, value: any) => {
      setData(prev => ({
          ...prev, categories: prev.categories.map(c => c.id === id ? { ...c, [field]: value } : c)
      }));
  };

  const deleteCategory = (id: string) => { setData(prev => ({ ...prev, categories: prev.categories.filter(c => c.id !== id) })); };
  const moveCategory = (id: string, direction: 'up' | 'down') => {
      const idx = data.categories.findIndex(c => c.id === id);
      if ((direction === 'up' && idx > 0) || (direction === 'down' && idx < data.categories.length - 1)) {
          const newCats = [...data.categories];
          const swapIdx = direction === 'up' ? idx - 1 : idx + 1;
          [newCats[idx], newCats[swapIdx]] = [newCats[swapIdx], newCats[idx]];
          setData(prev => ({ ...prev, categories: newCats }));
      }
  };

  const addItemToCategory = (categoryId: string, isSurcharge = false) => {
      const newItem: QuoteItem = {
          id: generateId(), description: '', unit: 'ks', quantity: 1, unitPrice: 0, purchasePrice: 0, vatRate: data.vatRate || 23, isSurcharge
      };
      setData(prev => ({
          ...prev, categories: prev.categories.map(c => c.id === categoryId ? { ...c, items: [...c.items, newItem] } : c)
      }));
  };

  const updateItem = (categoryId: string, itemId: string, field: keyof QuoteItem, value: any) => {
      setData(prev => ({
          ...prev, categories: prev.categories.map(c => c.id === categoryId ? { ...c, items: c.items.map(i => i.id === itemId ? { ...i, [field]: value } : i) } : c)
      }));
  };

  const deleteItem = (categoryId: string, itemId: string) => {
      setData(prev => ({
          ...prev, categories: prev.categories.map(c => c.id === categoryId ? { ...c, items: c.items.filter(i => i.id !== itemId) } : c)
      }));
  };

  const handleWizardInsert = (wizardData: MaterialWizardData) => {
      setData(prev => {
          let updatedCategories = [...prev.categories];
          const currentMode = prev.quoteMode || 'lift';
          const defaultCats = currentMode === 'control_system' ? CONTROL_SYSTEM_CATEGORIES : DEFAULT_CATEGORIES_LIST;

          // Process items by category
          const groupedItems: Record<string, QuoteItem[]> = {};

          wizardData.items.forEach(wizItem => {
              const newItem: QuoteItem = {
                  id: generateId(),
                  description: wizItem.description,
                  unit: wizItem.unit,
                  quantity: wizItem.quantity,
                  unitPrice: wizItem.price || 0, // Using purchase price
                  purchasePrice: wizItem.price || 0,
                  vatRate: 23,
                  isSurcharge: false
              };
              if (!groupedItems[wizItem.category]) groupedItems[wizItem.category] = [];
              groupedItems[wizItem.category].push(newItem);
          });

          // Add extra services if selected
          if (wizardData.includeTransport) {
              const transPrice = wizardData.transportPrice || 200;
              if (!groupedItems['Doprava']) groupedItems['Doprava'] = [];
              groupedItems['Doprava'].push({ id: generateId(), description: 'Doprava technológie na miesto určenia', unit: 'kpl', quantity: 1, unitPrice: transPrice, purchasePrice: transPrice, vatRate: 23 });
          }
          if (wizardData.includePackaging) {
              const packPrice = wizardData.packagingPrice || 50;
              if (!groupedItems['Balné']) groupedItems['Balné'] = [];
              groupedItems['Balné'].push({ id: generateId(), description: 'Balenie materiálu a paliet', unit: 'kpl', quantity: 1, unitPrice: packPrice, purchasePrice: packPrice, vatRate: 23 });
          }
          if (wizardData.includeAssembly) {
              if (!groupedItems['Montáž']) groupedItems['Montáž'] = [];
              groupedItems['Montáž'].push({ id: generateId(), description: 'Montáž výťahovej technológie', unit: 'kpl', quantity: 1, unitPrice: 0, purchasePrice: 0, vatRate: 23 });
          }

          // Merge into existing or new categories
          Object.entries(groupedItems).forEach(([catName, items]) => {
              const existingCatIndex = updatedCategories.findIndex(c => c.name === catName);
              if (existingCatIndex >= 0) {
                  // Replace items or Append? Let's Replace for wizard consistency
                  updatedCategories[existingCatIndex].items = items;
              } else {
                  // Create new
                  updatedCategories.push({
                      id: generateId(), type: 'items', name: catName, items: items, isExpanded: true, section: 'lift',
                      textContent: settings.defaultCategoryTexts?.[catName]
                  });
              }
          });

          // Reorder categories according to wizard preference + ensure others stay
          if (wizardData.categoryOrder && wizardData.categoryOrder.length > 0) {
              const ordered = [];
              const orderMap = new Set(wizardData.categoryOrder);

              // 1. Add explicitly ordered categories
              wizardData.categoryOrder.forEach(name => {
                  const cat = updatedCategories.find(c => c.name === name);
                  if (cat) ordered.push(cat);
                  else {
                      // If empty category requested in order, create it
                      ordered.push({ id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift', textContent: settings.defaultCategoryTexts?.[name] });
                  }
              });

              // 2. Add remaining categories that were not in the order list
              updatedCategories.forEach(c => {
                  if (!orderMap.has(c.name)) ordered.push(c);
              });

              updatedCategories = ordered;
          }

          return { ...prev, categories: updatedCategories, wizardData };
      });
  };

  const handleSaveToArchive = () => {
    const updated = { ...data, lastUpdated: Date.now() };
    const existingIndex = savedQuotes.findIndex(q => q.id === data.id);
    let newSaved = [...savedQuotes];
    if (existingIndex >= 0) { newSaved[existingIndex] = updated; } 
    else { newSaved = [updated, ...savedQuotes]; }
    setSavedQuotes(newSaved);
    setCalcSuccess("Uložené do Archívu");
    setTimeout(() => setCalcSuccess(null), 2000);
  };

  // --- NEW QUOTE CREATION LOGIC ---
  const handleCreateNewQuote = (type: 'lift' | 'control_system') => {
      const newId = generateId();
      const newNumber = generateDocNumber('quote', type);

      // Select appropriate defaults
      const initialCatsList = type === 'control_system' ? CONTROL_SYSTEM_CATEGORIES : DEFAULT_CATEGORIES_LIST;

      const newCategories: QuoteCategory[] = initialCatsList.map(name => ({
          id: generateId(),
          type: 'items',
          name: name,
          items: [],
          isExpanded: true,
          section: 'lift',
          textContent: settings.defaultCategoryTexts?.[name] || undefined
      }));

      // Update counters
      const newSettings = { ...settings };
      if (type === 'control_system') {
          newSettings.nextRsSequence = (newSettings.nextRsSequence || 1) + 1;
      } else {
          newSettings.nextCpSequence = newSettings.nextCpSequence + 1;
      }
      setSettings(newSettings);

      setData({
          id: newId,
          number: newNumber,
          type: 'quote',
          quoteMode: type, // SET MODE
          title: type === 'control_system' ? 'Cenová Ponuka - Riadiaci Systém' : 'Cenová Ponuka - Výťah',
          date: new Date().toISOString().split('T')[0],
          validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
          clientReference: '',
          supplier: data.supplier, // Keep current supplier
          client: { name: '', details: '' },
          layout: { ...DEFAULT_LAYOUT }, // Reset Layout
          controlLayout: { ...DEFAULT_CONTROL_LAYOUT }, // Reset Control Layout
          categories: newCategories,
          terms: DEFAULT_TERMS_HTML,
          currency: '€',
          globalMargin: 15,
          shaftMargin: 20,
          vatRate: 23,
          hideItemPrices: true,
          showTechSpecs: true,
          contractBody: DEFAULT_CONTRACT_TEXT
      });

      setIsNewQuoteModalOpen(false);
      setShowArchive(false);
  };

  const handleCreateOrder = () => {
     const newId = generateId();
     const newNumber = generateDocNumber('order');
     const order: QuoteData = {
         ...data, id: newId, number: newNumber, type: 'order', relatedDocId: data.id,
         date: new Date().toISOString().split('T')[0], title: 'Objednávka'
     };
     setSavedQuotes([order, ...savedQuotes]);
     setData(order);
     setSettings(prev => ({...prev, nextObjSequence: prev.nextObjSequence + 1}));
     setCalcSuccess("Vytvorená Objednávka");
     setTimeout(() => setCalcSuccess(null), 2000);
  };

  const handleCreateContract = () => {
     const newId = generateId();
     const newNumber = generateDocNumber('contract');
     let contractHtml = DEFAULT_CONTRACT_TEXT
        .replace('[CISLO_DOKLADU]', newNumber)
        .replace('[NAZOV_DODAVATELA]', data.supplier.name)
        .replace('[DETAILY_DODAVATELA]', data.supplier.details)
        .replace('[NAZOV_KLIENTA]', data.client.name)
        .replace('[DETAILY_KLIENTA]', data.client.details)
        .replace('[CENA_CELKOM]', totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2}) + ' €');

     const contract: QuoteData = {
         ...data, id: newId, number: newNumber, type: 'contract', relatedDocId: data.id,
         date: new Date().toISOString().split('T')[0], title: 'Zmluva o Dielo',
         contractBody: contractHtml
     };
     setSavedQuotes([contract, ...savedQuotes]);
     setData(contract);
     setSettings(prev => ({...prev, nextPlSequence: prev.nextPlSequence + 1}));
     setCalcSuccess("Vytvorená Zmluva");
     setTimeout(() => setCalcSuccess(null), 2000);
  };

  const handleLoadQuote = (q: QuoteData) => {
      // Ensure backward compatibility
      const loadedMode = q.quoteMode || 'lift';
      const loadedControlLayout = q.controlLayout || { ...DEFAULT_CONTROL_LAYOUT };

      setData({ 
          ...q, 
          quoteMode: loadedMode,
          controlLayout: loadedControlLayout 
      });
      setShowArchive(false);
  };

  const handleDeleteQuote = (id: string) => {
      if(window.confirm("Naozaj vymazať tento doklad z archívu?")) {
          setSavedQuotes(savedQuotes.filter(q => q.id !== id));
      }
  };

  const handleAiSuggest = async (catId: string, catName: string) => {
      setIsAiLoading(catId);
      const suggestion = await generateSuggestion(`Navrhni 3 položky pre kategóriu "${catName}" pre výťah.`, 'category_items');
      if (suggestion) {
          const items = suggestion.split(',').map(s => s.trim()).filter(s => s).map(desc => ({
              id: generateId(), description: desc, unit: 'ks', quantity: 1, unitPrice: 0, purchasePrice: 0, vatRate: 23
          }));
          setData(prev => ({ ...prev, categories: prev.categories.map(c => c.id === catId ? { ...c, items: [...c.items, ...items] } : c) }));
      }
      setIsAiLoading(false);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportData = () => {
      const backup = {
          version: 2,
          appVersion: APP_VERSION,
          timestamp: Date.now(),
          settings,
          quotes: savedQuotes,
          products,
          clients,
          suppliers,
          templates,
          contractTemplates,
          cabinClasses,
          customCategories: availableCategories
      };
      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `smartquote_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleImportData = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const content = e.target?.result as string;
              const backup = JSON.parse(content);
              if (backup.settings) setSettings(backup.settings);
              if (backup.quotes) setSavedQuotes(backup.quotes);
              if (backup.products) setProducts(backup.products);
              if (backup.clients) setClients(backup.clients);
              if (backup.suppliers) setSuppliers(backup.suppliers);
              if (backup.templates) setTemplates(backup.templates);
              if (backup.contractTemplates) setContractTemplates(backup.contractTemplates);
              if (backup.cabinClasses) setCabinClasses(backup.cabinClasses);
              if (backup.customCategories) setAvailableCategories(backup.customCategories);
              alert("Dáta úspešne obnovené.");
          } catch (err) { alert("Chyba pri importe súboru."); }
      };
      reader.readAsText(file);
  };

  const handleFactoryReset = () => {
      localStorage.clear();
      window.location.reload();
  };

  const handleCategoryDragStart = (e: React.DragEvent, id: string) => {
      setDraggedCatId(id);
      e.dataTransfer.effectAllowed = 'move';
  };
  const handleCategoryDragOver = (e: React.DragEvent, id: string) => {
      e.preventDefault();
      if (!draggedCatId || draggedCatId === id) return;

      const cats = [...data.categories];
      const srcIdx = cats.findIndex(c => c.id === draggedCatId);
      const dstIdx = cats.findIndex(c => c.id === id);

      const [removed] = cats.splice(srcIdx, 1);
      cats.splice(dstIdx, 0, removed);

      setData(prev => ({ ...prev, categories: cats }));
  };
  const handleCategoryDragEnd = () => {
      setDraggedCatId(null);
  };

  if (!isAuthenticated) {
    return <LoginGate onLogin={handleLogin} />;
  }

  // --- RENDERING ---

  if (showArchive) {
      const filteredQuotes = savedQuotes.filter(q => 
        q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || 
        q.clientReference?.toLowerCase().includes(archiveSearch.toLowerCase()) ||
        q.client.name.toLowerCase().includes(archiveSearch.toLowerCase())
      );

      return (
          <div className="min-h-screen bg-gray-50 p-8 animate-in fade-in">
              <div className="max-w-6xl mx-auto">
                  <div className="flex justify-between items-center mb-6">
                      <div className="flex items-center gap-4">
                        <button onClick={() => setShowArchive(false)} className="p-2 bg-white rounded-full shadow hover:bg-gray-100"><ArrowRightLeft size={20}/></button>
                        <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-2"><Archive className="text-blue-600"/> Archív Dokladov</h1>
                      </div>
                      <div className="flex gap-2">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18}/>
                            <input 
                                className="pl-10 pr-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none w-64"
                                placeholder="Hľadať CP, Klienta..."
                                value={archiveSearch}
                                onChange={e => setArchiveSearch(e.target.value)}
                            />
                        </div>
                        <button onClick={() => setIsNewQuoteModalOpen(true)} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 flex items-center gap-2">
                            <PlusCircle size={18}/> Nová Ponuka
                        </button>
                      </div>
                  </div>

                  <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                      <table className="w-full text-left">
                          <thead className="bg-gray-50 border-b">
                              <tr>
                                  <th className="p-4 font-bold text-gray-600 text-sm">Číslo</th>
                                  <th className="p-4 font-bold text-gray-600 text-sm">Typ</th>
                                  <th className="p-4 font-bold text-gray-600 text-sm">Dátum</th>
                                  <th className="p-4 font-bold text-gray-600 text-sm">Klient / Referencia</th>
                                  <th className="p-4 font-bold text-gray-600 text-sm text-right">Suma</th>
                                  <th className="p-4 font-bold text-gray-600 text-sm text-right">Akcie</th>
                              </tr>
                          </thead>
                          <tbody className="divide-y">
                              {filteredQuotes.map(q => (
                                  <tr key={q.id} className="hover:bg-blue-50 transition group">
                                      <td className="p-4 font-mono font-bold text-blue-600">{q.number}</td>
                                      <td className="p-4">
                                          <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${q.type === 'order' ? 'bg-purple-100 text-purple-700' : q.type === 'contract' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                                              {q.type === 'quote' ? (q.quoteMode === 'control_system' ? 'Ponuka (RS)' : 'Ponuka (Výťah)') : q.type === 'order' ? 'Objednávka' : 'Zmluva'}
                                          </span>
                                      </td>
                                      <td className="p-4 text-sm text-gray-600">{new Date(q.date).toLocaleDateString('sk-SK')}</td>
                                      <td className="p-4">
                                          <div className="font-bold text-gray-800">{q.client.name || 'Bez klienta'}</div>
                                          <div className="text-xs text-gray-500">{q.clientReference}</div>
                                      </td>
                                      <td className="p-4 text-right font-bold text-gray-800">
                                          {/* Calculate total on fly for display */}
                                          {(() => {
                                              let total = 0;
                                              q.categories.forEach(c => c.items.forEach(i => total += i.quantity * i.unitPrice * (1 + (c.section === 'shaft' ? q.shaftMargin : q.globalMargin)/100)));
                                              return (total * (1 + (q.vatRate || 23)/100)).toLocaleString('sk-SK', {minimumFractionDigits: 2}) + ' €';
                                          })()}
                                      </td>
                                      <td className="p-4 text-right flex justify-end gap-2 opacity-60 group-hover:opacity-100 transition-opacity">
                                          <button onClick={() => handleLoadQuote(q)} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200" title="Otvoriť"><Edit size={16}/></button>
                                          <button onClick={() => {
                                              const copy = { ...q, id: generateId(), number: q.number + '-COPY', title: q.title + ' (Kópia)', date: new Date().toISOString().split('T')[0] };
                                              setSavedQuotes([copy, ...savedQuotes]);
                                          }} className="p-2 bg-gray-100 text-gray-600 rounded hover:bg-gray-200" title="Duplikovať"><Copy size={16}/></button>
                                          <button onClick={() => handleDeleteQuote(q.id)} className="p-2 bg-red-50 text-red-500 rounded hover:bg-red-100" title="Vymazať"><Trash2 size={16}/></button>
                                      </td>
                                  </tr>
                              ))}
                              {filteredQuotes.length === 0 && (
                                  <tr><td colSpan={6} className="p-8 text-center text-gray-400 italic">Žiadne doklady v archíve.</td></tr>
                              )}
                          </tbody>
                      </table>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className={`min-h-screen bg-gray-100 font-sans print:bg-white print:text-black ${isPreviewMode ? 'bg-gray-500' : ''}`}>

      {/* HEADER TOOLBAR (No Print) */}
      <div className={`bg-gray-900 text-white shadow-md sticky top-0 z-50 print:hidden transition-all duration-300 ${isPreviewMode ? '-translate-y-full absolute' : ''}`}>
        <div className="max-w-[1400px] mx-auto px-4 py-2 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-1.5 rounded-lg font-bold text-xl tracking-tight flex items-center gap-2">
                    <Zap size={20} className="text-yellow-300"/> SmartQuote <span className="text-xs bg-white/20 px-1.5 rounded py-0.5 font-mono">{APP_VERSION}</span>
                </div>

                <div className="h-8 w-px bg-gray-700 mx-2"></div>

                <button onClick={() => setShowArchive(true)} className="flex items-center gap-2 px-3 py-1.5 bg-gray-800 hover:bg-gray-700 rounded-lg transition text-sm">
                    <Archive size={16} className="text-blue-300"/> Archív
                </button>

                <button onClick={() => setIsNewQuoteModalOpen(true)} className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 hover:bg-blue-500 text-white rounded-lg transition text-sm font-bold shadow-lg shadow-blue-900/50">
                    <PlusCircle size={16}/> Nová CP
                </button>
            </div>

            <div className="flex items-center gap-2">
                 <button onClick={() => setIsCatalogOpen(true)} className="flex items-center gap-2 px-3 py-1.5 text-gray-300 hover:text-white hover:bg-gray-800 rounded transition text-xs">
                    <Settings size={14}/> Katalóg
                 </button>
                 <button onClick={() => setIsClientModalOpen(true)} className="flex items-center gap-2 px-3 py-1.5 text-gray-300 hover:text-white hover:bg-gray-800 rounded transition text-xs">
                    <Users size={14}/> Klienti
                 </button>
                 <button onClick={() => setIsSupplierModalOpen(true)} className="flex items-center gap-2 px-3 py-1.5 text-gray-300 hover:text-white hover:bg-gray-800 rounded transition text-xs">
                    <Building size={14}/> Dodávatelia
                 </button>

                 <div className="h-8 w-px bg-gray-700 mx-2"></div>

                 <button onClick={handleSaveToArchive} className="flex items-center gap-2 px-4 py-1.5 bg-green-600 hover:bg-green-500 text-white rounded-lg transition font-bold shadow-lg shadow-green-900/50 text-sm">
                    <Save size={16}/> Uložiť
                 </button>
                 <button onClick={handleLogout} className="p-2 text-red-300 hover:bg-red-900/30 rounded-full ml-2" title="Odhlásiť"><LogOut size={16}/></button>
            </div>
        </div>
      </div>

      {/* SUCCESS NOTIFICATION */}
      {calcSuccess && (
          <div className="fixed top-20 right-8 bg-green-600 text-white px-6 py-3 rounded-lg shadow-xl z-[100] animate-in slide-in-from-right fade-in flex items-center gap-3">
              <CheckCircle size={20} className="text-white"/>
              <span className="font-bold">{calcSuccess}</span>
          </div>
      )}

      {/* PREVIEW MODE TOGGLE */}
      {isPreviewMode && (
          <button 
            onClick={() => setIsPreviewMode(false)} 
            className="fixed bottom-8 right-8 bg-gray-800 text-white px-6 py-3 rounded-full shadow-2xl z-50 font-bold hover:bg-gray-700 flex items-center gap-2 border-2 border-white/20 animate-in slide-in-from-bottom"
          >
              <Edit size={18}/> Späť na úpravu
          </button>
      )}

      {/* MAIN CONTENT WRAPPER */}
      <div className={`max-w-[210mm] mx-auto transition-all duration-500 ease-in-out ${isPreviewMode ? 'py-8 scale-95' : 'py-8 print:p-0'}`}>

        {/* DOCUMENT SHEET */}
        <div ref={printContentRef} className="bg-white shadow-2xl print:shadow-none min-h-[297mm] relative flex flex-col print:block">

            {/* --- TOP BAR (EDIT ONLY) --- */}
            {!isPreviewMode && !isContractMode && (
                <div className="p-4 border-b bg-gray-50 flex items-center justify-between no-print rounded-t-lg">
                    <div className="flex gap-2">
                        <button onClick={() => setIsMaterialModalOpen(true)} className={`flex items-center gap-2 px-4 py-2 rounded-lg font-bold transition shadow-sm border ${data.quoteMode === 'control_system' ? 'bg-green-100 text-green-800 border-green-200' : 'bg-orange-100 text-orange-800 border-orange-200'}`}>
                           {data.quoteMode === 'control_system' ? <Cpu size={18}/> : <Calculator size={18}/>}
                           {data.quoteMode === 'control_system' ? 'Sprievodca RS' : 'Sprievodca Materiálom'}
                        </button>
                        <button onClick={() => { setTemplateModalMode('save'); setTemplateContext('lift'); setIsTemplateModalOpen(true); }} className="flex items-center gap-2 px-3 py-2 bg-white border border-gray-300 rounded-lg text-gray-600 font-bold hover:bg-gray-100">
                           <LayoutTemplate size={16}/> Uložiť ako Šablónu
                        </button>
                        <button onClick={() => { setTemplateModalMode('select'); setTemplateContext('lift'); setIsTemplateModalOpen(true); }} className="flex items-center gap-2 px-3 py-2 bg-white border border-gray-300 rounded-lg text-gray-600 font-bold hover:bg-gray-100">
                           <LayoutTemplate size={16}/> Načítať Šablónu
                        </button>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={handleCreateOrder} className="px-3 py-2 bg-purple-100 text-purple-700 border border-purple-200 rounded-lg font-bold hover:bg-purple-200 flex items-center gap-2 text-xs">
                            <FileCheck size={16}/> Vytvoriť OBJ
                        </button>
                        <button onClick={handleCreateContract} className="px-3 py-2 bg-green-100 text-green-700 border border-green-200 rounded-lg font-bold hover:bg-green-200 flex items-center gap-2 text-xs">
                            <FileText size={16}/> Vytvoriť Zmluvu
                        </button>
                        <div className="w-px bg-gray-300 mx-2"></div>
                        <button onClick={() => setIsPreviewMode(true)} className="px-3 py-2 text-gray-500 hover:text-black hover:bg-gray-200 rounded"><Maximize size={20}/></button>
                        <button onClick={() => setIsEmailModalOpen(true)} className="px-3 py-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded"><Mail size={20}/></button>
                        <button onClick={handlePrint} className="px-3 py-2 text-gray-500 hover:text-black hover:bg-gray-200 rounded"><Printer size={20}/></button>
                    </div>
                </div>
            )}

            {/* --- PRINT HEADER --- */}
            <div className="p-12 pb-6 print:p-0 print:mb-4">
                <div className="flex justify-between items-start border-b-2 border-gray-900 pb-6 mb-6">
                    <div>
                         {/* Dynamic Logo */}
                         {data.logoUrl ? (
                             <img src={data.logoUrl} alt="Logo" className="h-16 object-contain mb-4"/>
                         ) : (
                             <div className="text-3xl font-black text-gray-900 tracking-tighter mb-1 flex items-center gap-2">
                                <Building size={32}/> {data.supplier.name}
                             </div>
                         )}
                         <div className="text-xs text-gray-500 whitespace-pre-wrap max-w-md leading-relaxed">{data.supplier.details}</div>
                    </div>
                    <div className="text-right">
                        <div className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-1">
                            {isContractMode ? 'Zmluva číslo' : isOrderMode ? 'Objednávka číslo' : 'Cenová Ponuka číslo'}
                        </div>
                        <div className="flex items-center justify-end gap-2 group relative">
                            <h1 className="text-2xl font-black text-gray-900">{data.number}</h1>
                            {!isPreviewMode && (
                                <button onClick={() => setIsNumberEditable(!isNumberEditable)} className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-blue-500 transition no-print"><Edit size={14}/></button>
                            )}
                            {isNumberEditable && (
                                <div className="absolute top-10 right-0 bg-white p-2 shadow-xl border z-50 rounded flex gap-1">
                                    <input className="border p-1 text-sm" value={data.number} onChange={e => setData({...data, number: e.target.value})} />
                                    <button onClick={() => setIsNumberEditable(false)} className="bg-blue-500 text-white p-1 rounded"><CheckCircle size={14}/></button>
                                </div>
                            )}
                        </div>
                        <div className="text-sm text-gray-500 mt-1 font-medium">{new Date(data.date).toLocaleDateString('sk-SK')}</div>
                        {!isContractMode && !isOrderMode && <div className="text-xs text-red-500 font-bold mt-1">Platnosť do: {new Date(data.validUntil).toLocaleDateString('sk-SK')}</div>}
                    </div>
                </div>

                <div className="flex justify-between items-start mb-8 gap-8">
                    <div className="w-1/2">
                        <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 border-b border-gray-100 pb-1">Odberateľ (Klient)</div>
                        {!isPreviewMode ? (
                            <div className="group relative border border-transparent hover:border-blue-200 rounded p-2 -ml-2 transition-colors">
                                <input 
                                    className="font-bold text-lg text-gray-900 w-full bg-transparent focus:outline-none placeholder-gray-300" 
                                    placeholder="Zadajte meno klienta..." 
                                    value={data.client.name}
                                    onChange={e => setData({...data, client: {...data.client, name: e.target.value}})}
                                />
                                <textarea 
                                    className="text-sm text-gray-600 w-full bg-transparent resize-none focus:outline-none mt-1 h-20 placeholder-gray-300 leading-relaxed" 
                                    placeholder="Zadajte adresu a detaily..."
                                    value={data.client.details}
                                    onChange={e => setData({...data, client: {...data.client, details: e.target.value}})}
                                />
                                <button onClick={() => setIsClientModalOpen(true)} className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 bg-blue-50 p-1.5 rounded text-blue-600 hover:bg-blue-100 transition no-print"><Search size={14}/></button>
                            </div>
                        ) : (
                            <div>
                                <div className="font-bold text-lg text-gray-900">{data.client.name}</div>
                                <div className="text-sm text-gray-600 whitespace-pre-wrap leading-relaxed">{data.client.details}</div>
                            </div>
                        )}
                    </div>
                    <div className="w-1/2">
                         <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2 border-b border-gray-100 pb-1">Projekt / Referencia</div>
                         <textarea 
                            className={`w-full text-lg font-bold text-gray-900 bg-transparent resize-none focus:outline-none leading-tight ${isPreviewMode ? '' : 'hover:bg-gray-50 rounded p-2 -ml-2 border border-transparent hover:border-gray-200'}`}
                            placeholder="Názov projektu..."
                            rows={2}
                            value={data.clientReference}
                            onChange={e => setData({...data, clientReference: e.target.value})}
                            readOnly={isPreviewMode}
                        />
                         <textarea 
                            ref={titleInputRef}
                            className={`w-full text-sm text-gray-500 bg-transparent resize-none focus:outline-none mt-2 italic leading-relaxed ${isPreviewMode ? '' : 'hover:bg-gray-50 rounded p-2 -ml-2 border border-transparent hover:border-gray-200'}`}
                            value={data.title}
                            onChange={e => {
                                setData({...data, title: e.target.value});
                                e.target.style.height = 'auto';
                                e.target.style.height = e.target.scrollHeight + 'px';
                            }}
                            readOnly={isPreviewMode}
                        />
                    </div>
                </div>
            </div>

            {/* --- CONTRACT MODE CONTENT --- */}
            {isContractMode ? (
                <StandaloneRichTextEditor 
                    content={data.contractBody || ''} 
                    onChange={val => setData({...data, contractBody: val})}
                    stickyToolbar={!isPreviewMode}
                    minimalPadding={true}
                />
            ) : (
            /* --- QUOTE MODE CONTENT --- */
            <div className="flex-1 px-12 print:px-0 flex flex-col">

                {/* TECH SPEC & SKETCH */}
                {data.showTechSpecs && !isOrderMode && (
                    <TechSpecTable 
                        data={data.layout!} 
                        controlData={data.controlLayout}
                        isVisible={true} 
                        onToggleVisibility={() => setData({...data, showTechSpecs: !data.showTechSpecs})} 
                        mode={data.quoteMode || 'lift'}
                    />
                )}

                {/* CATEGORIES */}
                <div className="space-y-6 print:space-y-4">
                    {data.categories.map(cat => (
                        (cat.type === 'items') ? (
                            <CategoryTable 
                                key={cat.id} 
                                category={cat} 
                                currency={data.currency}
                                globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                                onUpdateCategory={updateCategory}
                                onDeleteCategory={deleteCategory}
                                onAddItem={addItemToCategory}
                                onUpdateItem={updateItem}
                                onDeleteItem={deleteItem}
                                onAiSuggest={handleAiSuggest}
                                onOpenCatalog={(catId, itemId) => {
                                    if(itemId) {
                                       // Open for item mapping
                                       setIsProductModalOpen(true);
                                    } else {
                                       setIsProductModalOpen(true);
                                    }
                                }}
                                onMoveCategory={moveCategory}
                                isAiLoading={isAiLoading === cat.id}
                                readOnly={isPreviewMode}
                                hidePrices={data.hideItemPrices && !isOrderMode}
                                draggable={!isPreviewMode}
                                onDragStart={handleCategoryDragStart}
                                onDragOver={handleCategoryDragOver}
                                onDragEnd={handleCategoryDragEnd}
                                mode={data.quoteMode}
                            />
                        ) : (
                            <RichTextEditor
                                key={cat.id}
                                category={cat}
                                onUpdateCategory={updateCategory}
                                onDeleteCategory={deleteCategory}
                                draggable={!isPreviewMode}
                                onDragStart={handleCategoryDragStart}
                                onDragOver={handleCategoryDragOver}
                                onDragEnd={handleCategoryDragEnd}
                            />
                        )
                    ))}
                </div>

                {/* ADD BUTTONS (No Print) */}
                {!isPreviewMode && (
                    <div className="mt-6 mb-12 flex flex-col items-center gap-3 no-print p-6 border-2 border-dashed border-gray-200 rounded-xl bg-gray-50/50 hover:bg-gray-50 transition">
                         <div className="text-gray-400 text-sm font-bold uppercase tracking-widest mb-2">Pridať sekciu do ponuky</div>
                         <div className="flex flex-wrap justify-center gap-2">
                             {availableCategories.map(catName => (
                                 <button 
                                    key={catName} 
                                    onClick={() => {
                                        // Auto-detect section based on name keywords
                                        const sec = catName.toLowerCase().includes('šacht') || catName.toLowerCase().includes('konštrukc') ? 'shaft' : 'lift';
                                        addCategory('items', catName, [], sec);
                                    }}
                                    className="px-3 py-1.5 bg-white border border-gray-200 shadow-sm rounded-full text-sm font-bold text-gray-600 hover:bg-blue-50 hover:text-blue-600 hover:border-blue-200 transition"
                                 >
                                     + {catName}
                                 </button>
                             ))}
                             <button onClick={() => addCategory('text', 'Textová sekcia')} className="px-3 py-1.5 bg-white border border-gray-200 shadow-sm rounded-full text-sm font-bold text-purple-600 hover:bg-purple-50 hover:border-purple-200 transition">+ 📝 Text</button>
                         </div>
                         <div className="flex gap-2 mt-2">
                            <input 
                                id="newCatInput" 
                                placeholder="Vlastný názov..." 
                                className="px-3 py-1 rounded border text-sm"
                                onKeyDown={(e) => {
                                    if(e.key === 'Enter') {
                                        handleAddCategory((e.target as HTMLInputElement).value);
                                        addCategory('items', (e.target as HTMLInputElement).value);
                                        (e.target as HTMLInputElement).value = '';
                                    }
                                }}
                            />
                         </div>
                    </div>
                )}
            </div>
            )}

            {/* --- FOOTER & TOTALS --- */}
            {!isContractMode && (
                <div className="mt-auto break-inside-avoid px-12 pb-12 pt-6 bg-gray-50 border-t border-gray-200 print:bg-white print:px-0">
                    <div className="flex justify-end">
                        <div className="w-1/2 print:w-full">

                            {/* MARGIN CONTROL (EDIT ONLY) */}
                            {!isPreviewMode && !isOrderMode && (
                                <div className="mb-6 p-4 bg-white rounded-xl border border-blue-100 shadow-sm no-print">
                                    <h4 className="font-bold text-gray-800 mb-3 flex items-center gap-2 text-sm"><TrendingUp size={16} className="text-blue-500"/> Nastavenie Marže</h4>

                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <div className="flex justify-between text-xs mb-1">
                                                <span className="text-gray-500">Výťah (Tech.)</span>
                                                <span className="font-bold text-blue-600">{data.globalMargin}%</span>
                                            </div>
                                            <input 
                                                type="range" min="0" max="100" 
                                                value={data.globalMargin} 
                                                onChange={e => setData({...data, globalMargin: parseInt(e.target.value)})}
                                                className="w-full accent-blue-600 h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                                            />
                                        </div>
                                        {hasShaft && (
                                            <div>
                                                <div className="flex justify-between text-xs mb-1">
                                                    <span className="text-gray-500">Šachta (OK)</span>
                                                    <span className="font-bold text-orange-600">{data.shaftMargin}%</span>
                                                </div>
                                                <input 
                                                    type="range" min="0" max="100" 
                                                    value={data.shaftMargin} 
                                                    onChange={e => setData({...data, shaftMargin: parseInt(e.target.value)})}
                                                    className="w-full accent-orange-600 h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                                                />
                                            </div>
                                        )}
                                    </div>

                                    <div className="mt-4 pt-3 border-t border-gray-100 flex justify-between items-center">
                                        <div className="text-xs text-gray-400 font-mono">
                                            Nákup: {totals.totalPurchase.toFixed(2)}€ | Zisk: {(totals.liftProfit + totals.shaftProfit).toFixed(2)}€
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <label className="flex items-center gap-2 text-xs cursor-pointer select-none">
                                                <input type="checkbox" checked={data.hideItemPrices} onChange={e => setData({...data, hideItemPrices: e.target.checked})} className="rounded text-blue-600 focus:ring-0"/>
                                                Skryť jednotkové ceny
                                            </label>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* FINAL TOTALS TABLE */}
                            <table className="w-full text-sm">
                                <tbody>
                                    <tr className="border-b border-gray-200">
                                        <td className="py-2 text-gray-600 font-medium">Cena technológie bez DPH</td>
                                        <td className="py-2 text-right font-bold text-gray-800">{totals.liftSale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td>
                                    </tr>
                                    {totals.shaftSale > 0 && (
                                        <tr className="border-b border-gray-200">
                                            <td className="py-2 text-gray-600 font-medium">Cena šachty bez DPH</td>
                                            <td className="py-2 text-right font-bold text-gray-800">{totals.shaftSale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td>
                                        </tr>
                                    )}
                                    <tr className="border-b border-gray-900">
                                        <td className="py-3 text-lg font-bold text-gray-900">Spolu bez DPH</td>
                                        <td className="py-3 text-right text-lg font-black text-gray-900">{totals.totalSelling.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td>
                                    </tr>
                                    <tr>
                                        <td className="py-2 text-gray-500">DPH {data.vatRate}%</td>
                                        <td className="py-2 text-right text-gray-500">{totals.vat.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td>
                                    </tr>
                                    <tr className="bg-blue-600 text-white print:bg-transparent print:text-black">
                                        <td className="p-3 font-bold text-xl uppercase tracking-wider print:pl-0">Cena Celkom</td>
                                        <td className="p-3 text-right font-black text-2xl print:pr-0">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td>
                                    </tr>
                                </tbody>
                            </table>

                            {/* STAMP AREA */}
                            <div className="mt-12 flex justify-between items-end print:mt-16">
                                <div className="text-center w-40">
                                    <div className="border-b border-gray-400 mb-2"></div>
                                    <div className="text-[10px] text-gray-500 uppercase font-bold">Dátum a Podpis</div>
                                </div>
                                <div className="text-center w-40">
                                    <div className="h-24 mb-2 flex items-center justify-center opacity-20 bg-no-repeat bg-contain bg-center" style={{backgroundImage: "url('/stamp-placeholder.png')"}}>
                                        <div className="border-2 border-blue-200 rounded-full w-24 h-24 flex items-center justify-center -rotate-12">
                                            <span className="text-xs text-blue-200 font-bold uppercase text-center">Pečiatka<br/>Dodávateľa</span>
                                        </div>
                                    </div>
                                    <div className="border-b border-gray-400 mb-2"></div>
                                    <div className="text-[10px] text-gray-500 uppercase font-bold">Vypracoval</div>
                                </div>
                            </div>

                        </div>
                    </div>

                    {/* TERMS TEXT */}
                    <div className="mt-12 pt-6 border-t border-gray-200 text-xs text-gray-600 leading-relaxed print:mt-8 print:text-[10px]">
                        <div className="font-bold text-gray-900 mb-2 uppercase tracking-widest text-[10px]">Obchodné a Dodacie podmienky</div>
                        <StandaloneRichTextEditor 
                            content={data.terms} 
                            onChange={val => setData({...data, terms: val})}
                            placeholder="Vložte obchodné podmienky..."
                            className="min-h-[100px]"
                            stickyToolbar={false}
                            minimalPadding={true}
                        />
                         <div className="mt-2 text-right no-print">
                            <button 
                                onClick={async () => {
                                    setIsAiLoading('terms');
                                    const terms = await generateSuggestion('Napíš štandardné obchodné podmienky pre dodávku výťahu (platnosť, záruka, stavebná pripravenosť).', 'terms');
                                    if(terms) setData({...data, terms});
                                    setIsAiLoading(false);
                                }}
                                className="text-blue-600 hover:underline flex items-center gap-1 justify-end ml-auto"
                            >
                                <Sparkles size={12}/> {isAiLoading === 'terms' ? 'Generujem...' : 'Vygenerovať podmienky pomocou AI'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* --- MODALS --- */}

      {/* Product Database Modal */}
      <ProductDatabaseModal
        isOpen={isProductModalOpen}
        onClose={() => setIsProductModalOpen(false)}
        onSelectProduct={(p) => {
            // Logic to add selected product to current category/item
            // This needs context of WHICH item/category initiated the call
            // For now, simpler implementation:
            alert(`Selected: ${p.name}. Implementation pending context.`);
        }}
        products={products}
        onAddProduct={(p) => setProducts([...products, p])}
        onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))}
        layout={data.layout}
      />

      {/* Catalog Manager Modal */}
      <CatalogManagerModal
        isOpen={isCatalogOpen}
        onClose={() => setIsCatalogOpen(false)}
        products={products}
        onAddProduct={(p) => setProducts([...products, p])}
        onUpdateProduct={(p) => setProducts(products.map(pr => pr.id === p.id ? p : pr))}
        onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))}
        customCategories={availableCategories}
        onAddCategory={handleAddCategory}
        onDeleteCategory={handleDeleteCategory}
        onImportCatalog={handleImportData}
        cabinClasses={cabinClasses}
        onAddCabinClass={handleAddCabinClass}
        onUpdateCabinClass={handleUpdateCabinClass}
        onDeleteCabinClass={handleDeleteCabinClass}
      />

      <ClientDatabaseModal
        isOpen={isClientModalOpen}
        onClose={() => setIsClientModalOpen(false)}
        onSelectClient={(c) => { setData({...data, client: c}); setIsClientModalOpen(false); }}
        clients={clients}
        onAddClient={(c) => setClients([...clients, c])}
        onDeleteClient={(id) => setClients(clients.filter(c => c.id !== id))}
      />

      <SupplierDatabaseModal
        isOpen={isSupplierModalOpen}
        onClose={() => setIsSupplierModalOpen(false)}
        onSelectSupplier={(s) => { setData({...data, supplier: s, logoUrl: s.logoUrl}); setIsSupplierModalOpen(false); }}
        suppliers={suppliers}
        onAddSupplier={(s) => setSuppliers([...suppliers, s])}
        onDeleteSupplier={(id) => setSuppliers(suppliers.filter(s => s.id !== id))}
      />

      <TemplateDatabaseModal 
        isOpen={isTemplateModalOpen}
        onClose={() => setIsTemplateModalOpen(false)}
        mode={templateModalMode}
        templateType={templateContext}
        templates={templates}
        onSelectTemplate={(t) => {
             // Load categories from template
             const newCats = t.data.categories.map(c => ({...c, id: generateId(), items: c.items.map(i => ({...i, id: generateId()}))}));
             setData(prev => ({...prev, categories: newCats}));
             if (t.data.margin) setData(prev => ({...prev, globalMargin: t.data.margin!}));
             setIsTemplateModalOpen(false);
        }}
        onSaveTemplate={(name, type) => {
            const newT: QuoteTemplate = { 
                id: generateId(), name, type, 
                data: { categories: data.categories, layout: data.layout, margin: data.globalMargin } 
            };
            setTemplates([...templates, newT]);
        }}
        onDeleteTemplate={(id) => setTemplates(templates.filter(t => t.id !== id))}
      />

      <ContractRepositoryModal
        isOpen={isContractRepoOpen}
        onClose={() => setIsContractRepoOpen(false)}
        templates={contractTemplates}
        onSelectTemplate={(content) => {
             setData({...data, contractBody: content});
             setIsContractRepoOpen(false);
        }}
        onSaveCurrent={(name) => {
             const newT: ContractTemplate = { id: generateId(), name, content: data.contractBody || '' };
             setContractTemplates([...contractTemplates, newT]);
        }}
        onDeleteTemplate={(id) => setContractTemplates(contractTemplates.filter(t => t.id !== id))}
      />

      <SettingsModal 
        isOpen={isSettingsModalOpen}
        onClose={() => setIsSettingsModalOpen(false)}
        settings={settings}
        onSaveSettings={setSettings}
        onExportData={handleExportData}
        onImportData={handleImportData}
        onFactoryReset={handleFactoryReset}
        appVersion={APP_VERSION}
        availableCategories={availableCategories}
      />

      <EmailModal 
        isOpen={isEmailModalOpen}
        onClose={() => setIsEmailModalOpen(false)}
        onSend={(to, subj, msg) => {
            const mailto = `mailto:${to}?subject=${encodeURIComponent(subj)}&body=${encodeURIComponent(msg)}`;
            window.location.href = mailto;
            setIsEmailModalOpen(false);
        }}
        defaultSubject={`Cenová ponuka ${data.number} - ${data.clientReference}`}
        defaultMessage={`Dobrý deň,\n\nv prílohe Vám zasielame cenovú ponuku.\n\nS pozdravom,\n${data.supplier.name}`}
      />

      {/* NEW QUOTE SELECTION MODAL */}
      <NewQuoteModal 
          isOpen={isNewQuoteModalOpen}
          onClose={() => setIsNewQuoteModalOpen(false)}
          onSelect={handleCreateNewQuote}
      />

      {/* MATERIAL WIZARD - Updated for RS support */}
      <MaterialCalculatorModal 
          isOpen={isMaterialModalOpen}
          onClose={() => setIsMaterialModalOpen(false)}
          layout={data.layout!}
          controlLayout={data.controlLayout} 
          mode={data.quoteMode || 'lift'} // Pass Mode
          onInsert={handleWizardInsert}
          products={products}
          customCategories={availableCategories}
          onAddCategory={handleAddCategory}
          cabinClasses={cabinClasses}
          initialState={data.wizardData}
      />

    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  QuoteData, Product, Client, Supplier, QuoteTemplate, ContractTemplate, 
  AppSettings, QuoteCategory, LiftLayoutData, QuoteItem, RailType, DocumentType, CabinClass, ControlSystemLayout
} from './types';
import { 
  Archive, X, Search, FileInput, FileCheck, Sliders, ArrowRightLeft, 
  Box, Settings, Calculator, Building, Upload, Users, LayoutTemplate, 
  Save, LogOut, ArrowRight, CheckCircle, Printer, Mail, Edit, PlusCircle, GripVertical, FileText, Percent, TrendingUp, Trash2, Coins, Euro, Info, DoorOpen, Zap, ShieldCheck, Ruler, Maximize, RefreshCw, Copy, Tag, Cpu, Activity, MousePointerClick, Sparkles
} from 'lucide-react';
