          const currentMode = prev.quoteMode || 'lift';

          // 1. Determine allowed categories for this mode
          const allowedCategories = new Set(currentMode === 'control_system' ? CONTROL_SYSTEM_CATEGORIES : DEFAULT_CATEGORIES_LIST);

          // 2. Filter out *only* categories that belong to the *other* mode (cleanup)
          let updatedCategories = prev.categories.filter(c => {
              if (c.type === 'text') return true; // keep text
              // If we are in RS mode, remove Lift specific categories that are empty
              if (currentMode === 'control_system' && DEFAULT_CATEGORIES_LIST.includes(c.name) && !CONTROL_SYSTEM_CATEGORIES.includes(c.name)) return false;
              // If we are in Lift mode, remove RS specific categories that are empty
              if (currentMode === 'lift' && CONTROL_SYSTEM_CATEGORIES.includes(c.name) && !DEFAULT_CATEGORIES_LIST.includes(c.name)) return false;
              return true;
          });

          // 3. Prepare data from wizard
          const groupedItems: Record<string, QuoteItem[]> = {};

          wizardData.items.forEach(wizItem => {
              const newItem: QuoteItem = {
                  id: generateId(),
                  description: wizItem.description,
                  unit: wizItem.unit,
                  quantity: wizItem.quantity,
                  unitPrice: wizItem.price || 0,
                  purchasePrice: wizItem.price || 0,
                  vatRate: 23,
                  isSurcharge: false
              };
              if (!groupedItems[wizItem.category]) groupedItems[wizItem.category] = [];
              groupedItems[wizItem.category].push(newItem);
          });

          // 4. Add Services (Common)
          if (wizardData.includeTransport) {
              if (!groupedItems['Doprava']) groupedItems['Doprava'] = [];
              groupedItems['Doprava'].push({ id: generateId(), description: 'Doprava', unit: 'kpl', quantity: 1, unitPrice: wizardData.transportPrice || 200, purchasePrice: 0, vatRate: 23 });
          }
          if (wizardData.includePackaging) { // Usually Lift only, but safe to check
              if (!groupedItems['Balné']) groupedItems['Balné'] = [];
              groupedItems['Balné'].push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wizardData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 });
          }
          if (wizardData.includeAssembly) {
              if (!groupedItems['Montáž']) groupedItems['Montáž'] = [];
              groupedItems['Montáž'].push({ id: generateId(), description: 'Montáž technológie', unit: 'kpl', quantity: 1, unitPrice: 0, purchasePrice: 0, vatRate: 23 });
          }

          // 5. Update or Create Categories
          // We iterate through the Wizard's active categories list (or defaults)
          const categoriesToUpdate = Object.keys(groupedItems);

          categoriesToUpdate.forEach(catName => {
              const existingCatIndex = updatedCategories.findIndex(c => c.name === catName);

              if (existingCatIndex >= 0) {
                  // Replace items in existing category
                  updatedCategories[existingCatIndex].items = groupedItems[catName];
              } else {
                  // Create new category if valid for this mode
                  if (allowedCategories.has(catName) || catName === 'Oceľová konštrukcia') {
                      updatedCategories.push({
                          id: generateId(), type: 'items', name: catName, items: groupedItems[catName], isExpanded: true, section: 'lift',
                          textContent: settings.defaultCategoryTexts?.[catName]
                      });
                  }
              }
          });

          // 6. Sort Categories based on Mode Definition
          const sortOrder = currentMode === 'control_system' ? CONTROL_SYSTEM_CATEGORIES : DEFAULT_CATEGORIES_LIST;
          updatedCategories.sort((a, b) => {
              const idxA = sortOrder.indexOf(a.name);
              const idxB = sortOrder.indexOf(b.name);
              if (idxA === -1 && idxB === -1) return 0;
              if (idxA === -1) return 1;
              if (idxB === -1) return -1;
              return idxA - idxB;
          });

          return { ...prev, categories: updatedCategories, wizardData };
      });
  };

