                    <div className="flex flex-col"><div className="flex items-center gap-2 mb-2 pb-1"><h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Klient / Odberateľ</h3>{!isContractMode && <button onClick={() => setIsClientModalOpen(true)} className="p-0.5 text-blue-600 hover:bg-blue-50 rounded no-print"><Users size={12}/></button>}</div><div className="pl-4 border-l-2 border-gray-100 print:border-black"><textarea value={data.client.name} onChange={e => setData({...data,client:{...data.client, name:e.target.value}})} className="font-bold text-sm w-full bg-transparent mb-1 text-gray-900 print:text-black p-0 uppercase resize-none overflow-hidden h-auto whitespace-pre-wrap break-words" placeholder="Klient" rows={1}/><textarea value={data.client.details} onChange={e => setData({...data, client:{...data.client, details:e.target.value}})} className="w-full text-xs text-gray-600 resize-none bg-transparent print:text-black p-0 leading-relaxed" rows={5} placeholder="Adresa..."/></div></div>
