  initialState?: MaterialWizardData; 
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean;
        autoType?: string; 
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

interface MaterialTemplate {
    id: string;
    name: string;
    data: MaterialWizardData;
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, controlLayout, mode, onInsert, products, customCategories, initialState, cabinClasses
}) => {
  // State
  const [tabs, setTabs] = useState<{id: string, label: string}[]>([]);
  const [activeTab, setActiveTab] = useState('');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);

  // Options
  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);
  const [transportPrice, setTransportPrice] = useState(200);
  const [packagingPrice, setPackagingPrice] = useState(50);

  // Templates
  const [isTemplateMenuOpen, setIsTemplateMenuOpen] = useState(false);
  const [savedTemplates, setSavedTemplates] = useState<MaterialTemplate[]>([]);
  const [newTemplateName, setNewTemplateName] = useState('');

  // Dragging
  const [draggedItemIdx, setDraggedItemIdx] = useState<number | null>(null);

  // --- INITIALIZATION ---
  useEffect(() => {
      const storedTemplates = localStorage.getItem('smartquote_material_templates');
      if (storedTemplates) try { setSavedTemplates(JSON.parse(storedTemplates)); } catch (e) {}
  }, []);

  // --- LOGIC: RS vs LIFT ---
  useEffect(() => {
      if (isOpen) {
          // 1. DETERMINE TABS
          let generatedTabs = [];
          if (mode === 'control_system') {
              generatedTabs = RS_CATEGORIES.map(c => ({ id: c, label: c }));
          } else {
              // Lift Mode - Use custom categories but filter out non-material ones
              generatedTabs = customCategories
                  .filter(c => !['Montáž', 'Doprava', 'Balné', 'Ostatné', 'Ostatné šachta'].includes(c))
                  .map(c => ({ id: c, label: c }));
          }
          setTabs(generatedTabs);
          if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);

          // 2. LOAD DATA
          if (initialState) {
              setBomItems(initialState.items);
              setIncludeTransport(initialState.includeTransport);
              setIncludePackaging(initialState.includePackaging);
              setIncludeAssembly(initialState.includeAssembly);
              if (initialState.transportPrice) setTransportPrice(initialState.transportPrice);
              if (initialState.packagingPrice) setPackagingPrice(initialState.packagingPrice);
          } else {
              // FRESH CALCULATION
              handleResetToDefaults();
          }
      }
  }, [isOpen, mode]); 

  // --- CALCULATION LOGIC ---

  const findSmartItem = (keywords: string[], cat: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      return products.find(p => {
          const matchCat = p.category === cat;
          const matchName = lowerKeys.every(k => p.name.toLowerCase().includes(k));
          return matchCat && matchName;
      });
  };

  const calculateRsBOM = (c: ControlSystemLayout) => {
      const items: MaterialWizardData['items'] = [];
      const addItem = (desc: string, qty: number, unit: string, cat: string, keys: string[]) => {
          if (qty <= 0) return;
          const product = findSmartItem(keys, cat);
          items.push({
              category: cat,
              description: product ? product.name : desc,
              quantity: Number(qty.toFixed(2)),
              unit: unit,
              productId: product?.id,
              price: product?.price || 0,
              isAuto: true,
              autoType: 'rs_auto'
          });
      };

      // 1. Rozvádzač
      addItem(`Rozvádzač výťahu ${c.operationMode} ${c.motorPower}kW`, 1, 'ks', 'Rozvádzač', ['rozvádzač']);

      // 2. Menič
      if (c.driveType !== 'hydraulic') {
          addItem(`Frekvenčný menič ${c.motorPower}kW`, 1, 'ks', 'Menič a filter', ['menič']);
          addItem(`Brzdový odpor`, 1, 'ks', 'Menič a filter', ['odpor']);
          addItem(`Odrušovací filter`, 1, 'ks', 'Menič a filter', ['filter']);
      }

      // 3. Displeje a Privolávače
      if (!c.reuseLOP) {
          addItem(`Privolávač (LOP) kompletný`, c.numberOfStops, 'ks', 'Displeje a privolávače', ['privolávač']);
      }
      if (!c.reuseCOP) {
          addItem(`Kabínové tablo (COP) kompletné`, 1, 'ks', 'Displeje a privolávače', ['tablo']);
      }
      if (c.displaysCabin !== 'none') {
          addItem(`Displej Kabína (${c.displaysCabin})`, 1, 'ks', 'Displeje a privolávače', ['displej', 'kabín']);
      }
      if (c.displaysLanding !== 'none') {
          const qty = c.landingStationsConfiguration === 'main_only' ? 1 : c.numberOfStops;
          addItem(`Displej Stanica (${c.displaysLanding})`, qty, 'ks', 'Displeje a privolávače', ['displej', 'stanic']);
      }

      // 4. Snímanie
      if (c.positioning === 'absolute') {
          addItem(`Absolútny snímač polohy (Limax/Elgo)`, 1, 'set', 'Snímanie polohy', ['limax', 'absolútn']);
      } else {
          addItem(`Magnetické snímače (Sada)`, 1, 'set', 'Snímanie polohy', ['magnet', 'snímač']);
      }

      // 5. Kabeláž
      const travelM = c.travel / 1000;
      addItem(`Vlečný kábel plochý (${Math.ceil(travelM + 5)}m)`, Math.ceil(travelM + 5), 'm', 'Kabeláž', ['vlečný']);
      addItem(`Inštalačný materiál šachty`, 1, 'kpl', 'Kabeláž', ['inštalačný', 'šacht']);

      // 6. Revízia
      if (c.inspectionBox) {
          addItem(`Revízna skrinka (Box)`, 1, 'ks', 'Inšpekcia a revízia', ['revízna']); // Maps to standard cat if needed, or Atyp
      }

      return items;
  };

  // --- RESTORED LIFT LOGIC ---
  const calculateQuantitiesOnly = (l: LiftLayoutData): Record<string, number> => {
      const travel = l.travelHeight || 0;
      const hq = l.headroomHeight || 0;
      const pit = l.pitDepth || 0;
      const totalHeight = travel + hq + pit;
      const railLength = l.guideRailLength || 5000;
      const stops = l.numberOfStops || 2;
      const entrances = l.numberOfEntrances || stops;

      const railLinesCar = 2; 
      const railLinesCwt = 2; 
      const barsPerLine = Math.ceil(totalHeight / railLength);

      const railsCarTotal = barsPerLine * railLinesCar; 
      const railsCwtTotal = barsPerLine * railLinesCwt;

      const fishplatesPerLine = Math.max(0, barsPerLine - 1);
      const fishplatesTotalCar = fishplatesPerLine * railLinesCar; 
      const fishplatesTotalCwt = fishplatesPerLine * railLinesCwt;

      const firstBracketPos = 500; 
      const span = 2500; 
      const effectiveHeight = Math.max(0, totalHeight - firstBracketPos);
      const bracketsPerLine = 1 + Math.ceil(effectiveHeight / span) + 1;

      let bracketsMainTotal = 0; 
      let bracketsCwtTotal = 0;
      if (l.bracketType === 'combined') { 
          bracketsMainTotal = bracketsPerLine; 
          bracketsCwtTotal = 0; 
      } else { 
          bracketsMainTotal = bracketsPerLine * 2; 
          bracketsCwtTotal = bracketsPerLine * 2; 
      }

      const fasteningPoints = bracketsPerLine; 
      const clipsCar = fasteningPoints * 2 * 2; 
      const clipsCwt = fasteningPoints * 2 * 2; 
      const clipsTotal = clipsCar + clipsCwt;

      return {
          'rails_car': railsCarTotal, 'rails_cwt': railsCwtTotal, 
          'fishplates_car': fishplatesTotalCar, 'fishplates_cwt': fishplatesTotalCwt,
          'brackets_main': bracketsMainTotal, 'brackets_cwt': bracketsCwtTotal, 
          'clips_car': clipsCar, 'clips_cwt': clipsCwt,
          'doors_shaft': entrances, 'doors_car': l.isThroughCar ? 2 : 1, 'machine': 1,
          'rope_length': Number(((totalHeight * (l.suspensionType === '2:1' ? 2 : 1) * (l.numberOfPersons <= 8 ? 4 : 6) / 1000) + 15).toFixed(1))
      };
  };

  const calculateLiftBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const qtys = calculateQuantitiesOnly(l);

    // Category Mappings (Must match tabs)
    const catMap = {
        guides: 'Vodítka a kotvenie', 
        doors: 'Dvere', 
        cabin: 'Kabína a rám', 
        drive: 'Pohon', 
        electro: 'Elektro', 
        shaftInt: 'Ostatné šachta', 
        construction: 'Oceľová konštrukcia'
    };

    const addItem = (desc: string, qty: number, unit: string, cat: string, keys: string[]) => {
        if (qty <= 0) return;
        // Search products with these keys in this category
        const product = findSmartItem(keys, cat);
        items.push({
            category: cat, 
            description: product ? product.name : desc, 
            quantity: Number(qty.toFixed(2)), 
            unit: unit, 
            productId: product?.id, 
            price: product?.price || 0, 
            isAuto: true, 
            autoType: 'lift_auto' 
        });
    };

    // 1. Guides & Brackets
    addItem(`Vodidlá Kabína ${l.guideTypeCar} (${l.guideRailLength}mm)`, qtys['rails_car'], 'ks', catMap.guides, [l.guideTypeCar || 'T90']);
    addItem(`Vodidlá Protiváha ${l.guideTypeCwt} (${l.guideRailLength}mm)`, qtys['rails_cwt'], 'ks', catMap.guides, [l.guideTypeCwt || 'T50']);
    addItem(`Spojka vodidla ${l.guideTypeCar}`, qtys['fishplates_car'], 'ks', catMap.guides, ['spojka', l.guideTypeCar || 'T90']);
    addItem(`Spojka vodidla ${l.guideTypeCwt}`, qtys['fishplates_cwt'], 'ks', catMap.guides, ['spojka', l.guideTypeCwt || 'T50']);

    if (l.bracketType === 'combined') {
        addItem(`Konzola Kombinovaná (U-Typ)`, qtys['brackets_main'], 'ks', catMap.guides, ['konzola', 'kombinovaná']);
        addItem(`Konzola Kabínová (Z-Typ)`, qtys['brackets_main'], 'ks', catMap.guides, ['konzola', 'z', 'kabín']);
    } else {
        addItem(`Konzola Hlavná (á 2.5m)`, qtys['brackets_main'], 'ks', catMap.guides, ['konzola', 'hlavná']);
        addItem(`Konzola Protiváhy (á 2.5m)`, qtys['brackets_cwt'], 'ks', catMap.guides, ['konzola', 'protiváh']); 
    }

    addItem(`Príchytka vodidla ${l.guideTypeCar}`, qtys['clips_car'], 'ks', catMap.guides, ['príchytka', l.guideTypeCar || 'T90']);
    addItem(`Príchytka vodidla ${l.guideTypeCwt}`, qtys['clips_cwt'], 'ks', catMap.guides, ['príchytka', l.guideTypeCwt || 'T50']);

    // 2. Doors
    const sDoorType = l.doorOperation === 'manual' ? 'Krídlové' : 'Automatické';
    addItem(`Šachtové dvere ${sDoorType} ${l.doorWidth}`, qtys['doors_shaft'], 'ks', catMap.doors, ['dvere', sDoorType === 'Krídlové' ? 'krídlové' : 'automatické', String(l.doorWidth)]);

    const cDoorType = l.doorType === 'bus' ? 'BUS' : 'Automatické';
    addItem(`Kabínové dvere ${cDoorType} ${l.doorWidth}`, qtys['doors_car'], 'ks', catMap.doors, ['dvere', cDoorType === 'BUS' ? 'bus' : 'automatické', String(l.doorWidth)]);

    // 3. Cabin
    let linkedSet = null;
    if (cabinClasses && l.cabinClass) {
        const cls = cabinClasses.find(c => c.name === l.cabinClass);
        if (cls?.linkedProductId) linkedSet = products.find(p => p.id === cls.linkedProductId);
    }
    if (linkedSet) {
        items.push({ category: catMap.cabin, description: linkedSet.name, quantity: 1, unit: 'ks', productId: linkedSet.id, price: linkedSet.price, isAuto: true, autoType: 'cabin_set' });
    } else {
        addItem(`Kabína ${l.cabinClass} (${Math.round(l.cabinWidth)}x${Math.round(l.cabinDepth)}mm)`, 1, 'ks', catMap.cabin, ['kabína']);
    }
    addItem(`Rám kabíny (${l.frameType})`, 1, 'ks', catMap.cabin, ['rám', l.frameType === 'backpack' ? 'batoh' : 'rám']);

    // 4. Drive
    addItem('Trakčný stroj', 1, 'ks', catMap.drive, [l.tractionMedium || 'lan', 'stroj']);
    addItem(`Laná / Pásy (${l.tractionMedium})`, qtys['rope_length'], 'm', catMap.drive, ['lan', l.tractionMedium || 'ocel']);

    return items;
  };

  const handleResetToDefaults = () => {
      let fresh: MaterialWizardData['items'] = [];

      if (mode === 'control_system' && controlLayout) {
          fresh = calculateRsBOM(controlLayout);
      } else {
          fresh = calculateLiftBOM(layout);
      }
      setBomItems(fresh);
  };

  // --- UI HELPERS ---
  const moveTab = (index: number, direction: 'left' | 'right') => {
      const newTabs = [...tabs];
      const targetIndex = direction === 'left' ? index - 1 : index + 1;
      if (targetIndex >= 0 && targetIndex < tabs.length) {
          [newTabs[index], newTabs[targetIndex]] = [newTabs[targetIndex], newTabs[index]];
          setTabs(newTabs);
      }
  };

  const updateItem = (idx: number, field: string, value: any) => {
      const newItems = [...bomItems];
      // @ts-ignore
      newItems[idx][field] = value;
      setBomItems(newItems);
  };

  const handleDeleteItem = (index: number) => {
      setBomItems(bomItems.filter((_, i) => i !== index));
  };

  const addCustomItem = () => {
      setBomItems([...bomItems, { 
          category: activeTab, 
          description: 'Nová požiadavka', 
          quantity: 1, 
          unit: 'ks', 
          price: 0,
          isAuto: false 
      }]);
  };

  const handleInsert = () => {
      onInsert({
          items: bomItems,
          includeTransport,
          includePackaging,
          includeAssembly,
          transportPrice,
          packagingPrice,
          categoryOrder: tabs.map(t => t.id)
      });
      onClose();
  };

  if (!isOpen) return null;

  const currentItems = bomItems.map((item, index) => ({ item, index })).filter(({ item }) => item.category === activeTab);
  const categoryProducts = products.filter(p => p.category === activeTab);

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">

        {/* Header */}
        <div className={`p-4 border-b flex justify-between items-center rounded-t-xl ${mode === 'control_system' ? 'bg-green-50' : 'bg-orange-50'}`}>
          <div className="flex items-center gap-2">
            {mode === 'control_system' ? <Cpu className="text-green-600"/> : <Calculator className="text-orange-500" />}
            <div>
                <h2 className="text-xl font-bold text-gray-800">
                    {mode === 'control_system' ? 'Sprievodca RS (Riadiaci Systém)' : 'Materiálový Sprievodca (Výťah)'}
                </h2>
                <div className="text-xs text-gray-500">
                    {mode === 'control_system' ? 'Výpočet komponentov elektroinštalácie a riadenia' : 'Výpočet kompletného výťahu'}
                </div>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-3 py-2 transition cursor-pointer ${activeTab===tab.id ? 'bg-white border-gray-300 shadow-sm' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`} onClick={() => setActiveTab(tab.id)}>
                     {activeTab === tab.id && idx > 0 && <button onClick={(e) => {e.stopPropagation(); moveTab(idx, 'left')}} className="mr-2 text-gray-400 hover:text-black"><ArrowLeft size={12}/></button>}
                     <span className={`text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? (mode==='control_system'?'text-green-700':'text-orange-700') : 'text-gray-500'}`}>{tab.label}</span>
                     {activeTab === tab.id && idx < tabs.length - 1 && <button onClick={(e) => {e.stopPropagation(); moveTab(idx, 'right')}} className="ml-2 text-gray-400 hover:text-black"><ArrowRight size={12}/></button>}
                 </div>
            ))}
        </div>

        {/* Info Banner */}
        <div className={`border-b px-6 py-2 flex items-center gap-3 text-sm animate-in fade-in ${mode==='control_system'?'bg-green-50 border-green-100 text-green-800':'bg-orange-50 border-orange-100 text-orange-800'}`}>
            <Info size={16} className="shrink-0"/>
            <div className="font-medium">
                Aktívna kategória: <strong>{activeTab}</strong>
            </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">
            {currentItems.length === 0 ? (
                <div className="text-center text-gray-400 italic py-8 border-2 border-dashed border-gray-100 rounded-xl">
                    Žiadne automaticky vypočítané položky v tejto kategórii.<br/>
                    <button onClick={addCustomItem} className="mt-2 text-blue-600 font-bold hover:underline">+ Pridať manuálne</button>
                </div>
            ) : (
                <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                    <table className="w-full text-sm">
                        <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                            <tr>
                                <th className="p-3 text-left w-1/3">Popis</th>
                                <th className="p-3 text-left w-1/3">Skladový Produkt</th>
                                <th className="p-3 text-right w-24">Mn.</th>
                                <th className="p-3 text-right w-24">Cena</th>
                                <th className="p-3 text-center w-10"></th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {currentItems.map(({ item, index: originalIndex }) => (
                                <tr key={originalIndex} className="hover:bg-gray-50">
                                    <td className="p-3">
                                        <input value={item.description} onChange={e => updateItem(originalIndex, 'description', e.target.value)} className="w-full bg-transparent font-medium text-gray-800 focus:outline-none"/>
                                    </td>
                                    <td className="p-3">
                                        <div className="relative">
                                            <select 
                                                value={item.productId || ''} 
                                                onChange={e => {
                                                    const p = products.find(prod => prod.id === e.target.value);
                                                    if(p) {
                                                        updateItem(originalIndex, 'productId', p.id);
                                                        updateItem(originalIndex, 'price', p.price);
                                                        updateItem(originalIndex, 'unit', p.unit);
                                                        updateItem(originalIndex, 'description', p.name);
                                                    }
                                                }} 
                                                className={`w-full p-2 border rounded text-xs font-bold ${item.productId ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-400 border-gray-200'}`}
                                            >
                                                <option value="">-- Vybrať --</option>
                                                {categoryProducts.map(p => (
                                                    <option key={p.id} value={p.id}>{p.name} ({p.price}€)</option>
                                                ))}
                                            </select>
                                            {!item.productId && <AlertTriangle size={14} className="absolute right-8 top-1/2 -translate-y-1/2 text-orange-400"/>}
                                        </div>
                                    </td>
                                    <td className="p-3 text-right"><input type="number" value={item.quantity} onChange={e => updateItem(originalIndex, 'quantity', +e.target.value)} className="w-full text-right font-bold text-blue-600 bg-transparent focus:outline-none"/></td>
                                    <td className="p-3 text-right font-mono text-gray-600">{item.price ? item.price.toFixed(2) : '-'} €</td>
                                    <td className="p-3 text-center"><button onClick={() => handleDeleteItem(originalIndex)} className="text-gray-400 hover:text-red-500"><Trash2 size={16}/></button></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            <button onClick={addCustomItem} className="w-full py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-600 hover:bg-blue-50 transition flex justify-center items-center gap-2 font-medium">
                <Plus size={18} /> Pridať položku
            </button>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 bg-white p-3 rounded border border-gray-200">
                 <label className="flex items-center gap-2 cursor-pointer p-1"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="rounded text-blue-600"/> <span className="text-sm font-bold">Montáž</span></label>
                 <div className="flex items-center gap-2 border-l pl-2"><label className="flex items-center gap-2 cursor-pointer flex-1"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="rounded text-blue-600"/> <span className="text-sm font-bold">Doprava</span></label><input type="number" value={transportPrice} onChange={e => setTransportPrice(+e.target.value)} className="w-16 border rounded px-1 text-sm text-right" disabled={!includeTransport}/>€</div>
                 <div className="flex items-center gap-2 border-l pl-2"><label className="flex items-center gap-2 cursor-pointer flex-1"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600"/> <span className="text-sm font-bold">Balné</span></label><input type="number" value={packagingPrice} onChange={e => setPackagingPrice(+e.target.value)} className="w-16 border rounded px-1 text-sm text-right" disabled={!includePackaging}/>€</div>
            </div>

            <div className="flex justify-between items-center">
                <button onClick={handleResetToDefaults} className="text-xs text-orange-600 hover:text-orange-800 font-bold flex items-center gap-2 px-3 py-1 bg-orange-50 rounded border border-orange-200" title="Zahodiť manuálne zmeny"><RotateCcw size={14}/> Resetovať</button>
                <div className="flex gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium transition">Zrušiť</button>
                    <button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold flex items-center gap-2 shadow-sm transition"><Check size={18} /> Vložiť do ponuky</button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass, ProductComponent } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, AlertTriangle, Box, Download, Package, ListPlus, Calculator, RotateCcw, Factory, Truck, Tag, FileText, ArrowDown, Copy
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try {
        return crypto.randomUUID();
      } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

// Helper to generate consistent pastel colors from string
const getSubcatColor = (str: string) => {
    if (!str) return 'bg-gray-100 text-gray-600 border-gray-200';
    const colors = [
        'bg-blue-100 text-blue-700 border-blue-200',
        'bg-green-100 text-green-700 border-green-200',
        'bg-purple-100 text-purple-700 border-purple-200',
        'bg-orange-100 text-orange-700 border-orange-200',
        'bg-teal-100 text-teal-700 border-teal-200',
        'bg-indigo-100 text-indigo-700 border-indigo-200',
        'bg-pink-100 text-pink-700 border-pink-200',
        'bg-yellow-100 text-yellow-700 border-yellow-200',
    ];
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    const index = Math.abs(hash) % colors.length;
    return colors[index];
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [activeSubcategoryFilter, setActiveSubcategoryFilter] = useState<string>('ALL'); // 'ALL', 'NONE', or specific name
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk Actions State
  const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());

  // PRODUCT EDITOR STATE
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editorProduct, setEditorProduct] = useState<Partial<Product>>({});

  // Component Selection State inside Editor
  const [componentSearch, setComponentSearch] = useState('');
  const [componentCategoryFilter, setComponentCategoryFilter] = useState<string>('ALL'); // New filter inside editor

  // New Category State
  const [newCategoryName, setNewCategoryName] = useState('');

  // Class Management State
  const [editingClassId, setEditingClassId] = useState<string | null>(null);
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLinkedSet, setNewClassLinkedSet] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize active category
  useEffect(() => {
      if (customCategories.length > 0 && !activeCategory) {
          setActiveCategory(customCategories[0]);
      }
  }, [customCategories, activeCategory]);

  // Reset Subcategory filter when Category changes
  useEffect(() => {
      setActiveSubcategoryFilter('ALL');
      setSelectedProductIds(new Set());
  }, [activeCategory]);

  // Reset component filters when editor opens
  useEffect(() => {
      if (isEditorOpen) {
          setComponentSearch('');
          setComponentCategoryFilter('ALL');
      }
  }, [isEditorOpen]);

  // 1. Base Filter (Category + Search)
  const productsInCurrentCategory = useMemo(() => {
      return products.filter(p => {
          const matchCat = activeCategory ? p.category === activeCategory : true;
          const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
          return matchCat && matchSearch;
      });
  }, [products, activeCategory, searchTerm]);

  // 2. Identify Subcategories in current view
  const currentSubcategories = useMemo(() => {
      const subs = new Set<string>();
      productsInCurrentCategory.forEach(p => {
          if (p.subcategory) subs.add(p.subcategory);
      });
      return Array.from(subs).sort();
  }, [productsInCurrentCategory]);

  // 3. Final Display Filter (Subcategory Pill)
  const displayedProducts = useMemo(() => {
      if (activeSubcategoryFilter === 'ALL') return productsInCurrentCategory;
      if (activeSubcategoryFilter === 'NONE') return productsInCurrentCategory.filter(p => !p.subcategory);
      return productsInCurrentCategory.filter(p => p.subcategory === activeSubcategoryFilter);
  }, [productsInCurrentCategory, activeSubcategoryFilter]);


  // --- COMPONENT SELECTION LOGIC (Inside Editor) ---
  const availableComponentsGrouped = useMemo(() => {
      if (editorProduct.type !== 'composite') return { grouped: {}, sortedKeys: [] };

      // 1. Filter products based on search and category filter
      const filtered = products.filter(p => {
          if (p.id === editorProduct.id) return false; // Prevent self-reference
          const matchSearch = p.name.toLowerCase().includes(componentSearch.toLowerCase());
          const matchCat = componentCategoryFilter === 'ALL' || p.category === componentCategoryFilter;
          return matchSearch && matchCat;
      });

      // 2. Group by Subcategory
      const grouped: Record<string, Product[]> = {};

      filtered.forEach(p => {
          const sub = p.subcategory || 'Bez podkategórie';
          if (!grouped[sub]) grouped[sub] = [];
          grouped[sub].push(p);
      });

      // Sort categories: "Bez podkategórie" last, others alphabetical
      const sortedKeys = Object.keys(grouped).sort((a, b) => {
          if (a === 'Bez podkategórie') return 1;
          if (b === 'Bez podkategórie') return -1;
          return a.localeCompare(b);
      });

      return { grouped, sortedKeys };
  }, [products, editorProduct.id, componentSearch, componentCategoryFilter, editorProduct.type]);


  // --- Handlers ---

  const handleExportCatalog = () => {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(products, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `katalog_export_${new Date().toISOString().split('T')[0]}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const handleBulkSelection = (id: string) => {
      const newSet = new Set(selectedProductIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedProductIds(newSet);
  };

  const toggleSelectAll = () => {
      if (selectedProductIds.size === displayedProducts.length && displayedProducts.length > 0) {
          setSelectedProductIds(new Set());
      } else {
          setSelectedProductIds(new Set(displayedProducts.map(p => p.id)));
      }
  };

  const handlePillClick = (subcat: string | 'ALL' | 'NONE') => {
      if (selectedProductIds.size > 0) {
          if (subcat === 'ALL') return; // Cannot move to ALL

          const targetSubcatName = subcat === 'NONE' ? undefined : subcat;
          const idsToMove = Array.from(selectedProductIds);

          if (window.confirm(`Presunúť ${idsToMove.length} označených produktov do podkategórie "${subcat === 'NONE' ? 'Bez podkategórie' : subcat}"?`)) {
              idsToMove.forEach(id => {
                  const product = products.find(p => p.id === id);
                  if (product) {
                      onUpdateProduct({
                          ...product,
                          // IMPORTANT: Keep existing category, just update subcategory
                          subcategory: targetSubcatName
                      });
                  }
              });
              // Clear selection after move
              setSelectedProductIds(new Set());
          }
          return;
      }
      setActiveSubcategoryFilter(subcat);
  };

  const handleDeleteSelected = () => {
      if (window.confirm(`Naozaj vymazať ${selectedProductIds.size} produktov?`)) {
          selectedProductIds.forEach(id => onDeleteProduct(id));
          setSelectedProductIds(new Set());
      }
  };

  // --- EDITOR HANDLERS (Create/Edit) ---

  const openEditor = (product?: Product) => {
      if (product) {
          setEditorProduct({ ...product }); // Edit Mode
      } else {
          setEditorProduct({ // Create Mode
              id: generateId(),
              category: activeCategory,
              subcategory: activeSubcategoryFilter !== 'ALL' && activeSubcategoryFilter !== 'NONE' ? activeSubcategoryFilter : undefined,
              type: 'simple',
              unit: 'ks',
              price: 0,
              priceType: 'fixed',
              displayMode: 'itemized',
              subProducts: []
          });
      }
      setIsEditorOpen(true);
  };

  // DUPLICATE PRODUCT LOGIC
  const handleDuplicateProduct = (product: Product) => {
      const newProduct: Partial<Product> = {
          ...product,
          id: generateId(),
          name: `${product.name} (Kópia)`
      };
      setEditorProduct(newProduct);
      setIsEditorOpen(true);
  };

  const saveEditor = () => {
      if (!editorProduct.name) {
          alert("Zadajte názov produktu.");
          return;
      }

      const finalProduct = {
          ...editorProduct,
          price: Number(editorProduct.price) || 0
      } as Product;

      if (products.find(p => p.id === finalProduct.id)) {
          onUpdateProduct(finalProduct);
      } else {
          onAddProduct(finalProduct);
      }
      setIsEditorOpen(false);
  };

  const addComponentToSet = (component: Product) => {
      const currentSubs = editorProduct.subProducts || [];
      const exists = currentSubs.find(s => s.productId === component.id);
      if (exists) {
          // Move to top if updated? Or just update qty? Let's just update qty for existing.
          const updated = currentSubs.map(s => s.productId === component.id ? { ...s, quantity: s.quantity + 1 } : s);
          setEditorProduct({ ...editorProduct, subProducts: updated });
      } else {
          // PREPEND new item so it appears at the TOP
          setEditorProduct({ ...editorProduct, subProducts: [{ productId: component.id, quantity: 1 }, ...currentSubs] });
      }
      // Keep search open for multiple adds
  };

  const removeComponentFromSet = (productId: string) => {
      const currentSubs = editorProduct.subProducts || [];
      setEditorProduct({ ...editorProduct, subProducts: currentSubs.filter(s => s.productId !== productId) });
  };

  const updateComponentQty = (productId: string, qty: number) => {
      const currentSubs = editorProduct.subProducts || [];
      setEditorProduct({ ...editorProduct, subProducts: currentSubs.map(s => s.productId === productId ? { ...s, quantity: qty } : s) });
  };

  const calculateSetPrice = () => {
      if (!editorProduct.subProducts) return 0;
      return editorProduct.subProducts.reduce((sum, sub) => {
          const p = products.find(prod => prod.id === sub.productId);
          return sum + ((p?.price || 0) * sub.quantity);
      }, 0);
  };

  const generateDescriptionFromComponents = () => {
      if (!editorProduct.subProducts || editorProduct.subProducts.length === 0) {
          alert("Najskôr pridajte komponenty do setu.");
          return;
      }

      const componentNames = editorProduct.subProducts
          .map(sub => {
              const p = products.find(prod => prod.id === sub.productId);
              return p ? p.name : '';
          })
          .filter(Boolean)
          .join(' + ');

      if (componentNames) {
          const currentName = editorProduct.name || '';
          // Smart replacement: if already has (...) at end, replace it. If not, append.
          const newName = currentName.includes('(') 
              ? currentName.replace(/\(.*\)/, `(${componentNames})`) 
              : `${currentName} (${componentNames})`;

          setEditorProduct(prev => ({...prev, name: newName}));
      }
  };

  useEffect(() => {
      if (editorProduct.type === 'composite' && editorProduct.priceType === 'calculated') {
          const total = calculateSetPrice();
          if (total !== editorProduct.price) {
              setEditorProduct(prev => ({ ...prev, price: total }));
          }
      }
  }, [editorProduct.subProducts, editorProduct.priceType, editorProduct.type]);


  const handleAddCategorySubmit = () => {
      if (newCategoryName && !customCategories.includes(newCategoryName)) {
          onAddCategory(newCategoryName);
          setNewCategoryName('');
      }
  };

  // --- CABIN CLASS HANDLERS ---
  const handleEditClass = (cc: CabinClass) => {
      setEditingClassId(cc.id);
      setNewClassName(cc.name);
      setNewClassDesc(cc.description);
      setNewClassLinkedSet(cc.linkedProductId || '');
  };

  const handleCancelClassEdit = () => {
      setEditingClassId(null);
      setNewClassName('');
      setNewClassDesc('');
      setNewClassLinkedSet('');
  };

  const handleClassSubmit = () => {
      if (!newClassName) return;

      if (editingClassId) {
          // Update existing
          onUpdateCabinClass({
              id: editingClassId,
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
      } else {
          // Create new
          onAddCabinClass({
              id: generateId(),
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
      }
      handleCancelClassEdit();
  };

  const handleAddSubcategory = () => {
      const name = prompt("Názov novej podkategórie:");
      if (name) {
          // Just setting filter doesn't create it, but shows user intention
          alert(`Pre vytvorenie podkategórie "${name}" stačí pri úprave produktu napísať tento názov do poľa Podkategória.`);
      }
  };

  const handleDuplicateCategory = (sourceCat: string) => {
      const targetCat = prompt(`Zadajte názov novej kategórie (alebo existujúcej), kam sa skopírujú produkty z "${sourceCat}":`, `${sourceCat} (Kópia)`);
      if (!targetCat) return;

      if (!customCategories.includes(targetCat)) {
          onAddCategory(targetCat);
      }

      const productsToCopy = products.filter(p => p.category === sourceCat);
      let copiedCount = 0;
      productsToCopy.forEach(p => {
          onAddProduct({
              ...p,
              id: generateId(),
              category: targetCat
          });
          copiedCount++;
      });
      alert(`Skopírovaných ${copiedCount} produktov do kategórie "${targetCat}".`);
  };

  if (!isOpen) return null;

  // --- EDITOR OVERLAY ---
  if (isEditorOpen) {
      const isSet = editorProduct.type === 'composite';
      return (
          <div className="fixed inset-0 bg-black/60 z-[110] flex items-center justify-center p-4">
              {/* WIDER MODAL FOR EDITOR */}
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-7xl max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">
                  <div className="p-4 border-b bg-gray-50 flex justify-between items-center rounded-t-xl">
                      <h2 className="text-xl font-bold text-gray-800">
                          {products.find(p => p.id === editorProduct.id) ? 'Upraviť Produkt' : 'Nový Produkt'}
                      </h2>
                      <button onClick={() => setIsEditorOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X size={20}/></button>
                  </div>

                  <div className="p-6 flex-1 overflow-y-auto">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 h-full">
                          {/* Left Column: Basic Info */}
                          <div className="space-y-6 overflow-y-auto pr-2">
                              <div>
                                  <label className="block text-sm font-bold text-gray-700 mb-1">Názov produktu</label>
                                  <div className="flex gap-2">
                                      <input 
                                          className="w-full p-2 border rounded focus:ring-2 focus:ring-purple-500 font-bold text-lg" 
                                          value={editorProduct.name || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, name: e.target.value})}
                                          autoFocus
                                      />
                                      {isSet && (
                                          <button 
                                            onClick={generateDescriptionFromComponents}
                                            className="px-3 py-2 bg-yellow-100 text-yellow-800 border border-yellow-300 rounded hover:bg-yellow-200 text-xs font-bold whitespace-nowrap flex items-center gap-1"
                                            title="Vložiť zoznam komponentov do názvu (napr. do zátvorky)"
                                          >
                                              <FileText size={14}/> Doplniť zloženie
                                          </button>
                                      )}
                                  </div>
                              </div>

                              {/* NEW: Manufacturer & Supplier Inputs */}
                              <div className="grid grid-cols-2 gap-4 bg-gray-50 p-3 rounded border border-gray-200">
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1 flex items-center gap-1"><Factory size={12}/> Výrobca</label>
                                      <input 
                                          className="w-full p-2 border rounded text-sm bg-white" 
                                          placeholder="napr. Fermator"
                                          value={editorProduct.manufacturer || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, manufacturer: e.target.value})}
                                      />
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1 flex items-center gap-1"><Truck size={12}/> Dodávateľ</label>
                                      <input 
                                          className="w-full p-2 border rounded text-sm bg-white" 
                                          placeholder="napr. Sklad / Výťahy s.r.o."
                                          value={editorProduct.supplier || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, supplier: e.target.value})}
                                      />
                                  </div>
                              </div>

                              <div className="grid grid-cols-2 gap-4">
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Kategória</label>
                                      <select 
                                          className="w-full p-2 border rounded text-sm bg-gray-50"
                                          value={editorProduct.category || activeCategory} 
                                          onChange={e => setEditorProduct({...editorProduct, category: e.target.value})}
                                      >
                                          {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                      </select>
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Podkategória</label>
                                      <input 
                                          className="w-full p-2 border rounded text-sm" 
                                          list="subcat-options"
                                          value={editorProduct.subcategory || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, subcategory: e.target.value})}
                                          placeholder="napr. Trakčné stroje"
                                      />
                                      <datalist id="subcat-options">
                                          {currentSubcategories.map(s => <option key={s} value={s}/>)}
                                      </datalist>
                                  </div>
                              </div>

                              {/* TYPE SWITCHER */}
                              <div className="bg-gray-100 p-1 rounded-lg flex text-sm font-bold mt-4">
                                  <button 
                                      className={`flex-1 py-2 rounded-md transition flex items-center justify-center gap-2 ${!isSet ? 'bg-white shadow text-gray-800' : 'text-gray-500 hover:text-gray-700'}`}
                                      onClick={() => setEditorProduct({...editorProduct, type: 'simple'})}
                                  >
                                      <Box size={16}/> Jednoduchý Diel
                                  </button>
                                  <button 
                                      className={`flex-1 py-2 rounded-md transition flex items-center justify-center gap-2 ${isSet ? 'bg-purple-600 text-white shadow' : 'text-gray-500 hover:text-gray-700'}`}
                                      onClick={() => setEditorProduct({...editorProduct, type: 'composite', priceType: 'calculated'})}
                                  >
                                      <Layers size={16}/> Zložený SET
                                  </button>
                              </div>

                              <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-lg border border-gray-200">
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Cena (€)</label>
                                      <input 
                                          type="number"
                                          className={`w-full p-2 border rounded font-mono text-right font-bold text-lg ${isSet && editorProduct.priceType === 'calculated' ? 'bg-gray-100 text-gray-500 cursor-not-allowed' : 'bg-white'}`}
                                          value={editorProduct.price || 0} 
                                          onChange={e => setEditorProduct({...editorProduct, price: parseFloat(e.target.value) || 0})}
                                          readOnly={isSet && editorProduct.priceType === 'calculated'}
                                      />
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Jednotka</label>
                                      <select 
                                          className="w-full p-2 border rounded text-sm bg-white"
                                          value={editorProduct.unit || 'ks'} 
                                          onChange={e => setEditorProduct({...editorProduct, unit: e.target.value})}
                                      >
                                          <option value="ks">ks</option>
                                          <option value="set">set</option>
                                          <option value="kpl">kpl</option>
                                          <option value="m">m</option>
                                          <option value="hod">hod</option>
                                      </select>
                                  </div>

                                  {isSet && (
                                      <div className="col-span-2 pt-2 border-t border-gray-200 mt-2">
                                          <div className="flex flex-col gap-2">
                                              <label className="flex items-center gap-2 text-xs font-bold cursor-pointer">
                                                  <input 
                                                      type="radio" name="priceType" 
                                                      checked={editorProduct.priceType === 'calculated'} 
                                                      onChange={() => setEditorProduct({...editorProduct, priceType: 'calculated'})}
                                                  />
                                                  Automatický súčet cien komponentov
                                              </label>
                                              <label className="flex items-center gap-2 text-xs font-bold cursor-pointer">
                                                  <input 
                                                      type="radio" name="priceType" 
                                                      checked={editorProduct.priceType === 'fixed'} 
                                                      onChange={() => setEditorProduct({...editorProduct, priceType: 'fixed'})}
                                                  />
                                                  Manuálna fixná cena za SET
                                              </label>
                                          </div>

                                          <div className="mt-4 pt-2 border-t border-gray-200">
                                              <label className="block text-xs font-bold text-gray-500 mb-1">Zobrazenie v ponuke</label>
                                              <select 
                                                  className="w-full p-1 text-xs border rounded"
                                                  value={editorProduct.displayMode || 'itemized'}
                                                  onChange={e => setEditorProduct({...editorProduct, displayMode: e.target.value as any})}
                                              >
                                                  <option value="itemized">Rozpísať položky (Detailne)</option>
                                                  <option value="single_line">Iba jeden riadok (Ako komplet)</option>
                                              </select>
                                          </div>
                                      </div>
                                  )}
                              </div>
                          </div>

                          {/* Right Column: Set Components - REORDERED: SELECTED FIRST */}
                          <div className="border-l pl-6 border-gray-200 flex flex-col h-full overflow-hidden">
                              {isSet ? (
                                  <>
                                      <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2 shrink-0">
                                          <Package size={18}/> Komponenty SETu
                                      </h3>

                                      {/* 1. Selected Components List - MOVED TO TOP */}
                                      <div className="h-48 shrink-0 bg-yellow-50 rounded border border-yellow-200 overflow-y-auto p-2 space-y-1 mb-4 shadow-inner">
                                          <div className="flex justify-between items-center mb-1">
                                              <div className="text-[10px] font-bold text-yellow-700 uppercase">Obsah SETu</div>
                                              <div className="text-[10px] font-bold text-blue-600 bg-white px-2 rounded border">{calculateSetPrice().toFixed(2)} €</div>
                                          </div>

                                          {(!editorProduct.subProducts || editorProduct.subProducts.length === 0) && (
                                              <div className="text-center text-gray-400 text-xs py-4 italic">Zatiaľ žiadne komponenty.<br/>Pridajte ich zo zoznamu nižšie.</div>
                                          )}

                                          {editorProduct.subProducts?.map(sub => {
                                              const prod = products.find(p => p.id === sub.productId);
                                              return (
                                                  <div key={sub.productId} className="bg-white p-2 rounded border flex items-center justify-between shadow-sm animate-in slide-in-from-bottom-2">
                                                      <div className="flex-1 min-w-0 mr-2">
                                                          <div className="text-xs font-bold truncate" title={prod?.name}>{prod?.name || 'Neznámy'}</div>
                                                          <div className="text-[10px] text-gray-500">{prod?.price} € / {prod?.unit}</div>
                                                      </div>
                                                      <div className="flex items-center gap-1">
                                                          <input 
                                                              type="number" 
                                                              className="w-12 p-1 text-center border rounded text-xs font-bold" 
                                                              value={sub.quantity}
                                                              onChange={e => updateComponentQty(sub.productId, parseFloat(e.target.value) || 0)}
                                                          />
                                                          <button onClick={() => removeComponentFromSet(sub.productId)} className="text-red-400 hover:text-red-600 p-1"><X size={14}/></button>
                                                      </div>
                                                  </div>
                                              );
                                          })}
                                      </div>

                                      <div className="flex justify-center mb-2">
                                          <ArrowDown size={16} className="text-gray-300"/>
                                      </div>

                                      {/* 2. Enhanced Filter Section */}
                                      <div className="mb-2 shrink-0 space-y-2 bg-gray-50 p-2 rounded border border-gray-200">
                                          <div className="flex gap-2">
                                              <select 
                                                  className="w-1/3 p-2 border rounded text-xs font-bold text-gray-700 outline-none"
                                                  value={componentCategoryFilter}
                                                  onChange={e => setComponentCategoryFilter(e.target.value)}
                                              >
                                                  <option value="ALL">Všetky kategórie</option>
                                                  {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                              </select>
                                              <div className="relative flex-1">
                                                  <Search className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400" size={14}/>
                                                  <input 
                                                      className="w-full pl-8 p-2 border rounded text-xs outline-none focus:ring-1 focus:ring-purple-500" 
                                                      placeholder="Hľadať komponent..."
                                                      value={componentSearch}
                                                      onChange={e => setComponentSearch(e.target.value)}
                                                  />
                                              </div>
                                          </div>
                                      </div>

                                      {/* 3. Available Components List (Browsable) */}
                                      <div className="flex-1 overflow-y-auto mb-4 border rounded bg-white relative">
                                          <div className="sticky top-0 bg-gray-100 text-[10px] font-bold text-gray-500 uppercase px-2 py-1 border-b z-10">
                                              Dostupné produkty
                                          </div>

                                          {availableComponentsGrouped.sortedKeys.length === 0 ? (
                                              <div className="p-4 text-center text-gray-400 text-xs italic">Žiadne produkty nenašli.</div>
                                          ) : (
