                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[100px] print:h-auto" stickyToolbar={false} />
            </div>
        </div>
      </div>

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} controlLayout={data.controlLayout} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories} cabinClasses={cabinClasses}
          initialState={data.wizardData}
      />
      <CatalogManagerModal 
          isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} 
          onAddProduct={handleAddProduct} onUpdateProduct={handleUpdateProduct} onDeleteProduct={handleDeleteProduct} 
          customCategories={availableCategories} onAddCategory={handleAddCategory} onDeleteCategory={handleDeleteCategory} 
          onImportCatalog={handleImportCatalog} cabinClasses={cabinClasses} onAddCabinClass={handleAddCabinClass} 
          onUpdateCabinClass={handleUpdateCabinClass} onDeleteCabinClass={handleDeleteCabinClass} 
      />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const num = generateDocNumber('quote', t);
          const cats = t === 'lift' ? DEFAULT_CATEGORIES_LIST : CONTROL_SYSTEM_CATEGORIES;
          const newQuote = { ...data, id: generateId(), number: num, quoteMode: t, categories: cats.map(n => ({ id: generateId(), type: 'items', name: n, items: [], isExpanded: true, section: 'lift' })), title: t==='lift'?'Cenová Ponuka - Výťah':'Cenová Ponuka - RS' };
          setData(newQuote as any);
      }} />
      <SettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={settings} onSaveSettings={setSettings} onExportData={() => {}} onImportData={() => {}} onFactoryReset={() => {}} appVersion={APP_VERSION} availableCategories={availableCategories} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, CabinClass, ControlSystemLayout } from '../types';
import { X, Calculator, Check, AlertTriangle, Filter, Save, Trash2, GripVertical, RotateCcw, Plus, Layers, Info, Cpu, ArrowLeft, ArrowRight } from 'lucide-react';

const RS_CATEGORIES = ['Rozvádzač', 'Menič a filter', 'Displeje a privolávače', 'Snímanie polohy', 'Kabeláž', 'Atypické riešenia'];

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  controlLayout?: ControlSystemLayout; 
  mode: 'lift' | 'control_system';
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
  initialState?: MaterialWizardData; 
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean;
        autoType?: string; 
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, controlLayout, mode, onInsert, products, customCategories, initialState, cabinClasses
}) => {
  const [tabs, setTabs] = useState<{id: string, label: string}[]>([]);
  const [activeTab, setActiveTab] = useState('');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);
  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);
  const [transportPrice, setTransportPrice] = useState(200);
  const [packagingPrice, setPackagingPrice] = useState(50);

  useEffect(() => {
      if (isOpen) {
          let generatedTabs = [];
          if (mode === 'control_system') {
              generatedTabs = RS_CATEGORIES.map(c => ({ id: c, label: c }));
          } else {
              generatedTabs = customCategories
                  .filter(c => !['Montáž', 'Doprava', 'Balné', 'Ostatné', 'Ostatné šachta'].includes(c))
                  .map(c => ({ id: c, label: c }));
          }
          setTabs(generatedTabs);
          if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);

          if (initialState) {
              setBomItems(initialState.items);
              setIncludeTransport(initialState.includeTransport);
              setIncludePackaging(initialState.includePackaging);
              setIncludeAssembly(initialState.includeAssembly);
              if (initialState.transportPrice) setTransportPrice(initialState.transportPrice);
              if (initialState.packagingPrice) setPackagingPrice(initialState.packagingPrice);
          } else {
              handleResetToDefaults();
          }
      }
  }, [isOpen, mode]);

  const findSmartItem = (keywords: string[], cat: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      return products.find(p => {
          if (p.category !== cat) return false;
          const nameLow = p.name.toLowerCase();
          return lowerKeys.every(k => nameLow.includes(k));
      });
  };

  // --- LIFT CALCULATIONS (RESTORED V4.3.39) ---
  const calculateQuantitiesOnly = (l: LiftLayoutData): Record<string, number> => {
      const travel = l.travelHeight || 0;
      const hq = l.headroomHeight || 0;
      const pit = l.pitDepth || 0;
      const totalHeight = travel + hq + pit;
      const railLength = l.guideRailLength || 5000;
      const stops = l.numberOfStops || 2;

      // 1. Guides car/cwt
      const barsPerLine = Math.ceil(totalHeight / railLength);
      const railsCarTotal = barsPerLine * 2; 
      const railsCwtTotal = barsPerLine * 2;

      // 2. Fishplates
      const fishplatesPerLine = Math.max(0, barsPerLine - 1);
      const fpCar = fishplatesPerLine * 2;
      const fpCwt = fishplatesPerLine * 2;

      // 3. Brackets (Assume 2.5m span)
      const bracketRows = 1 + Math.ceil((totalHeight - 500) / 2500) + 1;
      const bracketsCar = bracketRows * 2;
      const bracketsCwt = bracketRows * 2;
      const clipsCar = bracketsCar * 2;
      const clipsCwt = bracketsCwt * 2;

      // 4. Ropes (Formula based on load/suspension)
      const suspension = l.suspensionType === '1:1' ? 1 : 2;
      const ropeCount = l.ratedLoad <= 630 ? 4 : 6;
      const ropeLen = Math.ceil((totalHeight * suspension * ropeCount / 1000) + 15);

      return {
          'rails_car': railsCarTotal, 'rails_cwt': railsCwtTotal, 
          'fp_car': fpCar, 'fp_cwt': fpCwt,
          'br_car': bracketsCar, 'br_cwt': bracketsCwt, 
          'cl_car': clipsCar, 'cl_cwt': clipsCwt,
          'rope': ropeLen, 'stops': stops, 'entrances': l.numberOfEntrances || stops
      };
  };

  const calculateLiftBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const qtys = calculateQuantitiesOnly(l);

    const addItem = (desc: string, qty: number, unit: string, cat: string, keys: string[]) => {
        if (qty <= 0) return;
        const product = findSmartItem(keys, cat);
        items.push({
            category: cat, description: product ? product.name : desc, quantity: Number(qty.toFixed(2)), 
            unit, productId: product?.id, price: product?.price || 0, isAuto: true 
        });
    };

    // Mapping logic
    addItem(`Vodidlá Kabína ${l.guideTypeCar}`, qtys['rails_car'], 'ks', 'Vodítka a kotvenie', [l.guideTypeCar || 'T89']);
    addItem(`Vodidlá CWT ${l.guideTypeCwt}`, qtys['rails_cwt'], 'ks', 'Vodítka a kotvenie', [l.guideTypeCwt || 'T50']);
    addItem(`Spojka vodidla Kabína`, qtys['fp_car'], 'ks', 'Vodítka a kotvenie', ['spojka', l.guideTypeCar || 'T89']);
    addItem(`Konzola Kabínová`, qtys['br_car'], 'ks', 'Vodítka a kotvenie', ['konzola', 'kabín']);
    addItem(`Príchytka vodidla Kabína`, qtys['cl_car'], 'ks', 'Vodítka a kotvenie', ['príchytka', l.guideTypeCar || 'T89']);

    addItem(`Šachtové dvere ${l.doorWidth}mm`, qtys['entrances'], 'ks', 'Dvere', ['dvere', 'šachtové', String(l.doorWidth)]);
    addItem(`Kabínové dvere ${l.doorWidth}mm`, l.isThroughCar?2:1, 'ks', 'Dvere', ['dvere', 'kabínové', String(l.doorWidth)]);

    addItem(`Pohon ${l.ratedLoad}kg`, 1, 'ks', 'Pohon', [l.driveType === 'traction' ? 'stroj' : 'hydraulika']);
    addItem(`Laná / Pásy`, qtys['rope'], 'm', 'Pohon', ['lano']);

    return items;
  };

  // --- RS CALCULATIONS ---
  const calculateRsBOM = (c: ControlSystemLayout) => {
      const items: MaterialWizardData['items'] = [];
      const addItem = (desc: string, qty: number, unit: string, cat: string, keys: string[]) => {
          const product = findSmartItem(keys, cat);
          items.push({
              category: cat, description: product ? product.name : desc, quantity: Number(qty.toFixed(2)), 
              unit, productId: product?.id, price: product?.price || 0, isAuto: true
          });
      };
      addItem(`Rozvádzač ${c.motorPower}kW`, 1, 'ks', 'Rozvádzač', ['rozvádzač']);
      if (c.driveType !== 'hydraulic') addItem(`Frekvenčný menič`, 1, 'ks', 'Menič a filter', ['menič']);
      if (!c.reuseLOP) addItem(`Privolávač`, c.numberOfStops, 'ks', 'Displeje a privolávače', ['privolávač']);
      return items;
  };

  const handleResetToDefaults = () => {
      setBomItems(mode === 'control_system' ? calculateRsBOM(controlLayout!) : calculateLiftBOM(layout));
  };

  const handleInsert = () => {
      onInsert({ items: bomItems, includeTransport, includePackaging, includeAssembly, transportPrice, packagingPrice, categoryOrder: tabs.map(t => t.id) });
      onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">
        <div className={`p-4 border-b flex justify-between items-center rounded-t-xl ${mode === 'control_system' ? 'bg-green-50' : 'bg-orange-50'}`}>
          <div className="flex items-center gap-2">
            {mode === 'control_system' ? <Cpu className="text-green-600"/> : <Calculator className="text-orange-500" />}
            <h2 className="text-xl font-bold text-gray-800">{mode === 'control_system' ? 'RS Sprievodca' : 'Lift Sprievodca (Inteligent V4.3)'}</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
        </div>

        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-3 py-2 transition cursor-pointer ${activeTab===tab.id ? 'bg-white border-gray-300' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`} onClick={() => setActiveTab(tab.id)}>
                     <span className={`text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? (mode==='control_system'?'text-green-700':'text-orange-700') : 'text-gray-500'}`}>{tab.label}</span>
                 </div>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-white">
            <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                        <tr>
                            <th className="p-3 text-left w-1/3">Položka (Formulár)</th>
                            <th className="p-3 text-left w-1/3">Skladový Produkt (Auto-Match)</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {bomItems.map((item, idx) => item.category === activeTab && (
                            <tr key={idx} className="hover:bg-gray-50">
                                <td className="p-3 font-bold text-gray-700">{item.description}</td>
                                <td className="p-3">
                                    <select 
                                        value={item.productId || ''} 
                                        onChange={e => {
                                            const p = products.find(prod => prod.id === e.target.value);
                                            if(p) {
                                                const updated = [...bomItems];
                                                updated[idx] = { ...updated[idx], productId: p.id, price: p.price, description: p.name, unit: p.unit };
                                                setBomItems(updated);
                                            }
                                        }} 
                                        className={`w-full p-2 border rounded text-xs font-bold ${item.productId ? 'bg-green-50 border-green-200 text-green-700' : 'bg-white'}`}
                                    >
                                        <option value="">-- Vybrať produkt --</option>
                                        {products.filter(p => p.category === activeTab).map(p => <option key={p.id} value={p.id}>{p.name} ({p.price}€)</option>)}
                                    </select>
                                </td>
                                <td className="p-3 text-right font-bold text-blue-600">{item.quantity}</td>
                                <td className="p-3 text-right font-mono">{item.price ? item.price.toFixed(2) : '-'} €</td>
                                <td className="p-3 text-center"><button onClick={() => setBomItems(bomItems.filter((_,i)=>i!==idx))} className="text-gray-400 hover:text-red-500"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            <button onClick={() => setBomItems([...bomItems, { category: activeTab, description: 'Nová položka', quantity: 1, unit: 'ks', price: 0, isAuto: false }])} className="w-full py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:text-blue-600 transition flex justify-center items-center gap-2 font-medium"><Plus size={18} /> Pridať položku manuálne</button>
        </div>

        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                 <label className="flex items-center gap-2 p-3 bg-white border rounded"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)}/> <strong>Montáž</strong></label>
                 <div className="flex items-center gap-2 p-3 bg-white border rounded"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)}/> <strong>Doprava</strong><input type="number" value={transportPrice} onChange={e => setTransportPrice(+e.target.value)} className="w-16 border rounded text-right px-1" disabled={!includeTransport}/>€</div>
                 <div className="flex items-center gap-2 p-3 bg-white border rounded"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)}/> <strong>Balné</strong><input type="number" value={packagingPrice} onChange={e => setPackagingPrice(+e.target.value)} className="w-16 border rounded text-right px-1" disabled={!includePackaging}/>€</div>
            </div>
            <div className="flex justify-between items-center">
                <button onClick={handleResetToDefaults} className="text-xs text-orange-600 font-bold flex items-center gap-2 px-3 py-1 bg-orange-50 rounded border border-orange-200"><RotateCcw size={14}/> Resetovať výpočet</button>
                <div className="flex gap-2"><button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium transition">Zrušiť</button><button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded font-bold flex items-center gap-2 transition shadow-lg"><Check size={18} /> Vložiť do ponuky</button></div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass, ProductComponent } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, AlertTriangle, Box, Download, Package, ListPlus, Calculator, RotateCcw, Factory, Truck, Tag, FileText, ArrowDown, Copy
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try { return crypto.randomUUID(); } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editorProduct, setEditorProduct] = useState<Partial<Product>>({});
  const [newCategoryName, setNewCategoryName] = useState('');

  const handleDuplicateCategory = (sourceCat: string) => {
      const targetCat = prompt(`Názov novej kategórie pre produkty z "${sourceCat}":`, `${sourceCat} - Kópia`);
      if (!targetCat) return;
      if (!customCategories.includes(targetCat)) onAddCategory(targetCat);
      const toCopy = products.filter(p => p.category === sourceCat);
      toCopy.forEach(p => onAddProduct({ ...p, id: generateId(), category: targetCat }));
      alert(`Skopírovaných ${toCopy.length} produktov do "${targetCat}".`);
  };

  const saveProduct = () => {
      if (!editorProduct.name) return;
      if (products.find(p => p.id === editorProduct.id)) onUpdateProduct(editorProduct as Product);
      else onAddProduct(editorProduct as Product);
      setIsEditorOpen(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-2">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[98vw] h-[95vh] flex flex-col">
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <h2 className="text-xl font-bold flex items-center gap-2"><Settings className="text-purple-600" /> Správca Katalógu</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full"><X size={20}/></button>
        </div>

        <div className="flex border-b">
            {['products', 'categories', 'classes'].map(t => (
                <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 py-3 font-bold text-sm border-b-2 capitalize transition ${activeTab===t ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500'}`}>{t==='products'?'Produkty':t==='categories'?'Kategórie':'Triedy'}</button>
            ))}
        </div>

        <div className="flex-1 overflow-hidden flex flex-col p-4 bg-gray-50">
            {activeTab === 'products' && (
                <div className="flex-1 flex flex-col bg-white rounded-lg shadow border overflow-hidden">
                    <div className="p-4 border-b flex gap-4">
                        <select value={activeCategory} onChange={e => setActiveCategory(e.target.value)} className="border rounded p-2 text-sm font-bold w-64">
                            {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Hľadať..." className="border rounded p-2 text-sm flex-1" />
                        <button onClick={() => { setEditorProduct({id: generateId(), category: activeCategory, name:'', price:0, unit:'ks'}); setIsEditorOpen(true); }} className="bg-purple-600 text-white px-4 py-2 rounded font-bold">+ Pridať</button>
                    </div>
                    <div className="flex-1 overflow-y-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-50 sticky top-0"><tr><th className="p-3">Názov</th><th className="p-3">Podkategória</th><th className="p-3 text-right">Cena</th><th className="p-3 text-center">Akcie</th></tr></thead>
                            <tbody className="divide-y">
                                {products.filter(p => p.category === activeCategory && p.name.toLowerCase().includes(searchTerm.toLowerCase())).map(p => (
                                    <tr key={p.id} className="hover:bg-gray-50">
                                        <td className="p-3 font-bold">{p.name}</td>
                                        <td className="p-3">{p.subcategory || '-'}</td>
                                        <td className="p-3 text-right font-mono">{p.price.toFixed(2)} €</td>
                                        <td className="p-3 text-center flex gap-1 justify-center">
                                            <button onClick={() => { setEditorProduct(p); setIsEditorOpen(true); }} className="p-1 text-blue-600"><Edit size={16}/></button>
                                            <button onClick={() => onDeleteProduct(p.id)} className="p-1 text-red-500"><Trash2 size={16}/></button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {activeTab === 'categories' && (
                <div className="flex-1 overflow-y-auto max-w-2xl mx-auto w-full">
                    <div className="bg-white p-4 rounded shadow border mb-4 flex gap-2">
                        <input value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} placeholder="Nová kategória..." className="flex-1 border rounded p-2" />
                        <button onClick={() => { if(newCategoryName) { onAddCategory(newCategoryName); setNewCategoryName(''); } }} className="bg-purple-600 text-white px-4 py-2 rounded font-bold">Pridať</button>
                    </div>
                    <div className="bg-white rounded shadow border divide-y">
                        {customCategories.map(c => (
                            <div key={c} className="p-4 flex justify-between items-center group">
                                <div className="font-bold">{c} <span className="text-xs text-gray-400">({products.filter(p=>p.category===c).length} ks)</span></div>
                                <div className="flex gap-2">
                                    <button onClick={() => handleDuplicateCategory(c)} className="p-2 text-blue-500 hover:bg-blue-50 rounded" title="Kopírovať produkty do inej kategórie"><Copy size={18}/></button>
                                    <button onClick={() => onDeleteCategory(c)} className="p-2 text-gray-300 hover:text-red-500 rounded"><Trash2 size={18}/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>

        {isEditorOpen && (
            <div className="fixed inset-0 bg-black/60 z-[120] flex items-center justify-center p-4">
                <div className="bg-white rounded-xl w-full max-w-md p-6">
                    <h3 className="text-lg font-bold mb-4">Editácia Produktu</h3>
                    <div className="space-y-4">
                        <input value={editorProduct.name} onChange={e => setEditorProduct({...editorProduct, name:e.target.value})} className="w-full border rounded p-2" placeholder="Názov" />
                        <input type="number" value={editorProduct.price} onChange={e => setEditorProduct({...editorProduct, price:+e.target.value})} className="w-full border rounded p-2" placeholder="Cena" />
                        <select value={editorProduct.unit} onChange={e => setEditorProduct({...editorProduct, unit:e.target.value})} className="w-full border rounded p-2">
                            <option value="ks">ks</option><option value="m">m</option><option value="set">set</option><option value="kpl">kpl</option>
                        </select>
                    </div>
                    <div className="mt-6 flex justify-end gap-2">
                        <button onClick={() => setIsEditorOpen(false)} className="px-4 py-2 text-gray-500">Zrušiť</button>
                        <button onClick={saveProduct} className="px-6 py-2 bg-purple-600 text-white rounded font-bold">Uložiť</button>
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

