  const [templateModalMode, setTemplateModalMode] = useState<'select' | 'save'>('select');
  const [templateContext, setTemplateContext] = useState<'lift' | 'shaft'>('lift');
  const [emailModalProps, setEmailModalProps] = useState({ to: '', subject: '', message: '' });
  const [calcSuccess, setCalcSuccess] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState<string | false>(false);
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [draggedCatId, setDraggedCatId] = useState<string | null>(null);

  const printContentRef = useRef<HTMLDivElement>(null);
  const titleInputRef = useRef<HTMLTextAreaElement>(null);

  const isContractMode = data.type === 'contract';
  const isControlMode = data.quoteMode === 'control_system';
  const relatedDoc = savedQuotes.find(q => q.id === data.relatedDocId);
  const currentAreaInfo = calculateEn8120(data.layout?.cabinWidth || 0, data.layout?.cabinDepth || 0, data.layout?.cabinHeight || 2100);

  useEffect(() => {
      document.title = `${data.number} ${data.clientReference ? `- ${data.clientReference}` : ''} | SmartQuote`;
  }, [data.number, data.clientReference]);

  useEffect(() => {
      const storedQuotes = localStorage.getItem('smartquote_archive');
      let archives: QuoteData[] = [];
      if (storedQuotes) {
          try {
              archives = JSON.parse(storedQuotes);
              setSavedQuotes(archives);
          } catch (e) { console.error("Failed to load archive", e); }
      }

      const storedSettings = localStorage.getItem('smartquote_settings');
      let loadedSettings: AppSettings = { nextCpSequence: 1, nextRsSequence: 1, nextObjSequence: 1, nextPlSequence: 1 };

      if (storedSettings) {
          try {
              const parsed = JSON.parse(storedSettings);
              if (archives.length > 0) {
                  let maxCp = 0; let maxRs = 0;
                  archives.forEach(q => {
                      const match = q.number.match(/_(\d{3})_/);
                      if (match && match[1]) {
                          const seq = parseInt(match[1], 10);
                          if (q.quoteMode === 'control_system' || q.number.startsWith('RS')) { if (seq > maxRs) maxRs = seq; } 
                          else { if (seq > maxCp) maxCp = seq; }
                      }
                  });
                  if (maxCp >= (parsed.nextCpSequence || 1)) parsed.nextCpSequence = maxCp + 1;
                  if (maxRs >= (parsed.nextRsSequence || 1)) parsed.nextRsSequence = maxRs + 1;
              }
              setSettings(parsed);
              loadedSettings = parsed;
          } catch (e) { console.error("Failed to load settings", e); }
      }

      if (data.categories.length === 0) {
          const initCats: QuoteCategory[] = DEFAULT_CATEGORIES_LIST.map(name => ({
                id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift',
                textContent: loadedSettings.defaultCategoryTexts?.[name] || undefined
          }));
          setData(prev => ({...prev, categories: initCats}));
      }

      const loadLS = (key: string, setter: any) => { const s = localStorage.getItem(key); if(s) try { setter(JSON.parse(s)); } catch(e){} };
      loadLS('smartquote_products', setProducts);
      loadLS('smartquote_clients', setClients);
      loadLS('smartquote_suppliers', setSuppliers);
      loadLS('smartquote_categories', (v: any) => {
          setAvailableCategories(Array.from(new Set([...DEFAULT_CATEGORIES_LIST, ...CONTROL_SYSTEM_CATEGORIES, ...v])));
      });
      loadLS('smartquote_cabin_classes', setCabinClasses);
  }, []); 

  useEffect(() => { localStorage.setItem('smartquote_archive', JSON.stringify(savedQuotes)); }, [savedQuotes]);
  useEffect(() => { localStorage.setItem('smartquote_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('smartquote_products', JSON.stringify(products)); }, [products]);
  useEffect(() => { localStorage.setItem('smartquote_clients', JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem('smartquote_suppliers', JSON.stringify(suppliers)); }, [suppliers]);
  useEffect(() => { localStorage.setItem('smartquote_categories', JSON.stringify(availableCategories)); }, [availableCategories]);
  useEffect(() => { localStorage.setItem('smartquote_cabin_classes', JSON.stringify(cabinClasses)); }, [cabinClasses]);

  const calculateTotals = () => {
      let lCost = 0; let lSale = 0; let sCost = 0; let sSale = 0;
      data.categories.forEach(cat => {
          if (cat.isHidden) return;
          const margin = cat.section === 'shaft' ? data.shaftMargin : data.globalMargin;
          cat.items.forEach(item => {
              const cost = item.quantity * item.unitPrice;
              const sale = cost * (1 + margin / 100);
              if (cat.section === 'shaft') { sCost += cost; sSale += sale; } else { lCost += cost; lSale += sale; }
          });
      });
      const vat = (lSale + sSale) * ((data.vatRate || 23) / 100);
      return { liftCost: lCost, liftSale: lSale, shaftCost: sCost, shaftSale: sSale, totalSelling: lSale + sSale, totalPurchase: lCost + sCost, vat, gross: lSale + sSale + vat, liftProfit: lSale - lCost, shaftProfit: sSale - sCost };
  };
  const totals = calculateTotals();

  const handleLogin = () => { sessionStorage.setItem('auth', 'true'); setIsAuthenticated(true); };
  const handleLogout = () => { sessionStorage.removeItem('auth'); setIsAuthenticated(false); }

  const generateDocNumber = (type: 'quote' | 'order' | 'contract', mode: 'lift' | 'control_system' = 'lift') => {
      const year = new Date().getFullYear().toString().slice(-2);
      let seq = 1; let prefix = 'CP';
      if (type === 'quote') {
          if (mode === 'control_system') { seq = settings.nextRsSequence || 1; prefix = 'RS'; } 
          else { seq = settings.nextCpSequence; prefix = 'CP'; }
      }
      if (type === 'order') { seq = settings.nextObjSequence; prefix = 'OBJ'; }
      if (type === 'contract') { seq = settings.nextPlSequence; prefix = 'PL'; }
      return `${prefix}_SK_${seq.toString().padStart(3, '0')}_${year}_BA`;
  };

  const handleDuplicateQuote = () => {
      const isRs = data.quoteMode === 'control_system';
      const switchMode = window.confirm(
          isRs ? "Doklad je RS. Kopírovať ako RS?\n[OK] = Áno, [Zrušiť] = Nie, zmeniť na VÝŤAH."
               : "Doklad je VÝŤAH. Kopírovať ako VÝŤAH?\n[OK] = Áno, [Zrušiť] = Nie, zmeniť na RS."
      );
      const targetMode = switchMode ? data.quoteMode : (isRs ? 'lift' : 'control_system');
      const newNum = generateDocNumber('quote', targetMode || 'lift');

      let newCats = [];
      if (switchMode) {
          newCats = data.categories.map(c => ({...c, id: generateId(), items: c.items.map(i => ({...i, id: generateId()}))}));
      } else {
          const cats = targetMode === 'lift' ? DEFAULT_CATEGORIES_LIST : CONTROL_SYSTEM_CATEGORIES;
          newCats = cats.map(name => ({ id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift' }));
      }
      const newData = { ...data, id: generateId(), number: newNum, quoteMode: targetMode, title: `${data.title} (Kópia)`, date: new Date().toISOString().split('T')[0], categories: newCats };
      setSavedQuotes([...savedQuotes, { ...newData, lastUpdated: Date.now() }]);
      setData(newData as any);
  };

  const handleLayoutChange = (field: keyof LiftLayoutData, value: any) => {
      setData(prev => {
          const newData = { ...prev, layout: { ...prev.layout!, [field]: value } };
          if (field === 'entrances') { newData.layout.isThroughCar = (value === 'AB' || value === 'AC'); }
          if (field === 'shaftWidth' || field === 'doorOpeningWidth') {
              const sw = field === 'shaftWidth' ? value : prev.layout?.shaftWidth || 0;
              const doW = field === 'doorOpeningWidth' ? value : prev.layout?.doorOpeningWidth || 0;
              if (sw > 0 && doW > 0 && sw > doW) {
                  const remainder = sw - doW;
                  const half = Math.floor(remainder / 2);
                  newData.layout.LDO = half; newData.layout.RDO = remainder - half;
              }
          }
          if (field === 'numberOfStops' || field === 'startStation') {
              const stops = field === 'numberOfStops' ? value : prev.layout?.numberOfStops || 2;
              const start = field === 'startStation' ? value : prev.layout?.startStation || 0;
              const labels = Array.from({length: stops}, (_, i) => i + start).join(',');
              newData.layout!.stationLabels = labels;
              if (newData.layout.entrances === 'A') newData.layout.numberOfEntrances = stops;
          }
          return newData;
      });
  };

  const handleControlLayoutChange = (field: keyof ControlSystemLayout, value: any) => {
      setData(prev => ({ ...prev, controlLayout: { ...prev.controlLayout!, [field]: value } }));
  };

  const handleAddCategory = (name: string) => { if (name && !availableCategories.includes(name)) { setAvailableCategories([...availableCategories, name]); } };
  const handleDeleteCategory = (name: string) => { setAvailableCategories(availableCategories.filter(c => c !== name)); };
  const handleAddCabinClass = (cc: CabinClass) => setCabinClasses([...cabinClasses, cc]);
  const handleUpdateCabinClass = (cc: CabinClass) => { setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c)); };
  const handleDeleteCabinClass = (id: string) => setCabinClasses(cabinClasses.filter(c => c.id !== id));
  const handleAddProduct = (p: Product) => { setProducts(prev => { const newProducts = [...prev, p]; if (!availableCategories.includes(p.category)) { setAvailableCategories(prevCats => [...prevCats, p.category]); } return newProducts; }); };
  const handleUpdateProduct = (p: Product) => { setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod)); };
  const handleDeleteProduct = (id: string) => setProducts(products.filter(p => p.id !== id));

  const handleImportCatalog = (file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const importedProducts = (JSON.parse(e.target?.result as string) as any) as any[];
              const newProductMap = new Map(products.map(p => [p.id, p]));
              importedProducts.forEach((p: any) => newProductMap.set(p.id, p));
              setProducts(Array.from(newProductMap.values()));
              alert(`Katalóg aktualizovaný.`);
          } catch (err) { alert("Chyba importu."); }
      };
      reader.readAsText(file);
  };

  const handleMaterialWizardInsert = (wData: MaterialWizardData) => {
      setData(prev => {
          const newData = { ...prev, wizardData: wData };
          const activeCategoryNames = new Set(wData.categoryOrder);
          if (wData.includeAssembly) activeCategoryNames.add('Montáž'); else activeCategoryNames.delete('Montáž');
          if (wData.includeTransport) activeCategoryNames.add('Doprava'); else activeCategoryNames.delete('Doprava');
          if (wData.includePackaging) activeCategoryNames.add('Balné'); else activeCategoryNames.delete('Balné');
          newData.categories = newData.categories.filter(c => {
              if (c.type === 'text') return true;
              if (c.name === 'Oceľová konštrukcia' && newData.layout?.hasExternalShaft) return true;
              return activeCategoryNames.has(c.name);
          });
          newData.categories.forEach(c => { if (activeCategoryNames.has(c.name) && c.type === 'items') { c.items = []; } });
          activeCategoryNames.forEach(catName => {
               if (!catName) return;
               let cat = newData.categories.find(c => c.name === catName);
               if (!cat) {
                   cat = { id: generateId(), name: catName, type: 'items', items: [], isExpanded: true, section: catName === 'Oceľová konštrukcia' ? 'shaft' : 'lift', textContent: settings.defaultCategoryTexts?.[catName] };
                   newData.categories.push(cat);
               }
          });
          const findCat = (namePart: string) => newData.categories.find(c => c.name === namePart);
          wData.items.forEach(bomItem => {
              if (!activeCategoryNames.has(bomItem.category)) return;
              const category = findCat(bomItem.category);
              if (category) {
                  category.items.push({ id: generateId(), description: bomItem.description, unit: bomItem.unit, quantity: bomItem.quantity, unitPrice: bomItem.price || 0, purchasePrice: 0, vatRate: 23 });
              }
          });
          if (wData.includeAssembly) { const cat = findCat('Montáž'); if (cat && cat.items.length === 0) { cat.items.push({ id: generateId(), description: 'Montáž technológie', unit: 'kpl', quantity: 1, unitPrice: 1500, purchasePrice: 0, vatRate: 23 }); } }
          if (wData.includeTransport) { const cat = findCat('Doprava'); if (cat && cat.items.length === 0) { cat.items.push({ id: generateId(), description: 'Doprava', unit: 'kpl', quantity: 1, unitPrice: wData.transportPrice || 200, purchasePrice: 0, vatRate: 23 }); } }
          if (wData.includePackaging) { const cat = findCat('Balné'); if (cat && cat.items.length === 0) { cat.items.push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); } }
          return newData;
      });
  };

  const handleRecalculateLoad = () => {
      if (!data.layout) return;
      const { suggestedLoad, persons } = calculateEn8120(data.layout.cabinWidth, data.layout.cabinDepth);
      setData(prev => ({ ...prev, layout: { ...prev.layout!, ratedLoad: suggestedLoad, numberOfPersons: persons } }));
      alert(`Prepočítané: Nosnosť ${suggestedLoad} kg, Osoby ${persons}`);
  };

  const handleToggleExternalShaft = (checked: boolean) => {
      handleLayoutChange('hasExternalShaft', checked);
      if (checked) {
          const exists = data.categories.find(c => c.name === 'Oceľová konštrukcia');
          if (!exists) {
              setData(prev => ({ ...prev, categories: [...prev.categories, { id: generateId(), type: 'items', name: 'Oceľová konštrukcia', items: SHAFT_TEMPLATE, isExpanded: true, section: 'shaft', textContent: SHAFT_DETAILS_HTML }] }));
          }
      }
  };

  const openEmailModal = () => { setEmailModalProps({ to: data.client.email || '', subject: `${data.number} - ${data.title}`, message: `Dobrý deň,\n\nzasielame Vám cenovú ponuku č. ${data.number}.\n\nS pozdravom,\n${data.supplier.name}` }); setIsEmailModalOpen(true); };

  if (!isAuthenticated) return <LoginGate onLogin={handleLogin} />;
  const recommendedRails = getRailTypesForLoad(data.layout?.ratedLoad || 630);

  return (
    <div className={`min-h-screen bg-gray-100 font-sans print:bg-white print:text-black ${isPreviewMode ? 'bg-gray-500' : ''}`}>
      <div className="bg-gray-900 text-white shadow-md sticky top-0 z-50 print:hidden">
        <div className="max-w-[1400px] mx-auto px-4 py-2 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-1.5 rounded-lg font-bold text-xl flex items-center gap-2">
                    <Zap size={20} className="text-yellow-300"/> SmartQuote <span className="text-xs bg-white/20 px-1.5 rounded py-0.5 font-mono">v{APP_VERSION}</span>
                </div>
                <button onClick={() => setShowArchive(true)} className="flex items-center gap-2 px-3 py-1.5 bg-gray-800 hover:bg-gray-700 rounded-lg transition text-sm"><Archive size={16}/> Archív</button>
                <button onClick={() => setIsNewQuoteModalOpen(true)} className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 hover:bg-blue-500 text-white rounded-lg transition text-sm font-bold shadow-lg"><PlusCircle size={16}/> Nová CP</button>
            </div>
            <div className="flex items-center gap-2">
                 <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-1.5 text-gray-300 hover:text-white hover:bg-gray-800 rounded transition text-xs"><Settings size={14}/> Katalóg</button>
                 <button onClick={() => setIsSettingsModalOpen(true)} className="px-3 py-1.5 text-gray-300 hover:text-white hover:bg-gray-800 rounded transition text-xs"><Activity size={14}/> Nastavenia</button>
                 <button onClick={() => { const now = Date.now(); setSavedQuotes(prev => { const ex = prev.find(q=>q.id===data.id); return ex ? prev.map(q=>q.id===data.id?{...data, lastUpdated: now}:q) : [...prev, {...data, lastUpdated: now}]; }); alert("Uložené."); }} className="px-4 py-1.5 bg-green-600 hover:bg-green-500 text-white rounded-lg transition font-bold shadow-lg text-sm"><Save size={16}/> Uložiť</button>
                 <button onClick={handleLogout} className="p-2 text-red-300 hover:bg-red-900/30 rounded-full ml-2"><LogOut size={16}/></button>
            </div>
        </div>
      </div>

      <div className="max-w-[210mm] mx-auto py-8 print:p-0">

        {/* CONFIG PANEL */}
        <div className={`mb-8 p-6 rounded-xl border shadow-sm text-sm no-print ${isControlMode ? 'bg-green-50 border-green-200' : 'bg-amber-50 border-amber-200'}`}>
             {!isControlMode ? (
             <div className="grid grid-cols-12 gap-4">
                <div className="col-span-12 font-bold text-amber-900 uppercase flex items-center gap-2 mb-1 pb-2 border-b border-amber-200"><Sliders size={16}/> Parametre Výťahu</div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Nosnosť (kg)</label><input type="number" value={data.layout?.ratedLoad} onChange={e => handleLayoutChange('ratedLoad', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Osoby</label><input type="number" value={data.layout?.numberOfPersons} onChange={e => handleLayoutChange('numberOfPersons', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Stanice</label><input type="number" value={data.layout?.numberOfStops} onChange={e => handleLayoutChange('numberOfStops', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-3"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Zdvih (mm)</label><input type="number" value={data.layout?.travelHeight} onChange={e => handleLayoutChange('travelHeight', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-medium bg-white"/></div>
                <div className="col-span-3 flex items-end"><button onClick={() => setIsMaterialModalOpen(true)} className="w-full h-10 bg-gradient-to-r from-orange-400 to-orange-500 text-white font-bold rounded shadow flex items-center justify-center gap-2 text-xs"> <Calculator size={14}/> Sprievodca LIFT (v4.3)</button></div>
             </div>
             ) : (
             <div className="grid grid-cols-12 gap-4">
                <div className="col-span-12 font-bold text-green-900 uppercase flex items-center gap-2 mb-1 pb-2 border-b border-green-200"><Cpu size={18}/> Parametre RS</div>
                <div className="col-span-4"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Výkon Motora (kW)</label><input type="number" step="0.1" value={data.controlLayout?.motorPower} onChange={e => handleControlLayoutChange('motorPower', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-4"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Počet Staníc</label><input type="number" value={data.controlLayout?.numberOfStops} onChange={e => handleControlLayoutChange('numberOfStops', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-4 flex items-end"><button onClick={() => setIsMaterialModalOpen(true)} className="w-full h-10 bg-gradient-to-r from-green-500 to-green-600 text-white font-bold rounded shadow flex items-center justify-center gap-2 text-xs"> <Cpu size={14}/> Sprievodca RS</button></div>
             </div>
             )}
        </div>

        {/* DOCUMENT VIEW */}
        <div ref={printContentRef} className="bg-white shadow-2xl print:shadow-none min-h-[297mm] relative flex flex-col print:block p-12 print:p-0">
            <div className="mb-8 border-b-2 border-gray-900 pb-6 flex justify-between items-start no-print">
                 <div className="flex gap-2">
                    <button onClick={handleDuplicateQuote} className="px-3 py-2 bg-white border border-gray-300 rounded-lg text-gray-600 font-bold hover:bg-gray-100 flex items-center gap-2"><Copy size={16}/> Kópia</button>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => window.print()} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold flex items-center gap-2 shadow-lg"><Printer size={18}/> Tlačiť PDF</button>
                 </div>
            </div>

            <div className="flex justify-between items-start mb-10">
                <div className="w-2/3">
                    <textarea value={data.title} onChange={e => setData({...data, title: e.target.value})} className="text-3xl font-black w-full border-none bg-transparent uppercase p-0" rows={2}/>
                    <div className="text-lg text-gray-500 font-bold mt-1 uppercase tracking-widest">{data.number}</div>
                </div>
                <div className="text-right">
                    <div className="text-xs font-bold text-gray-400 uppercase">Dátum vystavenia</div>
                    <div className="font-bold">{new Date(data.date).toLocaleDateString('sk-SK')}</div>
                    <div className="text-xs font-bold text-red-500 uppercase mt-2">Platnosť ponuky (60 dní)</div>
                    <div className="font-bold text-red-600">{new Date(data.validUntil).toLocaleDateString('sk-SK')}</div>
                </div>
            </div>

            {data.showTechSpecs && (
                <TechSpecTable data={data.layout!} controlData={data.controlLayout} isVisible={true} onToggleVisibility={() => {}} mode={data.quoteMode || 'lift'} embedded={true} />
            )}

            <div className="space-y-6 mt-10">
                {data.categories.map(cat => (
                    <CategoryTable 
                        key={cat.id} category={cat} currency={data.currency} 
                        globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData({...data, categories: data.categories.map(c => c.id === id ? {...c, [f]: v} : c)})}
                        onDeleteCategory={(id) => setData({...data, categories: data.categories.filter(c => c.id !== id)})}
                        onAddItem={(cid, sur) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: [...c.items, { id: generateId(), description: sur?'Príplatok':'Položka', unit:'ks', quantity:1, unitPrice:0, purchasePrice:0, vatRate:23, isSurcharge:sur }]} : c)})}
                        onUpdateItem={(cid, iid, f, v) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)})}
                        onDeleteItem={(cid, iid) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)})}
                        onAiSuggest={() => {}} onOpenCatalog={() => setIsProductModalOpen(true)} isAiLoading={false} mode={data.quoteMode}
                    />
                ))}
            </div>

            <div className="mt-12 flex justify-end break-inside-avoid">
                <div className="w-1/2">
                    <table className="w-full text-sm">
                        <tbody className="divide-y border-t-2 border-black">
                            <tr><td className="py-2 text-gray-500 font-bold uppercase">Cena technológie bez DPH</td><td className="py-2 text-right font-black">{totals.liftSale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                            {totals.shaftSale > 0 && <tr><td className="py-2 text-gray-500 font-bold uppercase">Cena šachty / montáž bez DPH</td><td className="py-2 text-right font-black">{totals.shaftSale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>}
                            <tr className="bg-gray-900 text-white"><td className="p-3 text-lg font-bold uppercase">Spolu k úhrade s DPH</td><td className="p-3 text-right text-2xl font-black">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-10 break-inside-avoid">
                <div className="flex justify-between items-center mb-3 no-print">
                    <h4 className="font-bold uppercase text-gray-500 text-xs">Obchodné a Platobné podmienky</h4>
                    <div className="flex gap-2">
                        <button onClick={() => setData({...data, terms: TERMS_FULL})} className="px-2 py-1 bg-blue-50 text-blue-700 rounded text-[10px] font-bold border border-blue-200 hover:bg-blue-100 flex items-center gap-1"><FileText size={12}/> Vložiť s montážou</button>
                        <button onClick={() => setData({...data, terms: TERMS_SUPPLY_ONLY})} className="px-2 py-1 bg-orange-50 text-orange-700 rounded text-[10px] font-bold border border-orange-200 hover:bg-orange-100 flex items-center gap-1"><FileMinus size={12}/> Vložiť len dodávku</button>
                    </div>
                </div>
                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[100px] print:h-auto" stickyToolbar={false} />
            </div>
        </div>
      </div>

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} controlLayout={data.controlLayout} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories} cabinClasses={cabinClasses}
          initialState={data.wizardData}
      />
      <CatalogManagerModal 
          isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} 
          onAddProduct={handleAddProduct} onUpdateProduct={handleUpdateProduct} onDeleteProduct={handleDeleteProduct} 
          customCategories={availableCategories} onAddCategory={handleAddCategory} onDeleteCategory={handleDeleteCategory} 
          onImportCatalog={handleImportCatalog} cabinClasses={cabinClasses} onAddCabinClass={handleAddCabinClass} 
          onUpdateCabinClass={handleUpdateCabinClass} onDeleteCabinClass={handleDeleteCabinClass} 
      />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const num = generateDocNumber('quote', t);
          const cats = t === 'lift' ? DEFAULT_CATEGORIES_LIST : CONTROL_SYSTEM_CATEGORIES;
          const newQuote = { ...data, id: generateId(), number: num, quoteMode: t, categories: cats.map(n => ({ id: generateId(), type: 'items', name: n, items: [], isExpanded: true, section: 'lift' })), title: t==='lift'?'Cenová Ponuka - Výťah':'Cenová Ponuka - RS' };
          setData(newQuote as any);
      }} />
      <SettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={settings} onSaveSettings={setSettings} onExportData={() => {}} onImportData={() => {}} onFactoryReset={() => {}} appVersion={APP_VERSION} availableCategories={availableCategories} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, CabinClass, ControlSystemLayout } from '../types';
import { X, Calculator, Check, AlertTriangle, RotateCcw, Plus, Cpu, ArrowLeft, ArrowRight } from 'lucide-react';

const RS_CATEGORIES = ['Rozvádzač', 'Menič a filter', 'Displeje a privolávače', 'Snímanie polohy', 'Kabeláž', 'Atypické riešenia'];

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  controlLayout?: ControlSystemLayout; 
  mode: 'lift' | 'control_system';
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
  initialState?: MaterialWizardData; 
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean;
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, controlLayout, mode, onInsert, products, customCategories, initialState, cabinClasses
}) => {
  const [tabs, setTabs] = useState<{id: string, label: string}[]>([]);
  const [activeTab, setActiveTab] = useState('');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);
  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);
  const [transportPrice, setTransportPrice] = useState(200);
  const [packagingPrice, setPackagingPrice] = useState(50);

  useEffect(() => {
      if (isOpen) {
          let generatedTabs = [];
          if (mode === 'control_system') {
              generatedTabs = RS_CATEGORIES.map(c => ({ id: c, label: c }));
          } else {
              generatedTabs = customCategories
                  .filter(c => !['Montáž', 'Doprava', 'Balné', 'Ostatné', 'Ostatné šachta'].includes(c))
                  .map(c => ({ id: c, label: c }));
          }
          setTabs(generatedTabs);
          if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);

          if (initialState) {
              setBomItems(initialState.items);
              setIncludeTransport(initialState.includeTransport);
              setIncludePackaging(initialState.includePackaging);
              setIncludeAssembly(initialState.includeAssembly);
              if (initialState.transportPrice) setTransportPrice(initialState.transportPrice);
              if (initialState.packagingPrice) setPackagingPrice(initialState.packagingPrice);
          } else {
              handleResetToDefaults();
          }
      }
  }, [isOpen, mode]);

  const findSmartItem = (keywords: string[], cat: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      return products.find(p => {
          if (p.category !== cat) return false;
          const nameLow = p.name.toLowerCase();
          return lowerKeys.every(k => nameLow.includes(k));
      });
  };

  // --- LIFT CALCULATIONS (V4.3.40 INTEL) ---
  const calculateQuantitiesOnly = (l: LiftLayoutData): Record<string, number> => {
      const travel = l.travelHeight || 0;
      const hq = l.headroomHeight || 0;
      const pit = l.pitDepth || 0;
      const totalHeight = travel + hq + pit;
      const railLength = l.guideRailLength || 5000;
      const stops = l.numberOfStops || 2;

      // 1. Vodítka (Vždy 2 línie)
      const barsPerLine = Math.ceil(totalHeight / railLength);
      const railsCarTotal = barsPerLine * 2; 
      const railsCwtTotal = barsPerLine * 2;

      // 2. Spojky (Vždy tyče - 1 na líniu)
      const fishplatesPerLine = Math.max(0, barsPerLine - 1);
      const fpCar = fishplatesPerLine * 2;
      const fpCwt = fishplatesPerLine * 2;

      // 3. Konzoly (Predpoklad rozteč cca 2.5m)
      const bracketRows = 1 + Math.ceil((totalHeight - 500) / 2500) + 1;
      const bracketsCar = bracketRows * 2;
      const bracketsCwt = bracketRows * 2;
      const clipsCar = bracketsCar * 2;
      const clipsCwt = bracketsCwt * 2;

      // 4. Laná (Vzorec: totalHeight * lanovanie * pocet_lan)
      const suspension = l.suspensionType === '1:1' ? 1 : 2;
      const ropeCount = l.ratedLoad <= 630 ? 4 : 6;
      const ropeLen = Math.ceil((totalHeight * suspension * ropeCount / 1000) + 15);

      return {
          'rails_car': railsCarTotal, 'rails_cwt': railsCwtTotal, 
          'fp_car': fpCar, 'fp_cwt': fpCwt,
          'br_car': bracketsCar, 'br_cwt': bracketsCwt, 
          'cl_car': clipsCar, 'cl_cwt': clipsCwt,
          'rope': ropeLen, 'stops': stops, 'entrances': l.numberOfEntrances || stops
      };
  };

  const calculateLiftBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const qtys = calculateQuantitiesOnly(l);

    const addItem = (desc: string, qty: number, unit: string, cat: string, keys: string[]) => {
        if (qty <= 0) return;
        const product = findSmartItem(keys, cat);
        items.push({
            category: cat, description: product ? product.name : desc, quantity: Number(qty.toFixed(2)), 
            unit, productId: product?.id, price: product?.price || 0, isAuto: true 
        });
    };

    addItem(`Vodidlá Kabína ${l.guideTypeCar}`, qtys['rails_car'], 'ks', 'Vodítka a kotvenie', [l.guideTypeCar || 'T89']);
    addItem(`Vodidlá CWT ${l.guideTypeCwt}`, qtys['rails_cwt'], 'ks', 'Vodítka a kotvenie', [l.guideTypeCwt || 'T50']);
    addItem(`Spojka vodidla Kabína`, qtys['fp_car'], 'ks', 'Vodítka a kotvenie', ['spojka', l.guideTypeCar || 'T89']);
    addItem(`Konzola Kabínová`, qtys['br_car'], 'ks', 'Vodítka a kotvenie', ['konzola', 'kabín']);
    addItem(`Príchytka vodidla Kabína`, qtys['cl_car'], 'ks', 'Vodítka a kotvenie', ['príchytka', l.guideTypeCar || 'T89']);

    addItem(`Šachtové dvere ${l.doorWidth}mm`, qtys['entrances'], 'ks', 'Dvere', ['dvere', 'šachtové', String(l.doorWidth)]);
    addItem(`Kabínové dvere ${l.doorWidth}mm`, l.isThroughCar?2:1, 'ks', 'Dvere', ['dvere', 'kabínové', String(l.doorWidth)]);

    addItem(`Pohon ${l.ratedLoad}kg`, 1, 'ks', 'Pohon', [l.driveType === 'traction' ? 'stroj' : 'hydraulika']);
    addItem(`Laná / Pásy`, qtys['rope'], 'm', 'Pohon', ['lano']);

    return items;
  };

  const calculateRsBOM = (c: ControlSystemLayout) => {
      const items: MaterialWizardData['items'] = [];
      const addItem = (desc: string, qty: number, unit: string, cat: string, keys: string[]) => {
          const product = findSmartItem(keys, cat);
          items.push({
              category: cat, description: product ? product.name : desc, quantity: Number(qty.toFixed(2)), 
              unit, productId: product?.id, price: product?.price || 0, isAuto: true
          });
      };
      addItem(`Rozvádzač ${c.motorPower}kW`, 1, 'ks', 'Rozvádzač', ['rozvádzač']);
      if (c.driveType !== 'hydraulic') addItem(`Frekvenčný menič`, 1, 'ks', 'Menič a filter', ['menič']);
      if (!c.reuseLOP) addItem(`Privolávač`, c.numberOfStops, 'ks', 'Displeje a privolávače', ['privolávač']);
      return items;
  };

  const handleResetToDefaults = () => {
      setBomItems(mode === 'control_system' ? calculateRsBOM(controlLayout!) : calculateLiftBOM(layout));
  };

  const handleInsert = () => {
      onInsert({ items: bomItems, includeTransport, includePackaging, includeAssembly, transportPrice, packagingPrice, categoryOrder: tabs.map(t => t.id) });
      onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">
        <div className={`p-4 border-b flex justify-between items-center rounded-t-xl ${mode === 'control_system' ? 'bg-green-50 border-green-200' : 'bg-orange-50 border-orange-200'}`}>
          <div className="flex items-center gap-2">
            {mode === 'control_system' ? <Cpu className="text-green-600"/> : <Calculator className="text-orange-500" />}
            <h2 className="text-xl font-bold text-gray-800">{mode === 'control_system' ? 'Sprievodca RS' : 'Inteligentný Sprievodca LIFT (v4.3.40)'}</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
        </div>

        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-3 py-2 transition cursor-pointer ${activeTab===tab.id ? 'bg-white border-gray-300' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`} onClick={() => setActiveTab(tab.id)}>
                     <span className={`text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? (mode==='control_system'?'text-green-700':'text-orange-700') : 'text-gray-500'}`}>{tab.label}</span>
                 </div>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-white">
            <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                        <tr>
                            <th className="p-3 text-left w-1/3">Položka (Zameranie)</th>
                            <th className="p-3 text-left w-1/3">Match s Katalógom</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {bomItems.map((item, idx) => item.category === activeTab && (
                            <tr key={idx} className="hover:bg-gray-50">
                                <td className="p-3 font-bold text-gray-700">{item.description}</td>
                                <td className="p-3">
                                    <select 
                                        value={item.productId || ''} 
                                        onChange={e => {
                                            const p = products.find(prod => prod.id === e.target.value);
                                            if(p) {
                                                const updated = [...bomItems];
                                                updated[idx] = { ...updated[idx], productId: p.id, price: p.price, description: p.name, unit: p.unit };
                                                setBomItems(updated);
                                            }
                                        }} 
                                        className={`w-full p-2 border rounded text-xs font-bold ${item.productId ? 'bg-green-50 border-green-200 text-green-700' : 'bg-white'}`}
                                    >
                                        <option value="">-- Manuálny výber --</option>
                                        {products.filter(p => p.category === activeTab).map(p => <option key={p.id} value={p.id}>{p.name} ({p.price}€)</option>)}
                                    </select>
                                </td>
                                <td className="p-3 text-right font-bold text-blue-600">{item.quantity}</td>
                                <td className="p-3 text-right font-mono">{item.price ? item.price.toFixed(2) : '-'} €</td>
                                <td className="p-3 text-center"><button onClick={() => setBomItems(bomItems.filter((_,i)=>i!==idx))} className="text-gray-400 hover:text-red-500"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            <button onClick={() => setBomItems([...bomItems, { category: activeTab, description: 'Nová položka', quantity: 1, unit: 'ks', price: 0, isAuto: false }])} className="w-full py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:text-blue-600 transition flex justify-center items-center gap-2 font-medium"><Plus size={18} /> Pridať položku manuálne</button>
        </div>

        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                 <label className="flex items-center gap-2 p-3 bg-white border rounded"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)}/> <strong>Montáž</strong></label>
                 <div className="flex items-center gap-2 p-3 bg-white border rounded"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)}/> <strong>Doprava</strong><input type="number" value={transportPrice} onChange={e => setTransportPrice(+e.target.value)} className="w-16 border rounded text-right px-1" disabled={!includeTransport}/>€</div>
                 <div className="flex items-center gap-2 p-3 bg-white border rounded"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)}/> <strong>Balné</strong><input type="number" value={packagingPrice} onChange={e => setPackagingPrice(+e.target.value)} className="w-16 border rounded text-right px-1" disabled={!includePackaging}/>€</div>
            </div>
            <div className="flex justify-between items-center">
                <button onClick={handleResetToDefaults} className="text-xs text-orange-600 font-bold flex items-center gap-2 px-3 py-1 bg-orange-50 rounded border border-orange-200"><RotateCcw size={14}/> Resetovať výpočet</button>
                <div className="flex gap-2"><button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium transition">Zrušiť</button><button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded font-bold flex items-center gap-2 transition shadow-lg"><Check size={18} /> Vložiť do ponuky</button></div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass, ProductComponent } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ChevronDown, AlertTriangle, Box, Download, Package, ListPlus, Calculator, RotateCcw, Factory, Truck, Tag, Copy
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try { return crypto.randomUUID(); } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editorProduct, setEditorProduct] = useState<Partial<Product>>({});
  const [newCategoryName, setNewCategoryName] = useState('');

  const handleDuplicateCategory = (sourceCat: string) => {
      const targetCat = prompt(`Názov novej kategórie, kam sa skopírujú produkty z "${sourceCat}":`, `${sourceCat} - Kópia`);
      if (!targetCat) return;
      if (!customCategories.includes(targetCat)) onAddCategory(targetCat);
      const toCopy = products.filter(p => p.category === sourceCat);
      toCopy.forEach(p => onAddProduct({ ...p, id: generateId(), category: targetCat }));
      alert(`Hotovo! Skopírovaných ${toCopy.length} produktov do "${targetCat}".`);
  };

  const saveProduct = () => {
      if (!editorProduct.name) return;
      if (products.find(p => p.id === editorProduct.id)) onUpdateProduct(editorProduct as Product);
      else onAddProduct(editorProduct as Product);
      setIsEditorOpen(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-2">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[98vw] h-[95vh] flex flex-col">
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <h2 className="text-xl font-bold flex items-center gap-2"><Settings className="text-purple-600" /> Správca Katalógu</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
        </div>

        <div className="flex border-b">
            {['products', 'categories', 'classes'].map(t => (
                <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 py-3 font-bold text-sm border-b-2 capitalize transition ${activeTab===t ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}>{t==='products'?'Produkty':t==='categories'?'Kategórie':'Triedy'}</button>
            ))}
        </div>

        <div className="flex-1 overflow-hidden flex flex-col p-4 bg-gray-50">
            {activeTab === 'products' && (
                <div className="flex-1 flex flex-col bg-white rounded-lg shadow border overflow-hidden">
                    <div className="p-4 border-b flex gap-4">
                        <select value={activeCategory} onChange={e => setActiveCategory(e.target.value)} className="border rounded p-2 text-sm font-bold w-64 bg-gray-50">
                            {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Hľadať produkt v katalógu..." className="border rounded p-2 text-sm flex-1 outline-none focus:ring-2 focus:ring-purple-500" />
                        <button onClick={() => { setEditorProduct({id: generateId(), category: activeCategory, name:'', price:0, unit:'ks'}); setIsEditorOpen(true); }} className="bg-purple-600 text-white px-4 py-2 rounded font-bold hover:bg-purple-700 transition shadow-sm">+ Pridať Produkt</button>
                    </div>
                    <div className="flex-1 overflow-y-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-50 sticky top-0 shadow-sm"><tr><th className="p-3">Názov Produktu</th><th className="p-3">Podkategória</th><th className="p-3 text-right">Cena (€)</th><th className="p-3 text-center">Akcie</th></tr></thead>
                            <tbody className="divide-y divide-gray-100">
                                {products.filter(p => p.category === activeCategory && p.name.toLowerCase().includes(searchTerm.toLowerCase())).map(p => (
                                    <tr key={p.id} className="hover:bg-purple-50 transition-colors">
                                        <td className="p-3 font-bold text-gray-800">{p.name}</td>
                                        <td className="p-3"><span className="text-xs bg-gray-100 px-2 py-1 rounded border">{p.subcategory || '-'}</span></td>
                                        <td className="p-3 text-right font-mono font-bold text-blue-600">{p.price.toFixed(2)} €</td>
                                        <td className="p-3 text-center flex gap-1 justify-center">
                                            <button onClick={() => { setEditorProduct(p); setIsEditorOpen(true); }} className="p-2 text-blue-600 hover:bg-blue-100 rounded transition"><Edit size={16}/></button>
                                            <button onClick={() => onDeleteProduct(p.id)} className="p-2 text-red-500 hover:bg-red-100 rounded transition"><Trash2 size={16}/></button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {activeTab === 'categories' && (
                <div className="flex-1 overflow-y-auto max-w-3xl mx-auto w-full">
                    <div className="bg-white p-6 rounded-xl shadow-sm border mb-6 flex gap-2">
                        <input value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} placeholder="Názov novej kategórie..." className="flex-1 border rounded p-3 outline-none focus:ring-2 focus:ring-purple-500" />
                        <button onClick={() => { if(newCategoryName) { onAddCategory(newCategoryName); setNewCategoryName(''); } }} className="bg-purple-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-purple-700 transition">Pridať</button>
                    </div>
                    <div className="bg-white rounded-xl shadow-sm border divide-y overflow-hidden">
                        <div className="p-3 bg-gray-100 text-[10px] font-bold text-gray-500 uppercase tracking-widest">Spravovať kategórie katalógu</div>
                        {customCategories.map(c => (
                            <div key={c} className="p-4 flex justify-between items-center group hover:bg-gray-50 transition-colors">
                                <div className="flex items-center gap-3">
                                    <Layers className="text-gray-400" size={18}/>
                                    <span className="font-bold text-gray-800">{c}</span>
                                    <span className="text-xs text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">{products.filter(p=>p.category===c).length} položiek</span>
