          customCategories={availableCategories} onAddCategory={(c) => setAvailableCategories([...availableCategories, c])} onDeleteCategory={(c) => setAvailableCategories(availableCategories.filter(cat => cat !== c))} 
          onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])} 
          onUpdateCabinClass={(cc) => setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c))} onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))} 
      />

      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const year = new Date().getFullYear().toString().slice(-2);
          const seq = t === 'control_system' ? (settings.nextRsSequence || 1) : (settings.nextCpSequence || 1);
          const prefix = t === 'control_system' ? 'RS' : 'CP';
          const num = `${prefix}_SK_${seq.toString().padStart(3, '0')}_${year}_BA`;

          if(t === 'control_system') setSettings({...settings, nextRsSequence: seq + 1});
          else setSettings({...settings, nextCpSequence: seq + 1});

          const cats = t === 'lift' ? DEFAULT_CATEGORIES_LIST : CONTROL_SYSTEM_CATEGORIES;
          setData({ 
              id: generateId(), number: num, type: 'quote', quoteMode: t, 
              title: t==='lift'?'Cenová Ponuka - Výťah':'Cenová Ponuka - RS', 
              date: new Date().toISOString().split('T')[0], 
              validUntil: new Date(Date.now() + 60*24*60*60*1000).toISOString().split('T')[0],
              supplier: data.supplier, client: { name: '', details: '' }, 
              layout: { ...DEFAULT_LAYOUT }, controlLayout: { ...DEFAULT_CONTROL_LAYOUT },
              categories: cats.map(n => ({ id: generateId(), type: 'items', name: n, items: [], isExpanded: true, section: 'lift' })), 
              terms: TERMS_FULL, currency: '€', globalMargin: 15, shaftMargin: 20, vatRate: 23, hideItemPrices: true, showTechSpecs: true 
          });
      }} />

      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details}})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, CabinClass, ControlSystemLayout } from '../types';
import { X, Calculator, Check, AlertTriangle, RotateCcw, Plus, Cpu, ArrowLeft, ArrowRight, Trash2, Search, Sparkles } from 'lucide-react';

const RS_CATEGORIES = ['Rozvádzač', 'Menič a filter', 'Displeje a privolávače', 'Snímanie polohy', 'Kabeláž', 'Atypické riešenia'];

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  controlLayout?: ControlSystemLayout; 
  mode: 'lift' | 'control_system';
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
  initialState?: MaterialWizardData; 
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, controlLayout, mode, onInsert, products, customCategories, initialState, cabinClasses
}) => {
  const [tabs, setTabs] = useState<{id: string, label: string}[]>([]);
  const [activeTab, setActiveTab] = useState('');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);
  const [includeTransport, setIncludeTransport] = useState(true);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(true);
  const [transportPrice, setTransportPrice] = useState(250);
  const [packagingPrice, setPackagingPrice] = useState(50);

  useEffect(() => {
      if (isOpen) {
          let generatedTabs = [];
          if (mode === 'control_system') {
              generatedTabs = RS_CATEGORIES.map(c => ({ id: c, label: c }));
          } else {
              generatedTabs = customCategories
                  .filter(c => !['Montáž', 'Doprava', 'Balné', 'Ostatné'].includes(c))
                  .map(c => ({ id: c, label: c }));
          }
          setTabs(generatedTabs);
          if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);

          if (initialState) {
              setBomItems(initialState.items);
              setIncludeTransport(initialState.includeTransport);
              setIncludePackaging(initialState.includePackaging);
              setIncludeAssembly(initialState.includeAssembly);
              setTransportPrice(initialState.transportPrice || 250);
              setPackagingPrice(initialState.packagingPrice || 50);
          } else {
              handleResetToDefaults();
          }
      }
  }, [isOpen, mode]);

  const findCatalogProduct = (keys: string[], cat: string) => {
      const lowerKeys = keys.map(k => k.toLowerCase());
      return products.find(p => p.category === cat && lowerKeys.every(k => p.name.toLowerCase().includes(k)));
  };

  // --- LIFT CALCULATIONS (V4.3.40 INTEL) ---
  const calculateLiftBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const h = (l.travelHeight + l.headroomHeight + l.pitDepth) || 15000;
    const railLen = l.guideRailLength || 5000;

    const addItem = (cat: string, desc: string, qty: number, unit: string, searchKeys: string[]) => {
        if (qty <= 0) return;
        const catalogMatch = findCatalogProduct(searchKeys, cat);
        items.push({
            category: cat,
            description: catalogMatch ? catalogMatch.name : desc,
            quantity: Number(qty.toFixed(2)),
            unit: catalogMatch ? catalogMatch.unit : unit,
            productId: catalogMatch?.id,
            price: catalogMatch?.price || 0
        });
    };

    // 1. Vodítka a kotvenie
    const barsCount = Math.ceil(h / railLen);
    addItem('Vodítka a kotvenie', `Vodidlá Kabína ${l.guideTypeCar}`, barsCount * 2, 'ks', [l.guideTypeCar || 'T89']);
    addItem('Vodítka a kotvenie', `Vodidlá CWT ${l.guideTypeCwt}`, barsCount * 2, 'ks', [l.guideTypeCwt || 'T50']);
    addItem('Vodítka a kotvenie', `Spojky vodidiel Kabína`, Math.max(0, barsCount - 1) * 2, 'ks', ['spojka', l.guideTypeCar || 'T89']);
    addItem('Vodítka a kotvenie', `Spojky vodidiel CWT`, Math.max(0, barsCount - 1) * 2, 'ks', ['spojka', l.guideTypeCwt || 'T50']);

    const bracketRows = 1 + Math.ceil((h - 500) / 2500) + 1; // Spodná + stredné každé 2.5m + horná
    addItem('Vodítka a kotvenie', `Konzoly vodidiel Kabína`, bracketRows * 2, 'ks', ['konzola', 'kabín']);
    addItem('Vodítka a kotvenie', `Konzoly vodidiel CWT`, bracketRows * 2, 'ks', ['konzola', 'cwt']);
    addItem('Vodítka a kotvenie', `Príchytky vodidiel`, (bracketRows * 4) * 2, 'ks', ['príchytka']);

    // 2. Dvere
    const entrances = l.numberOfEntrances || l.numberOfStops || 5;
    addItem('Dvere', `Šachtové dvere PL ${l.doorWidth}`, entrances, 'ks', ['šachtové', 'dvere', String(l.doorWidth)]);
    addItem('Dvere', `Kabínové dvere PL ${l.doorWidth}`, l.isThroughCar ? 2 : 1, 'ks', ['kabínové', 'dvere', String(l.doorWidth)]);

    // 3. Pohon
    const suspension = l.suspensionType === '1:1' ? 1 : 2;
    const ropeCount = l.ratedLoad <= 630 ? 4 : 6;
    const ropeTotalLen = Math.ceil(((h * suspension * ropeCount) / 1000) + 15);
    addItem('Pohon', `Trakčný stroj ${l.ratedLoad}kg`, 1, 'ks', ['stroj', String(l.ratedLoad)]);
    addItem('Pohon', `Nosné prostriedky (Laná/Pásy)`, ropeTotalLen, 'm', [l.tractionMedium === 'ctp' ? 'plast' : 'lano']);

    return items;
  };

  const calculateRsBOM = (c: ControlSystemLayout) => {
      const items: MaterialWizardData['items'] = [];
      const catalogCabinet = findCatalogProduct(['rozvádzač'], 'Rozvádzač');
      items.push({ category: 'Rozvádzač', description: catalogCabinet ? catalogCabinet.name : `Riadiaci rozvádzač ${c.motorPower}kW`, quantity: 1, unit: 'ks', productId: catalogCabinet?.id, price: catalogCabinet?.price || 0 });
      return items;
  };

  const handleResetToDefaults = () => {
      setBomItems(mode === 'control_system' ? calculateRsBOM(controlLayout!) : calculateLiftBOM(layout));
  };

  const handleInsert = () => {
      onInsert({ items: bomItems, includeTransport, includePackaging, includeAssembly, transportPrice, packagingPrice, categoryOrder: tabs.map(t => t.id) });
      onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-6xl max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">
        <div className={`p-6 border-b flex justify-between items-center rounded-t-2xl ${mode === 'control_system' ? 'bg-green-50' : 'bg-orange-50'}`}>
          <div className="flex items-center gap-3">
            {mode === 'control_system' ? <Cpu className="text-green-600" size={28}/> : <Calculator className="text-orange-500" size={28} />}
            <div>
                <h2 className="text-2xl font-black uppercase tracking-tight text-gray-800">{mode === 'control_system' ? 'RS Konfigurátor' : 'Lift Sprievodca (Inteligentný v4.3.40)'}</h2>
                <div className="text-xs font-bold text-gray-500 flex items-center gap-2 uppercase tracking-widest mt-1">
                    <Sparkles size={12} className="text-blue-500"/> Automatický výpočet na základe technických parametrov
                </div>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500 transition-colors"><X size={24}/></button>
        </div>

        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab) => (
                 <button key={tab.id} className={`flex items-center gap-2 rounded-xl px-5 py-3 transition-all font-black text-xs uppercase tracking-widest ${activeTab===tab.id ? 'bg-white text-blue-700 shadow-md scale-105' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-100'}`} onClick={() => setActiveTab(tab.id)}>
                     {activeTab === tab.id && <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse"/>}
                     {tab.label}
                 </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-8 bg-white">
            <div className="border rounded-2xl overflow-hidden shadow-sm mb-6">
                <table className="w-full text-sm">
                    <thead className="bg-gray-50 text-gray-400 font-black text-[10px] uppercase tracking-widest border-b">
                        <tr>
                            <th className="p-4 text-left w-1/3">Položka (Zameranie)</th>
                            <th className="p-4 text-left w-1/3">Produkt z Katalógu (Auto-Match)</th>
                            <th className="p-4 text-right w-24">Mn.</th>
                            <th className="p-4 text-right w-24">Jedn. Cena</th>
                            <th className="p-4 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {bomItems.map((item, idx) => item.category === activeTab && (
                            <tr key={idx} className="hover:bg-blue-50/50 transition-colors">
                                <td className="p-4 font-bold text-gray-700">{item.description}</td>
                                <td className="p-4">
                                    <select 
                                        value={item.productId || ''} 
                                        onChange={e => {
                                            const p = products.find(prod => prod.id === e.target.value);
                                            if(p) {
                                                const updated = [...bomItems];
                                                updated[idx] = { ...updated[idx], productId: p.id, price: p.price, description: p.name, unit: p.unit };
                                                setBomItems(updated);
                                            }
                                        }} 
                                        className={`w-full p-2.5 border rounded-lg text-xs font-bold transition-all ${item.productId ? 'bg-green-50 border-green-300 text-green-700' : 'bg-white border-gray-200'}`}
                                    >
                                        <option value="">-- Vyberte manuálne --</option>
                                        {products.filter(p => p.category === activeTab).map(p => <option key={p.id} value={p.id}>{p.name} ({p.price.toFixed(2)}€)</option>)}
                                    </select>
                                </td>
                                <td className="p-4 text-right font-black text-blue-600 text-lg">{item.quantity} <span className="text-[10px] font-bold text-gray-400 uppercase">{item.unit}</span></td>
                                <td className="p-4 text-right font-mono font-bold text-gray-900">{item.price ? item.price.toFixed(2) : '0.00'} €</td>
                                <td className="p-4 text-center"><button onClick={() => setBomItems(bomItems.filter((_,i)=>i!==idx))} className="text-gray-300 hover:text-red-500 transition-colors"><Trash2 size={18}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            <button onClick={() => setBomItems([...bomItems, { category: activeTab, description: 'Nová položka', quantity: 1, unit: 'ks', price: 0 }])} className="w-full py-4 border-2 border-dashed border-gray-200 rounded-2xl text-gray-400 hover:text-blue-600 hover:border-blue-300 transition-all flex justify-center items-center gap-2 font-bold uppercase text-xs tracking-widest"><Plus size={20} /> Pridať položku manuálne</button>
        </div>

        <div className="p-6 border-t bg-gray-50 rounded-b-2xl flex flex-col gap-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                 <label className="flex items-center gap-3 p-4 bg-white border border-gray-200 rounded-xl hover:bg-gray-100 transition shadow-sm cursor-pointer"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="w-5 h-5 rounded text-blue-600"/><div className="font-bold text-sm uppercase tracking-wide">Montáž technológie</div></label>
                 <div className="flex items-center gap-3 p-4 bg-white border border-gray-200 rounded-xl shadow-sm"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="w-5 h-5 rounded text-blue-600"/><div className="font-bold text-sm uppercase tracking-wide flex-1 text-left">Doprava</div><input type="number" value={transportPrice} onChange={e => setTransportPrice(+e.target.value)} className="w-20 border rounded-lg text-right font-bold py-1 px-2 focus:ring-2 focus:ring-blue-500 outline-none" disabled={!includeTransport}/>€</div>
                 <div className="flex items-center gap-3 p-4 bg-white border border-gray-200 rounded-xl shadow-sm"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="w-5 h-5 rounded text-blue-600"/><div className="font-bold text-sm uppercase tracking-wide flex-1 text-left">Balné</div><input type="number" value={packagingPrice} onChange={e => setPackagingPrice(+e.target.value)} className="w-20 border rounded-lg text-right font-bold py-1 px-2 focus:ring-2 focus:ring-blue-500 outline-none" disabled={!includePackaging}/>€</div>
            </div>
            <div className="flex justify-between items-center">
                <button onClick={handleResetToDefaults} className="text-xs text-orange-600 font-black uppercase tracking-widest flex items-center gap-2 px-5 py-2 hover:bg-orange-100 rounded-lg transition-colors"><RotateCcw size={16}/> Prepočítať všetko nanovo</button>
                <div className="flex gap-3">
                    <button onClick={onClose} className="px-6 py-3 text-gray-500 hover:bg-gray-200 rounded-xl font-bold uppercase text-xs transition">Zrušiť</button>
                    <button onClick={handleInsert} className="px-10 py-3 bg-blue-600 text-white hover:bg-blue-700 rounded-xl font-black uppercase text-xs tracking-widest flex items-center gap-3 transition shadow-xl hover:scale-105 active:scale-95"><Check size={20} /> Vložiť do ponuky</button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass, ProductComponent } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ChevronDown, AlertTriangle, Box, Download, Package, ListPlus, Calculator, RotateCcw, Factory, Truck, Tag, Copy
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try { return crypto.randomUUID(); } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>('Dvere'); 
  const [searchTerm, setSearchTerm] = useState('');
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editorProduct, setEditorProduct] = useState<Partial<Product>>({});
  const [newCategoryName, setNewCategoryName] = useState('');

  const handleDuplicateCategory = (sourceCat: string) => {
      const targetCat = prompt(`Názov novej cieľovej kategórie (Produkty z kategórie "${sourceCat}" budú skopírované):`, `${sourceCat} (RS)`);
      if (!targetCat || targetCat.trim() === '') return;

      if (!customCategories.includes(targetCat)) {
          onAddCategory(targetCat);
      }

      const toCopy = products.filter(p => p.category === sourceCat);
      toCopy.forEach(p => {
          onAddProduct({ ...p, id: generateId(), category: targetCat });
      });

      alert(`Úspešne skopírovaných ${toCopy.length} produktov do kategórie "${targetCat}".`);
  };

  const saveProduct = () => {
      if (!editorProduct.name) return;
      if (products.find(p => p.id === editorProduct.id)) onUpdateProduct(editorProduct as Product);
      else onAddProduct(editorProduct as Product);
      setIsEditorOpen(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-[98vw] h-[95vh] flex flex-col animate-in fade-in zoom-in-95">
        <div className="p-6 border-b flex justify-between items-center bg-gray-50 rounded-t-3xl">
          <h2 className="text-2xl font-black uppercase tracking-tighter flex items-center gap-3"><Settings className="text-purple-600" size={28} /> Master Katalóg & Dáta</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500 transition-colors"><X size={24}/></button>
        </div>

        <div className="flex border-b">
            {['products', 'categories', 'classes'].map(t => (
                <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 py-4 font-black text-xs uppercase tracking-widest transition-all ${activeTab===t ? 'border-b-4 border-purple-600 text-purple-700 bg-purple-50' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-100'}`}>{t==='products'?'Skladové Produkty':t==='categories'?'Správa Kategórií':'Triedy Kabín'}</button>
            ))}
        </div>

        <div className="flex-1 overflow-hidden flex flex-col p-6 bg-gray-50">
            {activeTab === 'products' && (
                <div className="flex-1 flex flex-col bg-white rounded-2xl shadow-xl border border-gray-200 overflow-hidden">
                    <div className="p-4 border-b flex gap-4 items-center bg-white">
                        <select value={activeCategory} onChange={e => setActiveCategory(e.target.value)} className="border-2 border-gray-100 rounded-xl p-3 text-sm font-black uppercase tracking-widest w-72 bg-gray-50 focus:ring-2 focus:ring-purple-500 outline-none">
                            {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={20}/>
                            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Hľadať v katalógu..." className="w-full border-2 border-gray-100 rounded-xl p-3 pl-10 text-sm outline-none focus:ring-2 focus:ring-purple-500" />
                        </div>
                        <button onClick={() => { setEditorProduct({id: generateId(), category: activeCategory, name:'', price:0, unit:'ks'}); setIsEditorOpen(true); }} className="bg-purple-600 text-white px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-purple-700 transition-all shadow-lg hover:scale-105">+ Pridať</button>
                    </div>
                    <div className="flex-1 overflow-y-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-50 sticky top-0 z-10 border-b"><tr><th className="p-4 font-black uppercase text-[10px] text-gray-400">Názov Produktu</th><th className="p-4 font-black uppercase text-[10px] text-gray-400 text-right">Cena</th><th className="p-4 font-black uppercase text-[10px] text-gray-400 text-center w-32">Akcie</th></tr></thead>
                            <tbody className="divide-y divide-gray-50">
                                {products.filter(p => p.category === activeCategory && p.name.toLowerCase().includes(searchTerm.toLowerCase())).map(p => (
                                    <tr key={p.id} className="hover:bg-purple-50 transition-colors">
                                        <td className="p-4 font-bold text-gray-800">{p.name} <span className="text-[10px] bg-gray-100 px-1.5 py-0.5 rounded text-gray-500 font-normal uppercase ml-2">{p.unit}</span></td>
                                        <td className="p-4 text-right font-black text-lg text-blue-600 font-mono">{p.price.toFixed(2)} €</td>
                                        <td className="p-4 text-center">
                                            <div className="flex gap-2 justify-center">
                                                <button onClick={() => { setEditorProduct(p); setIsEditorOpen(true); }} className="p-2 text-blue-500 hover:bg-blue-100 rounded-lg transition-colors"><Edit size={18}/></button>
                                                <button onClick={() => onDeleteProduct(p.id)} className="p-2 text-red-400 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={18}/></button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {activeTab === 'categories' && (
                <div className="flex-1 overflow-y-auto max-w-4xl mx-auto w-full">
