                    <div className="text-2xl text-slate-400 font-bold mt-2 uppercase tracking-[0.2em]">{data.number}</div>
                    <div className="mt-6"><input value={data.clientReference} onChange={e => setData({...data, clientReference: e.target.value})} className="text-xl font-black text-blue-700 w-full border-none p-0 uppercase placeholder-slate-200" placeholder="ZADAJTE REFERENCIU / NÁZOV PROJEKTU"/></div>
                </div>
                <div className="text-right">
                    <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Dátum vystavenia</div>
                    <div className="font-black text-xl">{new Date(data.date).toLocaleDateString('sk-SK')}</div>
                    <div className="text-[10px] font-black text-red-500 uppercase tracking-widest mt-4">Platnosť ponuky (60 dní)</div>
                    <div className="font-black text-red-600 text-xl">{new Date(data.validUntil).toLocaleDateString('sk-SK')}</div>
                    <button onClick={() => window.print()} className="mt-6 px-6 py-2.5 bg-slate-900 text-white rounded-xl font-black no-print flex items-center gap-2 ml-auto shadow-lg hover:bg-slate-800 transition-all active:scale-95"><Printer size={18}/> Tlačiť PDF</button>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-12 mb-10 pb-10 border-b border-slate-100">
                <div className="relative group"><div className="text-[10px] font-black text-slate-400 uppercase mb-3 flex items-center gap-2">DODÁVATEĽ <button onClick={() => setIsSupplierModalOpen(true)} className="no-print text-blue-500 p-1 hover:bg-blue-50 rounded transition"><Edit size={10}/></button></div><div className="font-black text-xl uppercase mb-1 tracking-tight">{data.supplier.name}</div><div className="text-xs text-slate-500 leading-relaxed whitespace-pre-wrap">{data.supplier.details}</div></div>
                <div className="relative group border-l-2 border-slate-50 pl-10"><div className="text-[10px] font-black text-slate-400 uppercase mb-3 flex items-center gap-2">KLIENT / ODBERATEĽ <button onClick={() => setIsClientModalOpen(true)} className="no-print text-blue-500 p-1 hover:bg-blue-50 rounded transition"><Edit size={10}/></button></div><div className="font-black text-xl uppercase mb-1 tracking-tight">{data.client.name || 'ZADAJTE KLIENTA'}</div><div className="text-xs text-slate-500 leading-relaxed whitespace-pre-wrap">{data.client.details}</div></div>
            </div>

            {data.showTechSpecs && (
                <TechSpecTable data={data.layout!} controlData={data.controlLayout} mode={data.quoteMode || 'lift'} isVisible={true} onToggleVisibility={() => {}} embedded={true} />
            )}

            <div className="space-y-8 mt-12">
                {data.categories.map(cat => (
                    <CategoryTable 
                        key={cat.id} category={cat} currency={data.currency} 
                        globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData({...data, categories: data.categories.map(c => c.id === id ? {...c, [f]: v} : c)})}
                        onDeleteCategory={(id) => setData({...data, categories: data.categories.filter(c => c.id !== id)})}
                        onAddItem={(cid, sur) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: [...c.items, { id: generateId(), description: sur?'Príplatok':'Nová položka', unit:'ks', quantity:1, unitPrice:0, purchasePrice:0, vatRate:23, isSurcharge:sur }]} : c)})}
                        onUpdateItem={(cid, iid, f, v) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)})}
                        onDeleteItem={(cid, iid) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)})}
                        onAiSuggest={() => {}} onOpenCatalog={() => {}} isAiLoading={false} mode={data.quoteMode}
                    />
                ))}
            </div>

            <div className="mt-16 pt-8 border-t-8 border-slate-900 flex justify-end">
                <div className="w-1/2">
                    <table className="w-full">
                        <tbody>
                            <tr><td className="py-2 text-slate-400 font-black uppercase text-xs tracking-widest">Cena technológie bez DPH</td><td className="py-2 text-right font-black text-xl">{totals.sale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                            <tr className="bg-slate-900 text-white"><td className="p-4 text-lg font-black uppercase tracking-tight">CELKOM S DPH</td><td className="p-4 text-right text-4xl font-black tracking-tighter">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-16 break-inside-avoid">
                 <div className="flex justify-between items-center mb-4 no-print">
                    <h4 className="font-black uppercase text-slate-400 text-xs tracking-widest">Obchodné podmienky</h4>
                    <div className="flex gap-2">
                        <button onClick={() => setData({...data, terms: TERMS_FULL})} className="px-4 py-1.5 bg-blue-50 text-blue-700 rounded-full text-[10px] font-black border border-blue-200 hover:bg-blue-100 flex items-center gap-2 transition-all"><FileText size={14}/> Vložiť plnú verziu (Montáž)</button>
                        <button onClick={() => setData({...data, terms: TERMS_SUPPLY_ONLY})} className="px-4 py-1.5 bg-amber-50 text-amber-700 rounded-full text-[10px] font-black border border-amber-200 hover:bg-amber-100 flex items-center gap-2 transition-all"><FileMinus size={14}/> Vložiť len dodávku (Supply)</button>
                    </div>
                </div>
                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[200px] print:h-auto" stickyToolbar={false} />
            </div>
        </div>
      </div>

      {/* ENHANCED ARCHIVE VIEW v5.9.0 */}
      {showArchive && (
          <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white rounded-3xl shadow-2xl w-full max-w-6xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-300">
                  <div className="p-8 border-b flex justify-between items-center bg-slate-50 rounded-t-3xl">
                      <div>
                          <h2 className="text-3xl font-black uppercase tracking-tighter flex items-center gap-3 text-slate-800"><Archive className="text-blue-600" size={32}/> Archív dokladov</h2>
