                  </div>
                  <div className="p-6 border-b bg-white">
                      <div className="relative">
                          <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
                          <input type="text" placeholder="Hľadať podľa čísla, klienta alebo názvu projektu..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-16 pr-8 py-4 bg-slate-100 border-none rounded-2xl focus:ring-4 focus:ring-blue-100 outline-none text-xl font-bold transition-all" />
                      </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-6 bg-slate-50">
                      <div className="grid grid-cols-1 gap-4">
                        {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase()) || q.clientReference?.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => {
                            const qTotals = calculateTotals(q);
                            const isRs = q.quoteMode === 'control_system' || q.number.startsWith('RS');
                            return (
                                <div key={q.id} className="p-6 bg-white border-2 border-slate-100 rounded-2xl hover:border-blue-400 hover:shadow-xl transition-all flex justify-between items-center group relative overflow-hidden">
                                    {isRs && <div className="absolute top-0 right-0 w-24 h-24 -mr-8 -mt-8 bg-emerald-50 rounded-full group-hover:bg-emerald-100 transition-colors -z-0 opacity-50"/>}
                                    <div className="flex-1 z-10">
                                        <div className="flex items-center gap-3 mb-2">
                                            <span className={`text-[10px] font-black px-3 py-1 rounded-full text-white tracking-widest uppercase ${q.type === 'contract' ? 'bg-emerald-600' : q.type === 'order' ? 'bg-blue-600' : 'bg-amber-500'}`}>{q.type === 'quote' ? 'CP' : q.type.toUpperCase()}</span>
                                            <div className="font-black text-2xl tracking-tight text-slate-800">{q.number}</div>
                                            {isRs && <span className="bg-emerald-100 text-emerald-700 text-[10px] px-2 py-0.5 rounded font-black uppercase tracking-wider">MODERNIZÁCIA RS</span>}
                                        </div>
                                        <div className="text-md font-black text-blue-700 uppercase tracking-tight">{q.clientReference || 'BEZ REFERENCIE'}</div>
                                        <div className="text-sm font-bold text-slate-400 mt-1 flex items-center gap-2">
                                            <Users size={14}/> {q.client.name || 'Neznámy klient'} <span className="text-slate-200">|</span> <Activity size={14}/> {new Date(q.lastUpdated || q.date).toLocaleDateString('sk-SK')}
                                        </div>
                                    </div>
                                    <div className="text-right flex items-center gap-8 z-10">
                                        <div>
                                            <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Celková cena s DPH</div>
                                            <div className="font-black text-3xl tracking-tighter text-slate-900">{qTotals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} €</div>
                                        </div>
                                        <div className="flex gap-2">
                                            <button onClick={() => loadFromArchive(q)} className="px-6 py-3 bg-slate-900 text-white font-black rounded-xl text-sm shadow-xl hover:bg-slate-800 hover:scale-105 transition-all active:scale-95">OTVORIŤ</button>
                                            <button onClick={() => { if(confirm("Naozaj vymazať doklad z archívu?")) setSavedQuotes(savedQuotes.filter(sq=>sq.id!==q.id)); }} className="p-3 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={22}/></button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                        {savedQuotes.length === 0 && <div className="text-center py-20 text-slate-300 font-black uppercase tracking-[0.2em] text-2xl italic">Archív je prázdny</div>}
                      </div>
                  </div>
              </div>
          </div>
      )}

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} controlLayout={data.controlLayout} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories} cabinClasses={cabinClasses}
          initialState={data.wizardData}
      />

      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={(p) => setProducts([...products, p])} onUpdateProduct={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))} customCategories={availableCategories} onAddCategory={(c) => setAvailableCategories([...availableCategories, c])} onDeleteCategory={(c) => setAvailableCategories(availableCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])} onUpdateCabinClass={(cc) => setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c))} onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const year = new Date().getFullYear().toString().slice(-2);
          const seq = t === 'control_system' ? (settings.nextRsSequence || 1) : (settings.nextCpSequence || 1);
          const prefix = t === 'control_system' ? 'RS' : 'CP';
          const num = `${prefix}_SK_${seq.toString().padStart(3, '0')}_${year}_BA`;
          if(t === 'control_system') setSettings({...settings, nextRsSequence: seq + 1}); else setSettings({...settings, nextCpSequence: seq + 1});
          const cats = t === 'lift' ? DEFAULT_CATEGORIES_LIST : CONTROL_SYSTEM_CATEGORIES;
          setData({ id: generateId(), number: num, type: 'quote', quoteMode: t, title: t==='lift'?'Cenová Ponuka - Výťah':'Cenová Ponuka - Modernizácia RS', date: new Date().toISOString().split('T')[0], validUntil: new Date(Date.now() + 60*24*60*60*1000).toISOString().split('T')[0], supplier: data.supplier, client: { name: '', details: '' }, layout: { ...DEFAULT_LAYOUT }, controlLayout: { ...DEFAULT_CONTROL_LAYOUT }, categories: cats.map(n => ({ id: generateId(), type: 'items', name: n, items: [], isExpanded: true, section: 'lift' })), terms: TERMS_FULL, currency: '€', globalMargin: 15, shaftMargin: 20, vatRate: 23, hideItemPrices: true, showTechSpecs: true });
      }} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details}})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, CabinClass, ControlSystemLayout } from '../types';
import { X, Calculator, Check, AlertTriangle, RotateCcw, Plus, Cpu, ArrowLeft, ArrowRight, Trash2, Search, Sparkles } from 'lucide-react';

const RS_CATEGORIES = ['Rozvádzač', 'Menič a filter', 'Displeje a privolávače', 'Snímanie polohy', 'Kabeláž', 'Atypické riešenia'];

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  controlLayout?: ControlSystemLayout; 
  mode: 'lift' | 'control_system';
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
  initialState?: MaterialWizardData; 
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, controlLayout, mode, onInsert, products, customCategories, initialState, cabinClasses
}) => {
  const [tabs, setTabs] = useState<{id: string, label: string}[]>([]);
  const [activeTab, setActiveTab] = useState('');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);
  const [includeTransport, setIncludeTransport] = useState(true);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(true);
  const [transportPrice, setTransportPrice] = useState(250);
  const [packagingPrice, setPackagingPrice] = useState(50);

  useEffect(() => {
      if (isOpen) {
          let generatedTabs = [];
          if (mode === 'control_system') {
              generatedTabs = RS_CATEGORIES.map(c => ({ id: c, label: c }));
          } else {
              generatedTabs = customCategories
                  .filter(c => !['Montáž', 'Doprava', 'Balné', 'Ostatné'].includes(c))
                  .map(c => ({ id: c, label: c }));
          }
          setTabs(generatedTabs);
          if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);

          if (initialState) {
              setBomItems(initialState.items);
              setIncludeTransport(initialState.includeTransport);
              setIncludePackaging(initialState.includePackaging);
              setIncludeAssembly(initialState.includeAssembly);
              setTransportPrice(initialState.transportPrice || 250);
              setPackagingPrice(initialState.packagingPrice || 50);
          } else {
              handleResetToDefaults();
          }
      }
  }, [isOpen, mode]);

  const findCatalogProduct = (keys: string[], cat: string) => {
      const lowerKeys = keys.map(k => k.toLowerCase());
      return products.find(p => p.category === cat && lowerKeys.every(k => p.name.toLowerCase().includes(k)));
  };

  // --- LIFT CALCULATIONS ENGINE (V4.3.40) ---
  const calculateLiftBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const travel = l.travelHeight || 15000;
    const hq = l.headroomHeight || 3400;
    const hs = l.pitDepth || 1100;
    const totalHeightMm = travel + hq + hs;
    const railLenMm = l.guideRailLength || 5000;

    const addItem = (cat: string, desc: string, qty: number, unit: string, searchKeys: string[]) => {
        if (qty <= 0) return;
        const catalogMatch = findCatalogProduct(searchKeys, cat);
        items.push({
            category: cat,
            description: catalogMatch ? catalogMatch.name : desc,
            quantity: Number(qty.toFixed(2)),
            unit: catalogMatch ? catalogMatch.unit : unit,
            productId: catalogMatch?.id,
            price: catalogMatch?.price || 0
        });
    };

    // 1. Vodítka a kotvenie (INTELLIGENT CALC)
    const barsCount = Math.ceil(totalHeightMm / railLenMm);
    const barsTotalCar = barsCount * 2;
    const barsTotalCwt = barsCount * 2;

    // Spojky = (počet tyčí - 1) na každú líniu
    const fishplatesCar = Math.max(0, barsCount - 1) * 2;
    const fishplatesCwt = Math.max(0, barsCount - 1) * 2;

    // Konzoly = spodná + horná + jedna každých 2500 mm
    const bracketRows = 1 + Math.ceil((totalHeightMm - 500) / 2500) + 1;
    const bracketsCar = bracketRows * 2;
    const bracketsCwt = bracketRows * 2;

    // Príchytky = 2 na konzolu
    const clipsTotal = (bracketsCar + bracketsCwt) * 2;

    addItem('Vodítka a kotvenie', `Vodidlá Kabína ${l.guideTypeCar}`, barsTotalCar, 'ks', [l.guideTypeCar || 'T89']);
    addItem('Vodítka a kotvenie', `Vodidlá CWT ${l.guideTypeCwt}`, barsTotalCwt, 'ks', [l.guideTypeCwt || 'T50']);
    addItem('Vodítka a kotvenie', `Spojky vodidiel Kabína`, fishplatesCar, 'ks', ['spojka', l.guideTypeCar || 'T89']);
    addItem('Vodítka a kotvenie', `Spojky vodidiel CWT`, fishplatesCwt, 'ks', ['spojka', l.guideTypeCwt || 'T50']);
    addItem('Vodítka a kotvenie', `Konzoly vodidiel Kabína`, bracketsCar, 'ks', ['konzola', 'kabín']);
    addItem('Vodítka a kotvenie', `Konzoly vodidiel CWT`, bracketsCwt, 'ks', ['konzola', 'cwt']);
    addItem('Vodítka a kotvenie', `Príchytky vodidiel (Set)`, clipsTotal, 'ks', ['príchytka']);

    // 2. Dvere (AUTO DETECTION)
    const entrances = l.numberOfEntrances || l.numberOfStops || 2;
    addItem('Dvere', `Šachtové dvere PL ${l.doorWidth}`, entrances, 'ks', ['šachtové', 'dvere', String(l.doorWidth)]);
    addItem('Dvere', `Kabínové dvere PL ${l.doorWidth}`, l.isThroughCar ? 2 : 1, 'ks', ['kabínové', 'dvere', String(l.doorWidth)]);

    // 3. Pohon & Laná
    const suspension = l.suspensionType === '1:1' ? 1 : (l.suspensionType === '2:1' ? 2 : 4);
    const ropeCount = l.ratedLoad <= 630 ? 4 : 6;
    // Dĺžka lán: (Zdvih + Hlava + Priehlbeň) * lanovanie * počet lán + rezerva
    const ropeTotalLen = Math.ceil(((totalHeightMm * suspension * ropeCount) / 1000) + 20);

    addItem('Pohon', `Trakčný stroj ${l.ratedLoad}kg`, 1, 'ks', ['stroj', String(l.ratedLoad)]);
    addItem('Pohon', `Nosné prostriedky (Laná/Pásy)`, ropeTotalLen, 'm', [l.tractionMedium === 'ctp' ? 'plast' : 'lano']);

    return items;
  };

  const calculateRsBOM = (c: ControlSystemLayout) => {
      const items: MaterialWizardData['items'] = [];
      const addItem = (cat: string, desc: string, qty: number, unit: string, keys: string[]) => {
          const match = findCatalogProduct(keys, cat);
          items.push({ category: cat, description: match ? match.name : desc, quantity: qty, unit: match ? match.unit : unit, productId: match?.id, price: match?.price || 0 });
      };
      addItem('Rozvádzač', `Riadiaci rozvádzač ${c.motorPower}kW`, 1, 'ks', ['rozvádzač']);
      if (c.driveType !== 'hydraulic') addItem('Menič a filter', 'Frekvenčný menič VVVF', 1, 'ks', ['menič']);
      if (!c.reuseLOP) addItem('Displeje a privolávače', 'Privolávač stanica', c.numberOfStops, 'ks', ['privolávač']);
      return items;
  };

  const handleResetToDefaults = () => {
      setBomItems(mode === 'control_system' ? calculateRsBOM(controlLayout!) : calculateLiftBOM(layout));
  };

  const handleInsert = () => {
      onInsert({ items: bomItems, includeTransport, includePackaging, includeAssembly, transportPrice, packagingPrice, categoryOrder: tabs.map(t => t.id) });
      onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-slate-950/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-6xl max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95 duration-300">
        <div className={`p-8 border-b flex justify-between items-center rounded-t-3xl ${mode === 'control_system' ? 'bg-emerald-50' : 'bg-amber-50'}`}>
          <div className="flex items-center gap-4">
            <div className={`p-3 rounded-2xl shadow-lg ${mode === 'control_system' ? 'bg-emerald-600 text-white' : 'bg-amber-500 text-white'}`}>
                {mode === 'control_system' ? <Cpu size={32}/> : <Calculator size={32} />}
            </div>
            <div>
                <h2 className="text-3xl font-black uppercase tracking-tight text-slate-800">{mode === 'control_system' ? 'RS Modernizácia' : 'Inteligentný Sprievodca (v4.3.40)'}</h2>
                <div className="text-xs font-black text-slate-400 flex items-center gap-2 uppercase tracking-widest mt-1">
                    <Sparkles size={14} className="text-blue-500 animate-pulse"/> Prediktívny výpočet materiálu podľa EN 81-20/50
                </div>
            </div>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-slate-200 rounded-full transition-colors"><X size={28}/></button>
        </div>

        <div className="flex border-b border-slate-100 overflow-x-auto bg-slate-50 p-2 gap-2">
            {tabs.map((tab) => (
                 <button key={tab.id} className={`flex items-center gap-2 rounded-2xl px-6 py-3 transition-all font-black text-[10px] uppercase tracking-widest ${activeTab===tab.id ? 'bg-white text-blue-700 shadow-xl scale-105 ring-1 ring-slate-200' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`} onClick={() => setActiveTab(tab.id)}>
                     {activeTab === tab.id && <div className="w-2.5 h-2.5 bg-blue-600 rounded-full animate-ping"/>}
                     {tab.label}
                 </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-8 bg-white">
            <div className="border-2 border-slate-100 rounded-3xl overflow-hidden shadow-sm mb-8">
