        <div className="bg-white shadow-xl print:shadow-none min-h-[297mm] p-12 print:p-0 border border-gray-300 rounded-sm">
            <div className="mb-10 border-b-2 border-gray-800 pb-6 flex justify-between items-start">
                 <div className="w-2/3">
                    <textarea value={data.title} onChange={e => setData({...data, title: e.target.value})} className="text-4xl font-bold w-full border-none bg-transparent uppercase p-0 leading-tight" rows={1}/>
                    <div className="text-xl text-gray-400 font-semibold mt-1 uppercase tracking-wider">{data.number}</div>
                    <div className="mt-4"><input value={data.clientReference} onChange={e => setData({...data, clientReference: e.target.value})} className="text-lg font-bold text-blue-600 w-full border-none p-0 uppercase" placeholder="REFERENCIA / NÁZOV PROJEKTU"/></div>
                </div>
                <div className="text-right">
                    <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Dátum vystavenia</div>
                    <div className="font-semibold text-lg">{new Date(data.date).toLocaleDateString('sk-SK')}</div>
                    <div className="text-[10px] font-bold text-red-500 uppercase tracking-widest mt-2">Platnosť ponuky (60 dní)</div>
                    <div className="font-semibold text-red-600 text-lg">{new Date(data.validUntil).toLocaleDateString('sk-SK')}</div>
                    <button onClick={() => window.print()} className="mt-4 px-4 py-2 bg-gray-800 text-white rounded font-bold no-print flex items-center gap-2 ml-auto shadow-sm"><Printer size={16}/> Tlačiť PDF</button>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-12 mb-10 pb-8 border-b border-gray-100">
                <div><div className="text-[10px] font-bold text-gray-400 uppercase mb-2">Dodávateľ <button onClick={() => setIsSupplierModalOpen(true)} className="no-print text-blue-500 ml-2 font-normal">Zmeniť</button></div><div className="font-bold text-lg uppercase">{data.supplier.name}</div><div className="text-xs text-gray-500 leading-relaxed whitespace-pre-wrap">{data.supplier.details}</div></div>
                <div><div className="text-[10px] font-bold text-gray-400 uppercase mb-2">Klient / Odberateľ <button onClick={() => setIsClientModalOpen(true)} className="no-print text-blue-500 ml-2 font-normal">Zmeniť</button></div><div className="font-bold text-lg uppercase">{data.client.name || 'ZADAJTE KLIENTA'}</div><div className="text-xs text-gray-500 leading-relaxed whitespace-pre-wrap">{data.client.details}</div></div>
            </div>

            {data.showTechSpecs && (
                <TechSpecTable data={data.layout!} controlData={data.controlLayout} mode={data.quoteMode || 'lift'} isVisible={true} onToggleVisibility={() => {}} embedded={true} />
            )}

            <div className="space-y-6 mt-10">
                {data.categories.map(cat => (
                    <CategoryTable 
                        key={cat.id} category={cat} currency={data.currency} 
                        globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData({...data, categories: data.categories.map(c => c.id === id ? {...c, [f]: v} : c)})}
                        onDeleteCategory={(id) => setData({...data, categories: data.categories.filter(c => c.id !== id)})}
                        onAddItem={(cid, sur) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: [...c.items, { id: generateId(), description: sur?'Príplatok':'Položka', unit:'ks', quantity:1, unitPrice:0, purchasePrice:0, vatRate:23, isSurcharge:sur }]} : c)})}
                        onUpdateItem={(cid, iid, f, v) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)})}
                        onDeleteItem={(cid, iid) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)})}
                        onAiSuggest={() => {}} onOpenCatalog={() => {}} isAiLoading={false} mode={data.quoteMode}
                    />
                ))}
            </div>

            <div className="mt-12 pt-6 border-t-2 border-gray-800 flex justify-end">
                <div className="w-1/2">
                    <table className="w-full">
                        <tbody>
                            <tr><td className="py-1 text-gray-500 font-bold uppercase text-xs">Technológia bez DPH</td><td className="py-1 text-right font-bold text-lg">{totals.sale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                            <tr className="bg-gray-100"><td className="p-3 text-lg font-bold uppercase">Spolu k úhrade s DPH</td><td className="p-3 text-right text-3xl font-bold">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-10">
                 <div className="flex justify-between items-center mb-3 no-print">
                    <h4 className="font-bold uppercase text-gray-400 text-[10px] tracking-widest">Obchodné podmienky</h4>
                    <div className="flex gap-2">
                        <button onClick={() => setData({...data, terms: TERMS_FULL})} className="px-3 py-1 bg-blue-50 text-blue-700 rounded text-[10px] font-bold border border-blue-200 hover:bg-blue-100 flex items-center gap-1 transition-all"><FileText size={12}/> Vložiť Plnú Verziu</button>
                        <button onClick={() => setData({...data, terms: TERMS_SUPPLY_ONLY})} className="px-3 py-1 bg-gray-50 text-gray-700 rounded text-[10px] font-bold border border-gray-200 hover:bg-gray-100 flex items-center gap-1 transition-all"><FileMinus size={12}/> Vložiť Len Dodávku</button>
                    </div>
                </div>
                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[150px] print:h-auto" stickyToolbar={false} />
            </div>
        </div>
      </div>

      {/* ARCHIVE VIEW - CLEAN TABLE STYLE */}
      {showArchive && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white rounded-lg shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200">
                  <div className="p-5 border-b flex justify-between items-center bg-gray-50 rounded-t-lg">
                      <h2 className="text-xl font-bold uppercase tracking-tight flex items-center gap-2"><Archive className="text-blue-600"/> Archív dokladov</h2>
                      <button onClick={() => setShowArchive(false)} className="p-2 hover:bg-gray-200 rounded-full"><X size={20}/></button>
                  </div>
                  <div className="p-4 border-b">
                      <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                          <input type="text" placeholder="Hľadať v archíve..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-400 outline-none font-medium" />
                      </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                      <table className="w-full text-sm">
                        <thead className="bg-white border-b-2 border-gray-200 sticky top-0 z-10">
                            <tr>
                                <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px]">Doklad</th>
                                <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px]">Referencia / Projekt</th>
                                <th className="p-3 text-left font-bold text-gray-500 uppercase text-[10px]">Klient</th>
                                <th className="p-3 text-right font-bold text-gray-500 uppercase text-[10px]">Cena s DPH</th>
                                <th className="p-3 text-center font-bold text-gray-500 uppercase text-[10px]">Akcie</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase()) || q.clientReference?.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => {
                                const qTotals = calculateTotals(q);
                                return (
                                    <tr key={q.id} className="bg-white hover:bg-blue-50 transition-colors group">
                                        <td className="p-3">
                                            <div className="font-bold text-gray-800">{q.number}</div>
                                            <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded text-white ${q.type === 'contract' ? 'bg-green-500' : q.type === 'order' ? 'bg-blue-500' : 'bg-yellow-500'}`}>{q.type === 'quote' ? 'CP' : q.type.toUpperCase()}</span>
                                        </td>
                                        <td className="p-3 font-semibold text-blue-600 uppercase">{q.clientReference || '-'}</td>
                                        <td className="p-3 font-medium text-gray-600">{q.client.name || 'Neznámy'}</td>
                                        <td className="p-3 text-right font-bold text-gray-900">{qTotals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} €</td>
                                        <td className="p-3 text-center">
                                            <div className="flex gap-2 justify-center">
                                                <button onClick={() => loadFromArchive(q)} className="px-3 py-1 bg-blue-600 text-white font-bold rounded text-xs">Otvoriť</button>
                                                <button onClick={() => { if(confirm("Vymazať?")) setSavedQuotes(savedQuotes.filter(sq=>sq.id!==q.id)); }} className="p-1.5 text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                      </table>
                  </div>
              </div>
          </div>
      )}

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} controlLayout={data.controlLayout} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories} cabinClasses={cabinClasses}
          initialState={data.wizardData}
      />

      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={(p) => setProducts([...products, p])} onUpdateProduct={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))} customCategories={availableCategories} onAddCategory={(c) => setAvailableCategories([...availableCategories, c])} onDeleteCategory={(c) => setAvailableCategories(availableCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])} onUpdateCabinClass={(cc) => setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c))} onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const year = new Date().getFullYear().toString().slice(-2);
          const seq = t === 'control_system' ? (settings.nextRsSequence || 1) : (settings.nextCpSequence || 1);
          const prefix = t === 'control_system' ? 'RS' : 'CP';
          const num = `${prefix}_SK_${seq.toString().padStart(3, '0')}_${year}_BA`;
          if(t === 'control_system') setSettings({...settings, nextRsSequence: seq + 1}); else setSettings({...settings, nextCpSequence: seq + 1});
          const cats = t === 'lift' ? DEFAULT_CATEGORIES_LIST : CONTROL_SYSTEM_CATEGORIES;
          setData({ id: generateId(), number: num, type: 'quote', quoteMode: t, title: t==='lift'?'Cenová Ponuka - Výťah':'Cenová Ponuka - RS', date: new Date().toISOString().split('T')[0], validUntil: new Date(Date.now() + 60*24*60*60*1000).toISOString().split('T')[0], supplier: data.supplier, client: { name: '', details: '' }, layout: { ...DEFAULT_LAYOUT }, controlLayout: { ...DEFAULT_CONTROL_LAYOUT }, categories: cats.map(n => ({ id: generateId(), type: 'items', name: n, items: [], isExpanded: true, section: 'lift' })), terms: TERMS_FULL, currency: '€', globalMargin: 15, shaftMargin: 20, vatRate: 23, hideItemPrices: true, showTechSpecs: true });
      }} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details}})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, CabinClass, ControlSystemLayout } from '../types';
import { X, Calculator, Check, AlertTriangle, RotateCcw, Plus, Cpu, ArrowLeft, ArrowRight, Trash2, Search, Sparkles } from 'lucide-react';

const RS_CATEGORIES = ['Rozvádzač', 'Menič a filter', 'Displeje a privolávače', 'Snímanie polohy', 'Kabeláž', 'Atypické riešenia'];

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  controlLayout?: ControlSystemLayout; 
  mode: 'lift' | 'control_system';
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[];
  initialState?: MaterialWizardData; 
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, controlLayout, mode, onInsert, products, customCategories, initialState, cabinClasses
}) => {
  const [tabs, setTabs] = useState<{id: string, label: string}[]>([]);
  const [activeTab, setActiveTab] = useState('');
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);
  const [includeTransport, setIncludeTransport] = useState(true);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(true);
  const [transportPrice, setTransportPrice] = useState(250);
  const [packagingPrice, setPackagingPrice] = useState(50);

  useEffect(() => {
      if (isOpen) {
          let generatedTabs = [];
          if (mode === 'control_system') {
              generatedTabs = RS_CATEGORIES.map(c => ({ id: c, label: c }));
          } else {
              generatedTabs = customCategories
                  .filter(c => !['Montáž', 'Doprava', 'Balné', 'Ostatné'].includes(c))
                  .map(c => ({ id: c, label: c }));
          }
          setTabs(generatedTabs);
          if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);

          if (initialState) {
              setBomItems(initialState.items);
              setIncludeTransport(initialState.includeTransport);
              setIncludePackaging(initialState.includePackaging);
              setIncludeAssembly(initialState.includeAssembly);
              setTransportPrice(initialState.transportPrice || 250);
              setPackagingPrice(initialState.packagingPrice || 50);
          } else {
              handleResetToDefaults();
          }
      }
  }, [isOpen, mode]);

  const findCatalogProduct = (keys: string[], cat: string) => {
      const lowerKeys = keys.map(k => k.toLowerCase());
      return products.find(p => p.category === cat && lowerKeys.every(k => p.name.toLowerCase().includes(k)));
  };

  // --- v4.3.40 CALCULATIONS LOGIC ---
  const calculateLiftBOM = (l: LiftLayoutData) => {
    const items: MaterialWizardData['items'] = [];
    const travel = l.travelHeight || 15000;
    const hq = l.headroomHeight || 3400;
    const pit = l.pitDepth || 1100;
    const totalHeight = travel + hq + pit;
    const railLen = l.guideRailLength || 5000;

    const addItem = (cat: string, desc: string, qty: number, unit: string, searchKeys: string[]) => {
        if (qty <= 0) return;
        const match = findCatalogProduct(searchKeys, cat);
        items.push({ category: cat, description: match ? match.name : desc, quantity: Number(qty.toFixed(2)), unit: match ? match.unit : unit, productId: match?.id, price: match?.price || 0 });
    };

    // 1. Vodítka
    const barsCount = Math.ceil(totalHeight / railLen);
    addItem('Vodítka a kotvenie', `Vodidlá Kabína ${l.guideTypeCar}`, barsCount * 2, 'ks', [l.guideTypeCar || 'T89']);
    addItem('Vodítka a kotvenie', `Vodidlá CWT ${l.guideTypeCwt}`, barsCount * 2, 'ks', [l.guideTypeCwt || 'T50']);
    addItem('Vodítka a kotvenie', `Spojky vodidiel Kabína`, Math.max(0, barsCount-1)*2, 'ks', ['spojka', l.guideTypeCar || 'T89']);

    // Konzoly (Spodná + Horná + každých 2500mm jedna)
    const bracketRows = 1 + Math.ceil((totalHeight - 500) / 2500) + 1;
    addItem('Vodítka a kotvenie', `Konzoly vodidiel`, (bracketRows * 4), 'ks', ['konzola']);
    addItem('Vodítka a kotvenie', `Príchytky vodidiel`, (bracketRows * 8), 'ks', ['príchytka']);

    // 2. Dvere
    const stops = l.numberOfEntrances || l.numberOfStops || 2;
    addItem('Dvere', `Šachtové dvere PL ${l.doorWidth}`, stops, 'ks', ['šachtové', String(l.doorWidth)]);
    addItem('Dvere', `Kabínové dvere PL ${l.doorWidth}`, l.isThroughCar ? 2 : 1, 'ks', ['kabínové', String(l.doorWidth)]);

    // 3. Pohon & Laná
    const suspension = l.suspensionType === '1:1' ? 1 : 2;
    const ropeCount = l.ratedLoad <= 630 ? 4 : 6;
    const ropeLen = Math.ceil(((totalHeight * suspension * ropeCount) / 1000) + 20);
    addItem('Pohon', `Trakčný stroj ${l.ratedLoad}kg`, 1, 'ks', ['stroj', String(l.ratedLoad)]);
    addItem('Pohon', `Nosné prostriedky`, ropeLen, 'm', [l.tractionMedium === 'ctp' ? 'plast' : 'lano']);

    return items;
  };

  const calculateRsBOM = (c: ControlSystemLayout) => {
      const items: MaterialWizardData['items'] = [];
      const match = findCatalogProduct(['rozvádzač'], 'Rozvádzač');
      items.push({ category: 'Rozvádzač', description: match ? match.name : `Riadiaci rozvádzač ${c.motorPower}kW`, quantity: 1, unit: 'ks', productId: match?.id, price: match?.price || 0 });
      return items;
  };

  const handleResetToDefaults = () => {
      setBomItems(mode === 'control_system' ? calculateRsBOM(controlLayout!) : calculateLiftBOM(layout));
  };

  const handleInsert = () => {
      onInsert({ items: bomItems, includeTransport, includePackaging, includeAssembly, transportPrice, packagingPrice, categoryOrder: tabs.map(t => t.id) });
      onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col animate-in fade-in zoom-in-95 duration-200">
        <div className="p-5 border-b flex justify-between items-center bg-gray-50 rounded-t-lg">
          <div className="flex items-center gap-3">
            <Calculator className="text-blue-600" size={24} />
            <h2 className="text-xl font-bold text-gray-800 uppercase tracking-tight">{mode === 'control_system' ? 'Sprievodca RS' : 'Materiálový Sprievodca (v4.3.40)'}</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
        </div>

        <div className="flex border-b border-gray-200 overflow-x-auto bg-white p-1 gap-1">
            {tabs.map((tab) => (
                 <button key={tab.id} className={`flex items-center gap-2 rounded-md px-4 py-2.5 transition-all font-bold text-xs uppercase ${activeTab===tab.id ? 'bg-blue-50 text-blue-700 border border-blue-200' : 'text-gray-500 hover:bg-gray-100'}`} onClick={() => setActiveTab(tab.id)}>
                     {tab.label}
                 </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
            <div className="bg-white border border-gray-300 rounded overflow-hidden shadow-sm mb-6">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-500 font-bold text-[10px] uppercase border-b">
                        <tr>
                            <th className="p-3 text-left w-1/3">Položka (Technický výpočet)</th>
                            <th className="p-3 text-left w-1/3">Zhoda v Katalógu</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena J.</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {bomItems.map((item, idx) => item.category === activeTab && (
                            <tr key={idx} className="hover:bg-blue-50/30">
                                <td className="p-3 font-semibold text-gray-800">{item.description}</td>
                                <td className="p-3">
                                    <select 
                                        value={item.productId || ''} 
                                        onChange={e => {
                                            const p = products.find(prod => prod.id === e.target.value);
                                            if(p) {
                                                const updated = [...bomItems];
                                                updated[idx] = { ...updated[idx], productId: p.id, price: p.price, description: p.name, unit: p.unit };
                                                setBomItems(updated);
                                            }
                                        }} 
                                        className={`w-full p-1.5 border rounded text-xs font-semibold ${item.productId ? 'bg-green-50 border-green-400 text-green-700' : 'bg-white border-gray-300'}`}
                                    >
                                        <option value="">-- Vybrať manuálne --</option>
                                        {products.filter(p => p.category === activeTab).map(p => <option key={p.id} value={p.id}>{p.name} ({p.price.toFixed(2)}€)</option>)}
                                    </select>
                                </td>
                                <td className="p-3 text-right font-bold text-blue-600">{item.quantity}</td>
                                <td className="p-3 text-right font-mono font-bold text-gray-700">{item.price ? item.price.toFixed(2) : '0.00'} €</td>
                                <td className="p-3 text-center"><button onClick={() => setBomItems(bomItems.filter((_,i)=>i!==idx))} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            <button onClick={() => setBomItems([...bomItems, { category: activeTab, description: 'Nová položka', quantity: 1, unit: 'ks', price: 0 }])} className="w-full py-3 border border-dashed border-gray-400 rounded text-gray-500 hover:text-blue-600 hover:border-blue-400 transition-all flex justify-center items-center gap-2 font-bold text-xs uppercase">+ Pridať manuálne</button>
        </div>

        <div className="p-5 border-t bg-white rounded-b-lg flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                 <label className="flex items-center gap-3 p-3 border border-gray-200 rounded hover:bg-gray-50 transition cursor-pointer"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="w-4 h-4"/><div className="font-bold text-xs uppercase text-gray-700">Montáž technológie</div></label>
                 <div className="flex items-center gap-3 p-3 border border-gray-200 rounded"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="w-4 h-4"/><div className="font-bold text-xs uppercase text-gray-700 flex-1">Doprava</div><input type="number" value={transportPrice} onChange={e => setTransportPrice(+e.target.value)} className="w-16 border rounded text-right font-bold text-xs p-1" disabled={!includeTransport}/>€</div>
