          if (wData.includeTransport) activeCats.add('Doprava');
          if (wData.includePackaging) activeCats.add('Balné');

          newData.categories = newData.categories.filter(c => c.type === 'text' || activeCats.has(c.name));

          activeCats.forEach(name => {
              let c = newData.categories.find(x => x.name === name);
              if (!c) {
