                <div className="col-span-3"><label className="text-[9px] uppercase font-bold text-gray-400 block mb-1">Počet Staníc</label><input type="number" value={data.controlLayout?.numberOfStops} onChange={e => setData({...data, controlLayout:{...data.controlLayout!, numberOfStops:+e.target.value}})} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-gray-50"/></div>
