                          <input type="text" placeholder="Hľadať v archíve..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-400 outline-none font-medium" />
                      </div>
