                  <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                      <table className="w-full text-sm">
                        <thead className="bg-white border-b-2 border-gray-200 sticky top-0 z-10 text-[10px] uppercase font-bold text-gray-400">
                            <tr>
                                <th className="p-4 text-left w-32">Doklad</th>
                                <th className="p-4 text-left">Referencia / Projekt</th>
                                <th className="p-4 text-left">Klient</th>
                                <th className="p-4 text-right w-40">Cena s DPH</th>
                                <th className="p-4 text-center w-24">Akcie</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase()) || q.clientReference?.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => {
                                const qTotals = calculateTotals(q);
                                return (
                                    <tr key={q.id} className="bg-white hover:bg-blue-50/50 transition-colors group">
                                        <td className="p-4">
                                            <div className="font-bold text-gray-900">{q.number}</div>
                                            <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded text-white ${q.type === 'contract' ? 'bg-green-500' : q.type === 'order' ? 'bg-blue-500' : 'bg-amber-500'}`}>{q.type === 'quote' ? 'CP' : q.type.toUpperCase()}</span>
                                        </td>
                                        <td className="p-4 font-bold text-blue-600 uppercase text-xs">{q.clientReference || '-'}</td>
                                        <td className="p-4">
                                            <div className="font-semibold text-gray-700">{q.client.name || 'Neznámy'}</div>
                                            <div className="text-[10px] text-gray-400">{new Date(q.lastUpdated || q.date).toLocaleDateString('sk-SK')}</div>
                                        </td>
                                        <td className="p-4 text-right font-bold text-gray-900 text-base">{qTotals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} €</td>
                                        <td className="p-4 text-center">
                                            <div className="flex gap-2 justify-center">
                                                <button onClick={() => loadFromArchive(q)} className="px-3 py-1 bg-blue-600 text-white font-bold rounded text-xs hover:bg-blue-700 shadow-sm transition">Otvoriť</button>
                                                <button onClick={() => { if(confirm("Vymazať z archívu?")) setSavedQuotes(savedQuotes.filter(sq=>sq.id!==q.id)); }} className="p-1.5 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded transition-all"><Trash2 size={18}/></button>
                                            </div>
