            </div>
            <div className="flex justify-between items-center border-t border-gray-100 pt-4">
                <button onClick={handleResetToDefaults} className="text-[10px] text-gray-400 font-bold uppercase flex items-center gap-1 hover:text-orange-600 transition-colors"><RotateCcw size={14}/> Resetovať prepočty podľa noriem</button>
                <div className="flex gap-3">
                    <button onClick={onClose} className="px-6 py-2.5 text-gray-500 hover:bg-gray-100 rounded font-bold uppercase text-xs transition-colors">Zrušiť</button>
                    <button onClick={handleInsert} className="px-10 py-2.5 bg-blue-600 text-white hover:bg-blue-700 rounded font-bold uppercase text-xs flex items-center gap-3 shadow-md transition-all hover:scale-[1.02] active:scale-95"><Check size={20} /> Potvrdiť a Vložiť do Rozpočtu</button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

