const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try { return crypto.randomUUID(); } catch (e) {}
  }
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!sessionStorage.getItem('auth'));
  const [data, setData] = useState<QuoteData>({
    id: generateId(), number: 'CP_SK_001_24_BA', type: 'quote', quoteMode: 'lift', title: 'Cenová Ponuka - Výťah',
    date: new Date().toISOString().split('T')[0], 
    validUntil: new Date(Date.now() + 60*24*60*60*1000).toISOString().split('T')[0],
    clientReference: '', supplier: { name: 'Moja Firma s.r.o.', details: 'IČO: 12345678, DPH: SK12345678' },
    client: { name: '', details: '' }, layout: { ...DEFAULT_LAYOUT }, controlLayout: { ...DEFAULT_CONTROL_LAYOUT },
    categories: [], terms: TERMS_FULL, currency: '€', globalMargin: 15, shaftMargin: 20, vatRate: 23, 
    hideItemPrices: true, showTechSpecs: true
  });

  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [settings, setSettings] = useState<AppSettings>({ nextCpSequence: 1, nextRsSequence: 1, nextObjSequence: 1, nextPlSequence: 1 });
  const [savedQuotes, setSavedQuotes] = useState<QuoteData[]>([]);
  const [availableCategories, setAvailableCategories] = useState<string[]>(DEFAULT_CATEGORIES_LIST);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);

  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isSupplierModalOpen, setIsSupplierModalOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [isNewQuoteModalOpen, setIsNewQuoteModalOpen] = useState(false);
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const [showArchive, setShowArchive] = useState(false);
  const [archiveSearch, setArchiveSearch] = useState('');
  const [draggedCatId, setDraggedCatId] = useState<string | null>(null);

  useEffect(() => {
      const storedQuotes = localStorage.getItem('smartquote_archive');
      if (storedQuotes) try { setSavedQuotes(JSON.parse(storedQuotes)); } catch (e) {}
      const storedSettings = localStorage.getItem('smartquote_settings');
      if (storedSettings) try { setSettings(JSON.parse(storedSettings)); } catch (e) {}

      const loadLS = (key: string, setter: any) => { const s = localStorage.getItem(key); if(s) try { setter(JSON.parse(s)); } catch(e){} };
      loadLS('smartquote_products', setProducts);
      loadLS('smartquote_clients', setClients);
      loadLS('smartquote_suppliers', setSuppliers);
      loadLS('smartquote_categories', (v: any) => setAvailableCategories(Array.from(new Set([...DEFAULT_CATEGORIES_LIST, ...v]))));
  }, []);

  const calculateTotals = (q: QuoteData = data) => {
      let total = 0;
      q.categories.forEach(cat => {
          if (cat.isHidden) return;
          const margin = cat.section === 'shaft' ? q.shaftMargin : q.globalMargin;
          cat.items.forEach(item => {
              total += (item.quantity * item.unitPrice) * (1 + margin / 100);
          });
      });
      const vat = total * ((q.vatRate || 23) / 100);
      return { sale: total, vat, gross: total + vat };
  };

  const totals = calculateTotals();

  const handleMaterialWizardInsert = (wData: MaterialWizardData) => {
      setData(prev => {
          const newData = { ...prev, wizardData: wData };
          const activeItems = wData.items.filter(i => i.selected !== false);
          const catNames = new Set(activeItems.map(i => i.category));

          if (wData.includeAssembly) catNames.add('Montáž');
          if (wData.includeTransport) catNames.add('Doprava');
          if (wData.includePackaging) catNames.add('Balné');

          newData.categories = newData.categories.filter(c => c.type === 'text' || catNames.has(c.name));
          catNames.forEach(name => {
              let c = newData.categories.find(x => x.name === name);
              if (!c) {
                  c = { id: generateId(), name, type: 'items', items: [], isExpanded: true, section: 'lift' };
                  newData.categories.push(c);
              }
              c.items = [];
          });

          activeItems.forEach(i => {
              const cat = newData.categories.find(x => x.name === i.category);
              if (cat) cat.items.push({ id: generateId(), description: i.description, unit: i.unit, quantity: i.quantity, unitPrice: i.price || 0, purchasePrice: 0, vatRate: 23 });
          });

          const findC = (n: string) => newData.categories.find(x => x.name === n);
          if (wData.includeAssembly) { const c = findC('Montáž'); if (c) c.items.push({ id: generateId(), description: 'Montáž technológie', unit: 'kpl', quantity: 1, unitPrice: 1500, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includeTransport) { const c = findC('Doprava'); if (c) c.items.push({ id: generateId(), description: 'Doprava a logistika', unit: 'kpl', quantity: 1, unitPrice: wData.transportPrice || 250, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includePackaging) { const c = findC('Balné'); if (c) c.items.push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); }

          return newData;
      });
  };

  const moveCategory = (id: string, dir: 'up' | 'down') => {
      const idx = data.categories.findIndex(c => c.id === id);
      if ((dir === 'up' && idx === 0) || (dir === 'down' && idx === data.categories.length - 1)) return;
      const newCats = [...data.categories];
      const targetIdx = dir === 'up' ? idx - 1 : idx + 1;
      [newCats[idx], newCats[targetIdx]] = [newCats[targetIdx], newCats[idx]];
      setData(p => ({ ...p, categories: newCats }));
  };

  if (!isAuthenticated) return <LoginGate onLogin={() => { sessionStorage.setItem('auth', 'true'); setIsAuthenticated(true); }} />;

  return (
    <div className="min-h-screen bg-gray-100 font-sans print:bg-white text-slate-800 antialiased">

      {/* HEADER - v4.3.40 */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-50 print:hidden shadow-sm h-14 flex items-center">
          <div className="max-w-[1400px] w-full mx-auto px-6 flex items-center justify-between">
            <div className="flex items-center gap-6">
                <div className="flex items-center gap-2">
                    <div className="bg-blue-600 p-1.5 rounded shadow-sm text-white">
                        <Zap size={20} className="fill-current"/>
                    </div>
                    <span className="font-bold text-lg tracking-tight text-gray-800">SmartQuote <span className="text-[10px] font-normal text-gray-400 bg-gray-100 px-1.5 py-0.5 rounded ml-1">v{APP_VERSION}</span></span>
                </div>
                <div className="h-6 w-px bg-gray-200"></div>
                <div className="flex items-center gap-1">
                    <button onClick={() => setShowArchive(true)} className="flex items-center gap-2 px-3 py-1.5 text-gray-600 hover:bg-gray-100 rounded transition font-semibold text-sm"><Archive size={16}/> Archív</button>
                    <button onClick={() => setIsNewQuoteModalOpen(true)} className="flex items-center gap-2 px-4 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded shadow-sm transition font-bold text-sm ml-2"><PlusCircle size={16}/> Nová CP</button>
                </div>
            </div>
            <div className="flex items-center gap-3">
                 <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-1.5 text-gray-500 hover:text-gray-800 transition text-sm font-semibold flex items-center gap-1"><Settings size={14}/> Katalóg</button>
                 <button onClick={() => { localStorage.setItem('smartquote_archive', JSON.stringify(savedQuotes)); alert("Uložené."); }} className="px-4 py-1.5 bg-green-600 hover:bg-green-700 text-white rounded shadow-sm transition font-bold text-sm flex items-center gap-2"><Save size={16}/> Uložiť</button>
                 <button onClick={() => { sessionStorage.removeItem('auth'); setIsAuthenticated(false); }} className="p-2 text-gray-400 hover:text-red-500 transition-colors ml-1"><LogOut size={18}/></button>
            </div>
          </div>
      </div>

      <div className="max-w-[210mm] mx-auto py-8 print:p-0">

        {/* PARAMS PANEL */}
        <div className={`mb-6 p-6 bg-white rounded-lg border border-gray-200 shadow-sm no-print border-t-4 ${data.quoteMode === 'control_system' ? 'border-t-green-500' : 'border-t-blue-500'}`}>
            <div className="grid grid-cols-12 gap-4">
                <div className="col-span-12 font-bold text-gray-600 uppercase flex items-center justify-between mb-2 pb-2 border-b border-gray-100">
                    <div className="flex items-center gap-2 text-xs">
                        {data.quoteMode === 'control_system' ? <Cpu size={16} className="text-green-600"/> : <Sliders size={16} className="text-blue-600"/>} 
                        Konfigurácia Projektu
                    </div>
                </div>
                <div className="col-span-2"><label className="text-[9px] uppercase font-bold text-gray-400 block mb-1">Nosnosť (kg)</label><input type="number" value={data.layout?.ratedLoad} onChange={e => setData({...data, layout:{...data.layout!, ratedLoad:+e.target.value}})} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-gray-50"/></div>
                <div className="col-span-2"><label className="text-[9px] uppercase font-bold text-gray-400 block mb-1">Stanice</label><input type="number" value={data.layout?.numberOfStops} onChange={e => setData({...data, layout:{...data.layout!, numberOfStops:+e.target.value}})} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-gray-50"/></div>
                <div className="col-span-3"><label className="text-[9px] uppercase font-bold text-gray-400 block mb-1">Zdvih (mm)</label><input type="number" value={data.layout?.travelHeight} onChange={e => setData({...data, layout:{...data.layout!, travelHeight:+e.target.value}})} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold bg-gray-50"/></div>
                <div className="col-span-5 flex items-end">
                    <button onClick={() => setIsMaterialModalOpen(true)} className={`w-full h-10 font-bold rounded shadow-sm flex items-center justify-center gap-2 text-sm transition-all ${data.wizardData ? 'bg-green-600 hover:bg-green-700 text-white' : 'bg-blue-600 hover:bg-blue-700 text-white'}`}>
                        {data.wizardData ? <CheckCircle size={18}/> : <Calculator size={18}/>} 
                        {data.wizardData ? 'Upraviť Konfiguráciu' : 'Materiálový Sprievodca'}
                    </button>
                </div>
            </div>
        </div>

        {/* DOCUMENT VIEW */}
        <div className="bg-white shadow-xl print:shadow-none min-h-[297mm] p-12 print:p-0 border border-gray-200 rounded-sm">
            <div className="mb-10 border-b-2 border-slate-900 pb-6 flex justify-between items-start">
                 <div className="w-2/3">
                    <textarea value={data.title} onChange={e => setData({...data, title: e.target.value})} className="text-4xl font-bold w-full border-none bg-transparent uppercase p-0 leading-tight" rows={1}/>
                    <div className="text-xl text-gray-400 font-semibold mt-1 uppercase tracking-wider">{data.number}</div>
                    <div className="mt-6"><input value={data.clientReference} onChange={e => setData({...data, clientReference: e.target.value})} className="text-lg font-bold text-blue-600 w-full border-none p-0 uppercase placeholder-gray-200" placeholder="REFERENCIA PROJEKTU"/></div>
                </div>
                <div className="text-right">
                    <div className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Dátum vystavenia</div>
                    <div className="font-semibold text-lg">{new Date(data.date).toLocaleDateString('sk-SK')}</div>
                    <button onClick={() => window.print()} className="mt-4 px-4 py-2 bg-gray-800 text-white rounded font-bold no-print flex items-center gap-2 ml-auto shadow-sm text-sm hover:bg-black transition-colors"><Printer size={16}/> Tlačiť PDF</button>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-12 mb-10 pb-8 border-b border-gray-100">
                <div><div className="text-[9px] font-bold text-gray-400 uppercase mb-2">Dodávateľ <button onClick={() => setIsSupplierModalOpen(true)} className="no-print text-blue-500 ml-2 font-normal">Zmeniť</button></div><div className="font-bold text-lg uppercase">{data.supplier.name}</div><div className="text-xs text-gray-500 leading-relaxed whitespace-pre-wrap">{data.supplier.details}</div></div>
                <div className="border-l border-gray-100 pl-10">
                    <div className="text-[9px] font-bold text-gray-400 uppercase mb-2">Klient <button onClick={() => setIsClientModalOpen(true)} className="no-print text-blue-500 ml-2 font-normal">Zmeniť</button></div>
                    <div className="font-bold text-lg uppercase">{data.client.name || 'ZADAJTE KLIENTA'}</div>
                    <div className="text-xs text-gray-500 leading-relaxed whitespace-pre-wrap">{data.client.details}</div>
                </div>
            </div>

            {data.showTechSpecs && (
                <TechSpecTable data={data.layout!} controlData={data.controlLayout} mode={data.quoteMode || 'lift'} isVisible={true} onToggleVisibility={() => {}} embedded={true} />
            )}

            <div className="space-y-6 mt-10">
                {data.categories.map(cat => (
                    <CategoryTable 
                        key={cat.id} category={cat} currency={data.currency} 
                        globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData({...data, categories: data.categories.map(c => c.id === id ? {...c, [f]: v} : c)})}
                        onDeleteCategory={(id) => setData({...data, categories: data.categories.filter(c => c.id !== id)})}
                        onAddItem={(cid, sur) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: [...c.items, { id: generateId(), description: sur?'Príplatok':'Položka', unit:'ks', quantity:1, unitPrice:0, purchasePrice:0, vatRate:23, isSurcharge:sur }]} : c)})}
                        onUpdateItem={(cid, iid, f, v) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)})}
                        onDeleteItem={(cid, iid) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)})}
                        onAiSuggest={() => {}} onOpenCatalog={() => {}} isAiLoading={false} mode={data.quoteMode}
                        onMoveCategory={moveCategory}
                    />
                ))}
            </div>

            <div className="mt-12 pt-6 border-t-2 border-slate-900 flex justify-end">
                <div className="w-1/2">
                    <table className="w-full text-sm">
                        <tbody>
                            <tr><td className="py-1 text-gray-500 font-bold uppercase text-[10px]">Cena bez DPH</td><td className="py-1 text-right font-bold text-lg">{totals.sale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                            <tr className="bg-gray-50"><td className="p-3 text-lg font-bold uppercase">Celkom s DPH</td><td className="p-3 text-right text-3xl font-bold">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-12 break-inside-avoid">
                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[120px] print:h-auto" stickyToolbar={false} />
            </div>
        </div>
      </div>

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} controlLayout={data.controlLayout} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories}
          initialState={data.wizardData}
      />

      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={(p) => setProducts([...products, p])} onUpdateProduct={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))} customCategories={availableCategories} onAddCategory={(c) => setAvailableCategories([...availableCategories, c])} onDeleteCategory={(c) => setAvailableCategories(availableCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])} onUpdateCabinClass={(cc) => setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c))} onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const seq = t === 'control_system' ? (settings.nextRsSequence || 1) : (settings.nextCpSequence || 1);
          const prefix = t === 'control_system' ? 'RS' : 'CP';
          const num = `${prefix}_SK_${seq.toString().padStart(3, '0')}_24_BA`;
          setData({ ...data, id: generateId(), number: num, quoteMode: t, categories: (t==='lift'?DEFAULT_CATEGORIES_LIST:CONTROL_SYSTEM_CATEGORIES).map(n => ({ id: generateId(), name: n, type: 'items', items: [], isExpanded: true })) });
      }} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details}})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />

      {showArchive && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4">
              <div className="bg-white rounded-lg shadow-2xl w-full max-w-5xl h-[80vh] flex flex-col">
                  <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-lg">
                      <h2 className="text-xl font-bold uppercase flex items-center gap-2"><Archive className="text-blue-600"/> Archív</h2>
                      <button onClick={() => setShowArchive(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
                  </div>
                  <div className="p-4 border-b bg-white">
                      <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
                          <input type="text" placeholder="Hľadať v archíve..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg outline-none font-medium" />
                      </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                      <table className="w-full text-sm">
                        <thead className="bg-white border-b sticky top-0 z-10 text-[10px] uppercase font-bold text-gray-400">
                            <tr><th className="p-4 text-left">Doklad</th><th className="p-4 text-left">Projekt</th><th className="p-4 text-left">Klient</th><th className="p-4 text-right">Cena s DPH</th><th className="p-4 text-center">Akcia</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => (
                                <tr key={q.id} className="bg-white hover:bg-blue-50/50 transition-colors group">
                                    <td className="p-4 font-bold">{q.number}</td>
                                    <td className="p-4 font-bold text-blue-600">{q.clientReference || '-'}</td>
                                    <td className="p-4">{q.client.name || 'Neznámy'}</td>
                                    <td className="p-4 text-right font-bold">{calculateTotals(q).gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} €</td>
                                    <td className="p-4 text-center"><button onClick={() => { setData(q); setShowArchive(false); }} className="px-3 py-1 bg-blue-600 text-white font-bold rounded text-xs">Otvoriť</button></td>
                                </tr>
                            ))}
                        </tbody>
                      </table>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, ControlSystemLayout } from '../types';
import { X, Calculator, Check, RotateCcw, Plus, GripVertical, CheckCircle, Trash2 } from 'lucide-react';

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  controlLayout?: ControlSystemLayout; 
  mode: 'lift' | 'control_system';
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[];
  initialState?: MaterialWizardData; 
}

export interface MaterialWizardItem {
    category: string;
    description: string;
    quantity: number;
    unit: string;
    productId?: string;
    price?: number;
    selected?: boolean; 
}

export interface MaterialWizardData {
    items: MaterialWizardItem[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    transportPrice?: number; 
    packagingPrice?: number; 
    categoryOrder: string[];
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, controlLayout, mode, onInsert, products, customCategories, initialState
}) => {
  const [tabs, setTabs] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState('');
  const [bomItems, setBomItems] = useState<MaterialWizardItem[]>([]);
  const [includeTransport, setIncludeTransport] = useState(true);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(true);
  const [transportPrice, setTransportPrice] = useState(250);
  const [packagingPrice, setPackagingPrice] = useState(50);
  const [draggedIdx, setDraggedIdx] = useState<number | null>(null);

  useEffect(() => {
      if (isOpen) {
          const generatedTabs = customCategories.filter(c => !['Montáž', 'Doprava', 'Balné'].includes(c));
          setTabs(generatedTabs);
          if (generatedTabs.length > 0) setActiveTab(generatedTabs[0]);

          if (initialState) {
              setBomItems(initialState.items);
              setIncludeTransport(initialState.includeTransport);
              setIncludePackaging(initialState.includePackaging);
              setIncludeAssembly(initialState.includeAssembly);
              setTransportPrice(initialState.transportPrice || 250);
              setPackagingPrice(initialState.packagingPrice || 50);
          } else {
              handleRecalculate();
          }
      }
  }, [isOpen]);

  const handleRecalculate = () => {
    const items: MaterialWizardItem[] = [];
    if (mode === 'control_system' && controlLayout) {
        items.push({ category: 'Rozvádzač', description: `Riadiaci rozvádzač ${controlLayout.motorPower}kW`, quantity: 1, unit: 'ks', price: 0, selected: true });
    } else {
        const h = (layout.travelHeight + layout.headroomHeight + layout.pitDepth) / 1000;
        const findProd = (cat: string, search: string) => products.find(p => p.category === cat && p.name.toLowerCase().includes(search.toLowerCase()));

        const railCount = Math.ceil(h / (layout.guideRailLength / 1000 || 5)) * 2;
        const matchRail = findProd('Vodítka a kotvenie', layout.guideTypeCar || 'T89');
        items.push({ category: 'Vodítka a kotvenie', description: matchRail?.name || `Vodidlo Kabína ${layout.guideTypeCar}`, quantity: railCount, unit: 'ks', price: matchRail?.price || 0, selected: true });

        const bracketRows = 1 + Math.ceil(((h * 1000) - 500) / 2500) + 1;
        items.push({ category: 'Vodítka a kotvenie', description: 'Konzoly vodidiel (Set)', quantity: bracketRows * 4, unit: 'ks', price: 0, selected: true });

        const susp = layout.suspensionType === '1:1' ? 1 : 2;
        const ropeCount = layout.ratedLoad <= 630 ? 4 : 6;
        const ropeLen = Math.ceil((h * susp * ropeCount) + 20);
        items.push({ category: 'Pohon', description: 'Nosné laná / prostriedky', quantity: ropeLen, unit: 'm', price: 0, selected: true });
    }
    setBomItems(items);
  };

  const onDragStart = (idx: number) => setDraggedIdx(idx);
  const onDragOver = (e: React.DragEvent, targetIdx: number) => {
      e.preventDefault();
      if (draggedIdx === null || draggedIdx === targetIdx) return;
      const newItems = [...bomItems];
      const [removed] = newItems.splice(draggedIdx, 1);
      newItems.splice(targetIdx, 0, removed);
      setBomItems(newItems);
      setDraggedIdx(targetIdx);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[92vh] flex flex-col animate-in zoom-in-95 duration-200">
        <div className="p-5 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-3">
            <Calculator className="text-blue-600" size={26} />
            <h2 className="text-xl font-bold text-gray-800 uppercase tracking-tight">Sprievodca v4.3.40</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500 transition-colors"><X size={20}/></button>
        </div>

        <div className="flex border-b overflow-x-auto bg-white p-1 gap-1">
            {tabs.map((tab) => (
                 <button key={tab} className={`px-5 py-2.5 rounded-md transition-all font-bold text-xs uppercase ${activeTab===tab ? 'bg-blue-50 text-blue-700 ring-1 ring-blue-200' : 'text-gray-500 hover:bg-gray-100'}`} onClick={() => setActiveTab(tab)}>{tab}</button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
            <div className="bg-white border border-gray-300 rounded overflow-hidden shadow-sm mb-6">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-100 text-gray-500 font-bold text-[10px] uppercase border-b border-gray-200">
                        <tr>
                            <th className="w-8 p-3"></th>
                            <th className="w-8 p-3"><CheckCircle size={14}/></th>
                            <th className="p-3">Položka</th>
                            <th className="p-3 text-right w-20">Mn.</th>
                            <th className="p-3 text-right w-24">Cena J.</th>
                            <th className="w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {bomItems.map((item, idx) => item.category === activeTab && (
                            <tr key={idx} className={`hover:bg-blue-50/30 transition-colors group ${!item.selected ? 'opacity-40' : ''}`} draggable onDragStart={() => onDragStart(idx)} onDragOver={(e) => onDragOver(e, idx)}>
                                <td className="p-3 text-center cursor-grab text-gray-300 group-hover:text-gray-500"><GripVertical size={14}/></td>
                                <td className="p-3 text-center"><input type="checkbox" checked={item.selected !== false} onChange={e => { const updated = [...bomItems]; updated[idx].selected = e.target.checked; setBomItems(updated); }} className="w-4 h-4 rounded text-blue-600"/></td>
                                <td className="p-3 font-semibold text-gray-800 text-xs">{item.description}</td>
                                <td className="p-3 text-right font-bold text-blue-600">{item.quantity}</td>
                                <td className="p-3 text-right font-bold">{item.price?.toFixed(2)} €</td>
                                <td className="p-3 text-center"><button onClick={() => setBomItems(bomItems.filter((_,i)=>i!==idx))} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <button 
                onClick={() => setBomItems([...bomItems, { category: activeTab, description: 'Atypická položka', quantity: 1, unit: 'ks', price: 0, selected: true }])} 
                className="w-full py-3 border-2 border-dashed border-orange-200 bg-orange-50 text-orange-600 hover:bg-orange-100 hover:border-orange-400 transition-all flex justify-center items-center gap-2 font-bold text-xs uppercase rounded-lg shadow-sm"
            >
                <Plus size={18} /> Pridať položku manuálne
            </button>
        </div>

        <div className="p-5 border-t bg-white flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                 <label className="flex items-center gap-3 p-4 border border-gray-200 rounded shadow-sm"><input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="w-5 h-5 rounded text-blue-600"/><div className="font-bold text-xs uppercase text-gray-700">Montáž</div></label>
                 <div className="flex items-center gap-3 p-4 border border-gray-200 rounded shadow-sm"><input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="w-5 h-5 rounded text-blue-600"/><div className="font-bold text-xs uppercase text-gray-700 flex-1">Doprava</div><input type="number" value={transportPrice} onChange={e => setTransportPrice(+e.target.value)} className="w-20 border border-gray-300 rounded text-right p-1.5"/>€</div>
                 <div className="flex items-center gap-3 p-4 border border-gray-200 rounded shadow-sm"><input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="w-5 h-5 rounded text-blue-600"/><div className="font-bold text-xs uppercase text-gray-700 flex-1">Balné</div><input type="number" value={packagingPrice} onChange={e => setPackagingPrice(+e.target.value)} className="w-20 border border-gray-300 rounded text-right p-1.5"/>€</div>
            </div>
            <div className="flex justify-between items-center pt-4">
                <button onClick={handleRecalculate} className="text-[10px] text-gray-400 font-bold uppercase flex items-center gap-1 hover:text-orange-600 transition-colors"><RotateCcw size={14}/> Prepočítať na predvolené</button>
                <div className="flex gap-3">
                    <button onClick={onClose} className="px-6 py-2 text-gray-500 hover:bg-gray-100 rounded font-bold uppercase text-xs">Zrušiť</button>
                    <button onClick={() => { onInsert({ items: bomItems, includeTransport, includePackaging, includeAssembly, transportPrice, packagingPrice, categoryOrder: tabs }); onClose(); }} className="px-10 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded font-bold uppercase text-xs flex items-center gap-3 shadow-md transition-all"><Check size={20} /> Potvrdiť a Vložiť</button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

