      const storedSettings = localStorage.getItem('smartquote_settings');
      if (storedSettings) try { setSettings(JSON.parse(storedSettings)); } catch (e) {}

      const loadLS = (key: string, setter: any) => { const s = localStorage.getItem(key); if(s) try { setter(JSON.parse(s)); } catch(e){} };
      loadLS('smartquote_products', setProducts);
      loadLS('smartquote_clients', setClients);
      loadLS('smartquote_suppliers', setSuppliers);
      loadLS('smartquote_categories', (v: any) => setAvailableCategories(Array.from(new Set([...DEFAULT_CATEGORIES_LIST, ...v]))));
