          if (wData.includePackaging) { const c = findC('Balné'); if (c) c.items.push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); }

          return newData;
      });
  };

