                        <Zap size={20} className="fill-current"/>
                    </div>
                    <span className="font-bold text-lg tracking-tight text-gray-800">SmartQuote <span className="text-[10px] font-normal text-gray-400 bg-gray-50 px-1.5 py-0.5 rounded ml-1">v{APP_VERSION}</span></span>
                </div>
