                            <tr className="bg-gray-50"><td className="p-3 text-lg font-bold uppercase">Celkom s DPH</td><td className="p-3 text-right text-3xl font-bold">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-12 break-inside-avoid">
                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[120px] print:h-auto" stickyToolbar={false} />
            </div>
        </div>
      </div>

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} controlLayout={data.controlLayout} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories}
          initialState={data.wizardData}
      />

      {showArchive && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4">
              <div className="bg-white rounded-lg shadow-2xl w-full max-w-5xl h-[80vh] flex flex-col">
                  <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-lg">
                      <h2 className="text-xl font-bold uppercase flex items-center gap-2"><Archive className="text-blue-600"/> Archív</h2>
                      <button onClick={() => setShowArchive(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
                  </div>
                  <div className="p-4 border-b bg-white">
                      <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
                          <input type="text" placeholder="Hľadať v archíve..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-400 outline-none font-medium" />
                      </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                      <table className="w-full text-sm">
                        <thead className="bg-white border-b sticky top-0 z-10 text-[10px] uppercase font-bold text-gray-400">
                            <tr><th className="p-4 text-left">Doklad</th><th className="p-4 text-left">Projekt</th><th className="p-4 text-left">Klient</th><th className="p-4 text-right">Cena s DPH</th><th className="p-4 text-center">Akcia</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => (
                                <tr key={q.id} className="bg-white hover:bg-blue-50/50 transition-colors group">
                                    <td className="p-4 font-bold text-gray-900">{q.number}</td>
                                    <td className="p-4 font-bold text-blue-600 uppercase text-xs">{q.clientReference || '-'}</td>
                                    <td className="p-4 font-semibold text-gray-700">{q.client.name || 'Neznámy'}</td>
                                    <td className="p-4 text-right font-bold text-gray-900 text-base">{calculateTotals(q).gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} €</td>
                                    <td className="p-4 text-center"><button onClick={() => { setData(q); setShowArchive(false); }} className="px-3 py-1 bg-blue-600 text-white font-bold rounded text-xs hover:bg-blue-700">Otvoriť</button></td>
                                </tr>
                            ))}
                        </tbody>
                      </table>
                  </div>
              </div>
          </div>
      )}

      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={(p) => setProducts([...products, p])} onUpdateProduct={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))} customCategories={availableCategories} onAddCategory={(c) => setAvailableCategories([...availableCategories, c])} onDeleteCategory={(c) => setAvailableCategories(availableCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])} onUpdateCabinClass={(cc) => setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c))} onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const seq = t === 'control_system' ? (settings.nextRsSequence || 1) : (settings.nextCpSequence || 1);
          const prefix = t === 'control_system' ? 'RS' : 'CP';
          const num = `${prefix}_SK_${seq.toString().padStart(3, '0')}_24_BA`;
          setData({ ...data, id: generateId(), number: num, quoteMode: t, categories: (t==='lift'?DEFAULT_CATEGORIES_LIST:CONTROL_SYSTEM_CATEGORIES).map(n => ({ id: generateId(), name: n, type: 'items', items: [], isExpanded: true })) });
      }} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details}})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  QuoteData, Product, Client, Supplier, AppSettings, QuoteCategory, 
  LiftLayoutData, CabinClass, ControlSystemLayout
} from './types';
