];

const DEFAULT_LAYOUT: LiftLayoutData = {
  liftType: 'passenger', driveType: 'traction', ratedLoad: 630, numberOfPersons: 8, ratedSpeed: 1.0, powerSupply: '400V / 50Hz',
  shaftWidth: 1600, shaftDepth: 1800, cabinWidth: 1100, cabinDepth: 1400, cabinHeight: 2100, doorWidth: 800, doorOffsetL: 0,
  pitDepth: 1100, headroomHeight: 3400, travelHeight: 15000,
  doorType: 'central', doorOperation: 'automatic', counterWeightPosition: 'back', machineRoomPosition: 'head',
  gapLeft: 270, gapRight: 80, gapFront: 210, gapRear: 50, notes: '',
  numberOfStops: 5, numberOfEntrances: 5, startStation: 0,
  tractionMedium: 'ctp', frameType: 'central',
  hasExternalShaft: false, bracketType: 'combined', guideTypeCar: 'T89', guideTypeCwt: 'T50',
  guideRailLength: 5000, doorOpeningWidth: 1060, doorOpeningHeight: 2060, LDO: 270, RDO: 270, 
  suspensionType: '2:1', cabinClass: 'FUN', entrances: 'A', isThroughCar: false
};

const DEFAULT_CONTROL_LAYOUT: ControlSystemLayout = {
    driveType: 'gearless', driveManufacturer: '', motorPower: 5.5, nominalCurrent: 14, brakeVoltage: '2x110V DC',
    doorType: 'automatic', doorManufacturer: '', doorControl: 'digital', doorControlModel: '',
    numberOfStops: 5, shaftHeadroom: 3400, shaftPit: 1100, travel: 15000,
    displaysCabin: 'lcd', displaysLanding: 'lcd', landingStationsConfiguration: 'all',
    cutoutLOP: '', cutoutCOP: '', reuseLOP: false, reuseCOP: false,
    operationMode: 'simplex', inspectionBox: true, positioning: 'absolute', mainCabinetLocation: 'mrl_shaft'
};

const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try { return crypto.randomUUID(); } catch (e) {}
  }
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!sessionStorage.getItem('auth'));
  const [data, setData] = useState<QuoteData>({
    id: generateId(), number: 'CP_SK_001_24_BA', type: 'quote', quoteMode: 'lift', title: 'Cenová Ponuka - Výťah',
    date: new Date().toISOString().split('T')[0], 
    validUntil: new Date(Date.now() + 60*24*60*60*1000).toISOString().split('T')[0],
    clientReference: '', supplier: { name: 'Moja Firma s.r.o.', details: 'IČO: 12345678, DPH: SK12345678' },
    client: { name: '', details: '' }, layout: { ...DEFAULT_LAYOUT }, controlLayout: { ...DEFAULT_CONTROL_LAYOUT },
    categories: [], terms: `<p><strong>1. Platnosť:</strong> 60 dní. <strong>2. Dodanie:</strong> 8-12 týždňov. <strong>3. Záruka:</strong> 24 mesiacov.</p>`, currency: '€', globalMargin: 15, shaftMargin: 20, vatRate: 23, 
    hideItemPrices: true, showTechSpecs: true
  });

  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [settings, setSettings] = useState<AppSettings>({ nextCpSequence: 1, nextRsSequence: 1, nextObjSequence: 1, nextPlSequence: 1 });
  const [savedQuotes, setSavedQuotes] = useState<QuoteData[]>([]);
  const [availableCategories, setAvailableCategories] = useState<string[]>(DEFAULT_CATEGORIES_LIST);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);

  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isSupplierModalOpen, setIsSupplierModalOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [isNewQuoteModalOpen, setIsNewQuoteModalOpen] = useState(false);
  const [showArchive, setShowArchive] = useState(false);
  const [archiveSearch, setArchiveSearch] = useState('');

  useEffect(() => {
      const storedQuotes = localStorage.getItem('smartquote_archive');
      if (storedQuotes) try { setSavedQuotes(JSON.parse(storedQuotes)); } catch (e) {}
      const storedSettings = localStorage.getItem('smartquote_settings');
      if (storedSettings) try { setSettings(JSON.parse(storedSettings)); } catch (e) {}

      const loadLS = (key: string, setter: any) => { const s = localStorage.getItem(key); if(s) try { setter(JSON.parse(s)); } catch(e){} };
      loadLS('smartquote_products', setProducts);
      loadLS('smartquote_clients', setClients);
      loadLS('smartquote_suppliers', setSuppliers);
      loadLS('smartquote_categories', (v: any) => setAvailableCategories(Array.from(new Set([...DEFAULT_CATEGORIES_LIST, ...v]))));
  }, []);

  const calculateTotals = (q: QuoteData = data) => {
      let total = 0;
      q.categories.forEach(cat => {
          if (cat.isHidden) return;
          const margin = cat.section === 'shaft' ? q.shaftMargin : q.globalMargin;
          cat.items.forEach(item => {
              total += (item.quantity * item.unitPrice) * (1 + margin / 100);
          });
      });
      const vat = total * ((q.vatRate || 23) / 100);
      return { sale: total, vat, gross: total + vat };
  };

  const totals = calculateTotals();

  const handleMaterialWizardInsert = (wData: MaterialWizardData) => {
      setData(prev => {
          const newData = { ...prev, wizardData: wData };
          const activeItems = wData.items.filter(i => i.selected !== false);
          const catNames = new Set(activeItems.map(i => i.category));

          if (wData.includeAssembly) catNames.add('Montáž');
          if (wData.includeTransport) catNames.add('Doprava');
          if (wData.includePackaging) catNames.add('Balné');

          newData.categories = newData.categories.filter(c => c.type === 'text' || catNames.has(c.name));
          catNames.forEach(name => {
              let c = newData.categories.find(x => x.name === name);
              if (!c) {
                  c = { id: generateId(), name, type: 'items', items: [], isExpanded: true, section: 'lift' };
                  newData.categories.push(c);
              }
              c.items = [];
          });

          activeItems.forEach(i => {
              const cat = newData.categories.find(x => x.name === i.category);
              if (cat) cat.items.push({ id: generateId(), description: i.description, unit: i.unit, quantity: i.quantity, unitPrice: i.price || 0, purchasePrice: 0, vatRate: 23 });
          });

          const findC = (n: string) => newData.categories.find(x => x.name === n);
          if (wData.includeAssembly) { const c = findC('Montáž'); if (c) c.items.push({ id: generateId(), description: 'Montáž technológie', unit: 'kpl', quantity: 1, unitPrice: 1500, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includeTransport) { const c = findC('Doprava'); if (c) c.items.push({ id: generateId(), description: 'Doprava a logistika', unit: 'kpl', quantity: 1, unitPrice: wData.transportPrice || 250, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includePackaging) { const c = findC('Balné'); if (c) c.items.push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); }

          return newData;
      });
  };

  const moveCategory = (id: string, dir: 'up' | 'down') => {
      const idx = data.categories.findIndex(c => c.id === id);
      if ((dir === 'up' && idx === 0) || (dir === 'down' && idx === data.categories.length - 1)) return;
      const newCats = [...data.categories];
      const targetIdx = dir === 'up' ? idx - 1 : idx + 1;
      const temp = newCats[idx];
      newCats[idx] = newCats[targetIdx];
      newCats[targetIdx] = temp;
      setData(p => ({ ...p, categories: newCats }));
  };

  if (!isAuthenticated) return <LoginGate onLogin={() => { sessionStorage.setItem('auth', 'true'); setIsAuthenticated(true); }} />;

  return (
    <div className="min-h-screen bg-gray-200 font-sans print:bg-white text-slate-800 antialiased pb-20">

      {/* PROFESSIONAL HEADER 4.3.40 */}
      <div className="bg-slate-900 border-b border-slate-700 sticky top-0 z-50 print:hidden shadow-lg h-16 flex items-center">
          <div className="max-w-[1400px] w-full mx-auto px-6 flex items-center justify-between">
            <div className="flex items-center gap-8">
                <div className="flex items-center gap-3">
                    <div className="bg-blue-500 p-2 rounded-lg shadow-inner text-white">
                        <Zap size={24} className="fill-current"/>
                    </div>
                    <div className="flex flex-col">
                        <span className="font-black text-xl tracking-tighter text-white leading-none">SmartQuote</span>
                        <span className="text-[10px] font-bold text-blue-400 uppercase tracking-widest mt-0.5">v{APP_VERSION}</span>
                    </div>
                </div>
                <div className="h-10 w-px bg-slate-700"></div>
                <div className="flex items-center gap-2">
                    <button onClick={() => setShowArchive(true)} className="flex items-center gap-2 px-4 py-2 text-slate-300 hover:text-white hover:bg-slate-800 rounded-lg transition font-bold text-sm"><Archive size={18}/> Archív</button>
                    <button onClick={() => setIsNewQuoteModalOpen(true)} className="flex items-center gap-2 px-5 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg shadow-md transition font-black text-sm uppercase tracking-wider ml-2"><PlusCircle size={18}/> Nový Projekt</button>
                </div>
            </div>
            <div className="flex items-center gap-4">
                 <button onClick={() => setIsCatalogOpen(true)} className="px-4 py-2 text-slate-400 hover:text-white transition text-sm font-bold flex items-center gap-2 border border-slate-700 rounded-lg"><Settings size={18}/> Katalóg</button>
                 <button onClick={() => { localStorage.setItem('smartquote_archive', JSON.stringify(savedQuotes)); alert("Dáta úspešne uložené do databázy."); }} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg shadow-lg transition font-black text-sm flex items-center gap-2 uppercase tracking-widest"><Save size={18}/> Uložiť</button>
                 <button onClick={() => { sessionStorage.removeItem('auth'); setIsAuthenticated(false); }} className="p-2 text-slate-500 hover:text-red-400 transition-colors ml-2"><LogOut size={22}/></button>
            </div>
          </div>
      </div>

      <div className="max-w-[210mm] mx-auto py-10 print:p-0">

        {/* PARAMS PANEL - Heritage Style */}
        <div className={`mb-8 p-8 bg-white rounded-2xl border border-gray-300 shadow-xl no-print border-t-8 ${data.quoteMode === 'control_system' ? 'border-t-emerald-500' : 'border-t-blue-600'}`}>
            <div className="grid grid-cols-12 gap-6">
                <div className="col-span-12 flex items-center justify-between mb-2 pb-4 border-b border-gray-100">
                    <div className="flex items-center gap-3 text-xs font-black uppercase tracking-widest text-gray-400">
                        {data.quoteMode === 'control_system' ? <Cpu size={20} className="text-emerald-500"/> : <Sliders size={20} className="text-blue-600"/>} 
                        Technická konfigurácia
                    </div>
                </div>

                <div className="col-span-2">
                    <label className="text-[10px] uppercase font-black text-gray-400 block mb-2 tracking-widest">Nosnosť (kg)</label>
                    <input type="number" value={data.layout?.ratedLoad} onChange={e => setData({...data, layout:{...data.layout!, ratedLoad:+e.target.value}})} className="w-full h-12 border-2 border-gray-100 rounded-xl px-4 text-center font-black text-xl bg-gray-50 focus:bg-white focus:border-blue-500 outline-none transition-all"/>
                </div>
                <div className="col-span-2">
                    <label className="text-[10px] uppercase font-black text-gray-400 block mb-2 tracking-widest">Stanice</label>
                    <input type="number" value={data.layout?.numberOfStops} onChange={e => setData({...data, layout:{...data.layout!, numberOfStops:+e.target.value}})} className="w-full h-12 border-2 border-gray-100 rounded-xl px-4 text-center font-black text-xl bg-gray-50 focus:bg-white focus:border-blue-500 outline-none transition-all"/>
                </div>
                <div className="col-span-3">
                    <label className="text-[10px] uppercase font-black text-gray-400 block mb-2 tracking-widest">Zdvih (mm)</label>
                    <input type="number" value={data.layout?.travelHeight} onChange={e => setData({...data, layout:{...data.layout!, travelHeight:+e.target.value}})} className="w-full h-12 border-2 border-gray-100 rounded-xl px-4 text-center font-black bg-gray-50 focus:bg-white focus:border-blue-500 outline-none transition-all"/>
                </div>
                <div className="col-span-5 flex items-end">
                    <button 
                        onClick={() => setIsMaterialModalOpen(true)} 
                        className={`w-full h-12 font-black rounded-xl shadow-lg flex items-center justify-center gap-3 text-sm transition-all uppercase tracking-widest hover:scale-[1.02] active:scale-95 ${data.wizardData ? 'bg-emerald-600 hover:bg-emerald-500 text-white' : 'bg-blue-600 hover:bg-blue-500 text-white'}`}
                    >
                        {data.wizardData ? <CheckCircle size={20}/> : <Calculator size={20}/>} 
                        {data.wizardData ? 'Upraviť rozpočet' : 'Materiálový sprievodca'}
                    </button>
                </div>
            </div>
        </div>

        {/* DOCUMENT VIEW */}
        <div className="bg-white shadow-2xl print:shadow-none min-h-[297mm] p-16 print:p-0 border border-gray-300 rounded-sm">
            <div className="mb-12 border-b-4 border-slate-900 pb-8 flex justify-between items-start">
                 <div className="w-2/3">
                    <textarea value={data.title} onChange={e => setData({...data, title: e.target.value})} className="text-5xl font-black w-full border-none bg-transparent uppercase p-0 leading-tight tracking-tighter" rows={1}/>
                    <div className="text-2xl text-gray-400 font-bold mt-2 uppercase tracking-widest">{data.number}</div>
                    <div className="mt-8"><input value={data.clientReference} onChange={e => setData({...data, clientReference: e.target.value})} className="text-xl font-black text-blue-600 w-full border-none p-0 uppercase placeholder-gray-200 focus:outline-none" placeholder="REFERENCIA PROJEKTU"/></div>
                </div>
                <div className="text-right">
                    <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2">Dátum vystavenia</div>
                    <div className="font-bold text-xl">{new Date(data.date).toLocaleDateString('sk-SK')}</div>
                    <button onClick={() => window.print()} className="mt-6 px-6 py-3 bg-slate-900 text-white rounded-lg font-black no-print flex items-center gap-3 ml-auto shadow-lg text-sm hover:bg-black transition-all hover:scale-105 active:scale-95"><Printer size={20}/> TLAČIŤ PONUKU</button>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-16 mb-12 pb-10 border-b border-gray-100">
                <div><div className="text-[10px] font-black text-gray-400 uppercase mb-4 tracking-widest flex items-center gap-2">Dodávateľ <button onClick={() => setIsSupplierModalOpen(true)} className="no-print text-blue-500 hover:underline font-bold text-[9px] uppercase">Zmeniť</button></div><div className="font-black text-xl uppercase text-slate-900">{data.supplier.name}</div><div className="text-sm text-gray-500 leading-relaxed whitespace-pre-wrap mt-2">{data.supplier.details}</div></div>
                <div className="border-l-2 border-gray-100 pl-16">
                    <div className="text-[10px] font-black text-gray-400 uppercase mb-4 tracking-widest flex items-center gap-2">Klient <button onClick={() => setIsClientModalOpen(true)} className="no-print text-blue-500 hover:underline font-bold text-[9px] uppercase">Zmeniť</button></div>
                    <div className="font-black text-xl uppercase text-slate-900">{data.client.name || 'ZADAJTE KLIENTA'}</div>
                    <div className="text-sm text-gray-500 leading-relaxed whitespace-pre-wrap mt-2">{data.client.details}</div>
                </div>
            </div>

            {data.showTechSpecs && (
                <TechSpecTable data={data.layout!} controlData={data.controlLayout} mode={data.quoteMode || 'lift'} isVisible={true} onToggleVisibility={() => {}} embedded={true} />
            )}

            <div className="space-y-10 mt-12">
                {data.categories.map(cat => (
                    <CategoryTable 
                        key={cat.id} category={cat} currency={data.currency} 
                        globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData({...data, categories: data.categories.map(c => c.id === id ? {...c, [f]: v} : c)})}
                        onDeleteCategory={(id) => setData({...data, categories: data.categories.filter(c => c.id !== id)})}
                        onAddItem={(cid, sur) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: [...c.items, { id: generateId(), description: sur?'Príplatok':'Nová položka', unit:'ks', quantity:1, unitPrice:0, purchasePrice:0, vatRate:23, isSurcharge:sur }]} : c)})}
                        onUpdateItem={(cid, iid, f, v) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)})}
                        onDeleteItem={(cid, iid) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)})}
                        onAiSuggest={() => {}} onOpenCatalog={() => {}} isAiLoading={false} mode={data.quoteMode}
                        onMoveCategory={moveCategory}
                    />
                ))}
            </div>

            <div className="mt-16 pt-8 border-t-4 border-slate-900 flex justify-end">
                <div className="w-3/5">
                    <table className="w-full">
                        <tbody>
                            <tr><td className="py-2 text-gray-500 font-black uppercase text-[11px] tracking-widest">Cena projektu bez DPH</td><td className="py-2 text-right font-black text-2xl">{totals.sale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                            <tr className="bg-slate-50 border-t border-slate-200"><td className="p-4 text-xl font-black uppercase tracking-tighter">Celková cena s DPH</td><td className="p-4 text-right text-4xl font-black">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-16 break-inside-avoid">
                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[150px] print:h-auto border-2 border-gray-100 rounded-xl" stickyToolbar={false} />
            </div>
        </div>
      </div>

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} controlLayout={data.controlLayout} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories}
          initialState={data.wizardData}
      />

      {showArchive && (
          <div className="fixed inset-0 bg-slate-900/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md">
              <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl h-[85vh] flex flex-col overflow-hidden border border-white/20">
                  <div className="p-6 border-b flex justify-between items-center bg-gray-50">
                      <h2 className="text-2xl font-black uppercase tracking-tighter flex items-center gap-3 text-slate-800"><Archive className="text-blue-600" size={28}/> Archív projektov</h2>
                      <button onClick={() => setShowArchive(false)} className="p-3 hover:bg-gray-200 rounded-full text-gray-500 transition-all"><X size={24}/></button>
                  </div>
                  <div className="p-6 border-b bg-white shadow-sm">
                      <div className="relative">
                          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={22} />
                          <input type="text" placeholder="Hľadať podľa čísla, referencie alebo klienta..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-12 pr-6 py-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:ring-4 focus:ring-blue-100 focus:border-blue-500 outline-none font-bold text-lg transition-all" />
                      </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-6 bg-gray-50/50">
                      <table className="w-full text-sm">
                        <thead className="bg-white border-b-2 sticky top-0 z-10 text-[11px] uppercase font-black text-gray-400 tracking-widest">
                            <tr><th className="p-5 text-left">Doklad</th><th className="p-5 text-left">Referencia</th><th className="p-5 text-left">Klient</th><th className="p-5 text-right">Cena s DPH</th><th className="p-5 text-center w-32">Akcia</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase()) || (q.clientReference || '').toLowerCase().includes(archiveSearch.toLowerCase())).map(q => (
                                <tr key={q.id} className="bg-white hover:bg-blue-50 transition-all group">
                                    <td className="p-5 font-black text-slate-800">{q.number}</td>
                                    <td className="p-5 font-bold text-blue-600 uppercase text-xs tracking-wider">{q.clientReference || '-'}</td>
                                    <td className="p-5 font-semibold text-slate-600">{q.client.name || 'Neznámy'}</td>
                                    <td className="p-5 text-right font-black text-slate-900 text-lg">{calculateTotals(q).gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} €</td>
                                    <td className="p-5 text-center"><button onClick={() => { setData(q); setShowArchive(false); }} className="px-5 py-2 bg-slate-900 text-white font-black rounded-lg text-xs hover:bg-black transition-all uppercase tracking-widest shadow-md">Otvoriť</button></td>
                                </tr>
                            ))}
                        </tbody>
                      </table>
                  </div>
              </div>
          </div>
      )}

      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={(p) => setProducts([...products, p])} onUpdateProduct={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))} customCategories={availableCategories} onAddCategory={(c) => setAvailableCategories([...availableCategories, c])} onDeleteCategory={(c) => setAvailableCategories(availableCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])} onUpdateCabinClass={(cc) => setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c))} onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const seq = t === 'control_system' ? (settings.nextRsSequence || 1) : (settings.nextCpSequence || 1);
          const prefix = t === 'control_system' ? 'RS' : 'CP';
          const num = `${prefix}_SK_${seq.toString().padStart(3, '0')}_24_BA`;
          setData({ ...data, id: generateId(), number: num, quoteMode: t, categories: (t==='lift'?DEFAULT_CATEGORIES_LIST:CONTROL_SYSTEM_CATEGORIES).map(n => ({ id: generateId(), name: n, type: 'items', items: [], isExpanded: true })) });
      }} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details}})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  QuoteData, Product, Client, Supplier, AppSettings, QuoteCategory, 
  LiftLayoutData, CabinClass, ControlSystemLayout
} from './types';
import { 
  Archive, X, Search, Sliders, Settings, Calculator, Save, LogOut, 
  CheckCircle, Printer, PlusCircle, FileText, FileMinus, Trash2, Zap
} from 'lucide-react';
import { CatalogManagerModal } from './components/CatalogManagerModal';
import { ClientDatabaseModal } from './components/ClientDatabaseModal';
import { SupplierDatabaseModal } from './components/SupplierDatabaseModal';
import { SettingsModal } from './components/SettingsModal';
import { MaterialCalculatorModal, MaterialWizardData } from './components/MaterialCalculatorModal';
import { CategoryTable } from './components/CategoryTable';
import { TechSpecTable } from './components/TechSpecTable';
import { StandaloneRichTextEditor } from './components/StandaloneRichTextEditor';
import { LoginGate } from './components/LoginGate';
import { NewQuoteModal } from './components/NewQuoteModal';

const APP_VERSION = "4.3.40 Heritage";

const DEFAULT_CATEGORIES_LIST = [
    'Dvere', 'Kabína a rám', 'Pohon', 'Vodítka a kotvenie', 'Obmedzovač', 'Elektro', 'Rozvádzač a riadenie', 'Montáž', 'Doprava', 'Balné', 'Ostatné'
];

const DEFAULT_LAYOUT: LiftLayoutData = {
  liftType: 'passenger', driveType: 'traction', ratedLoad: 630, numberOfPersons: 8, ratedSpeed: 1.0, powerSupply: '400V / 50Hz',
  shaftWidth: 1600, shaftDepth: 1800, cabinWidth: 1100, cabinDepth: 1400, cabinHeight: 2100, doorWidth: 800, doorOffsetL: 0,
  pitDepth: 1100, headroomHeight: 3400, travelHeight: 15000,
  doorType: 'central', doorOperation: 'automatic', counterWeightPosition: 'back', machineRoomPosition: 'head',
  gapLeft: 270, gapRight: 80, gapFront: 210, gapRear: 50, notes: '',
  numberOfStops: 5, numberOfEntrances: 5, startStation: 0,
  tractionMedium: 'ctp', frameType: 'central',
  hasExternalShaft: false, bracketType: 'combined', guideTypeCar: 'T89', guideTypeCwt: 'T50',
  guideRailLength: 5000, doorOpeningWidth: 1060, doorOpeningHeight: 2060, LDO: 270, RDO: 270, 
  suspensionType: '2:1', cabinClass: 'FUN', entrances: 'A', isThroughCar: false
};

const TERMS_DEFAULT = `<p><strong>1. Platnosť:</strong> 60 dní. <strong>2. Dodanie:</strong> 8-12 týždňov. <strong>3. Záruka:</strong> 24 mesiacov.</p>`;

const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try { return crypto.randomUUID(); } catch (e) {}
  }
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!sessionStorage.getItem('auth'));
  const [data, setData] = useState<QuoteData>({
    id: generateId(), number: 'CP_SK_001_24_BA', type: 'quote', quoteMode: 'lift', title: 'Cenová Ponuka - Výťah',
    date: new Date().toISOString().split('T')[0], 
    validUntil: new Date(Date.now() + 60*24*60*60*1000).toISOString().split('T')[0],
    clientReference: '', supplier: { name: 'Moja Firma s.r.o.', details: 'IČO: 12345678, DPH: SK12345678' },
    client: { name: '', details: '' }, layout: { ...DEFAULT_LAYOUT },
    categories: DEFAULT_CATEGORIES_LIST.map(n => ({ id: generateId(), name: n, type: 'items', items: [], isExpanded: true })), 
    terms: TERMS_DEFAULT, currency: '€', globalMargin: 15, shaftMargin: 20, vatRate: 23, 
    hideItemPrices: true, showTechSpecs: true
  });

  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [settings, setSettings] = useState<AppSettings>({ nextCpSequence: 1, nextRsSequence: 1, nextObjSequence: 1, nextPlSequence: 1 });
  const [savedQuotes, setSavedQuotes] = useState<QuoteData[]>([]);
  const [availableCategories, setAvailableCategories] = useState<string[]>(DEFAULT_CATEGORIES_LIST);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);

  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isSupplierModalOpen, setIsSupplierModalOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);
  const [isNewQuoteModalOpen, setIsNewQuoteModalOpen] = useState(false);
  const [showArchive, setShowArchive] = useState(false);
  const [archiveSearch, setArchiveSearch] = useState('');

  useEffect(() => {
      const storedQuotes = localStorage.getItem('smartquote_archive');
      if (storedQuotes) try { setSavedQuotes(JSON.parse(storedQuotes)); } catch (e) {}
      const storedSettings = localStorage.getItem('smartquote_settings');
      if (storedSettings) try { setSettings(JSON.parse(storedSettings)); } catch (e) {}

      const loadLS = (key: string, setter: any) => { const s = localStorage.getItem(key); if(s) try { setter(JSON.parse(s)); } catch(e){} };
      loadLS('smartquote_products', setProducts);
      loadLS('smartquote_clients', setClients);
      loadLS('smartquote_suppliers', setSuppliers);
      loadLS('smartquote_categories', (v: any) => setAvailableCategories(Array.from(new Set([...DEFAULT_CATEGORIES_LIST, ...v]))));
  }, []);

  const calculateTotals = (q: QuoteData = data) => {
      let total = 0;
      q.categories.forEach(cat => {
          if (cat.isHidden) return;
          const margin = cat.section === 'shaft' ? q.shaftMargin : q.globalMargin;
          cat.items.forEach(item => {
              total += (item.quantity * item.unitPrice) * (1 + margin / 100);
          });
      });
      const vat = total * ((q.vatRate || 23) / 100);
      return { sale: total, vat, gross: total + vat };
  };

  const totals = calculateTotals();

  const handleMaterialWizardInsert = (wData: MaterialWizardData) => {
      setData(prev => {
          const newData = { ...prev, wizardData: wData };
          const activeItems = wData.items.filter(i => i.selected !== false);
          const catNames = new Set(activeItems.map(i => i.category));

          if (wData.includeAssembly) catNames.add('Montáž');
          if (wData.includeTransport) catNames.add('Doprava');
          if (wData.includePackaging) catNames.add('Balné');

          newData.categories = newData.categories.filter(c => c.type === 'text' || catNames.has(c.name));
          catNames.forEach(name => {
              let c = newData.categories.find(x => x.name === name);
              if (!c) {
                  c = { id: generateId(), name, type: 'items', items: [], isExpanded: true, section: 'lift' };
                  newData.categories.push(c);
              }
              c.items = [];
          });

          activeItems.forEach(i => {
              const cat = newData.categories.find(x => x.name === i.category);
              if (cat) cat.items.push({ id: generateId(), description: i.description, unit: i.unit, quantity: i.quantity, unitPrice: i.price || 0, purchasePrice: 0, vatRate: 23 });
          });

          const findC = (n: string) => newData.categories.find(x => x.name === n);
          if (wData.includeAssembly) { const c = findC('Montáž'); if (c) c.items.push({ id: generateId(), description: 'Montáž technológie', unit: 'kpl', quantity: 1, unitPrice: 1500, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includeTransport) { const c = findC('Doprava'); if (c) c.items.push({ id: generateId(), description: 'Doprava a logistika', unit: 'kpl', quantity: 1, unitPrice: wData.transportPrice || 250, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includePackaging) { const c = findC('Balné'); if (c) c.items.push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); }

          return newData;
      });
  };

  const moveCategory = (id: string, dir: 'up' | 'down') => {
      const idx = data.categories.findIndex(c => c.id === id);
      if (idx === -1) return;
      if (dir === 'up' && idx === 0) return;
      if (dir === 'down' && idx === data.categories.length - 1) return;

      const newCats = [...data.categories];
      const targetIdx = dir === 'up' ? idx - 1 : idx + 1;
      const [moved] = newCats.splice(idx, 1);
      newCats.splice(targetIdx, 0, moved);
      setData(p => ({ ...p, categories: newCats }));
  };

  if (!isAuthenticated) return <LoginGate onLogin={() => { sessionStorage.setItem('auth', 'true'); setIsAuthenticated(true); }} />;

  return (
    <div className="min-h-screen bg-gray-100 font-sans print:bg-white text-slate-800 antialiased">

      {/* HEADER - v4.3.40 Pure White Header */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-50 print:hidden shadow-sm h-14 flex items-center">
          <div className="max-w-[1400px] w-full mx-auto px-6 flex items-center justify-between">
            <div className="flex items-center gap-8">
                <div className="flex items-center gap-2">
                    <div className="bg-blue-600 p-1.5 rounded shadow-sm text-white">
                        <Zap size={20} className="fill-current"/>
                    </div>
                    <span className="font-bold text-lg tracking-tight text-gray-800">SmartQuote <span className="text-[10px] font-normal text-gray-400 bg-gray-50 px-1.5 py-0.5 rounded ml-1">v{APP_VERSION}</span></span>
                </div>
                <div className="h-6 w-px bg-gray-200"></div>
                <div className="flex items-center gap-1">
                    <button onClick={() => setShowArchive(true)} className="flex items-center gap-2 px-3 py-1.5 text-gray-600 hover:bg-gray-100 rounded transition font-semibold text-sm"><Archive size={16}/> Archív</button>
                    <button onClick={() => setIsNewQuoteModalOpen(true)} className="flex items-center gap-2 px-4 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded shadow-sm transition font-bold text-sm ml-2"><PlusCircle size={16}/> Nová CP</button>
                </div>
            </div>
            <div className="flex items-center gap-3">
                 <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-1.5 text-gray-500 hover:text-gray-800 transition text-sm font-semibold flex items-center gap-1"><Settings size={14}/> Katalóg</button>
                 <button onClick={() => { localStorage.setItem('smartquote_archive', JSON.stringify(savedQuotes)); alert("Dáta boli uložené."); }} className="px-4 py-1.5 bg-green-600 hover:bg-green-700 text-white rounded shadow-sm transition font-bold text-sm flex items-center gap-2"><Save size={16}/> Uložiť</button>
                 <button onClick={() => { sessionStorage.removeItem('auth'); setIsAuthenticated(false); }} className="p-2 text-gray-400 hover:text-red-500 transition-colors ml-1"><LogOut size={18}/></button>
            </div>
          </div>
      </div>

      <div className="max-w-[210mm] mx-auto py-8 print:p-0">

        {/* PARAMS PANEL - Heritage Style */}
        <div className="mb-6 p-6 bg-white rounded-lg border border-gray-200 shadow-sm no-print border-t-4 border-t-blue-600">
            <div className="grid grid-cols-12 gap-4">
                <div className="col-span-12 font-bold text-gray-400 uppercase flex items-center justify-between mb-2 pb-2 border-b border-gray-100 text-[10px] tracking-widest">
                    <div className="flex items-center gap-2">
                        <Sliders size={16} className="text-blue-600"/> 
                        Konfigurácia Projektu
                    </div>
                    {data.wizardData && <div className="bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-bold flex items-center gap-1"><CheckCircle size={10}/> Sprievodca Aktívny</div>}
                </div>

                <div className="col-span-2"><label className="text-[9px] uppercase font-bold text-gray-400 block mb-1">Nosnosť (kg)</label><input type="number" value={data.layout?.ratedLoad} onChange={e => setData({...data, layout:{...data.layout!, ratedLoad:+e.target.value}})} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-gray-50 focus:bg-white outline-none"/></div>
                <div className="col-span-2"><label className="text-[9px] uppercase font-bold text-gray-400 block mb-1">Stanice</label><input type="number" value={data.layout?.numberOfStops} onChange={e => setData({...data, layout:{...data.layout!, numberOfStops:+e.target.value}})} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-gray-50 focus:bg-white outline-none"/></div>
                <div className="col-span-3"><label className="text-[9px] uppercase font-bold text-gray-400 block mb-1">Zdvih (mm)</label><input type="number" value={data.layout?.travelHeight} onChange={e => setData({...data, layout:{...data.layout!, travelHeight:+e.target.value}})} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold bg-gray-50 focus:bg-white outline-none"/></div>
                <div className="col-span-5 flex items-end">
                    <button 
                        onClick={() => setIsMaterialModalOpen(true)} 
                        className={`w-full h-10 font-bold rounded shadow-sm flex items-center justify-center gap-2 text-sm transition-all hover:scale-[1.01] active:scale-95 ${data.wizardData ? 'bg-green-600 hover:bg-green-700 text-white' : 'bg-blue-600 hover:bg-blue-700 text-white'}`}
                    >
                        {data.wizardData ? <CheckCircle size={18}/> : <Calculator size={18}/>} 
                        {data.wizardData ? 'Upraviť Sprievodcu' : 'Materiálový Sprievodca'}
                    </button>
                </div>
            </div>
        </div>

        {/* DOCUMENT VIEW */}
        <div className="bg-white shadow-xl print:shadow-none min-h-[297mm] p-12 print:p-0 border border-gray-200 rounded-sm">
            <div className="mb-10 border-b-2 border-slate-900 pb-6 flex justify-between items-start">
                 <div className="w-2/3 text-left">
                    <textarea value={data.title} onChange={e => setData({...data, title: e.target.value})} className="text-4xl font-bold w-full border-none bg-transparent uppercase p-0 leading-tight focus:outline-none" rows={1}/>
                    <div className="text-xl text-gray-400 font-semibold mt-1 uppercase tracking-wider">{data.number}</div>
                    <div className="mt-6"><input value={data.clientReference} onChange={e => setData({...data, clientReference: e.target.value})} className="text-lg font-bold text-blue-600 w-full border-none p-0 uppercase placeholder-gray-200 focus:outline-none" placeholder="REFERENCIA PROJEKTU"/></div>
                </div>
                <div className="text-right">
                    <div className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Dátum vystavenia</div>
                    <div className="font-semibold text-lg">{new Date(data.date).toLocaleDateString('sk-SK')}</div>
                    <button onClick={() => window.print()} className="mt-4 px-4 py-2 bg-gray-800 text-white rounded font-bold no-print flex items-center gap-2 ml-auto shadow-sm text-sm hover:bg-black transition-colors"><Printer size={16}/> Tlačiť PDF</button>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-12 mb-10 pb-8 border-b border-gray-100">
                <div className="text-left"><div className="text-[9px] font-bold text-gray-400 uppercase mb-2">Dodávateľ <button onClick={() => setIsSupplierModalOpen(true)} className="no-print text-blue-500 ml-2 font-normal">Zmeniť</button></div><div className="font-bold text-lg uppercase">{data.supplier.name}</div><div className="text-xs text-gray-500 leading-relaxed whitespace-pre-wrap mt-1">{data.supplier.details}</div></div>
                <div className="border-l border-gray-100 pl-10 text-left">
                    <div className="text-[9px] font-bold text-gray-400 uppercase mb-2">Klient <button onClick={() => setIsClientModalOpen(true)} className="no-print text-blue-500 ml-2 font-normal">Zmeniť</button></div>
                    <div className="font-bold text-lg uppercase">{data.client.name || 'ZADAJTE KLIENTA'}</div>
                    <div className="text-xs text-gray-500 leading-relaxed whitespace-pre-wrap mt-1">{data.client.details}</div>
                </div>
            </div>

            {data.showTechSpecs && (
                <TechSpecTable data={data.layout!} mode={data.quoteMode || 'lift'} isVisible={true} onToggleVisibility={() => {}} embedded={true} />
            )}

            <div className="space-y-6 mt-10">
                {data.categories.map(cat => (
                    <CategoryTable 
                        key={cat.id} category={cat} currency={data.currency} 
                        globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData({...data, categories: data.categories.map(c => c.id === id ? {...c, [f]: v} : c)})}
                        onDeleteCategory={(id) => setData({...data, categories: data.categories.filter(c => c.id !== id)})}
                        onAddItem={(cid, sur) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: [...c.items, { id: generateId(), description: sur?'Príplatok':'Nová položka', unit:'ks', quantity:1, unitPrice:0, purchasePrice:0, vatRate:23, isSurcharge:sur }]} : c)})}
                        onUpdateItem={(cid, iid, f, v) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)})}
                        onDeleteItem={(cid, iid) => setData({...data, categories: data.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)})}
                        onAiSuggest={() => {}} onOpenCatalog={() => {}} isAiLoading={false} mode={data.quoteMode}
                        onMoveCategory={moveCategory}
                    />
                ))}
            </div>

            <div className="mt-12 pt-6 border-t-2 border-slate-900 flex justify-end">
                <div className="w-1/2">
                    <table className="w-full text-sm">
                        <tbody>
                            <tr><td className="py-1 text-gray-500 font-bold uppercase text-[10px] text-left">Cena bez DPH</td><td className="py-1 text-right font-bold text-lg">{totals.sale.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                            <tr className="bg-gray-50"><td className="p-3 text-lg font-bold uppercase text-left">Celkom s DPH</td><td className="p-3 text-right text-3xl font-bold">{totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} {data.currency}</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-12 break-inside-avoid">
                <StandaloneRichTextEditor content={data.terms} onChange={v => setData({...data, terms: v})} minimalPadding={true} className="min-h-[120px] print:h-auto" stickyToolbar={false} />
            </div>
        </div>
      </div>

      <MaterialCalculatorModal 
          key={data.id} isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} 
          layout={data.layout!} mode={data.quoteMode || 'lift'} 
          onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories}
          initialState={data.wizardData}
      />

      {showArchive && (
          <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4">
              <div className="bg-white rounded-lg shadow-2xl w-full max-w-5xl h-[80vh] flex flex-col">
                  <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-lg">
                      <h2 className="text-xl font-bold uppercase flex items-center gap-2"><Archive className="text-blue-600"/> Archív CP</h2>
                      <button onClick={() => setShowArchive(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
                  </div>
                  <div className="p-4 border-b bg-white">
                      <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={20} />
                          <input type="text" placeholder="Hľadať CP..." value={archiveSearch} onChange={(e) => setArchiveSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-400 outline-none font-medium" />
                      </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                      <table className="w-full text-sm">
                        <thead className="bg-white border-b sticky top-0 z-10 text-[10px] uppercase font-bold text-gray-400">
                            <tr><th className="p-4 text-left">Doklad</th><th className="p-4 text-left">Projekt</th><th className="p-4 text-left">Klient</th><th className="p-4 text-right">Cena s DPH</th><th className="p-4 text-center">Akcia</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {savedQuotes.filter(q => q.number.toLowerCase().includes(archiveSearch.toLowerCase()) || q.client.name.toLowerCase().includes(archiveSearch.toLowerCase())).map(q => (
                                <tr key={q.id} className="bg-white hover:bg-blue-50/50 transition-colors group">
                                    <td className="p-4 font-bold text-gray-900 text-left">{q.number}</td>
                                    <td className="p-4 font-bold text-blue-600 uppercase text-xs text-left">{q.clientReference || '-'}</td>
                                    <td className="p-4 font-semibold text-gray-700 text-left">{q.client.name || 'Neznámy'}</td>
                                    <td className="p-4 text-right font-bold text-gray-900 text-base">{calculateTotals(q).gross.toLocaleString('sk-SK', {minimumFractionDigits: 2})} €</td>
                                    <td className="p-4 text-center"><button onClick={() => { setData(q); setShowArchive(false); }} className="px-3 py-1 bg-blue-600 text-white font-bold rounded text-xs hover:bg-blue-700">Otvoriť</button></td>
                                </tr>
                            ))}
                        </tbody>
                      </table>
                  </div>
              </div>
          </div>
      )}

      <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={(p) => setProducts([...products, p])} onUpdateProduct={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} onDeleteProduct={(id) => setProducts(products.filter(p => p.id !== id))} customCategories={availableCategories} onAddCategory={(c) => setAvailableCategories([...availableCategories, c])} onDeleteCategory={(c) => setAvailableCategories(availableCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])} onUpdateCabinClass={(cc) => setCabinClasses(prev => prev.map(c => c.id === cc.id ? cc : c))} onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />
      <NewQuoteModal isOpen={isNewQuoteModalOpen} onClose={() => setIsNewQuoteModalOpen(false)} onSelect={(t) => {
          setIsNewQuoteModalOpen(false);
          const seq = (settings.nextCpSequence || 1);
          const prefix = 'CP';
          const num = `${prefix}_SK_${seq.toString().padStart(3, '0')}_24_BA`;
          setData({ ...data, id: generateId(), number: num, quoteMode: 'lift', categories: DEFAULT_CATEGORIES_LIST.map(n => ({ id: generateId(), name: n, type: 'items', items: [], isExpanded: true })) });
      }} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details}})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
    </div>
  );
};
